-- ============================================================
-- end of 0001_init.sql
-- ============================================================

-- ############################################################
-- ## 0002_transactions.sql
-- ############################################################

-- ============================================================
-- Invento v2 — transactional side effects (inventory ledger)
-- All SECURITY DEFINER so they can write to inventory_ledger despite its
-- "no direct write" RLS policy. Each fires inside the same transaction as
-- the triggering insert, so a partial failure rolls back everything —
-- this is the DB-level fix for the baseline's "not built atomically" gaps.
-- ============================================================

-- A. Purchase line insert -> push remaining_qty (never the full quantity —
--    this is the "Automatic Sampling Deduction" fix, DESIGN.md §7.1).
create or replace function public.trg_fn_purchase_line_push()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.remaining_qty > 0 then
    insert into public.inventory_ledger
      (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('push', new.item_id, new.id, new.remaining_qty, new.unit, 'purchase', new.id, auth.uid());
  end if;
  return new;
end $$;
create trigger trg_purchase_line_push
  after insert on public.purchase_lines
  for each row execute function public.trg_fn_purchase_line_push();

-- B. QC record insert against an RM batch -> pull the sample out of stock
--    at the moment testing actually starts, not at purchase time.
create or replace function public.trg_fn_qc_sample_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.purchase_line_id is not null and coalesce(new.sample_qty, 0) > 0 then
    insert into public.inventory_ledger
      (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('pull', new.item_id, new.purchase_line_id, new.sample_qty, new.sample_unit, 'qc', new.id, auth.uid());
  end if;
  return new;
end $$;
create trigger trg_qc_sample_pull
  after insert on public.quality_checks
  for each row execute function public.trg_fn_qc_sample_pull();

-- C. Finished Product composition line insert -> pull the scaled quantity
--    from the chosen (QC-Approved — enforced by trg_fp_component_qc_gate)
--    RM batch.
create or replace function public.trg_fn_fp_component_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, reference_type, reference_id, event_by)
  values
    ('pull', new.item_id, new.purchase_line_id, new.quantity, 'finished_product', new.finished_product_batch_id, auth.uid());
  return new;
end $$;
create trigger trg_fp_component_pull
  after insert on public.finished_product_components
  for each row execute function public.trg_fn_fp_component_pull();

-- D. Packaging issue insert -> pull the packaging material used, and bump
--    the FP batch's running packaged_qty (see DESIGN.md §9 — a simple
--    running counter, not unit-converted against net_weight in this pass).
create or replace function public.trg_fn_packaging_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_ledger
    (event_type, item_id, quantity, department, reference_type, reference_id, event_by)
  values
    ('pull', new.packaging_item_id, new.packaging_qty_used, new.department, 'packaging', new.id, auth.uid());

  update public.finished_product_batches
    set packaged_qty = packaged_qty +
      case new.transaction_type when 'unpack' then -new.unit_count else new.unit_count end
    where id = new.finished_product_batch_id;
  return new;
end $$;
create trigger trg_packaging_pull
  after insert on public.packaging_issues
  for each row execute function public.trg_fn_packaging_pull();

-- E. Wastage helper — RPC used by the Inventory Ledger module's "record
--    wastage" action (a dedicated event type the baseline never had).
create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;
  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by)
  values ('wastage', p_item_id, p_purchase_line_id, p_quantity, p_unit, 'purchase', auth.uid())
  returning id into v_id;
  return v_id;
end $$;

-- ############################################################
-- ## 0003_fixes.sql
-- ############################################################

-- ============================================================
-- Invento v2 — fixes found while building the modules against
-- 0001_init.sql / 0002_transactions.sql (see docs/modules/*.md for the
-- agent reports that flagged each of these).
-- ============================================================

-- 1. finished-product.md: an mfr_manager could do everything on the
--    Finished Product module except "Submit to QC", because the
--    quality_checks insert policy didn't include mfr_manager. Finished
--    Product batches are legitimately mfr_manager's to submit.
drop policy if exists qc_insert on public.quality_checks;
create policy qc_insert on public.quality_checks for insert
  with check (public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer','mfr_manager'));

-- 2. inventory.md: record_wastage() accepted p_reason but never stored it —
--    the wastage form collects and submits a reason today with nowhere for
--    it to land.
alter table public.inventory_ledger add column if not exists reason text;

create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;
  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by, reason)
  values ('wastage', p_item_id, p_purchase_line_id, p_quantity, p_unit, 'purchase', auth.uid(), p_reason)
  returning id into v_id;
  return v_id;
end $$;

-- 3. bmr.md: one BMR per finished-product batch was enforced only by the
--    /bmr/new picker filtering out batches that already have one — a race
--    could produce two. Make it a real constraint.
alter table public.bmr_records
  add constraint bmr_records_one_per_batch unique (finished_product_batch_id);

-- ############################################################
-- ## 0004_feedback.sql
-- ############################################################

-- ============================================================
-- Page feedback / tester observations
--
-- Standalone, additive migration — run this ON ITS OWN in the SQL
-- Editor against the already-live project. Unlike 0001_init.sql this
-- does NOT reset the public schema; it only creates one new table.
-- Safe to re-run: it drops and recreates just page_feedback.
--
-- Depends on objects created by 0001_init.sql (public.is_signed_in(),
-- public.has_role(), public.set_updated_at()) — run 0001-0003 first
-- on a fresh project.
-- ============================================================

drop table if exists public.page_feedback cascade;

create table public.page_feedback (
  id uuid primary key default gen_random_uuid(),
  -- normalized page identity, e.g. "/purchase" (dynamic segments like
  -- /purchase/[id] are stripped client-side before insert) — this is
  -- what the per-page widget filters by.
  page_path text not null,
  page_label text not null,
  -- the exact URL the tester was on, kept for context even though
  -- page_path is what groups the changelog.
  url_path text not null,
  observation text not null,
  submitted_by uuid references auth.users(id) on delete set null,
  -- denormalized so the changelog still shows who reported something
  -- even if that account is later removed.
  submitted_by_name text not null,
  -- set on triage (by Claude/system_admin), null until then.
  category text check (category in ('bug', 'enhancement', 'invalid', 'user_education', 'duplicate', 'other')),
  status text not null default 'new' check (status in ('new', 'awaiting_implementation', 'implemented', 'rejected')),
  claude_notes text,
  resolved_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  updated_by uuid references auth.users(id)
);

create index page_feedback_page_path_idx on public.page_feedback (page_path);
create index page_feedback_status_idx on public.page_feedback (status);
create index page_feedback_created_at_idx on public.page_feedback (created_at desc);

alter table public.page_feedback enable row level security;

-- Any signed-in user can read the changelog on any page.
create policy page_feedback_select on public.page_feedback
  for select using (public.is_signed_in());

-- Any signed-in user (any role — "testers" broadly) can submit
-- feedback, but only as themselves.
create policy page_feedback_insert on public.page_feedback
  for insert with check (public.is_signed_in() and submitted_by = auth.uid());

-- Only System Admin can triage (set category/status/notes) or delete
-- (e.g. spam/test rows). This is where Claude's classification pass
-- writes, acting through a system_admin account.
create policy page_feedback_update on public.page_feedback
  for update using (public.has_role('system_admin'))
  with check (public.has_role('system_admin'));

create policy page_feedback_delete on public.page_feedback
  for delete using (public.has_role('system_admin'));

create trigger page_feedback_set_updated_at
  before update on public.page_feedback
  for each row execute function public.set_updated_at();

-- ############################################################
-- ## 0005_feedback_ticket_number.sql
-- ############################################################

-- ============================================================
-- Tester feedback — unique ticket identifier
--
-- Standalone, additive migration — run this ON ITS OWN in the SQL Editor
-- against the already-live project, after 0001-0004. Unlike 0004_feedback.sql
-- this does NOT drop/recreate page_feedback (that would destroy every
-- submission already on file) — it only adds a column and backfills it.
-- Safe to re-run: every statement is idempotent (if not exists / if null).
--
-- Why: testers and Ravi need a short, stable identifier for each piece of
-- feedback ("implement FB-0003") — the uuid `id` isn't practical to read
-- back over chat. Follows the same nextval()+lpad() convention already
-- used for po_number/ar_number/vendor_code/etc. in 0001_init.sql.
-- ============================================================

create sequence if not exists public.feedback_ticket_seq start 1;

create or replace function public.get_next_feedback_ticket()
returns text language sql as $$
  select 'FB-' || lpad(nextval('public.feedback_ticket_seq')::text, 4, '0');
$$;

alter table public.page_feedback add column if not exists ticket_number text;

-- Backfill existing rows (oldest first, so ticket numbers read in the same
-- order feedback was originally submitted) before the column is made
-- required, then advance the sequence past whatever we just assigned so
-- the next live get_next_feedback_ticket() call doesn't collide.
with ordered as (
  select id, row_number() over (order by created_at) as rn
  from public.page_feedback
  where ticket_number is null
)
update public.page_feedback pf
set ticket_number = 'FB-' || lpad(ordered.rn::text, 4, '0')
from ordered
where pf.id = ordered.id;

select setval('public.feedback_ticket_seq', greatest((select count(*) from public.page_feedback), 1), true);

alter table public.page_feedback alter column ticket_number set not null;
alter table public.page_feedback drop constraint if exists page_feedback_ticket_number_unique;
alter table public.page_feedback add constraint page_feedback_ticket_number_unique unique (ticket_number);

-- ############################################################
-- ## 0006_sequence_grants.sql
-- ############################################################

-- ============================================================
-- Fix: "Could not generate item code: permission denied for sequence
-- item_code_seq_raw" (and the same error for every other auto-numbered
-- code in the app).
--
-- Root cause: 0001_init.sql's default-privilege grants cover tables
-- ("alter default privileges in schema public grant select, insert,
-- update, delete on tables to anon, authenticated") and functions
-- ("... grant execute on functions to anon, authenticated") but NOT
-- sequences — sequences were only granted to postgres/service_role. Every
-- get_next_*() function (get_next_item_code, get_next_vendor_code,
-- get_next_po_number, get_next_ar_number, get_next_mfr_code,
-- get_next_fp_batch_number, get_next_coa_number, get_next_feedback_ticket)
-- is a plain `language sql` function — not `security definer` — so it runs
-- as the CALLING role (authenticated, via the anon/authenticated Postgres
-- roles Supabase's RLS-enforced client uses), and that role never had
-- nextval() rights on any of these sequences. Any signed-in user hitting
-- "New Item" / "New Vendor" / "New Purchase Order" / etc. would hit this.
--
-- Standalone, additive migration — run this ON ITS OWN in the SQL Editor.
-- Purely a privilege grant; touches no data, no table structure. Safe to
-- re-run any number of times.
-- ============================================================

grant usage, select on all sequences in schema public to anon, authenticated;

-- Cover any sequence created after this migration runs too (mirrors the
-- default-privilege statements already in place for tables/functions).
alter default privileges in schema public grant usage, select on sequences to anon, authenticated;

-- ############################################################
-- ## 0007_item_code_fp_and_sample_unit.sql
-- ############################################################

-- ============================================================
-- FB-0002 (Item Master, /items/new):
--   1. "Category should be Raw Material, Packaging and Finished Product" —
--      makes 'processed' a normal, user-creatable/editable category
--      (application-side change in lib/actions/items.ts + item-form.tsx;
--      this migration only changes the DB-side code generator).
--   2. "autogenerated Item Code starting RM/PKG/FP suffixed by autogenerated
--      number ... RM-00001, PKG-00001, FP-00001" — get_next_item_code() was
--      only a 2-way if/else (raw->RM, else->PKG) with 4-digit padding.
--      Rewritten to a 3-way branch (raw->RM, packaging->PKG,
--      processed->FP) with 5-digit padding on all three, using a new
--      sequence for the FP prefix so it doesn't share numbering with
--      RM/PKG.
--   3. "unit selection for Default QC Qty, Default stability qty, default
--      R&D qty (one selection for all three)" — adds
--      items.default_sample_unit, a single unit shared by all three
--      default-sampling-quantity fields, independent of the item's base
--      `unit`. This is deliberately DISPLAY-ONLY for now: it is not wired
--      into purchase_lines' qc_qty/stability_qty/rnd_qty, which still share
--      one `unit` column with `quantity` and feed the generated
--      `remaining_qty` column (quantity - qc_qty - stability_qty -
--      rnd_qty) — automatically converting between units there would need
--      a real unit-conversion table, which doesn't exist anywhere in this
--      schema yet. See the app-side change for how it's surfaced (a
--      "recommended sample" hint on the purchase line form) — flagged in
--      chat as an intentional scope decision, not an oversight.
--
-- Standalone, additive migration. Safe to re-run.
-- ============================================================

create sequence if not exists public.item_code_seq_fp start 1;
grant usage, select on public.item_code_seq_fp to anon, authenticated;

create or replace function public.get_next_item_code(p_category text)
returns text language plpgsql as $$
declare v_num int; v_prefix text;
begin
  if p_category = 'packaging' then
    v_num := nextval('public.item_code_seq_pkg'); v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_num := nextval('public.item_code_seq_fp'); v_prefix := 'FP';
  else
    v_num := nextval('public.item_code_seq_raw'); v_prefix := 'RM';
  end if;
  return v_prefix || '-' || lpad(v_num::text, 5, '0');
end $$;

alter table public.items add column if not exists default_sample_unit text;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'items_default_sample_unit_check'
  ) then
    alter table public.items
      add constraint items_default_sample_unit_check
      check (default_sample_unit in ('kg','g','mg','ltr','ml','count','bottle','pack'));
  end if;
end $$;

-- ############################################################
-- ## 0008_item_type_delete_policy.sql
-- ############################################################

-- ============================================================
-- FB-0004 (Item Type Master): "Admin should have access to delete item
-- type record."
--
-- item_types_write (0001_init.sql) is a single `for all` policy covering
-- insert/update/delete for system_admin, inventory_manager and
-- mfr_manager alike — the app never exposed a delete action, so this was
-- latent, unused. The ticket asks specifically for Admin-only delete, so
-- this migration splits that one policy into insert/update (unchanged,
-- same three roles) and a new delete policy restricted to system_admin —
-- a deliberate tightening, not a loosening, and matches the app-side
-- check in deleteItemType() (lib/actions/item-types.ts) so the two layers
-- agree, per the briefing's "app checks are UI-affordance only, RLS is
-- the real backstop" convention.
--
-- Standalone, additive migration (drops and recreates one policy; no data
-- or table-structure changes). Safe to re-run.
-- ============================================================

drop policy if exists item_types_write on public.item_types;

create policy item_types_insert on public.item_types for insert
  with check (public.has_any_role('system_admin','inventory_manager','mfr_manager'));

create policy item_types_update on public.item_types for update
  using (public.has_any_role('system_admin','inventory_manager','mfr_manager'))
  with check (public.has_any_role('system_admin','inventory_manager','mfr_manager'));

create policy item_types_delete on public.item_types for delete
  using (public.has_any_role('system_admin'));

-- ############################################################
-- ## 0009_master_data_delete_policy.sql
-- ############################################################

-- ============================================================
-- "Provide delete access for all master data including vendor, item etc
-- to admin" — a follow-up to FB-0004 (which did this for Item Type
-- Master), extending the same admin-only delete pattern to the other two
-- Master Data screens: Item Master (items) and Vendor Master (vendors).
--
-- items_write (0001_init.sql) and vendors_write are each a single `for
-- all` policy covering insert/update/delete for a few roles — the app
-- never exposed a delete action for either, so this was latent, unused.
-- Same treatment as 0008_item_type_delete_policy.sql: split each into
-- insert/update (unchanged roles) plus a new delete policy restricted to
-- system_admin alone — a deliberate tightening, not a loosening, and
-- matches the app-side checks in deleteItem() (lib/actions/items.ts) and
-- deleteVendor() (lib/actions/vendors.ts) so the two layers agree, per
-- the briefing's "app checks are UI-affordance only, RLS is the real
-- backstop" convention.
--
-- Standalone, additive migration (drops and recreates two policies; no
-- data or table-structure changes). Safe to re-run.
-- ============================================================

drop policy if exists items_write on public.items;

create policy items_insert on public.items for insert
  with check (public.has_any_role('system_admin','inventory_manager','mfr_manager'));

create policy items_update on public.items for update
  using (public.has_any_role('system_admin','inventory_manager','mfr_manager'))
  with check (public.has_any_role('system_admin','inventory_manager','mfr_manager'));

create policy items_delete on public.items for delete
  using (public.has_any_role('system_admin'));

drop policy if exists vendors_write on public.vendors;

create policy vendors_insert on public.vendors for insert
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy vendors_update on public.vendors for update
  using (public.has_any_role('system_admin','inventory_manager'))
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy vendors_delete on public.vendors for delete
  using (public.has_any_role('system_admin'));

-- ############################################################
-- ## 0010_mfr_finished_product_link.sql
-- ############################################################

-- ============================================================
-- "let MFR screen be entry point for Finished Product master list
-- creation. Each MFR be associated with one Finished Product and while
-- creating MFR, new finished product master entry be created with
-- automatic item code such as FP-00001. Remove access to create Finished
-- product master list from Item Master."
--
-- Links each MFR recipe to exactly one Finished Product item
-- (items.category = 'processed'). createMfrDefinition() now creates both
-- rows together — the items row (auto FP- code via get_next_item_code)
-- and the mfr_definitions row pointing at it — instead of the two being
-- created independently through two different screens. UNIQUE enforces
-- the 1:1 both ways: one MFR per finished product, one finished product
-- per MFR.
--
-- Nullable rather than NOT NULL: existing mfr_definitions rows, and any
-- 'processed' items already created directly through Item Master before
-- this change, predate this link and have no counterpart on the other
-- side. This migration doesn't touch or guess at pairing them up — it
-- only adds the column. Every *new* MFR created from here on always sets
-- it (enforced in the app, lib/actions/mfr.ts).
--
-- mfr_definitions.item_type_id (0001_init.sql) is intentionally NOT
-- dropped here — left in place, deprecated, simply unused by new code
-- going forward. The linked Finished Product item now carries its own
-- item_type_id, reached via finished_product_item_id, so duplicating it
-- on mfr_definitions would just be a second place for the same fact to
-- drift out of sync. Not dropping the column avoids losing whatever
-- values already exist on file for pre-existing rows.
-- ============================================================

alter table public.mfr_definitions
  add column finished_product_item_id uuid references public.items(id);

alter table public.mfr_definitions
  add constraint mfr_definitions_finished_product_item_id_key unique (finished_product_item_id);

-- ############################################################
-- ## 0011_mfr_delete_policy.sql
-- ############################################################

-- ============================================================
-- "give admin access to delete mfr as well along with all master data"
--
-- Extends the admin-only-delete pattern already applied to item_types
-- (0008_item_type_delete_policy.sql) and items/vendors
-- (0009_master_data_delete_policy.sql) to MFR: split the single
-- mfr_def_write "for all" policy into insert/update (unchanged roles:
-- system_admin, mfr_manager — same as canWrite(roles, "mfr")) plus a
-- delete policy restricted to system_admin only.
--
-- mfr_lines_write is NOT split here. mfr_lines rows are never deleted
-- directly by any Server Action — they're only removed via
-- `on delete cascade` off mfr_definitions (0001_init.sql) when an MFR
-- definition itself is deleted. The existing mfr_lines_write "for all"
-- policy already permits system_admin to do that (system_admin is in both
-- policies), so the cascade succeeds under RLS without any change here.
-- ============================================================

drop policy mfr_def_write on public.mfr_definitions;

create policy mfr_def_insert on public.mfr_definitions for insert
  with check (public.has_any_role('system_admin','mfr_manager'));

create policy mfr_def_update on public.mfr_definitions for update
  using (public.has_any_role('system_admin','mfr_manager'))
  with check (public.has_any_role('system_admin','mfr_manager'));

create policy mfr_def_delete on public.mfr_definitions for delete
  using (public.has_any_role('system_admin'));

-- ############################################################
-- ## 0012_peek_next_codes.sql
-- ############################################################

-- ============================================================
-- "Add vendor functionality should be available in the same screen as of
-- Vendor page. The next assigned vendor code should be visible in the add
-- vendor page" + "while adding new Item, next assigned Item Code should be
-- visible e.g. RM-00005"
--
-- Both get_next_item_code() and get_next_vendor_code() call nextval() —
-- calling either just to show a preview would burn a real code number
-- (sequences are non-transactional; a rolled-back or abandoned page load
-- would still permanently skip that number). These two functions instead
-- read the sequence's current state (last_value/is_called) without
-- advancing it, so the New Item / Add Vendor screens can show what code
-- WILL be assigned without consuming it.
--
-- Caveat, by design: this is a best-effort preview, not a reservation. If
-- two people load the form at the same time, both see the same next code,
-- but only one of them gets it — the actual value always still comes from
-- get_next_item_code()/get_next_vendor_code() (nextval) at insert time in
-- createItem()/createVendor(), so the assigned code is always correct and
-- unique even if the preview briefly went stale.
-- ============================================================

create or replace function public.peek_next_item_code(p_category text)
returns text language plpgsql stable as $$
declare
  v_num bigint;
  v_prefix text;
  v_seq regclass;
begin
  if p_category = 'packaging' then
    v_seq := 'public.item_code_seq_pkg'; v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_seq := 'public.item_code_seq_fp'; v_prefix := 'FP';
  else
    v_seq := 'public.item_code_seq_raw'; v_prefix := 'RM';
  end if;

  execute format(
    'select case when is_called then last_value + 1 else last_value end from %s',
    v_seq
  ) into v_num;

  return v_prefix || '-' || lpad(v_num::text, 5, '0');
end $$;

create or replace function public.peek_next_vendor_code()
returns text language sql stable as $$
  select 'V-' || lpad(
    (case when is_called then last_value + 1 else last_value end)::text,
    4, '0'
  )
  from public.vendor_code_seq;
$$;

-- ############################################################
-- ## 0013_batch_number_integrity.sql
-- ############################################################

-- ============================================================
-- Backstop for a race condition in purchase-line batch numbering, found
-- during a full-app integrity audit (1 Sept 2026, see
-- claude/known-issues.md).
--
-- get_next_batch_number(p_item_id) computes the next number with
-- `select count(*)+1 from purchase_lines where item_id=... and
-- to_char(created_at,'YY')=...` (0001_init.sql). The app then inserts the
-- purchase_lines row in a SEPARATE round trip (createPurchaseLine, added
-- alongside this migration to retry on conflict). Nothing serializes the
-- two calls: two people entering a purchase line for the same item on the
-- same day can both compute the same batch number and both save it —
-- silently duplicating a GMP-critical traceability field.
--
-- REVISED after the first attempt at a plain `unique (item_id,
-- batch_number)` failed to apply: it found a real, legitimate collision —
-- item 2e7da1cc-.../batch 'LEG-PR-40' — two genuinely different legacy
-- purchase lines (different POs, six months apart, different quantities)
-- that just happen to share the same free-text legacy batch code. That's
-- expected: legacy batch numbers are free text carried over from the old
-- SQL Server app with no uniqueness guarantee, and each already has a
-- linked inventory_ledger "push" row from the original import (on delete
-- restrict), so deleting either to force a full-table constraint through
-- would both very likely fail on that FK and, if forced anyway, would
-- quietly reduce that item's *current* computed stock-on-hand — a live
-- data change, not a historical cleanup. Not worth it for a code-quality
-- fix, and not necessary: the race this migration actually needs to close
-- only affects NEW, app-generated batch numbers (from get_next_batch_
-- number(), never 'LEG-' prefixed) — legacy numbers are written once at
-- import time and never again.
--
-- So this is a PARTIAL unique index instead of a table-wide constraint:
-- it only applies to batch numbers that don't start with 'LEG-', which
-- covers every future app-generated batch number while leaving all
-- historical legacy data (including any other such collisions that may
-- exist among the ~92,000 legacy rows, unchecked and untouched) alone.
-- Turns any FUTURE app-side collision into a loud, visible constraint
-- violation (23505) instead of a silent duplicate — which
-- lib/actions/purchase.ts now catches and retries (the retry recomputes
-- the batch number, which by then accounts for the row the other request
-- just inserted).
-- ============================================================

create unique index purchase_lines_item_batch_unique
  on public.purchase_lines (item_id, batch_number)
  where batch_number not like 'LEG-%';

-- ############################################################
-- ## 0014_fp_bmr_delete_policy.sql
-- ############################################################

-- ============================================================
-- Closes a gap found during a full-app integrity audit (1 Sept 2026, see
-- claude/known-issues.md): finished_product_batches and bmr_records were
-- never given the admin-only-delete treatment the other "master data /
-- record" tables (items, vendors, item_types, mfr_definitions) already
-- have — each still uses a single `for all` policy covering
-- insert/update/delete for the same role set. The app itself exposes no
-- delete UI for either table, but RLS is the real backstop (per the
-- project's "app checks are UI-affordance only" convention) — as it stood,
-- any inventory_manager/mfr_manager/quality_checker/qc_reviewer could
-- delete a finished-product batch or BMR record via a direct API call,
-- cascading away its component-consumption, weighment, and observation
-- history.
--
-- Same split-into-insert/update/delete pattern as
-- 0009_master_data_delete_policy.sql / 0011_mfr_delete_policy.sql: roles
-- that could already write keep insert/update; delete narrows to
-- system_admin only. Standalone, additive migration — drops and recreates
-- policies only, no data or table-structure changes. Safe to re-run.
-- ============================================================

drop policy if exists fp_write on public.finished_product_batches;

create policy fp_insert on public.finished_product_batches for insert
  with check (public.has_any_role('system_admin','mfr_manager','inventory_manager'));

create policy fp_update on public.finished_product_batches for update
  using (public.has_any_role('system_admin','mfr_manager','inventory_manager'))
  with check (public.has_any_role('system_admin','mfr_manager','inventory_manager'));

create policy fp_delete on public.finished_product_batches for delete
  using (public.has_any_role('system_admin'));

drop policy if exists bmr_write on public.bmr_records;

create policy bmr_insert on public.bmr_records for insert
  with check (public.has_any_role('system_admin','mfr_manager','quality_checker','qc_reviewer'));

create policy bmr_update on public.bmr_records for update
  using (public.has_any_role('system_admin','mfr_manager','quality_checker','qc_reviewer'))
  with check (public.has_any_role('system_admin','mfr_manager','quality_checker','qc_reviewer'));

create policy bmr_delete on public.bmr_records for delete
  using (public.has_any_role('system_admin'));

-- ############################################################
-- ## 0015_qc_duplicate_backstop.sql
-- ############################################################

-- ============================================================
-- Backstop for a check-then-insert race found during a full-app integrity
-- audit (1 Sept 2026, see claude/known-issues.md), present in both places
-- quality_checks rows get created:
--
--   - createQualityCheck() (lib/actions/qc.ts) reads purchase_batch_status
--     for the chosen purchase_line, and only inserts if it's still
--     'not_submitted'.
--   - submitFinishedProductToQc() (lib/actions/finished-product.ts) reads
--     the batch's status, and only inserts if it's still 'in_process'.
--
-- Both are two separate round trips (read, then insert) with nothing
-- serializing them — two concurrent submissions against the same
-- purchase_line or the same finished-product batch can both pass the
-- check and both insert, producing two AR numbers (and, for the RM side,
-- two automatic sample-pull ledger events) for what the app's own rules
-- say should be a single QC record per batch.
--
-- A unique constraint on each of the two "subject" columns is a correct
-- backstop, not an overreach: quality_checks already enforces (via a check
-- constraint, 0001_init.sql) that exactly one of purchase_line_id /
-- finished_product_batch_id is set per row, and both app paths above
-- already treat "one ever" as the rule (submitting again once a record
-- exists — approved, rejected, or still submitted — is already refused).
-- Postgres unique constraints allow unlimited NULLs, so RM-only rows
-- (finished_product_batch_id null) and FP-only rows (purchase_line_id
-- null) are both unaffected — only a genuine duplicate on the non-null
-- side is now rejected at the database level.
--
-- Standalone, additive migration. Should not fail on existing data: the
-- 31-assertion integrity check run during the sample data load already
-- confirmed no such duplicates exist in that data (claude/data-gap-
-- analysis.md), and both app code paths have refused re-submission since
-- day one — but if it does fail, stop and tell Claude the exact error
-- rather than editing/deleting rows yourself.
-- ============================================================

alter table public.quality_checks
  add constraint quality_checks_purchase_line_unique unique (purchase_line_id);

alter table public.quality_checks
  add constraint quality_checks_fp_batch_unique unique (finished_product_batch_id);

-- ############################################################
-- ## 0016_quantity_check_constraints.sql
-- ############################################################

-- ============================================================
-- Found during a full-app integrity audit (1 Sept 2026, see
-- claude/known-issues.md): only purchase_lines.quantity and
-- inventory_ledger.quantity have a database-level CHECK against
-- negative/zero values — every other quantity column relies entirely on
-- Server Action validation, so a direct PostgREST insert/update by an
-- otherwise-authorized role could silently corrupt yield/stock math
-- (mfr recipe ratios, actual_yield_pct, on-hand balances, etc).
--
-- All constraints below are added `not valid` deliberately: this means
-- Postgres does NOT scan/reject existing rows when the migration runs (so
-- it cannot fail or be blocked by historical legacy-imported or
-- synthesized-sample data that might already contain an edge-case 0 or
-- null), while still enforcing the check on every INSERT and UPDATE from
-- this point forward. Once you've had a chance to review whether any
-- existing rows would violate these (a query, not a change — ask Claude),
-- each can be flipped to fully validated with, e.g.:
--   alter table public.mfr_lines validate constraint mfr_lines_quantity_positive;
-- That's a separate, optional follow-up — not required for the constraint
-- to protect all future writes.
--
-- Where a field is nullable in the schema (wt_total_rm, wastage,
-- actual_qty), the check allows null and only constrains non-null values,
-- matching how the column is actually used today (e.g. wt_total_rm is
-- filled in once a batch is completed, not at creation).
-- ============================================================

alter table public.mfr_lines
  add constraint mfr_lines_quantity_positive check (quantity > 0) not valid;

alter table public.finished_product_components
  add constraint fp_components_quantity_positive check (quantity > 0) not valid;

alter table public.bmr_weighment_lines
  add constraint bmr_weighment_standard_qty_positive check (standard_qty > 0) not valid;
alter table public.bmr_weighment_lines
  add constraint bmr_weighment_actual_qty_nonnegative check (actual_qty is null or actual_qty >= 0) not valid;

alter table public.finished_product_batches
  add constraint fp_batches_target_qty_positive check (target_qty > 0) not valid;
alter table public.finished_product_batches
  add constraint fp_batches_wt_total_rm_nonnegative check (wt_total_rm is null or wt_total_rm >= 0) not valid;
alter table public.finished_product_batches
  add constraint fp_batches_wastage_nonnegative check (wastage is null or wastage >= 0) not valid;

alter table public.packaging_issues
  add constraint packaging_unit_count_positive check (unit_count > 0) not valid;
alter table public.packaging_issues
  add constraint packaging_qty_used_positive check (packaging_qty_used > 0) not valid;

-- ############################################################
-- ## 0017_feedback_owner_crud.sql
-- ############################################################

-- ============================================================
-- FB-0012 (1 Sept 2026): "there should be option to edit/delete the
-- feedback throughout the app" — a tester couldn't fix a typo or retract
-- their own submitted observation; 0004_feedback.sql only ever gave
-- system_admin write access past the initial insert.
--
-- Adds two new RLS policies alongside (not replacing) the existing
-- system_admin-only page_feedback_update/page_feedback_delete policies —
-- Postgres OR's multiple permissive policies together, so either the
-- admin path or this owner path can authorize a given statement.
--
-- Scoped to `status = 'new'` on purpose: once a ticket has been triaged
-- (category/status/notes set — see triageFeedback() in
-- lib/actions/feedback.ts), it's part of the project's record of what
-- was found and fixed (referenced from claude/known-issues.md,
-- feedback-status.md, commit messages, ...). Letting the original
-- submitter edit or delete it out from under that record after the fact
-- would be confusing at best. While it's still 'new' (untouched by triage)
-- it's entirely the tester's own note and safe to fix or retract freely.
--
-- RLS is row-level, not column-level: these policies only gate *which
-- rows* an owner's UPDATE/DELETE can touch, not *which columns* an
-- UPDATE may set. Column restriction (owners may only ever change
-- `observation`, never category/status/claude_notes) is enforced in
-- application code — updateOwnFeedback() in lib/actions/feedback.ts only
-- ever builds an update of `observation` — the same convention
-- triageFeedback()'s system_admin check already uses (app-level check,
-- RLS as the backstop), not a new pattern.
-- ============================================================

create policy page_feedback_owner_update on public.page_feedback
  for update
  using (submitted_by = auth.uid() and status = 'new')
  with check (submitted_by = auth.uid() and status = 'new');

create policy page_feedback_owner_delete on public.page_feedback
  for delete
  using (submitted_by = auth.uid() and status = 'new');

-- ############################################################
-- ## 0018_purchase_delete_policy.sql
-- ############################################################

-- ============================================================
-- FB-0015 ("admin should be able to delete purchase records") — extends
-- the same admin-only delete pattern already used for Item Type Master
-- (0008), Item/Vendor Master (0009), and MFR (0011) to Purchase.
--
-- po_write and pl_write (0001_init.sql) are each a single `for all`
-- policy covering insert/update/delete for system_admin + inventory_
-- manager — the app never exposed a delete action for either, so this
-- was latent, unused. Split each into insert/update (unchanged roles)
-- plus a new delete policy restricted to system_admin alone, matching
-- the app-side check in deletePurchaseOrder() (lib/actions/purchase.ts).
--
-- purchase_lines.purchase_order_id is `on delete cascade` (0001_init.sql)
-- — deleting a purchase_orders row cascade-deletes its purchase_lines
-- rows too. Postgres enforces RLS on the referencing table for a
-- cascaded delete same as a direct one, so pl_delete has to exist (and
-- allow system_admin) or an admin's PO delete would fail with a
-- permission error the moment it tried to cascade into purchase_lines —
-- there is deliberately no standalone "delete one purchase line" UI
-- action, this policy only exists to let the PO-level cascade through.
--
-- quality_checks.purchase_line_id, finished_product_components.
-- purchase_line_id, bmr_weighment_lines.purchase_line_id, and inventory_
-- ledger.purchase_line_id all reference purchase_lines(id) with no
-- cascade/nullify of their own (0001_init.sql) — so once any line in a
-- PO has been QC'd, consumed by MFR/BMR, or has ledger activity, the
-- cascade hits a foreign-key violation (23503) and the whole delete is
-- rolled back. deletePurchaseOrder() translates that into a friendly
-- message rather than a raw DB error, same convention as deleteItem().
-- This means only a PO that's genuinely untouched downstream (a mistaken
-- entry, the actual use case in the ticket) can ever be deleted — exactly
-- the same safety property the item/vendor/MFR deletes already have.
--
-- Standalone, additive migration (drops and recreates two policies; no
-- data or table-structure changes). Safe to re-run.
-- ============================================================

drop policy if exists po_write on public.purchase_orders;

create policy po_insert on public.purchase_orders for insert
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy po_update on public.purchase_orders for update
  using (public.has_any_role('system_admin','inventory_manager'))
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy po_delete on public.purchase_orders for delete
  using (public.has_any_role('system_admin'));

drop policy if exists pl_write on public.purchase_lines;

create policy pl_insert on public.purchase_lines for insert
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy pl_update on public.purchase_lines for update
  using (public.has_any_role('system_admin','inventory_manager'))
  with check (public.has_any_role('system_admin','inventory_manager'));

create policy pl_delete on public.purchase_lines for delete
  using (public.has_any_role('system_admin'));

-- ############################################################
-- ## 0019_purchase_submit_workflow.sql
-- ############################################################

-- ============================================================
-- FB-0018 ("there should be a final submit button post which the record
-- should be committed. Before that all users should have access to
-- review/edit entered record.") — draft/submit workflow for Purchase.
--
-- Design decisions confirmed with Ravi 2 Sept 2026:
--  1. A draft PO's lines do NOT push to inventory at all — only Final
--     Submit pushes everything at once. (Today, trg_purchase_line_push
--     pushes the instant a line is inserted — see 0002_transactions.sql —
--     which is also why a PO with any line can't be cleanly deleted; see
--     claude/known-issues.md "Fourth pass".)
--  2. Once submitted, a normal write-role user (system_admin,
--     inventory_manager — same as "purchase" write today) can no longer
--     edit/delete its lines. system_admin alone can Reopen it, which
--     reverses whatever was pushed (via a compensating ledger entry, never
--     by deleting/editing the original — inventory_ledger is an audit
--     trail) and puts it back in draft.
--  3. Final Submit is whole-PO, not per-line.
--
-- purchase_orders/purchase_lines already existed with ~92k legacy rows and
-- real inventory_ledger activity behind every one of them (pushed either
-- by the old trigger or by whatever loaded the legacy dataset) — so this
-- migration explicitly backfills every EXISTING row to 'submitted'/
-- 'pushed' before the new 'draft' default takes effect for anything
-- created after this runs. Getting this backfill wrong would either
-- silently re-push ~92k lines' worth of stock (if left as draft and
-- someone hit Submit) or hide every existing batch from QC/BMR/Wastage/
-- Finished-Product/Labels pickers (once those are filtered to
-- submitted-only, in the same app deploy as this migration).
-- ============================================================

-- ------------------------------------------------------------
-- 1. New columns — nullable first, so existing rows get backfilled
--    explicitly rather than picking up whatever default is added later.
-- ------------------------------------------------------------
alter table public.purchase_orders
  add column status text,
  add column submitted_at timestamptz,
  add column submitted_by uuid references auth.users(id),
  add column reopened_at timestamptz,
  add column reopened_by uuid references auth.users(id);

alter table public.purchase_lines
  add column pushed_at timestamptz;

-- ------------------------------------------------------------
-- 2. Backfill: every purchase order that already exists predates this
--    feature and is treated as already submitted, as of when it was
--    created. Every purchase line that already has a 'push' ledger row
--    is marked pushed as of when that row was written. A line with
--    remaining_qty = 0 never got a ledger row in the first place (the old
--    trigger's own `if new.remaining_qty > 0` guard, see
--    0002_transactions.sql) — pushed_at correctly stays NULL for those;
--    there's nothing to reverse for them if their PO is ever reopened.
-- ------------------------------------------------------------
update public.purchase_orders set status = 'submitted', submitted_at = created_at;

update public.purchase_lines pl
set pushed_at = il.event_at
from public.inventory_ledger il
where il.purchase_line_id = pl.id
  and il.event_type = 'push'
  and il.reference_type = 'purchase'
  and pl.pushed_at is null;

-- ------------------------------------------------------------
-- 3. Now that every existing row has an explicit status, make it
--    required and default new rows to 'draft'.
-- ------------------------------------------------------------
alter table public.purchase_orders
  alter column status set not null,
  alter column status set default 'draft',
  add constraint po_status_check check (status in ('draft', 'submitted'));

-- ------------------------------------------------------------
-- 4. Stop pushing to inventory the instant a line is inserted. Pushing
--    now happens only inside submit_purchase_order() below, once, for
--    the whole PO. The function is left in place (unused) rather than
--    dropped, in case anything still references it.
-- ------------------------------------------------------------
drop trigger if exists trg_purchase_line_push on public.purchase_lines;

-- ------------------------------------------------------------
-- 5. Final Submit — pushes every not-yet-pushed line on the PO in one
--    transaction, then flips the PO to 'submitted'. SECURITY DEFINER so
--    it can write inventory_ledger despite its "no direct write" policy
--    (ledger_no_direct_write, 0001_init.sql) — same pattern as every
--    other ledger-writing function in 0002_transactions.sql. Row-locks
--    the PO first (`for update`) so two concurrent submits on the same
--    PO can't both push.
-- ------------------------------------------------------------
create or replace function public.submit_purchase_order(p_po_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_status text;
begin
  if not public.has_any_role('system_admin', 'inventory_manager') then
    raise exception 'Not authorized.';
  end if;

  select status into v_status from public.purchase_orders where id = p_po_id for update;
  if v_status is null then
    raise exception 'Purchase order not found.';
  end if;
  if v_status <> 'draft' then
    raise exception 'This purchase order has already been submitted.';
  end if;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'push', pl.item_id, pl.id, pl.remaining_qty, pl.unit, 'purchase', pl.id, auth.uid()
  from public.purchase_lines pl
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is null
    and pl.remaining_qty > 0;

  update public.purchase_lines
  set pushed_at = now()
  where purchase_order_id = p_po_id and pushed_at is null;

  update public.purchase_orders
  set status = 'submitted', submitted_at = now(), submitted_by = auth.uid()
  where id = p_po_id;
end $$;

-- ------------------------------------------------------------
-- 6. Reopen (system_admin only) — reverses every line this PO actually
--    pushed with a compensating 'pull' of the SAME quantity that was
--    originally pushed (read back from the ledger row itself, not the
--    line's current remaining_qty, so it's exact even if the line gets
--    edited before a later resubmit). The original 'push' row is never
--    deleted or edited — inventory_ledger is an audit trail — this just
--    nets its effect back to zero. Then clears pushed_at so a later
--    Final Submit re-pushes with whatever the lines say at that time,
--    and flips the PO back to 'draft'.
-- ------------------------------------------------------------
create or replace function public.reopen_purchase_order(p_po_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_status text;
begin
  if not public.has_any_role('system_admin') then
    raise exception 'Not authorized.';
  end if;

  select status into v_status from public.purchase_orders where id = p_po_id for update;
  if v_status is null then
    raise exception 'Purchase order not found.';
  end if;
  if v_status <> 'submitted' then
    raise exception 'This purchase order is not currently submitted.';
  end if;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', il.item_id, il.purchase_line_id, il.quantity, il.unit, 'purchase', il.purchase_line_id, auth.uid()
  from public.inventory_ledger il
  join public.purchase_lines pl on pl.id = il.purchase_line_id
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is not null
    and il.event_type = 'push'
    and il.reference_type = 'purchase'
    and il.reference_id = il.purchase_line_id;

  update public.purchase_lines
  set pushed_at = null
  where purchase_order_id = p_po_id and pushed_at is not null;

  update public.purchase_orders
  set status = 'draft', reopened_at = now(), reopened_by = auth.uid()
  where id = p_po_id;
end $$;

-- Note: po_update/pl_update (0018_purchase_delete_policy.sql) already let
-- system_admin/inventory_manager update any column of purchase_orders/
-- purchase_lines directly, same as before this migration — the app itself
-- only ever changes `status` through the two functions above (never a
-- raw .update() on status from client code), consistent with the trust
-- already placed in those two roles for every other write in this app
-- (e.g. they could already update qc_qty directly, bypassing FB-0017's
-- conversion logic, if they chose to call the API by hand).

-- ############################################################
-- ## 0020_qc_sample_pull_unit_fix.sql
-- ############################################################

-- ============================================================
-- Bugfix (2 Sept 2026) — QC sample pull wrote inventory_ledger in the
-- SAMPLE unit, not the item's own unit, silently corrupting stock_balance.
--
-- Found live by Ravi: Jatamansi (RM-00002) showed -32.75 kg on hand
-- ("stock should never go negative"). Root cause traced to
-- trg_fn_qc_sample_pull() (0002_transactions.sql, part B): it inserts
-- new.sample_qty / new.sample_unit into inventory_ledger verbatim, with NO
-- conversion into the item's own tracked unit. stock_balance
-- (0001_init.sql) is a plain `sum(quantity)` over inventory_ledger — it
-- has no idea what `unit` means, it just adds/subtracts the raw number.
-- Every OTHER event-writing trigger already only ever writes in the
-- item's/line's own unit (push: purchase_lines.unit; FP/packaging pulls:
-- the consuming table's own quantity, already in that unit) — QC sample
-- pull was the one place this could drift, and it only actually bit today
-- because FB-0018/0019/0020/0021's QC sample-unit auto-populate
-- (qc-assign-form.tsx) made picking a genuinely different, smaller sample
-- unit than the line's own unit the normal case rather than a rare one.
--
-- The immediate trigger for today's -32.75: one QC record was saved with
-- sample_qty=50, sample_unit='gm' — 'gm' is not a canonical unit
-- (lib/constants/units.ts only knows 'g'; 'gm' is a common free-text
-- variant a person would naturally type). The Sample unit field on
-- qc-assign-form.tsx has always been a free-text <Input>, not a <Select>
-- restricted to a known unit — that gap is fixed in the same app deploy as
-- this migration (Sample unit is now a <Select> over compatibleUnits(),
-- same pattern Purchase's own Sample unit field already used per FB-0017).
-- This migration is the DB-side half: even with the UI fixed, the trigger
-- itself should never again be able to write a ledger row in anything but
-- the item's own tracked unit — belt and suspenders, matching how every
-- other ledger-writing trigger already behaves.
-- ============================================================

-- ------------------------------------------------------------
-- 1. SQL-side unit conversion, mirroring lib/constants/units.ts exactly
--    (weight family mg/g/kg, volume family ml/ltr; every other unit is its
--    own one-member family — count/bottle/pack can only convert to
--    themselves). Returns null when the two units aren't in the same
--    family, exactly like the TS convertUnit() contract, so callers can
--    detect and handle an incompatible pair rather than getting a wrong
--    number silently. from = to always short-circuits to the input value
--    unchanged, even for a unit string outside the two known families —
--    this matters below, where a null/legacy sample_unit is treated as
--    "already in the target unit" and must pass through as-is.
-- ------------------------------------------------------------
create or replace function public.convert_unit(p_value numeric, p_from text, p_to text)
returns numeric language plpgsql immutable as $$
declare
  v_factor_from numeric;
  v_factor_to numeric;
begin
  if p_from = p_to then
    return p_value;
  end if;

  v_factor_from := case p_from
    when 'mg' then 0.001 when 'g' then 1 when 'kg' then 1000
    when 'ml' then 1 when 'ltr' then 1000
    else null
  end;
  v_factor_to := case p_to
    when 'mg' then 0.001 when 'g' then 1 when 'kg' then 1000
    when 'ml' then 1 when 'ltr' then 1000
    else null
  end;

  -- Both units must resolve to a factor AND belong to the same family
  -- (weight factors are grams-per-unit, volume factors are ml-per-unit —
  -- comparing across families would silently produce a nonsense number,
  -- so require both to be in {mg,g,kg} or both in {ml,ltr}).
  if v_factor_from is null or v_factor_to is null then
    return null;
  end if;
  if (p_from in ('mg','g','kg')) <> (p_to in ('mg','g','kg')) then
    return null;
  end if;

  return (p_value * v_factor_from) / v_factor_to;
end $$;

-- ------------------------------------------------------------
-- 2. Fix the trigger: convert into the purchase line's own unit (the same
--    unit its corresponding 'push' row used) before writing to
--    inventory_ledger, instead of writing sample_unit verbatim.
--    quality_checks.sample_qty/sample_unit themselves are UNCHANGED by
--    this fix and keep recording exactly what was actually sampled, in
--    whatever unit was convenient at the time (e.g. a QC certificate
--    legitimately says "50 g sample taken") — that's a deliberate
--    difference from Purchase's qc_qty (which stores already-converted,
--    with no separate "as entered" unit kept at all). Only the ledger
--    write — which must share one consistent per-item unit for
--    stock_balance's raw sum to mean anything — needs converting.
--    A null/legacy sample_unit falls back to "already in the line's own
--    unit" (matches the pre-FB-0021 behavior, when sample_unit always
--    equaled the line's unit and no conversion was ever needed). A
--    genuinely incompatible pair now fails loudly instead of silently
--    corrupting the ledger.
-- ------------------------------------------------------------
create or replace function public.trg_fn_qc_sample_pull()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_line_unit text;
  v_from_unit text;
  v_converted numeric;
begin
  if new.purchase_line_id is not null and coalesce(new.sample_qty, 0) > 0 then
    select unit into v_line_unit from public.purchase_lines where id = new.purchase_line_id;
    v_from_unit := coalesce(new.sample_unit, v_line_unit);
    v_converted := public.convert_unit(new.sample_qty, v_from_unit, v_line_unit);
    if v_converted is null then
      raise exception 'Cannot record QC sample pull: sample unit "%" is not convertible to this batch''s unit "%".',
        v_from_unit, v_line_unit;
    end if;

    insert into public.inventory_ledger
      (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('pull', new.item_id, new.purchase_line_id, v_converted, v_line_unit, 'qc', new.id, auth.uid());
  end if;
  return new;
end $$;

-- ------------------------------------------------------------
-- 3. One-time data correction for the single QC record already affected
--    (AR record for purchase_line_id 1bfc6a85-4e61-4c1e-8c49-66e54bc35a60,
--    Jatamansi RM-00002, batch RM-01/26). The original ledger row
--    (id 8bf46f6a-afa5-4ebe-96e6-0226c5f03eae, quantity 50, unit 'gm') is
--    left exactly as it was written — inventory_ledger is an append-only
--    audit trail, never edited/deleted, same principle as Reopen's
--    compensating pull in 0019. Instead, a new compensating 'push' entry
--    cancels its wrong effect on stock_balance's unit-blind raw sum: the
--    bad row was counted as -50 (raw), when the true pull was -0.05 kg
--    (50 gm); +49.95 kg brings the running total back to the correct
--    5.5 + 11.80 - 0.05 - 0.05 = 17.20 kg. Timestamped now() (when this
--    correction is actually applied), not backdated — an honest new
--    entry, not a rewrite of history. event_by is left null: this runs as
--    a migration, not inside an authenticated request, so auth.uid() has
--    nothing to resolve.
--
--    Identifies the bad row by its actual characteristics (item, batch,
--    event_type/quantity/unit, reference_type) rather than its own `id` —
--    an earlier version of this migration mistakenly matched on
--    `inventory_ledger.id = <value>` using a value that was actually the
--    row's `reference_id` (the linked quality_checks.id), never its own
--    `id`, which was never queried. That guard silently matched nothing,
--    so the correction insert ran but affected zero rows (Postgres
--    reports this identically to a real no-op insert — "Success. No rows
--    returned" either way, which is what made the mistake easy to miss
--    live). Fixed here to match on content rather than an unverified id,
--    and confirmed live 2 Sept 2026: this produced exactly the expected
--    single row, and Jatamansi's Stock Balance read back as 17.2 kg / OK
--    immediately after.
-- ------------------------------------------------------------
insert into public.inventory_ledger
  (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
select
  'push',
  bad.item_id,
  bad.purchase_line_id,
  49.95,
  'kg',
  'qc',
  bad.reference_id,
  null
from public.inventory_ledger bad
join public.items i on i.id = bad.item_id
where i.item_code = 'RM-00002'
  and bad.event_type = 'pull'
  and bad.quantity = 50
  and bad.unit = 'gm'
  and bad.reference_type = 'qc'
  and not exists (
    -- Idempotency guard: never double-apply this specific correction if
    -- the migration is somehow run twice.
    select 1 from public.inventory_ledger existing
    where existing.item_id = bad.item_id
      and existing.quantity = 49.95
      and existing.unit = 'kg'
      and existing.reference_id = bad.reference_id
  );

-- ############################################################
-- ## 0021_fp_stability_rnd_qty.sql
-- ############################################################

-- ============================================================
-- Finished Product — Stability qty / R&D qty capture (2 Sept 2026)
--
-- Raw Material / Packaging has captured QC + Stability + R&D quantity
-- together, per purchase line, since FB-0007/FB-0017. Finished Product
-- never had a Stability/R&D equivalent — finished_product_batches only
-- had `qc_sample_qty`, captured on the Complete Batch screen
-- (complete-batch-form.tsx) with no unit-conversion support at all (it
-- was always assumed to already be in the batch's own `unit`).
--
-- Per direct request ("QC sample quantity will remain in complete batch
-- screen along with Yield, Stability Sample, R&D Sample and sample
-- unit"): two new nullable columns, additive only — no existing data is
-- touched, no backfill, no constraint tightened. Existing batches simply
-- have stability_qty/rnd_qty = null until someone fills them in.
--
-- Same storage convention as purchase_lines.qc_qty/stability_qty/
-- rnd_qty: the app-layer converts whatever "sample unit" the person
-- entered these in down to the batch's own `unit` before saving (see
-- completeFinishedProductBatch() in lib/actions/finished-product.ts,
-- using the same convertUnit() as Purchase/QC) — no separate "as
-- entered" unit column is kept here, deliberately, matching
-- purchase_lines rather than quality_checks (see 0020's comment for why
-- those two tables made opposite choices).
-- ============================================================
alter table public.finished_product_batches
  add column if not exists stability_qty numeric,
  add column if not exists rnd_qty numeric;

-- ############################################################
-- ## 0022_fp_batch_yield.sql
-- ############################################################

-- ============================================================
-- Finished Product — replace wt_total_rm/net_weight with a manually
-- entered Batch Yield (2 Sept 2026)
--
-- Per direct request: "Total Weight of RM used is incorrect and should
-- be removed from app and database... after each new batch is created,
-- Batch Yield needs to be entered manually basis on how much Finished
-- Product has been created. The unit will be same as of unit of
-- Finished product item." Confirmed destructive and explicitly OK'd —
-- this environment is test data, not live ("we are working on test
-- data so its ok to drop any data available. we are in testing phase
-- and not live").
--
-- This is the one migration this session that's genuinely destructive:
-- wt_total_rm held real values on 7 legacy-imported batches (30 kg,
-- 125 kg, 69.6 kg, etc.), and net_weight/actual_yield_pct were both
-- GENERATED columns computed from wt_total_rm and wastage — Postgres
-- can't drop a column that a generated column still depends on, so the
-- generated columns have to go first, then the column they depended on.
--
-- net_weight has no replacement — there's no longer a coherent "RM
-- weight in, minus wastage" concept once wt_total_rm is gone, and
-- nothing asked for one. actual_yield_pct IS kept, but redefined:
-- instead of (wt_total_rm - wastage) / wt_total_rm, it's now
-- batch_yield / target_qty — a much simpler, directly meaningful
-- number ("how much finished product actually came out, as a
-- percentage of what was targeted"). Every other reader of
-- actual_yield_pct (finished-product list, reports, this detail page)
-- needs no code change — same column name, same numeric type, just a
-- different (simpler, more honest) formula behind it.
--
-- net_qty was left alone by 0010 (removed from the Complete Batch form,
-- but not from the database, since dropping it wasn't asked for at the
-- time) — per a same-thread follow-up ("remove net_qty if unused"), it's
-- dropped here too. It was NOT actually unused, though: app/(dashboard)/
-- labels/page.tsx was still reading net_qty (falling back to total_units)
-- as the printed quantity on Finished Product labels — a real, working
-- consumer that patch 0010 silently broke going forward (any batch
-- completed after 0010 would print a blank/wrong label quantity, since
-- nothing filled net_qty/total_units anymore) without anyone noticing
-- until this migration's impact check caught it. Fixed in the same
-- change: labels/page.tsx now reads batch_yield instead, which is
-- exactly the "how much Finished Product came out of this batch" value
-- Labels actually needs. wastage and total_units are similarly unused
-- since 0010 but were NOT named in either request — left in place;
-- worth a follow-up if the same cleanup is wanted for those (checked:
-- neither has any other reader left in app/ or lib/).
-- ============================================================

alter table public.finished_product_batches drop column if exists net_weight;
alter table public.finished_product_batches drop column if exists actual_yield_pct;
alter table public.finished_product_batches drop column if exists wt_total_rm;
alter table public.finished_product_batches drop column if exists net_qty;

alter table public.finished_product_batches add column if not exists batch_yield numeric;

alter table public.finished_product_batches add column actual_yield_pct numeric generated always as (
  case when target_qty > 0 and batch_yield is not null
    then round(batch_yield / target_qty * 100, 2)
  end
) stored;

-- ############################################################
-- ## 0023_packaging_purchase_batch_prefix.sql
-- ############################################################

-- ============================================================
-- Packaging items are now purchasable (2 Sept 2026)
--
-- Per direct request: "In Purchase Screen - there should be option to
-- choose Purchase Raw Material or Packaging Item. For Packaging Item, no
-- need to capture QC, R&D or Stability Sample." Until now, /purchase only
-- ever offered category='raw' items — there was no way to buy more
-- packaging stock through the app at all (Packaging Issue only ever
-- consumed existing stock; packaging items' only inventory came from the
-- legacy import's opening balances). The app-side change adds a Raw
-- Material / Packaging Item toggle to the Add-line and Edit-line forms and
-- hides QC/Stability/R&D/Sample-unit capture for packaging lines entirely
-- (no schema change needed there — qc_qty/stability_qty/rnd_qty already
-- default to 0 server-side when the form doesn't send them).
--
-- This migration covers the one thing that DOES need a DB-side change:
-- get_next_batch_number(p_item_id) (0001_init.sql) hard-coded the 'RM-'
-- prefix on every batch number it generated, regardless of the item's
-- category — a packaging purchase would have been assigned a batch number
-- like "RM-01/26", which is wrong and inconsistent with the item-code
-- convention already in place (items.item_code uses RM-/PKG-/FP- per
-- category, see get_next_item_code() in 0007_item_code_fp_and_sample_
-- unit.sql). Rewritten to look up the item's category and prefix
-- accordingly: 'PKG-' for packaging, 'RM-' for everything else (raw is
-- the only other category ever purchased here — processed/Finished
-- Product items never go through Purchase).
--
-- Purely a function replace — no data migration, nothing destructive.
-- purchase_lines_item_batch_unique (0013_batch_number_integrity.sql) is
-- keyed on (item_id, batch_number) regardless of prefix, so this doesn't
-- affect that constraint or the per-item/year counting logic at all, only
-- the label.
-- ============================================================

create or replace function public.get_next_batch_number(p_item_id uuid)
returns text language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_category text;
  v_prefix text;
begin
  select category into v_category from public.items where id = p_item_id;
  v_prefix := case when v_category = 'packaging' then 'PKG' else 'RM' end;

  select count(*) + 1 into v_n from public.purchase_lines
  where item_id = p_item_id and to_char(created_at, 'YY') = v_year;

  return v_prefix || '-' || lpad(v_n::text, 2, '0') || '/' || v_year;
end $$;

-- ############################################################
-- ## 0024_purchase_lines_currency_retest.sql
-- ############################################################

-- ============================================================
-- Purchase lines: Re-Test Date optional for packaging (2 Sept 2026)
--
-- Per direct request, following on from Packaging Item purchases
-- (0023_packaging_purchase_batch_prefix.sql): "No need to show 'Expiry
-- Date' for Packaging Products. For Raw Material Rename Expiry Date to
-- Re-Test Date." The Purchase Add-line/Edit-line forms (purchase-
-- line-form.tsx) now only render this field for raw material lines, and
-- lib/actions/purchase.ts enforces it server-side as required for raw
-- material / not applicable for packaging by looking up the item's real
-- category — but the underlying column was `date not null`, which would
-- reject a packaging line's insert outright, so the constraint has to
-- move first.
--
-- Purely a loosened constraint (not null -> nullable) — additive/safe,
-- no data touched. Every existing row (all raw material to date) already
-- has a real date, so nothing here changes what's on file.
-- ============================================================

alter table public.purchase_lines alter column expiry_date drop not null;

-- ############################################################
-- ## 0025_qc_retest_workflow.sql
-- ############################################################

-- ============================================================
-- Part B of the "Re-Test" feature (see claude/known-issues.md, Eighth
-- pass): "Once Re-Test date has come, Item should go through QC again
-- using the stability sample already available."
--
-- The trigger for this workflow is quality_checks.retest_date — the
-- QC-computed column already populated by trg_fn_qc_compute_retest_date
-- (reviewed_at + retest_period_days, 0001_init.sql) and already surfaced
-- on the Dashboard's "Retest due soon" card, the QC list/detail pages,
-- Labels, and the QC Register report. It is NOT purchase_lines.expiry_date
-- (the hand-entered field renamed "Re-Test Date" on the Purchase screen
-- in Part A) — that field stays a purchase-time reference value and is
-- untouched by this migration. Confirmed with the user via AskUserQuestion
-- before building this.
--
-- A genuine retest cycle means a second (third, ...) quality_checks row
-- against the same purchase_line_id, dated later, pulling from the
-- stability_qty already reserved at Purchase time (fp_stability_rnd_qty,
-- 0021) rather than a fresh sample pull — trg_fn_qc_sample_pull
-- (0002_transactions.sql) already logs an inventory_ledger 'pull' event
-- for ANY quality_checks insert with purchase_line_id set and sample_qty
-- > 0, so inserting sample_qty = stability_qty is enough; no trigger
-- changes are needed. purchase_batch_status's lateral join (0001_init.sql,
-- "order by created_at desc limit 1") already returns the latest QC row's
-- qc_status/retest_date/ar_number per line, so it already supports
-- multiple historical rows with zero view changes.
--
-- The one real blocker: quality_checks_purchase_line_unique
-- (0015_qc_duplicate_backstop.sql) permits at most one quality_checks row
-- ever per purchase_line_id, which was correct before this feature existed
-- (it was a backstop against a check-then-insert race, not a deliberate
-- "one QC per batch, forever" rule) but now conflicts with the whole
-- point of a retest history. Replacing it with a partial unique index
-- scoped to status = 'submitted' preserves the original invariant this
-- codebase actually needs — no two concurrent *unreviewed* QC records
-- against the same batch — while allowing unlimited reviewed
-- (approved/rejected) rows to accumulate as dated history. Partial unique
-- indexes are an established idiom here (0013_batch_number_integrity.sql
-- excludes LEG- rows the same way).
--
-- is_retest flags which quality_checks rows came from this new workflow
-- (vs. the original Purchase -> QC assignment), so the UI can show a
-- "(Retest)" indicator without having to infer it from row order.
-- Additive, nullable-default column — no backfill needed, existing rows
-- default to false (correctly: they are all original assignments).
--
-- `drop constraint if exists`, not a bare `drop constraint`: running this
-- against the live project (2 Sept 2026) surfaced that
-- quality_checks_purchase_line_unique never actually existed there —
-- 0015_qc_duplicate_backstop.sql's *other* constraint
-- (quality_checks_fp_batch_unique) is present, but its purchase_line_id
-- twin apparently failed silently when 0015 was originally run and was
-- never caught (the app-level check-then-insert in createQualityCheck()
-- masked the gap — no observed incident). `if exists` makes this
-- migration a correct no-op for that half on a project where it's
-- already missing, and still drops it cleanly on one where 0015 ran in
-- full.
-- ============================================================

alter table public.quality_checks
  drop constraint if exists quality_checks_purchase_line_unique;

create unique index if not exists quality_checks_purchase_line_pending_unique
  on public.quality_checks (purchase_line_id)
  where status = 'submitted';

alter table public.quality_checks
  add column if not exists is_retest boolean not null default false;

-- ############################################################
-- ## 0026_qc_retest_consumption_gate.sql
-- ############################################################

-- "Only QC Approved batches can be used for making finished product" (Ravi,
-- 3 Sept 2026) — check_batch_qc_approved() (0001_init.sql) already gates
-- both finished_product_components (Finished Product composition) and
-- bmr_weighment_lines (BMR weighment) on the batch being QC-Approved, but it
-- never checked whether that approval's retest date has since passed. A
-- batch sitting in "Awaiting Retest" (quality_checks.retest_date <= today,
-- see 0025_qc_retest_workflow.sql) was still, silently, fully usable.
--
-- Extends the same trigger function both consumption points already share,
-- so this one change closes the gap identically everywhere it applies —
-- consistent with this app's existing "not just discouraged, impossible"
-- enforcement style (DESIGN.md §7.2). Separate exception messages for the
-- two rejection reasons, rather than one generic message, so a blocked
-- attempt tells the operator which of the two problems it actually is.
create or replace function public.check_batch_qc_approved()
returns trigger language plpgsql as $$
declare
  v_status public.purchase_batch_status%rowtype;
begin
  select * into v_status
  from public.purchase_batch_status
  where purchase_line_id = new.purchase_line_id;

  if v_status.qc_status is distinct from 'approved' then
    raise exception 'Batch (purchase_line_id=%) is not QC-Approved and cannot be consumed', new.purchase_line_id;
  end if;

  if v_status.retest_date is not null and v_status.retest_date <= current_date then
    raise exception 'Batch (purchase_line_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
      new.purchase_line_id, v_status.retest_date;
  end if;

  return new;
end $$;
-- Both trg_fp_component_qc_gate (finished_product_components) and
-- trg_bmr_weighment_qc_gate (bmr_weighment_lines) already point at this
-- function by name — no trigger changes needed, `create or replace` alone
-- picks this up for both.

-- ############################################################
-- ## 0027_packaging_multi_material.sql
-- ############################################################

-- "In packaging allow selection of multiple packaging materials such as
-- bottles, caps etc. Each material can have a different unit/quantity."
-- (Ravi, 3 Sept 2026) — packaging_issues (0001_init.sql) modeled one issue
-- as exactly one packaging_item_id + packaging_qty_used, so a single "Pack"
-- event could never record e.g. bottles AND caps AND labels together; the
-- old flow needed a separate issue per material, with no shared context
-- tying them to the same packing run.
--
-- New child table, same header/lines shape already used for MFR recipe
-- lines and Finished Product composition (finished_product_components):
-- packaging_issues stays the one row per packing event (FP batch, pack
-- size, unit count, department, transaction type); packaging_issue_items
-- becomes one row per material actually used on that event, each with its
-- own quantity and unit.
create table public.packaging_issue_items (
  id uuid primary key default gen_random_uuid(),
  packaging_issue_id uuid not null references public.packaging_issues(id) on delete cascade,
  item_id uuid not null references public.items(id),
  quantity numeric not null check (quantity > 0),
  unit text not null,
  created_at timestamptz not null default now()
);
alter table public.packaging_issue_items enable row level security;
create policy packaging_issue_items_select on public.packaging_issue_items for select using (public.is_signed_in());
-- Same write-role set as packaging_insert (packaging_issues) — a material
-- line is only ever created alongside its parent issue by the same action.
create policy packaging_issue_items_insert on public.packaging_issue_items for insert
  with check (public.has_any_role('system_admin','inventory_manager','mfr_manager'));

-- Backfill every existing packaging_issues row into the new shape as its
-- own one-material line, so history isn't lost. There was never a captured
-- unit for packaging_qty_used (trg_fn_packaging_pull's ledger insert below
-- didn't set one either — see the fix in that function) — the item's own
-- Item Master unit is the closest available truth and is used here as a
-- best-effort default; it does not change what was actually recorded, only
-- how it's now represented.
insert into public.packaging_issue_items (packaging_issue_id, item_id, quantity, unit, created_at)
select pi.id, pi.packaging_item_id, pi.packaging_qty_used, coalesce(it.unit, 'count'), pi.created_at
from public.packaging_issues pi
join public.items it on it.id = pi.packaging_item_id
where pi.packaging_item_id is not null and pi.packaging_qty_used is not null;

-- packaging_issues.packaging_item_id / packaging_qty_used are no longer
-- written by the app going forward (material lines live in the new table
-- instead) — dropped to nullable rather than dropped outright, so every
-- existing row keeps its original single-material value on file untouched.
-- packaging_qty_used_positive (0016_quantity_check_constraints.sql, "> 0")
-- needs no change: a CHECK constraint passes automatically on a null value.
alter table public.packaging_issues alter column packaging_item_id drop not null;
alter table public.packaging_issues alter column packaging_qty_used drop not null;

-- trg_fn_packaging_pull (0002_transactions.sql) used to do two things off
-- one packaging_issues row: pull packaging_item_id/packaging_qty_used from
-- stock, and bump finished_product_batches.packaged_qty. With material
-- lines now living in their own table (and there possibly being several
-- per issue), the stock pull moves to a new trigger on
-- packaging_issue_items — one pull per material line — while the
-- packaged_qty bump stays here, still exactly once per issue regardless of
-- how many materials it has.
create or replace function public.trg_fn_packaging_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.finished_product_batches
    set packaged_qty = packaged_qty +
      case new.transaction_type when 'unpack' then -new.unit_count else new.unit_count end
    where id = new.finished_product_batch_id;
  return new;
end $$;
-- trg_packaging_pull (after insert on packaging_issues) already points at
-- this function by name — create or replace alone picks up the new body,
-- no trigger redefinition needed.

-- New trigger: one ledger 'pull' per packaging_issue_items row, using that
-- row's own item/quantity/unit. Also closes a pre-existing gap in the
-- function this replaces: the old ledger insert never set a `unit` at all
-- (packaging_issues had no unit column to read one from) — every packaging
-- pull's ledger row has always had unit = null. That's now fixed for every
-- new pull, since packaging_issue_items.unit is not null.
create or replace function public.trg_fn_packaging_item_pull()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_department text;
begin
  select department into v_department
  from public.packaging_issues
  where id = new.packaging_issue_id;

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', new.item_id, new.quantity, new.unit, v_department, 'packaging', new.packaging_issue_id, auth.uid());
  return new;
end $$;
create trigger trg_packaging_item_pull
  after insert on public.packaging_issue_items
  for each row execute function public.trg_fn_packaging_item_pull();

-- ############################################################
-- ## 0028_ledger_sample_pull_fix.sql
-- ############################################################

-- ============================================================
-- Inventory Ledger redesign, Phase 1 — fix the QC/Stability/R&D sample
-- double-count, give each its own visible ledger line.
--
-- Requested by Ravi: "help me think and re-design inventory page Ledger
-- page... Raw Material Items available for creating finished product
-- batch would be purchase - QC Sample - R&D Sample - Stability Sample -
-- Wastage." Scoped via AskUserQuestion (full writeup in the Invento
-- project doc claude/inventory-ledger-redesign.md) — this migration is
-- Phase 1 of 4: the double-count fix Ravi confirmed ("Yes, fix it").
--
-- THE BUG
-- --------
-- The real push path is submit_purchase_order() (0019_purchase_submit_
-- workflow.sql) — NOT trg_fn_purchase_line_push()/trg_purchase_line_push
-- (0002_transactions.sql): 0019 explicitly dropped that trigger ("Stop
-- pushing to inventory the instant a line is inserted. Pushing now
-- happens only inside submit_purchase_order(), once, for the whole PO.
-- The function is left in place (unused) rather than dropped") and left
-- the now-dead function untouched. Confirmed by grepping app code: only
-- submit_purchase_order/reopen_purchase_order are ever RPC'd from
-- lib/actions/purchase.ts. This migration was actually verified end to
-- end against a scratch local Postgres 16 (all 27 prior migrations +
-- this one, replayed with a minimal auth-schema shim) rather than by
-- inspection alone — that's what caught this: an earlier draft of this
-- migration edited the dead trigger function, which would have shipped
-- looking like a fix while changing nothing for real purchases. The
-- trigger function itself is left exactly as 0019 left it (untouched,
-- unused, on purpose) so nothing about that prior decision changes.
--
-- submit_purchase_order() pushes `remaining_qty` (quantity already net of
-- qc_qty/stability_qty/rnd_qty) once per line, at submit — so the sample
-- amounts are excluded from stock from submission onward.
-- trg_fn_qc_sample_pull() (0002_transactions.sql part B, unit-fixed by
-- 0020) then fires on every quality_checks insert with purchase_line_id
-- set and sample_qty > 0 and PULLS that amount again — sample_qty
-- defaults from purchase_lines.qc_qty at initial QC assignment
-- (qc-assign-form.tsx's computeBatchDisplay()) and from stability_qty at
-- every retest (0025_qc_retest_workflow.sql — same trigger, no changes
-- needed for retests to fire it, which is exactly the problem: it fires
-- again each time). Net effect on stock_balance: qc_qty
-- double-subtracted as soon as QC happens once; stability_qty
-- double-subtracted, and then subtracted again per additional retest.
-- rnd_qty has the opposite gap — excluded at submit, never pulled
-- anywhere, so it never appears on the ledger at all.
--
-- THE FIX (going forward)
-- ------------------------
-- Reservation now happens once, at submit: submit_purchase_order() pushes
-- the FULL quantity of each submitted line, then inserts three separately
-- labeled 'pull' events in the same transaction for qc_qty/stability_qty/
-- rnd_qty (each only if > 0). trg_fn_qc_sample_pull is retired to a
-- no-op: QC/retest record creation no longer moves stock (the reservation
-- already happened at submit).
--
-- reopen_purchase_order() reverses whatever submit actually wrote, so it
-- also needs to reverse the three new sample pulls now, not just the
-- purchase push — otherwise a reopen-then-resubmit would double-pull the
-- sample amounts a second time (submit re-runs for any line with
-- pushed_at null, which reopen clears).
--
-- inventory_ledger is append-only and never edited (same principle as
-- every prior migration here, e.g. 0020's compensating-entry approach) —
-- 'qc' stays a valid reference_type for the historical rows already
-- written by the old trigger; it is simply not written by anything new.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Widen reference_type to carry the three new, separately-labeled
--    sample-pull kinds. 'qc' is kept (not replaced) for the historical
--    rows already on the ledger from the old trg_fn_qc_sample_pull.
-- ------------------------------------------------------------
alter table public.inventory_ledger
  drop constraint if exists inventory_ledger_reference_type_check;
alter table public.inventory_ledger
  add constraint inventory_ledger_reference_type_check
  check (reference_type in ('purchase','qc','qc_sample','stability_sample','rnd_sample','finished_product','packaging'));

-- ------------------------------------------------------------
-- 2. Final Submit -> push the FULL quantity of every newly-submitted
--    line (was remaining_qty), then reserve qc_qty/stability_qty/
--    rnd_qty as three separate labeled pulls in the same transaction.
--    reference_id stays the purchase line's own id for all four kinds,
--    matching the existing push row's convention.
-- ------------------------------------------------------------
create or replace function public.submit_purchase_order(p_po_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_status text;
begin
  if not public.has_any_role('system_admin', 'inventory_manager') then
    raise exception 'Not authorized.';
  end if;

  select status into v_status from public.purchase_orders where id = p_po_id for update;
  if v_status is null then
    raise exception 'Purchase order not found.';
  end if;
  if v_status <> 'draft' then
    raise exception 'This purchase order has already been submitted.';
  end if;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'push', pl.item_id, pl.id, pl.quantity, pl.unit, 'purchase', pl.id, auth.uid()
  from public.purchase_lines pl
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is null
    and pl.quantity > 0;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', pl.item_id, pl.id, pl.qc_qty, pl.unit, 'qc_sample', pl.id, auth.uid()
  from public.purchase_lines pl
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is null
    and coalesce(pl.qc_qty, 0) > 0;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', pl.item_id, pl.id, pl.stability_qty, pl.unit, 'stability_sample', pl.id, auth.uid()
  from public.purchase_lines pl
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is null
    and coalesce(pl.stability_qty, 0) > 0;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', pl.item_id, pl.id, pl.rnd_qty, pl.unit, 'rnd_sample', pl.id, auth.uid()
  from public.purchase_lines pl
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is null
    and coalesce(pl.rnd_qty, 0) > 0;

  update public.purchase_lines
  set pushed_at = now()
  where purchase_order_id = p_po_id and pushed_at is null;

  update public.purchase_orders
  set status = 'submitted', submitted_at = now(), submitted_by = auth.uid()
  where id = p_po_id;
end $$;

-- ------------------------------------------------------------
-- 3. Reopen -> reverse everything submit actually wrote for this PO's
--    lines: the purchase push (as before, unchanged logic — a
--    compensating 'pull' of whatever was pushed) AND, now, the three
--    sample pulls (a compensating 'push' of whatever was pulled). Both
--    read the amount back from the ledger row itself rather than the
--    line's current qc_qty/stability_qty/rnd_qty, so it's exact even if
--    the line gets edited before a later resubmit — same principle the
--    original purchase-push reversal already used.
-- ------------------------------------------------------------
create or replace function public.reopen_purchase_order(p_po_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_status text;
begin
  if not public.has_any_role('system_admin') then
    raise exception 'Not authorized.';
  end if;

  select status into v_status from public.purchase_orders where id = p_po_id for update;
  if v_status is null then
    raise exception 'Purchase order not found.';
  end if;
  if v_status <> 'submitted' then
    raise exception 'This purchase order is not currently submitted.';
  end if;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', il.item_id, il.purchase_line_id, il.quantity, il.unit, 'purchase', il.purchase_line_id, auth.uid()
  from public.inventory_ledger il
  join public.purchase_lines pl on pl.id = il.purchase_line_id
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is not null
    and il.event_type = 'push'
    and il.reference_type = 'purchase'
    and il.reference_id = il.purchase_line_id;

  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'push', il.item_id, il.purchase_line_id, il.quantity, il.unit, il.reference_type, il.purchase_line_id, auth.uid()
  from public.inventory_ledger il
  join public.purchase_lines pl on pl.id = il.purchase_line_id
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is not null
    and il.event_type = 'pull'
    and il.reference_type in ('qc_sample', 'stability_sample', 'rnd_sample')
    and il.reference_id = il.purchase_line_id;

  update public.purchase_lines
  set pushed_at = null
  where purchase_order_id = p_po_id and pushed_at is not null;

  update public.purchase_orders
  set status = 'draft', reopened_at = now(), reopened_by = auth.uid()
  where id = p_po_id;
end $$;

-- ------------------------------------------------------------
-- 4. Retire the QC-time pull entirely. QC/retest record creation no
--    longer moves stock — the reservation already happened once, at
--    submit, above. The trigger and function are left in place (not
--    dropped) purely so nothing else has to change; it is now
--    permanently a no-op.
-- ------------------------------------------------------------
create or replace function public.trg_fn_qc_sample_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  return new;
end $$;

-- ------------------------------------------------------------
-- 5. Idempotent backfill for existing purchase_lines: active AND already
--    submitted (pushed_at is not null) — a still-draft line has no stock
--    effect at all today (FB-0018) and must stay that way; only a
--    submitted line's ledger state needs correcting.
--
--    Recomputes each line's ACTUAL current ledger state fresh on every
--    run (never assumes it wasn't already partially corrected), and
--    inserts only the remaining gap needed to reach the target state:
--      - total push = full quantity (was remaining_qty)
--      - qc_qty reserved exactly once, as a labeled pull, whether that
--        reservation already happened (an old-style 'qc' pull from the
--        original QC assignment) or needs inserting now
--      - stability_qty reserved exactly once the same way — but a batch
--        that went through MULTIPLE retests had trg_fn_qc_sample_pull
--        fire on every one of them (0025's explicit design note: no
--        trigger changes needed for retests to "work", which is exactly
--        how this over-pulled), so any pulls beyond the first
--        stability_qty are a second bug this same backfill corrects
--      - rnd_qty reserved once (it was never pulled by anything before
--        this migration, so this is purely additive)
--
--    Safe to run more than once: every insert is gated on the current
--    (freshly summed) state, so a second run computes zero gap.
-- ------------------------------------------------------------
do $$
declare
  r record;
  v_pushed_net numeric;
  v_qc_pulled_old numeric;
  v_stability_pulled_old numeric;
  v_qc_reserved boolean;
  v_stability_reserved boolean;
  v_rnd_reserved boolean;
  v_gap numeric;
  v_epsilon constant numeric := 0.000001;
begin
  for r in
    select id, item_id, unit, quantity, qc_qty, stability_qty, rnd_qty
    from public.purchase_lines
    where active = true and pushed_at is not null
  loop
    -- Net, not raw sum: a line that's been through a reopen/resubmit
    -- cycle (old-style OR new-style) already has offsetting push/pull
    -- 'purchase' rows, which a raw sum would double-count. Net is what
    -- actually reflects "how much of this line's quantity is currently
    -- pushed", regardless of how many submit/reopen cycles produced it.
    select coalesce(sum(case when event_type = 'push' then quantity else -quantity end), 0)
      into v_pushed_net
      from public.inventory_ledger
      where purchase_line_id = r.id and reference_type = 'purchase';

    -- Old-style pulls (from the retired trg_fn_qc_sample_pull, tagged
    -- 'qc' and tied to a real quality_checks row) represent genuine lab
    -- consumption that already happened — never reversed, so a plain
    -- sum (not net) is correct and intentional here.
    select coalesce(sum(l.quantity), 0) into v_qc_pulled_old
      from public.inventory_ledger l
      join public.quality_checks qc on qc.id = l.reference_id
      where l.purchase_line_id = r.id and l.event_type = 'pull' and l.reference_type = 'qc'
        and qc.is_retest = false;

    select coalesce(sum(l.quantity), 0) into v_stability_pulled_old
      from public.inventory_ledger l
      join public.quality_checks qc on qc.id = l.reference_id
      where l.purchase_line_id = r.id and l.event_type = 'pull' and l.reference_type = 'qc'
        and qc.is_retest = true;

    -- "Already reserved" must recognize BOTH an old-style pull (real QC/
    -- retest already happened) and a new-style qc_sample/stability_sample/
    -- rnd_sample row already on the ledger (this line already went
    -- through the new submit_purchase_order() — e.g. submitted after this
    -- migration's code deployed but before the backfill ran, or this is a
    -- second run of the backfill itself). Checking only the old-style
    -- join here was the actual bug this fix replaces: it made the
    -- backfill re-insert a reservation that already existed, on both a
    -- second run and on any already-correct line, which is exactly the
    -- double-count this migration exists to remove.
    v_qc_reserved := v_qc_pulled_old > v_epsilon or exists (
      select 1 from public.inventory_ledger
      where purchase_line_id = r.id and event_type = 'pull' and reference_type = 'qc_sample'
    );
    v_stability_reserved := v_stability_pulled_old > v_epsilon or exists (
      select 1 from public.inventory_ledger
      where purchase_line_id = r.id and event_type = 'pull' and reference_type = 'stability_sample'
    );
    v_rnd_reserved := exists (
      select 1 from public.inventory_ledger
      where purchase_line_id = r.id and event_type = 'pull' and reference_type = 'rnd_sample'
    );

    -- Full-quantity push gap (net-based, see above), plus a compensating
    -- push for any multiple-retest over-pull beyond the first
    -- stability_qty — old-style retests only; the new model can't
    -- over-pull since QC/retest no longer moves stock at all.
    v_gap := (r.quantity - v_pushed_net) + greatest(v_stability_pulled_old - coalesce(r.stability_qty, 0), 0);
    if v_gap > v_epsilon then
      insert into public.inventory_ledger
        (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('push', r.item_id, r.id, v_gap, r.unit, 'purchase', r.id, null);
    end if;

    if coalesce(r.qc_qty, 0) > v_epsilon and not v_qc_reserved then
      insert into public.inventory_ledger
        (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', r.item_id, r.id, r.qc_qty, r.unit, 'qc_sample', r.id, null);
    end if;

    if coalesce(r.stability_qty, 0) > v_epsilon and not v_stability_reserved then
      insert into public.inventory_ledger
        (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', r.item_id, r.id, r.stability_qty, r.unit, 'stability_sample', r.id, null);
    end if;

    if coalesce(r.rnd_qty, 0) > v_epsilon and not v_rnd_reserved then
      insert into public.inventory_ledger
        (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', r.item_id, r.id, r.rnd_qty, r.unit, 'rnd_sample', r.id, null);
    end if;
  end loop;
end $$;

-- ############################################################
-- ## 0029_purchase_line_live_remaining_qty.sql
-- ############################################################

-- ============================================================
-- Inventory Ledger redesign, Phase 2 — a live, maintained per-batch
-- remaining quantity.
--
-- Ravi's ask (see claude/inventory-ledger-redesign.md, Gap 2): a purchase
-- batch's "how much is left" needs to reflect Finished Product consumption
-- and any wastage recorded against that specific batch, not just what was
-- left right after QC/Stability/R&D sampling at receipt.
--
-- THE GAP
-- --------
-- purchase_lines.remaining_qty is a Postgres GENERATED column
-- (quantity - qc_qty - stability_qty - rnd_qty) — static, fixed at
-- purchase time. It never decreases when that specific batch is later
-- consumed by a finished_product_components insert, or has wastage
-- recorded against it (record_wastage(), when a batch is picked).
-- purchase_lines-table.tsx, the FP compose picker, RM Report As On Date,
-- the wastage batch dropdown, and the Purchase Register report all show
-- this static figure as if it were live "what's left in this batch" —
-- most consequentially the FP compose picker, whose "X avail." hint (and,
-- until this migration, its total absence of any DB-level check) could
-- suggest consuming from a batch well past what's actually left in it.
-- Only item-level stock_balance (Phase 1, now correct) reflects
-- consumption at all today; nothing reflects it per-batch.
--
-- Scoped with Ravi via AskUserQuestion before building: a maintained
-- column kept current by a trigger (not computed on read), and — a
-- follow-up question this migration's design surfaced — batch-tied
-- wastage counts as consumption here too, not just FP composition
-- (matches Ravi's original formula: "available raw material = purchase -
-- QC sample - R&D sample - stability sample - wastage").
--
-- THE FIX
-- --------
-- purchase_lines.live_remaining_qty: starts at remaining_qty for every
-- line (set by a BEFORE INSERT trigger — new.remaining_qty itself isn't
-- readable yet at BEFORE-trigger time since it's a generated column, so
-- the same formula is computed directly from new.quantity/qc_qty/
-- stability_qty/rnd_qty), then decremented by:
--   - a finished_product_components insert against that purchase_line_id
--     (new AFTER INSERT trigger)
--   - record_wastage() when a batch is specified (rewritten below)
--
-- A draft line's quantity/qc_qty/stability_qty/rnd_qty can still be
-- edited before Final Submit (updatePurchaseLine, lib/actions/
-- purchase.ts) — the same trigger handles UPDATE OF those four columns
-- too, recomputing the new base figure while PRESERVING whatever's
-- already been consumed (always zero for a genuine draft edit, since
-- nothing can be pushed/consumed before submit — FB-0018 — but this also
-- covers the rarer System-Admin-reopens-then-edits-then-resubmits path
-- without silently erasing real consumption history that happened before
-- the reopen).
--
-- A `not valid` check constraint (same idiom as 0016_quantity_check_
-- constraints.sql) makes this a real DB-level guard going forward: an FP
-- composition or a wastage record that would drive a batch's live
-- remaining below zero is now rejected outright, instead of silently
-- succeeding the way it always has until now. `not valid` means existing
-- rows are never scanned/rejected by this migration itself — only
-- confirmed safe by the backfill below actually landing at a
-- non-negative figure for everything active (verified locally, see
-- docs/modules/purchase.md).
-- ============================================================

-- ------------------------------------------------------------
-- 1. New column, nullable first (see 0019's staged pattern for the same
--    reason — backfill explicitly before anything requires a value).
-- ------------------------------------------------------------
alter table public.purchase_lines
  add column if not exists live_remaining_qty numeric;

-- ------------------------------------------------------------
-- 2. Backfill every existing line: start from the same base
--    (quantity - qc_qty - stability_qty - rnd_qty) remaining_qty already
--    computes, then subtract everything actually consumed from THAT
--    batch so far — finished_product_components quantities, and wastage
--    recorded against it (inventory_ledger event_type = 'wastage',
--    purchase_line_id = this line — record_wastage()'s only reference_type
--    is 'purchase', so no reference_type filter is needed/possible here).
-- ------------------------------------------------------------
update public.purchase_lines pl
set live_remaining_qty =
  (pl.quantity - coalesce(pl.qc_qty, 0) - coalesce(pl.stability_qty, 0) - coalesce(pl.rnd_qty, 0))
  - coalesce((select sum(fpc.quantity) from public.finished_product_components fpc where fpc.purchase_line_id = pl.id), 0)
  - coalesce((select sum(il.quantity) from public.inventory_ledger il
              where il.purchase_line_id = pl.id and il.event_type = 'wastage'), 0);

alter table public.purchase_lines
  alter column live_remaining_qty set not null;

alter table public.purchase_lines
  drop constraint if exists live_remaining_not_negative;
alter table public.purchase_lines
  add constraint live_remaining_not_negative check (live_remaining_qty >= 0) not valid;

-- ------------------------------------------------------------
-- 3. Keep it current on insert (new line) and on update of the four
--    quantity-defining columns (a draft-line edit, per updatePurchaseLine
--    — see the comment block above for why this preserves already-
--    consumed amounts rather than resetting them).
-- ------------------------------------------------------------
create or replace function public.trg_fn_purchase_line_live_remaining()
returns trigger language plpgsql as $$
declare
  v_new_base numeric;
  v_consumed numeric;
begin
  v_new_base := new.quantity - coalesce(new.qc_qty, 0) - coalesce(new.stability_qty, 0) - coalesce(new.rnd_qty, 0);
  if tg_op = 'INSERT' then
    new.live_remaining_qty := v_new_base;
  else
    v_consumed := (old.quantity - coalesce(old.qc_qty, 0) - coalesce(old.stability_qty, 0) - coalesce(old.rnd_qty, 0))
      - coalesce(old.live_remaining_qty, 0);
    new.live_remaining_qty := v_new_base - v_consumed;
  end if;
  return new;
end $$;
drop trigger if exists trg_purchase_line_live_remaining on public.purchase_lines;
create trigger trg_purchase_line_live_remaining
  before insert or update of quantity, qc_qty, stability_qty, rnd_qty on public.purchase_lines
  for each row execute function public.trg_fn_purchase_line_live_remaining();

-- ------------------------------------------------------------
-- 4. Finished Product composition consumes from a specific batch —
--    decrement it. SECURITY DEFINER: the app role that can insert
--    finished_product_components (finished_product write roles) isn't
--    necessarily granted UPDATE on purchase_lines directly (that's
--    system_admin/inventory_manager, per pl_update in
--    0018_purchase_delete_policy.sql) — same cross-module-write pattern
--    every other ledger-writing trigger in this app already uses.
-- ------------------------------------------------------------
create or replace function public.trg_fn_fp_component_live_remaining_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.purchase_lines
  set live_remaining_qty = live_remaining_qty - new.quantity
  where id = new.purchase_line_id;
  return new;
end $$;
drop trigger if exists trg_fp_component_live_remaining_pull on public.finished_product_components;
create trigger trg_fp_component_live_remaining_pull
  after insert on public.finished_product_components
  for each row execute function public.trg_fn_fp_component_live_remaining_pull();

-- ------------------------------------------------------------
-- 5. record_wastage(): decrement the batch's live remaining too, when a
--    batch was specified (the "Batch" field on Record Wastage is
--    optional — p_purchase_line_id can be null, in which case there's no
--    per-batch figure to touch, same as before).
-- ------------------------------------------------------------
create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;
  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by, reason)
  values ('wastage', p_item_id, p_purchase_line_id, p_quantity, p_unit, 'purchase', auth.uid(), p_reason)
  returning id into v_id;

  if p_purchase_line_id is not null then
    update public.purchase_lines
    set live_remaining_qty = live_remaining_qty - p_quantity
    where id = p_purchase_line_id;
  end if;

  return v_id;
end $$;

-- ############################################################
-- ## 0030_finished_product_ledger.sql
-- ############################################################

-- ============================================================
-- Inventory Ledger redesign, Phase 3 — Finished Product as a real,
-- ledger-tracked item.
--
-- Ravi's ask (claude/inventory-ledger-redesign.md, Gap 3): "available
-- finished product" should be computable the same way raw material and
-- packaging stock already are. Scoped via AskUserQuestion: Full — real
-- items, not just summing packaged_qty — with stock becoming available
-- "at QC approval" (not at packaging), and nothing yet consuming/
-- dispatching it (no such flow exists in the app).
--
-- THE GOOD NEWS: most of the "real item" infrastructure already exists.
-- 0010_mfr_finished_product_link.sql (2 Sept 2026) already gives every
-- MFR its own `items` row (category = 'processed', an FP-00001-style
-- code) via `mfr_definitions.finished_product_item_id`, created together
-- by createMfrDefinition(). What was actually missing, confirmed by
-- checking items.category (still exactly 'raw'/'processed'/'packaging' —
-- no new category needed) and by grepping for any trigger that writes to
-- inventory_ledger on finished_product_batches/quality_checks activity
-- (there is none): nothing ever PUSHES to inventory_ledger when a batch
-- is produced. This migration is that push, not a new items category.
--
-- WHERE IT HOOKS IN: reviewQualityCheck() (lib/actions/qc.ts) is the one
-- place quality_checks.status ever becomes 'approved'/'rejected' — for
-- BOTH raw-material batches (purchase_line_id set) and Finished Product
-- batches (finished_product_batch_id set; qc_one_subject, 0001_init.sql,
-- guarantees exactly one of the two). A trigger on that transition,
-- scoped to the FP case, is the single natural place to push stock "at
-- QC approval."
--
-- A SECOND KNOWN GAP THIS SAME HOOK CLOSES: lib/finished-product-status.ts
-- has carried this comment since it was written — "A DB trigger syncing
-- finished_product_batches.status from quality_checks would be the clean
-- fix, but this pass is not allowed to add new migrations — so instead
-- we compute the *displayed* status at read time... Known follow-up: add
-- that trigger in a later migration so finished_product_batches.status
-- itself stays authoritative." That trigger is added here, in the same
-- migration, since it's the same transition this phase already hooks —
-- resolveDisplayStatus()/latestQcByBatch() are left in place as a
-- harmless safety net (they now just confirm what the DB already says)
-- rather than ripped out across every caller, which is a larger, separate
-- change this phase doesn't need to make.
--
-- WHY A BATCH CAN ONLY BE APPROVED ONCE (simplifying this considerably
-- compared to Phase 1's RM retest handling): quality_checks_fp_batch_
-- unique (0015_qc_duplicate_backstop.sql) is a real, still-standing
-- UNIQUE constraint on finished_product_batch_id — unlike purchase_
-- line_id's later relaxation for retests (0025_qc_retest_workflow.sql),
-- nothing loosened this one. There is no FP retest workflow anywhere in
-- this codebase (startRetestQualityCheck, lib/actions/qc.ts, is scoped
-- to purchase_line_id only) — an FP batch's quality_checks row is
-- created exactly once and reviewed exactly once. No compounding-pull
-- risk to guard against here.
--
-- WHAT GETS PUSHED, mirroring Phase 1's RM pattern exactly: the full
-- batch_yield ("how much Finished Product has been created," entered at
-- Complete Batch — 0022_fp_batch_yield.sql) as a push, then qc_sample_
-- qty/stability_qty/rnd_qty (captured on the same screen, mirroring
-- purchase_lines' qc_qty/stability_qty/rnd_qty) as three separately
-- labeled pulls — reusing the existing 'qc_sample'/'stability_sample'/
-- 'rnd_sample' reference_type values from Phase 1 (a QC sample is a QC
-- sample whether it came from a purchase batch or a production batch;
-- reference_id already means different things per reference_type
-- throughout this schema — see FB-0013, docs/modules/inventory.md — this
-- is consistent with that, not a new kind of ambiguity). The push itself
-- gets its own new reference_type, 'fp_yield', distinct from the
-- existing 'finished_product' (which already means something else: RM
-- pulled *for* FP composition, not the FP batch's own output).
--
-- GRACEFUL, NOT BLOCKING: a legacy mfr_definitions row created before
-- 0010 can have finished_product_item_id = null (that migration
-- deliberately didn't guess at pairing old rows up). If so, this trigger
-- skips the ledger push (nothing to push against) but still syncs
-- finished_product_batches.status — a QC reviewer approving an old
-- recipe's batch is never blocked by a missing link on that recipe.
-- Same defensive posture for a null/zero batch_yield (shouldn't happen —
-- submitFinishedProductToQc() already requires it before a QC record can
-- even be created — but the trigger doesn't assume the app is the only
-- caller).
--
-- A new `not valid` check constraint (batch_yield can't be oversampled
-- past zero) mirrors purchase_lines' remaining_not_negative the same way
-- Phase 2 mirrored it for live_remaining_qty — nothing enforced this for
-- Finished Product at all before now.
-- ============================================================

-- ------------------------------------------------------------
-- 1. New reference_type for the FP batch's own push.
-- ------------------------------------------------------------
alter table public.inventory_ledger
  drop constraint if exists inventory_ledger_reference_type_check;
alter table public.inventory_ledger
  add constraint inventory_ledger_reference_type_check
  check (reference_type in ('purchase','qc','qc_sample','stability_sample','rnd_sample','finished_product','packaging','fp_yield'));

-- ------------------------------------------------------------
-- 2. Defensive parity with purchase_lines.remaining_not_negative — never
--    enforced for Finished Product before. `not valid`: existing rows
--    are never scanned/rejected by adding this; only new inserts/updates
--    are checked going forward (0016_quantity_check_constraints.sql's
--    idiom, reused again after Phase 2).
-- ------------------------------------------------------------
alter table public.finished_product_batches
  drop constraint if exists fp_batch_yield_not_negative;
alter table public.finished_product_batches
  add constraint fp_batch_yield_not_negative
  check (
    batch_yield is null or
    (batch_yield - coalesce(qc_sample_qty, 0) - coalesce(stability_qty, 0) - coalesce(rnd_qty, 0)) >= 0
  ) not valid;

-- ------------------------------------------------------------
-- 3. The trigger itself.
-- ------------------------------------------------------------
create or replace function public.trg_fn_qc_review_finished_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_batch record;
  v_item_id uuid;
begin
  update public.finished_product_batches
  set status = new.status
  where id = new.finished_product_batch_id;

  if new.status <> 'approved' then
    return new;
  end if;

  select fpb.batch_yield, fpb.qc_sample_qty, fpb.stability_qty, fpb.rnd_qty, fpb.unit, fpb.mfr_definition_id
    into v_batch
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_item_id
    from public.mfr_definitions md
    where md.id = v_batch.mfr_definition_id;

  -- Graceful skip, not a hard failure — see the migration header comment
  -- for why both of these are possible and neither should block a real
  -- QC approval.
  if v_item_id is null or v_batch.batch_yield is null or v_batch.batch_yield <= 0 then
    return new;
  end if;

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
  values
    ('push', v_item_id, v_batch.batch_yield, v_batch.unit, 'fp_yield', new.finished_product_batch_id, auth.uid());

  if coalesce(v_batch.qc_sample_qty, 0) > 0 then
    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('pull', v_item_id, v_batch.qc_sample_qty, v_batch.unit, 'qc_sample', new.finished_product_batch_id, auth.uid());
  end if;

  if coalesce(v_batch.stability_qty, 0) > 0 then
    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('pull', v_item_id, v_batch.stability_qty, v_batch.unit, 'stability_sample', new.finished_product_batch_id, auth.uid());
  end if;

  if coalesce(v_batch.rnd_qty, 0) > 0 then
    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('pull', v_item_id, v_batch.rnd_qty, v_batch.unit, 'rnd_sample', new.finished_product_batch_id, auth.uid());
  end if;

  return new;
end $$;

drop trigger if exists trg_qc_review_finished_product on public.quality_checks;
create trigger trg_qc_review_finished_product
  after update on public.quality_checks
  for each row
  when (new.finished_product_batch_id is not null and old.status = 'submitted' and new.status in ('approved', 'rejected'))
  execute function public.trg_fn_qc_review_finished_product();

-- ------------------------------------------------------------
-- 4. Idempotent backfill: every FP batch whose (at most one,
--    quality_checks_fp_batch_unique-guaranteed) quality_checks row is
--    already approved/rejected but hasn't been synced/pushed yet — same
--    logic as the trigger, applied once for existing data. Guarded by
--    "no fp_yield push already on file for this batch" so a second run
--    is a true no-op.
-- ------------------------------------------------------------
do $$
declare
  r record;
  v_item_id uuid;
begin
  for r in
    select fpb.id, fpb.status as batch_status, fpb.batch_yield, fpb.qc_sample_qty, fpb.stability_qty,
           fpb.rnd_qty, fpb.unit, fpb.mfr_definition_id, qc.status as qc_status
    from public.finished_product_batches fpb
    join public.quality_checks qc on qc.finished_product_batch_id = fpb.id
    where qc.status in ('approved', 'rejected')
  loop
    if r.batch_status is distinct from r.qc_status then
      update public.finished_product_batches set status = r.qc_status where id = r.id;
    end if;

    if r.qc_status <> 'approved' then
      continue;
    end if;

    if exists (select 1 from public.inventory_ledger where reference_type = 'fp_yield' and reference_id = r.id) then
      continue;
    end if;

    select md.finished_product_item_id into v_item_id
      from public.mfr_definitions md
      where md.id = r.mfr_definition_id;

    if v_item_id is null or r.batch_yield is null or r.batch_yield <= 0 then
      continue;
    end if;

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
    values
      ('push', v_item_id, r.batch_yield, r.unit, 'fp_yield', r.id, null);

    if coalesce(r.qc_sample_qty, 0) > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', v_item_id, r.qc_sample_qty, r.unit, 'qc_sample', r.id, null);
    end if;

    if coalesce(r.stability_qty, 0) > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', v_item_id, r.stability_qty, r.unit, 'stability_sample', r.id, null);
    end if;

    if coalesce(r.rnd_qty, 0) > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, quantity, unit, reference_type, reference_id, event_by)
      values
        ('pull', v_item_id, r.rnd_qty, r.unit, 'rnd_sample', r.id, null);
    end if;
  end loop;
end $$;

-- ############################################################
-- ## 0031_stock_position.sql
-- ############################################################

-- ============================================================
-- Inventory Ledger redesign, Phase 4 — Stock Position + per-item detail
-- page + Ledger running balance/filters.
--
-- Scoped via AskUserQuestion (claude/inventory-ledger-redesign.md, Part 3,
-- Option B+C+A folded together): all three categories (raw material,
-- packaging, finished product) get the full breakdown treatment, not just
-- raw material; the per-item drill-down page ships in this same phase, not
-- a later one; the Ledger tab's running-balance column and filters ship
-- in this same phase too.
--
-- This migration is additive reporting infrastructure — two new views
-- plus one new generated-identity column (added while testing the
-- running-balance view, see below; nothing that changes what gets
-- written otherwise). Both views are read through the exact same RLS
-- surface Stock Balance/RM Report already rely on (items_select/
-- ledger_select: "any signed-in user," not row-scoped) — same precedent
-- as the pre-existing stock_balance/purchase_batch_status views, so no
-- new policy is needed and no security_invoker option is set (matches
-- those two).
-- ============================================================

-- ------------------------------------------------------------
-- 1. item_position — the Stock Position breakdown, one row per item
--    (including items with zero ledger activity, via the left join),
--    generic across category: the page picks which of these 8 raw
--    numbers to show as columns per category (RM gets the full
--    purchase/QC/Stability/R&D/wastage/FP-consumption breakdown; FP gets
--    Yield/QC/Stability/R&D; Packaging gets Received/Issued). `on_hand`
--    is computed with the exact same case expression stock_balance
--    (0001_init.sql) already uses, so the two can never disagree —
--    verified during local testing that summing the breakdown columns
--    reconciles to `on_hand` for every item and every category, since
--    every reference_type in inventory_ledger's check constraint is
--    covered by exactly one bucket below (see the migration's commit
--    message for the reconciliation this was checked against).
--    reference_type = 'qc' (kept only for historical rows since Phase 1,
--    0028_ledger_sample_pull_fix.sql — nothing new writes it) is folded
--    into held_qc alongside 'qc_sample', since it's the same kind of
--    event under an old label.
-- ------------------------------------------------------------
create or replace view public.item_position as
select
  i.id as item_id,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'purchase' then l.quantity else 0 end), 0) as received,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'fp_yield' then l.quantity else 0 end), 0) as yielded,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type in ('qc', 'qc_sample') then l.quantity else 0 end), 0) as held_qc,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'stability_sample' then l.quantity else 0 end), 0) as held_stability,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'rnd_sample' then l.quantity else 0 end), 0) as held_rnd,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'finished_product' then l.quantity else 0 end), 0) as consumed_by_fp,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaging' then l.quantity else 0 end), 0) as issued_packaging,
  coalesce(sum(case when l.event_type = 'wastage' then l.quantity else 0 end), 0) as wastage,
  coalesce(sum(case l.event_type when 'push' then l.quantity when 'wastage' then -l.quantity else -l.quantity end), 0) as on_hand
from public.items i
left join public.inventory_ledger l on l.item_id = i.id
group by i.id;

-- ------------------------------------------------------------
-- 2. A real insertion-order column, found necessary while testing the
--    running-balance view below: several rows can share the exact same
--    event_at (every trigger that pushes-then-pulls within one
--    transaction — e.g. submit_purchase_order's push + 3 sample pulls,
--    or Phase 3's fp_yield push + 3 sample pulls — inserts them all at
--    the same `now()`). Tie-breaking the running-balance window function
--    on `id` (a random UUID) sorts these arbitrarily, which can put a
--    pull before its own push and show a momentarily negative balance
--    that never actually happened — confirmed locally: a same-transaction
--    RM purchase (push 100, pulls 5/3/2) showed running_balance dip to
--    -2 before recovering to 98, purely a display artifact of UUID
--    ordering. `generated always as identity` gives every row a real,
--    monotonically increasing sequence number in actual insert order —
--    existing rows get backfilled in whatever order Postgres's table
--    scan visits them (fine: bulk-imported legacy rows have no truer
--    "original insertion order" to recover, and don't share event_at
--    collisions with anything that matters), and every future insert
--    (including several in the same transaction) gets sequential values
--    in the order its own INSERT statement actually ran — which, for
--    every existing trigger, is push-before-its-pulls, matching reality.
-- ------------------------------------------------------------
alter table public.inventory_ledger add column if not exists seq bigint generated always as identity;

-- ------------------------------------------------------------
-- 3. inventory_ledger_with_balance — every inventory_ledger column plus
--    running_balance: that item's on-hand balance immediately after this
--    event, computed via a window function partitioned by item and
--    ordered by (event_at, seq) — chronological, with same-instant rows
--    broken by real insertion order rather than an arbitrary UUID (see
--    above). The Ledger page queries this view instead of the base
--    table; it can still be displayed newest-first (or filtered/paged
--    any way) without disturbing the balance, since the window
--    function's own ORDER BY is independent of the outer query's
--    display order.
-- ------------------------------------------------------------
create or replace view public.inventory_ledger_with_balance as
select
  il.*,
  sum(case il.event_type when 'push' then il.quantity when 'wastage' then -il.quantity else -il.quantity end)
    over (partition by il.item_id order by il.event_at, il.seq rows between unbounded preceding and current row) as running_balance
from public.inventory_ledger il;

-- ############################################################
-- ## 0032_packaged_finished_product.sql
-- ############################################################

-- ============================================================
-- Task F — "how Finished Product which is only incremental right now in
-- inventory will go out of inventory" (Ravi, 3 Sept 2026).
--
-- Full design/rationale: claude/packaged-fp-redesign.md (project doc).
-- Short version: this is built into the existing Packaging screen, not a
-- new module. A "New Packaging Issue" for department Store or R&D now, in
-- one transaction: (1) pulls bulk Finished Product + Packaging Material
-- as today, (2) pushes a brand-new paired item "Packaged Finished
-- Product" (e.g. PKG-FP-00001 for FP-00001 — same item name, different
-- code/category), (3) immediately pulls that same quantity back out as
-- "issued to Store"/"issued to R&D" — always fully issued, one-shot.
-- Department = Production is explicitly held back ("We will work on this
-- later") — its existing trg_fn_packaging_pull/trg_fn_packaging_item_pull
-- behavior is byte-for-byte unchanged by this migration.
--
-- Entirely additive: one new items.category value, one new nullable
-- self-referencing items column, one new sequence, three new nullable
-- packaging_issues columns, three new inventory_ledger reference_type
-- values, one new trigger (alongside, not replacing, the existing two),
-- and four new item_position columns. No existing row, trigger, or
-- column is altered destructively.
-- ============================================================

-- ------------------------------------------------------------
-- 1. New items.category value: 'packaged_fp'. Distinct from the
--    pre-existing 'packaging' (materials — bottles, caps) despite the
--    similar-looking code prefix chosen below, and distinct from
--    'processed' (bulk Finished Product) — see the design doc for why a
--    fourth value was chosen over reusing either.
-- ------------------------------------------------------------
alter table public.items drop constraint if exists items_category_check;
alter table public.items
  add constraint items_category_check
  check (category in ('raw','processed','packaging','packaged_fp'));

-- ------------------------------------------------------------
-- 2. Pairing column: set once, on the bulk FP ('processed') item, to the
--    id of its paired Packaged FP ('packaged_fp') item. Mirrors
--    mfr_definitions.finished_product_item_id (0010) one level further
--    down the chain. `unique` enforces the strict 1:1 relationship the
--    spec calls for ("For each Finished Product code ... there will be a
--    unique packaged Finished Product code"). Not DB-enforced that the
--    target actually has category = 'packaged_fp' — same lightweight-
--    trust precedent as the mfr_definitions link, which likewise doesn't
--    constrain finished_product_item_id's target category.
-- ------------------------------------------------------------
alter table public.items add column if not exists packaged_item_id uuid references public.items(id);
alter table public.items drop constraint if exists items_packaged_item_id_unique;
alter table public.items add constraint items_packaged_item_id_unique unique (packaged_item_id);
alter table public.items drop constraint if exists items_packaged_item_id_not_self;
alter table public.items add constraint items_packaged_item_id_not_self check (packaged_item_id is null or packaged_item_id <> id);

-- ------------------------------------------------------------
-- 3. Item code generator: new sequence + branch for 'packaged_fp',
--    prefix 'PKG-FP' (-> PKG-FP-00001), matching Ravi's own example code
--    exactly. peek_next_item_code() (0012) updated the same way so a
--    preview never falls through to the wrong prefix if this category is
--    ever surfaced on a preview screen.
-- ------------------------------------------------------------
create sequence if not exists public.item_code_seq_pkgfp start 1;
grant usage, select on public.item_code_seq_pkgfp to anon, authenticated;

create or replace function public.get_next_item_code(p_category text)
returns text language plpgsql as $$
declare v_num int; v_prefix text;
begin
  if p_category = 'packaging' then
    v_num := nextval('public.item_code_seq_pkg'); v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_num := nextval('public.item_code_seq_fp'); v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_num := nextval('public.item_code_seq_pkgfp'); v_prefix := 'PKG-FP';
  else
    v_num := nextval('public.item_code_seq_raw'); v_prefix := 'RM';
  end if;
  return v_prefix || '-' || lpad(v_num::text, 5, '0');
end $$;

create or replace function public.peek_next_item_code(p_category text)
returns text language plpgsql stable as $$
declare
  v_num bigint;
  v_prefix text;
  v_seq regclass;
begin
  if p_category = 'packaging' then
    v_seq := 'public.item_code_seq_pkg'; v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_seq := 'public.item_code_seq_fp'; v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_seq := 'public.item_code_seq_pkgfp'; v_prefix := 'PKG-FP';
  else
    v_seq := 'public.item_code_seq_raw'; v_prefix := 'RM';
  end if;

  execute format(
    'select case when is_called then last_value + 1 else last_value end from %s',
    v_seq
  ) into v_num;

  return v_prefix || '-' || lpad(v_num::text, 5, '0');
end $$;

-- ------------------------------------------------------------
-- 4. packaging_issues: three new nullable columns, populated only by
--    createPackagingIssue() and only for department in ('store','rnd').
--    Production rows leave all three null and go on using free-text
--    pack_size exactly as before this migration — nothing here changes
--    Production's existing shape or behavior.
--
--    pack_size_qty / pack_size_unit: the structured "how much bulk FP per
--    packaged unit" the user enters (e.g. 1 + 'ltr' for a 1L bottle).
--    fp_qty_consumed: pack_size_qty * unit_count, already converted (via
--    lib/constants/units.ts convertUnit(), app-side) into the FP item's
--    own base unit — so the trigger below is a straight read, never unit
--    arithmetic in SQL.
-- ------------------------------------------------------------
alter table public.packaging_issues add column if not exists pack_size_qty numeric;
alter table public.packaging_issues add column if not exists pack_size_unit text;
alter table public.packaging_issues add column if not exists fp_qty_consumed numeric;
alter table public.packaging_issues drop constraint if exists packaging_pack_size_qty_positive;
alter table public.packaging_issues add constraint packaging_pack_size_qty_positive check (pack_size_qty is null or pack_size_qty > 0);
alter table public.packaging_issues drop constraint if exists packaging_fp_qty_consumed_positive;
alter table public.packaging_issues add constraint packaging_fp_qty_consumed_positive check (fp_qty_consumed is null or fp_qty_consumed > 0);

-- ------------------------------------------------------------
-- 5. Three new inventory_ledger reference_type values for the transform-
--    and-issue flow. Store vs R&D is distinguished by the existing
--    `department` column on each row, not by separate reference_type
--    values per department — same pattern the pre-existing 'packaging'
--    pulls already use.
-- ------------------------------------------------------------
alter table public.inventory_ledger
  drop constraint if exists inventory_ledger_reference_type_check;
alter table public.inventory_ledger
  add constraint inventory_ledger_reference_type_check
  check (reference_type in (
    'purchase','qc','qc_sample','stability_sample','rnd_sample','finished_product',
    'packaging','fp_yield','fp_packaging_pull','packaged_fp_yield','packaged_fp_issue'
  ));

-- ------------------------------------------------------------
-- 6. The transform-and-issue trigger. Fires alongside (not instead of)
--    the existing trg_packaging_pull (packaged_qty bump) and
--    trg_packaging_item_pull (packaging-material pulls, unchanged, fires
--    for every department including production). This one is a no-op for
--    production and for any row the server action didn't populate
--    fp_qty_consumed on.
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_transform_and_issue()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_mfr_definition_id uuid;
  v_fp_item_id uuid;
  v_fp_unit text;
  v_pkg_item_id uuid;
begin
  -- Production is explicitly held back for now — see the migration header
  -- and claude/packaged-fp-redesign.md. Nothing below this line ever runs
  -- for a production issue.
  if new.department not in ('store', 'rnd') then
    return new;
  end if;

  -- Defensive: the server action always sets this for store/rnd issues,
  -- but this trigger never fabricates a pull against a null/zero amount.
  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  select fpb.mfr_definition_id into v_mfr_definition_id
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_fp_item_id
    from public.mfr_definitions md
    where md.id = v_mfr_definition_id;

  -- Graceful skip, same posture as Phase 3's fp_yield trigger: a legacy
  -- MFR with no linked FP item has nothing to transform.
  if v_fp_item_id is null then
    return new;
  end if;

  select unit, packaged_item_id into v_fp_unit, v_pkg_item_id
    from public.items where id = v_fp_item_id;

  -- Graceful skip: the FP item predates this feature's paired-item
  -- backfill, or was never paired for some other reason. Nothing to
  -- transform into — the packaging-material pulls above still happened
  -- normally; only the bulk-FP transform is skipped.
  if v_pkg_item_id is null then
    return new;
  end if;

  -- 1. Pull the bulk Finished Product consumed into this packaging run.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

  -- 2. Push the Packaged Finished Product created — counted in packaged
  --    units (unit_count), not bulk volume.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('push', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_yield', new.id, auth.uid());

  -- 3. Immediately issue it back out. "Always fully issued, one-shot" —
  --    Packaged FP never sits in stock partially issued; on_hand for this
  --    item always nets back to zero right after this insert.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_issue', new.id, auth.uid());

  return new;
end $$;

drop trigger if exists trg_packaging_transform_and_issue on public.packaging_issues;
create trigger trg_packaging_transform_and_issue
  after insert on public.packaging_issues
  for each row execute function public.trg_fn_packaging_transform_and_issue();

-- ------------------------------------------------------------
-- 7. item_position (0031_stock_position.sql) extended with four more
--    additive columns. Every new reference_type value above is covered
--    by exactly one bucket here, preserving the view's existing
--    reconciliation invariant (every inventory_ledger reference_type is
--    covered by exactly one item_position bucket). on_hand's generic
--    push-minus-pull expression is unchanged — it already nets a
--    Packaged FP item to zero automatically once yield and issue both
--    land.
-- ------------------------------------------------------------
create or replace view public.item_position as
select
  i.id as item_id,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'purchase' then l.quantity else 0 end), 0) as received,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'fp_yield' then l.quantity else 0 end), 0) as yielded,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type in ('qc', 'qc_sample') then l.quantity else 0 end), 0) as held_qc,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'stability_sample' then l.quantity else 0 end), 0) as held_stability,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'rnd_sample' then l.quantity else 0 end), 0) as held_rnd,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'finished_product' then l.quantity else 0 end), 0) as consumed_by_fp,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaging' then l.quantity else 0 end), 0) as issued_packaging,
  coalesce(sum(case when l.event_type = 'wastage' then l.quantity else 0 end), 0) as wastage,
  coalesce(sum(case l.event_type when 'push' then l.quantity when 'wastage' then -l.quantity else -l.quantity end), 0) as on_hand,
  -- New columns appended after the pre-existing ones (`create or replace
  -- view` requires every existing column to keep its exact name, type and
  -- ordinal position — new columns can only ever be added at the end).
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'fp_packaging_pull' then l.quantity else 0 end), 0) as consumed_by_packaging,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'packaged_fp_yield' then l.quantity else 0 end), 0) as packaged_yield,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'store' then l.quantity else 0 end), 0) as issued_store,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'rnd' then l.quantity else 0 end), 0) as issued_rnd
from public.items i
left join public.inventory_ledger l on l.item_id = i.id
group by i.id;

-- ############################################################
-- ## 0033_sufficient_stock_check.sql
-- ############################################################

-- ============================================================
-- Sufficient-stock check for pull-side operations with no existing
-- backstop (claude/known-issues.md, Sixth pass's "not yet addressed"
-- item, scoped and confirmed with Ravi before building).
--
-- WHAT WAS ALREADY COVERED (confirmed by reading the actual trigger code,
-- not assumed) — no change needed for these:
--   - QC/Stability/R&D sample pulls: reserved automatically inside
--     submit_purchase_order() (0028_ledger_sample_pull_fix.sql), and
--     createPurchaseLine()/updatePurchaseLine() (lib/actions/purchase.ts)
--     already reject qc_qty+stability_qty+rnd_qty > quantity at entry
--     time — this pull can never exceed what's available, by construction.
--   - FP component pulls (raw material consumed composing a Finished
--     Product batch): already a real hard block via
--     0029_purchase_line_live_remaining_qty.sql's
--     live_remaining_not_negative CHECK constraint on the purchase
--     batch's own live_remaining_qty, enforced on every new insert.
--   - Wastage against a specific batch: same 0029 constraint covers it —
--     record_wastage() already decrements purchase_lines.live_remaining_qty
--     and that CHECK rejects the update if it would go negative.
--
-- THE TWO REAL GAPS, both confirmed to have zero stock check today:
--   1. Wastage recorded with NO batch specified (the Wastage form's batch
--      field is optional — "leave blank for wastage not tied to a
--      specific received batch"). Nothing bounds this against the item's
--      actual on-hand balance.
--   2. Packaging pulls — both the packaging-material pulls (bottles, caps,
--      etc. consumed in a packaging issue, trg_fn_packaging_item_pull)
--      and the bulk Finished Product consumed when transforming into
--      Packaged FP (trg_fn_packaging_transform_and_issue's
--      fp_packaging_pull). Neither has ever checked stock_balance before
--      inserting its pull.
--
-- Decisions confirmed with Ravi: hard block (reject the transaction, not
-- a warn-and-allow), scoped to these two real gaps. The two known
-- legacy-negative packaging items (LEG-PKG-00055, LEG-PKG-00115 — see
-- known-issues.md's Sixth pass) are deliberately left as-is: if anything
-- ever tries to pull against them, correctly hitting this new block is
-- the right behavior (you can't consume from stock that's already
-- negative), not a regression to work around.
-- ============================================================

-- ------------------------------------------------------------
-- Shared guard. Locks the item row first (same `for update` serialization
-- idiom already used by submit_purchase_order()/reopen_purchase_order() in
-- 0019/0028 to close a different double-submit race) so two concurrent
-- pulls against the same item can't both read the same "available" figure
-- and each pass the check — the second caller blocks until the first's
-- transaction commits or rolls back, then re-reads a balance that already
-- reflects it. stock_balance (0001_init.sql) has no row at all for an item
-- with zero ledger activity yet (a plain `group by`, not a left join), so
-- an absent row means 0 available, not "unknown" — coalesced explicitly.
-- ------------------------------------------------------------
create or replace function public.check_sufficient_stock(p_item_id uuid, p_quantity numeric)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_item_name text;
  v_available numeric;
begin
  select name into v_item_name from public.items where id = p_item_id for update;

  select on_hand into v_available from public.stock_balance where item_id = p_item_id;
  v_available := coalesce(v_available, 0);

  if p_quantity > v_available then
    raise exception 'Not enough stock on hand for %: % available, % requested.',
      coalesce(v_item_name, 'this item'), v_available, p_quantity;
  end if;
end $$;

-- ------------------------------------------------------------
-- Gap 1: wastage with no batch specified.
-- ------------------------------------------------------------
create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;

  -- A batch-specified wastage is already bounded by the
  -- live_remaining_not_negative CHECK below (via the purchase_lines
  -- update further down) — only the no-batch case had no backstop at all.
  if p_purchase_line_id is null then
    perform public.check_sufficient_stock(p_item_id, p_quantity);
  end if;

  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by, reason)
  values ('wastage', p_item_id, p_purchase_line_id, p_quantity, p_unit, 'purchase', auth.uid(), p_reason)
  returning id into v_id;

  if p_purchase_line_id is not null then
    update public.purchase_lines
    set live_remaining_qty = live_remaining_qty - p_quantity
    where id = p_purchase_line_id;
  end if;

  return v_id;
end $$;

-- ------------------------------------------------------------
-- Gap 2a: packaging-material pulls (packaging_issue_items).
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_item_pull()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_department text;
begin
  select department into v_department
  from public.packaging_issues
  where id = new.packaging_issue_id;

  perform public.check_sufficient_stock(new.item_id, new.quantity);

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', new.item_id, new.quantity, new.unit, v_department, 'packaging', new.packaging_issue_id, auth.uid());
  return new;
end $$;
-- trg_packaging_item_pull already points at this function by name —
-- create or replace alone picks up the new body, no trigger redefinition
-- needed.

-- ------------------------------------------------------------
-- Gap 2b: bulk Finished Product consumed transforming into Packaged FP.
-- The packaged_fp_yield push immediately followed by packaged_fp_issue
-- pull (further down in this function, unchanged) always nets to zero
-- within the same transaction — nothing to check there, it can never go
-- negative by construction.
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_transform_and_issue()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_mfr_definition_id uuid;
  v_fp_item_id uuid;
  v_fp_unit text;
  v_pkg_item_id uuid;
begin
  -- Production is explicitly held back for now — see 0032's header and
  -- claude/packaged-fp-redesign.md. Nothing below this line ever runs for
  -- a production issue.
  if new.department not in ('store', 'rnd') then
    return new;
  end if;

  -- Defensive: the server action always sets this for store/rnd issues,
  -- but this trigger never fabricates a pull against a null/zero amount.
  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  select fpb.mfr_definition_id into v_mfr_definition_id
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_fp_item_id
    from public.mfr_definitions md
    where md.id = v_mfr_definition_id;

  -- Graceful skip, same posture as Phase 3's fp_yield trigger: a legacy
  -- MFR with no linked FP item has nothing to transform.
  if v_fp_item_id is null then
    return new;
  end if;

  select unit, packaged_item_id into v_fp_unit, v_pkg_item_id
    from public.items where id = v_fp_item_id;

  -- Graceful skip: the FP item predates this feature's paired-item
  -- backfill, or was never paired for some other reason. Nothing to
  -- transform into — the packaging-material pulls above still happened
  -- normally; only the bulk-FP transform is skipped.
  if v_pkg_item_id is null then
    return new;
  end if;

  -- 1. Pull the bulk Finished Product consumed into this packaging run.
  perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

  -- 2. Push the Packaged Finished Product created — counted in packaged
  --    units (unit_count), not bulk volume.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('push', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_yield', new.id, auth.uid());

  -- 3. Immediately issue it back out. "Always fully issued, one-shot" —
  --    Packaged FP never sits in stock partially issued; on_hand for this
  --    item always nets back to zero right after this insert.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_issue', new.id, auth.uid());

  return new;
end $$;
-- trg_packaging_transform_and_issue already points at this function by
-- name — create or replace alone picks up the new body.

-- ############################################################
-- ## 0034_equipment_master.sql
-- ############################################################

-- ============================================================
-- Instrument / Equipment Master
--
-- Requested per the open-requirements-log gap analysis (12-13 Sept 2026):
-- spec.md lists "Equipment | Instrument ID, Name, Room No, Section,
-- Calibration Status" as a key master-data entity with no equivalent
-- anywhere in the schema. Software Point.docx separately lists "Instrument
-- ID | Name of instrument and ID no" under Master data.
--
-- Seeded from the real legacy inventory: "ROOM WISE INSTRUMENT AND
-- EQUIPMENT ID DEC 2023 FINAL.xlsx" (Sheet1 only — Sheet2 duplicates Room 7
-- and Sheet3 is an unrelated RM/vendor purchase list, both skipped). Per
-- Ravi (13 Sept 2026): this source data is for reference only, not
-- production-critical, so the two-level "type + individually tagged unit"
-- structure in the source sheet is deliberately flattened to one row per
-- line in the sheet — a bare count with no tag becomes one row with that
-- quantity; a tagged physical unit becomes its own row with quantity 1.
-- `calibration_status` has no equivalent anywhere in the source data (it's
-- a spec.md-only ask) and starts null for every seeded row.
-- ============================================================

create sequence public.equipment_code_seq start 1;

create table public.equipment (
  id uuid primary key default gen_random_uuid(),
  equipment_code text not null unique,
  name text not null,
  room_no text,
  section text,
  legacy_asset_id text,
  quantity numeric not null default 1,
  calibration_status text check (calibration_status in ('calibrated', 'due', 'not_applicable')),
  last_calibration_date date,
  next_calibration_due date,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id),
  updated_at timestamptz,
  updated_by uuid references auth.users(id)
);
create trigger trg_equipment_updated before update on public.equipment
  for each row execute function public.set_updated_at();
alter table public.equipment enable row level security;
create policy equipment_select on public.equipment for select using (public.is_signed_in());
-- Insert/update per Ravi's 13 Sept 2026 decision: broader than the plain
-- master-data default (system_admin/inventory_manager/mfr_manager) —
-- equipment lives across QC and production rooms alike, and calibration
-- status is itself a QC concern, so quality_checker/qc_reviewer are
-- included too. Mirrors MODULE_WRITE_ROLES.equipment in roles.ts.
-- Delete is split out and kept admin-only, matching the convention set in
-- 0009_master_data_delete_policy.sql for every other master-data table
-- (items_delete, vendors_delete) — a deliberate tightening, not something
-- to loosen just because this table's write roles are broader.
create policy equipment_insert on public.equipment for insert
  with check (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'));
create policy equipment_update on public.equipment for update
  using (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'))
  with check (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'));
create policy equipment_delete on public.equipment for delete
  using (public.has_any_role('system_admin'));

create or replace function public.get_next_equipment_code()
returns text language sql as $$
  select 'EQ-' || lpad(nextval('public.equipment_code_seq')::text, 4, '0');
$$;

-- Non-consuming preview, same pattern as peek_next_vendor_code() /
-- peek_next_item_code() in 0012_peek_next_codes.sql.
create or replace function public.peek_next_equipment_code()
returns text language sql stable as $$
  select 'EQ-' || lpad(
    (case when is_called then last_value + 1 else last_value end)::text,
    4, '0'
  )
  from public.equipment_code_seq;
$$;

-- ------------------------------------------------------------
-- One-time seed from the legacy room-wise equipment list (304 rows).
-- equipment_code is assigned here directly (EQ-0001..EQ-0304) rather than
-- via get_next_equipment_code(), so the sequence is advanced to match in
