-- ============================================================
-- Dead Stock Register
--
-- Requested per the open-requirements-log gap analysis (12-13 Sept 2026):
-- spec.md 4.3 "Asset Register: Dead Stock Log — track purchase date,
-- original value, and 25% Depreciation to show Balance Value." A real
-- legacy spreadsheet ("Dead Stock Register.xlsx") is on hand, but it
-- contains only a single worked example row (one PC, qty 4, purchased at
-- 40000, 25% depreciated, one unit rejected, three remaining) — a template
-- to build the field set against, not a historical backlog to import. So
-- this migration ships the schema only, with no seed data.
--
-- Per Ravi (13 Sept 2026): balance_qty/balance_value are plain editable
-- fields, not an auto-computed running ledger like Inventory Ledger's
-- push/pull model — this register is reviewed and adjusted by hand a few
-- times a year in practice, so a v1 that mirrors that (enter a rejection,
-- manually update the balance) is lower-risk than building disposal-event
-- triggers for a low-volume module.
--
-- purchase_price is a PER-UNIT price, not a line total — confirmed by
-- reconciling the source sheet's one worked example against its own
-- numbers: Qty 4, Purchase Price 40000, 25% depreciation -> "Value" 30000,
-- Balance Qty 3 -> "Value" 90000. That only holds together if 40000 is the
-- per-unit price (40000 * 0.75 = 30000 depreciated value per unit; 3 *
-- 30000 = 90000 balance value) — a line-total reading (40000 for all 4)
-- does not reconcile. depreciated_unit_value is the one figure that IS
-- computed, since it's a pure function of purchase_price and
-- depreciation_pct with no write-side ambiguity: the value one unit is
-- still worth after applying the depreciation percentage (NOT the amount
-- lost to depreciation). rejected_value/balance_value stay manual, since
-- a written-off unit's value in the source data is a business call (0),
-- not a formula.
-- ============================================================

create sequence public.dead_stock_code_seq start 1;

create table public.dead_stock_items (
  id uuid primary key default gen_random_uuid(),
  asset_code text not null unique,
  article_name text not null,
  date_of_purchase date,
  quantity numeric not null default 1,
  purchase_price numeric, -- per unit, not a line total — see note above
  depreciation_pct numeric not null default 25,
  depreciated_unit_value numeric generated always as (
    round(coalesce(purchase_price, 0) * (100 - coalesce(depreciation_pct, 0)) / 100, 2)
  ) stored,
  resolution_date date,
  rejected_qty numeric not null default 0,
  rejected_value numeric not null default 0,
  balance_qty numeric,
  balance_value numeric,
  remark text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id),
  updated_at timestamptz,
  updated_by uuid references auth.users(id)
);
create trigger trg_dead_stock_items_updated before update on public.dead_stock_items
  for each row execute function public.set_updated_at();
alter table public.dead_stock_items enable row level security;
create policy dead_stock_items_select on public.dead_stock_items for select using (public.is_signed_in());
-- Insert/update role set matches Equipment (Ravi's 13 Sept 2026 decision
-- applied consistently to both new modules) — mirrors
-- MODULE_WRITE_ROLES.dead_stock in roles.ts. Delete is split out and kept
-- admin-only, same convention as 0009_master_data_delete_policy.sql.
create policy dead_stock_items_insert on public.dead_stock_items for insert
  with check (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'));
create policy dead_stock_items_update on public.dead_stock_items for update
  using (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'))
  with check (public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager', 'quality_checker', 'qc_reviewer'));
create policy dead_stock_items_delete on public.dead_stock_items for delete
  using (public.has_any_role('system_admin'));

create or replace function public.get_next_dead_stock_code()
returns text language sql as $$
  select 'DS-' || lpad(nextval('public.dead_stock_code_seq')::text, 4, '0');
$$;

-- Non-consuming preview, same pattern as peek_next_vendor_code() /
-- peek_next_item_code() in 0012_peek_next_codes.sql.
create or replace function public.peek_next_dead_stock_code()
returns text language sql stable as $$
  select 'DS-' || lpad(
    (case when is_called then last_value + 1 else last_value end)::text,
    4, '0'
  )
  from public.dead_stock_code_seq;
$$;

-- ############################################################
-- ## 0036_wastage_batch_required.sql
-- ############################################################

-- ============================================================
-- FB-0033 / FB-0034 (exact duplicates of each other, per the 12 Sept 2026
-- tester triage in claude/feedback-status.md's Fifteenth pass): "In
-- wastage entry, batch number of RM/FP should be compulsory."
--
-- Today the Wastage form's batch (purchase line) field is optional —
-- record_wastage() happily accepts p_purchase_line_id = null, in which
-- case the wastage is only checked against the item's overall on-hand
-- balance (check_sufficient_stock(), 0033_sufficient_stock_check.sql),
-- never tied to a specific received batch. Ravi wants batch selection
-- required going forward, but explicitly NOT retroactively — existing
-- wastage rows recorded without a batch (historical records, predating
-- this change) are left exactly as they are, no backfill, no cleanup.
--
-- THE FIX
-- --------
-- 1. record_wastage() now raises a friendly exception if
--    p_purchase_line_id is null, before doing anything else. This is the
--    real enforcement — RLS's ledger_no_direct_write policy (0001_init.sql,
--    `for insert with check (false)`) already means this
--    security-definer RPC is the ONLY way any code path can insert an
--    inventory_ledger row, so there's no other route into the table to
--    close.
-- 2. A `not valid` CHECK constraint on inventory_ledger, same idiom as
--    0016_quantity_check_constraints.sql and 0029's
--    live_remaining_not_negative: defense-in-depth for the (currently
--    hypothetical) case of a future write path, without scanning or
--    rejecting a single existing row. `not valid` means it only applies
--    to new inserts/updates from here on — every historical wastage row
--    with a null purchase_line_id is grandfathered in untouched, and
--    every non-wastage event_type (push/pull, which legitimately use
--    purchase_line_id in their own ways, including null for some pull
--    types) is unaffected since the constraint only constrains rows
--    where event_type = 'wastage'.
-- ============================================================

alter table public.inventory_ledger
  drop constraint if exists wastage_requires_batch;
alter table public.inventory_ledger
  add constraint wastage_requires_batch
  check (event_type <> 'wastage' or purchase_line_id is not null) not valid;

create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;

  if p_purchase_line_id is null then
    raise exception 'Batch (purchase line) is required to record wastage.';
  end if;

  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by, reason)
  values ('wastage', p_item_id, p_purchase_line_id, p_quantity, p_unit, 'purchase', auth.uid(), p_reason)
  returning id into v_id;

  -- live_remaining_not_negative (0029) is still the real bound on a
  -- batch-tied wastage — unchanged from before this migration.
  update public.purchase_lines
  set live_remaining_qty = live_remaining_qty - p_quantity
  where id = p_purchase_line_id;

  return v_id;
end $$;

-- ############################################################
-- ## 0037_bulk_upload_mfr.sql
-- ############################################################

-- ============================================================
-- Bulk data upload — MFR RPC.
--
-- Ravi (13 Sept 2026): "create a temporary link in admin panel to upload
-- data... as bulk upload" for Item Master, Vendor, Item Type, and MFR
-- (scoped via AskUserQuestion to these four pure master/setup-data
-- modules — no ledger/workflow side effects — with Purchase deliberately
-- left for a later, separately-scoped pass; codes always auto-generated,
-- never taken from the file; all-or-nothing per upload).
--
-- Item Master, Vendor Master and Item Type Master don't need a new
-- migration: each bulk upload is (a) a loop of get_next_item_code()/
-- get_next_vendor_code() RPC calls (already existing, already
-- correct — no new function needed) followed by (b) exactly one
-- ordinary multi-row `insert()` from the app, which Postgres already
-- treats as a single atomic statement — no extra plumbing required for
-- "all rows or none."
--
-- MFR is different: createMfrDefinition() (lib/actions/mfr.ts) already
-- shows why — one MFR is FIVE separate inserts/updates across three
-- tables (Finished Product item → Packaged FP item → pairing update →
-- mfr_definitions → mfr_lines), each with manual best-effort rollback of
-- the others on failure, because the Supabase client gives no real
-- multi-statement transaction. That's an acceptable shape for ONE MFR
-- submitted by hand, but a bulk file can contain many MFRs, and
-- "all-or-nothing across the whole file" done via the same one-call-at-a-
-- time application-layer pattern would mean a failure on MFR #8 leaves
-- MFRs #1-7 already committed — exactly the partial-import outcome
-- Ravi's chosen error-handling model rules out.
--
-- The real fix, matching this project's dominant pattern for multi-step
-- transactional business logic (submit_purchase_order(),
-- reopen_purchase_order(), record_wastage(), check_sufficient_stock()):
-- one `security definer` function that does the whole file's worth of
-- work in a single RPC call. A Postgres function body runs inside the
-- caller's transaction; any RAISE EXCEPTION anywhere in the loop below
-- rolls back every insert the function has done so far in this call —
-- true all-or-nothing across every MFR in the uploaded file, not just
-- within one MFR's own five-step sequence.
--
-- Caveat, same as this project's existing sequence-gap precedent
-- elsewhere (batch-number retries, the standing tolerance noted in
-- claude/known-issues.md): get_next_item_code()/get_next_mfr_code() call
-- nextval() on a real sequence, and sequence advances are NOT
-- transactional in Postgres — they are not undone by a rollback. So a
-- file that fails validation partway through (e.g. MFR #8 of 10) rolls
-- back every row this call inserted, but the code numbers already
-- generated for MFRs #1-8 are still "spent" and will not be reused.
-- This is a cosmetic gap in the code sequence, not a data-integrity
-- issue — exactly the same acceptable tradeoff already made elsewhere in
-- this app.
--
-- This function trusts that the app layer (lib/actions/bulk-upload.ts)
-- has already done the bulk of validation (required fields, numeric
-- ranges, unit/category values, item/item-type existence) before
-- calling it — the checks below are a defensive backstop (matching the
-- project's "app-level + RPC-level + DB constraint" defense-in-depth
-- convention), not the primary validation layer.
-- ============================================================

create or replace function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text, fp_item_code text, packaged_item_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_fp_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_id uuid;
  v_pkg_item_code text;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
begin
  -- Same reason record_wastage()/submit_purchase_order() check roles
  -- explicitly: SECURITY DEFINER bypasses RLS entirely, so the RLS
  -- policies on items/mfr_definitions/mfr_lines are not what's actually
  -- gating this call — this check is. Mirrors MODULE_WRITE_ROLES.mfr
  -- (lib/constants/roles.ts).
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;

    -- 1. Finished Product item — same shape as createMfrDefinition()'s
    --    first insert.
    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_name, 'processed', v_item_type_id, v_batch_unit)
      returning id into v_fp_item_id;

    -- 2. Paired Packaged Finished Product item (Task F) — same as
    --    createMfrDefinition()'s second insert.
    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_name, 'packaged_fp', v_item_type_id, 'count')
      returning id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where id = v_fp_item_id;

    -- 3. MFR definition itself.
    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (code, name, batch_size_qty, batch_size_unit, finished_product_item_id)
      values (v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_fp_item_id)
      returning id into v_def_id;

    -- 4. Recipe lines (version 1 — a bulk-created MFR has no prior
    --    version to increment past, same as a manually-created one).
    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    fp_item_code := v_fp_item_code;
    packaged_item_code := v_pkg_item_code;
    return next;
  end loop;
end $$;

-- No explicit grant needed — 0001_init.sql's
-- `alter default privileges in schema public grant execute on functions
-- to anon, authenticated` already covers every function created after
-- it, functions included (unlike sequences, which do need an explicit
-- grant each time — see 0006_sequence_grants.sql / 0032's
-- item_code_seq_pkgfp grant).

-- ############################################################
-- ## 0038_bulk_upload_purchase.sql
-- ############################################################

-- ============================================================
-- Bulk data upload — Purchase RPC.
--
-- Ravi (13 Sept 2026): "can we have purchase, instrument and dead stock
-- entries done as excel as part of bulk upload utility we created."
-- Purchase was deliberately left out of the original Bulk Data Upload
-- pass (0037_bulk_upload_mfr.sql's header comment) as "a materially more
-- complex multi-table shape... left for a later, separately-scoped
-- pass" — this is that pass. Equipment and Dead Stock need no new
-- migration at all (see lib/actions/bulk-upload.ts): both are flat,
-- single-table master data with no cross-table references, same shape
-- as Vendor Master, so a loop of get_next_equipment_code()/
-- get_next_dead_stock_code() calls followed by one multi-row insert is
-- already atomic — no new RPC required, same reasoning 0037's header
-- comment gives for why Item/Vendor/Item Type Master didn't need one.
--
-- Purchase does, for the same reason MFR did: one purchase order in this
-- app is a header row plus one-or-more line rows (one row = one recipe
-- line for MFR; here, one row = one purchase line), and "all-or-nothing
-- across the whole uploaded file" needs those to land in a single
-- transaction, not one createPurchaseOrder()/createPurchaseLine() call
-- per group from the app layer (a failure on PO #8 would otherwise leave
-- POs #1-7 already committed).
--
-- Scoped with Ravi via AskUserQuestion before writing this: a bulk-
-- uploaded purchase order lands as a Draft, exactly like one entered by
-- hand — nothing in it touches inventory_ledger until someone opens it
-- and clicks Final Submit (submit_purchase_order(), unchanged). This
-- needs zero extra work here beyond simply not calling that function:
-- purchase_orders.status already defaults to 'draft'
-- (0019_purchase_submit_workflow.sql), and the trigger that used to push
-- to the ledger the instant a line was inserted was dropped by that same
-- migration — a plain insert into purchase_lines has had no ledger side
-- effect at all since FB-0018 shipped.
--
-- Same caveats as bulk_create_mfr_definitions (0037), same reasons:
--  - get_next_po_number()/get_next_batch_number() are not undone by a
--    rollback (sequence advances / count()-based batch numbers aren't
--    transactional) — a file that fails partway through leaves the PO/
--    batch numbers already generated before the failing group "spent,"
--    a cosmetic gap only, not a data-integrity issue.
--  - This function trusts the app layer (lib/actions/bulk-upload.ts) has
--    already done the bulk of validation (vendor/item existence and
--    category match, unit validity, QC/Stability/R&D unit conversion,
--    the qc+stability+rnd <= quantity bound) before calling it — the
--    checks below are a defensive backstop, not the primary layer,
--    matching this project's "app-level + RPC-level + DB constraint"
--    defense-in-depth convention. remaining_not_negative (0001_init.sql)
--    and purchase_lines_item_batch_unique (0013_batch_number_integrity.sql)
--    are the real DB-level backstops underneath both layers.
-- ============================================================

create or replace function public.bulk_create_purchase_orders(p_payload jsonb)
returns table(po_number text, invoice_number text, line_count int)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_po jsonb;
  v_line jsonb;
  v_vendor_id uuid;
  v_invoice_number text;
  v_invoice_date date;
  v_lines jsonb;
  v_po_number text;
  v_po_id uuid;
  v_batch_number text;
  v_line_count int;
  v_idx int := 0;
begin
  -- Mirrors MODULE_WRITE_ROLES.purchase (lib/constants/roles.ts) — same
  -- reason every other SECURITY DEFINER write function in this app checks
  -- roles explicitly: SECURITY DEFINER bypasses RLS, so the po_write/
  -- pl_write policies are not what's actually gating this call.
  if not public.has_any_role('system_admin', 'inventory_manager') then
    raise exception 'Not authorized to bulk-create purchase orders.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No purchase orders to create.';
  end if;

  for v_po in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_vendor_id := nullif(v_po->>'vendor_id', '')::uuid;
    v_invoice_number := trim(both from coalesce(v_po->>'invoice_number', ''));
    v_invoice_date := nullif(v_po->>'invoice_date', '')::date;
    v_lines := v_po->'lines';

    if v_vendor_id is null then
      raise exception 'Purchase order #%: vendor is required.', v_idx;
    end if;
    if v_invoice_number = '' then
      raise exception 'Purchase order #%: invoice number is required.', v_idx;
    end if;
    if v_invoice_date is null then
      raise exception 'Purchase order "%": invoice date is required.', v_invoice_number;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'Purchase order "%": needs at least one line.', v_invoice_number;
    end if;

    v_po_number := public.get_next_po_number();
    insert into public.purchase_orders (po_number, vendor_id, invoice_number, invoice_date)
      values (v_po_number, v_vendor_id, v_invoice_number, v_invoice_date)
      returning id into v_po_id;
    -- status defaults to 'draft' and nothing here pushes to
    -- inventory_ledger — see the header comment above.

    v_line_count := 0;
    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'Purchase order "%": every line needs an item, quantity, and unit.', v_invoice_number;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'Purchase order "%": line quantity must be greater than 0.', v_invoice_number;
      end if;

      -- batch_number is always generated here, never trusted from the
      -- file — same rule as every other code column in this feature.
      v_batch_number := public.get_next_batch_number((v_line->>'item_id')::uuid);
      insert into public.purchase_lines
        (purchase_order_id, item_id, batch_number, quantity, unit, qc_qty, stability_qty, rnd_qty, unit_price, gst_pct)
        values (
          v_po_id,
          (v_line->>'item_id')::uuid,
          v_batch_number,
          (v_line->>'quantity')::numeric,
          v_line->>'unit',
          coalesce((v_line->>'qc_qty')::numeric, 0),
          coalesce((v_line->>'stability_qty')::numeric, 0),
          coalesce((v_line->>'rnd_qty')::numeric, 0),
          nullif(v_line->>'unit_price', '')::numeric,
          nullif(v_line->>'gst_pct', '')::numeric
        );
      -- remaining_qty (generated column) and live_remaining_qty
      -- (trg_purchase_line_live_remaining, 0029) both compute themselves
      -- from the row just inserted — nothing else to set here.
      v_line_count := v_line_count + 1;
    end loop;

    po_number := v_po_number;
    invoice_number := v_invoice_number;
    line_count := v_line_count;
    return next;
  end loop;
end $$;

-- No explicit grant needed — see 0037's closing comment (default
-- privileges already cover functions created after 0001_init.sql).

-- ############################################################
-- ## 0039_purge_test_data.sql
-- ############################################################

-- ============================================================
-- Admin "Purge Test Data" utility.
--
-- Ravi (13 Sept 2026): "Create an admin controlled button to Purge all
-- inventory/purchase related data except authentication and similar
-- records so i can do testing from scratch without any historical
-- records" — part of setting up repeatable end-to-end testing for the
-- Purchase/Equipment/Dead-Stock bulk upload feature. Scoped via
-- AskUserQuestion before writing this:
--   - Scope: EVERYTHING except auth-adjacent tables — including master
--     data (Item Master, Vendor Master, Item Type Master, MFR
--     definitions), not just transactional/ledger data. A true blank
--     slate: after purging, a fresh set of Item Master / Vendor Master
--     bulk uploads is what re-populates the app, exactly like a brand
--     new install.
--   - Legacy data: ALSO wiped. The ~92,000 LEG- prefixed rows from the
--     original migration are not preserved by this button (unlike the
--     one-off reset-test-data-2026-09-02.sql script, which deliberately
--     kept them) — Ravi explicitly chose this for a genuinely clean
--     testing baseline.
--   - What's kept: `profiles`, `user_roles` (authentication/access —
--     Ravi's own account and role assignments must survive so the app
--     stays usable immediately after a purge) and `page_feedback` (the
--     tracked tester-feedback ticket history this whole project's audit
--     trail is built from — Ravi confirmed directly: "do not remove
--     feedback/suggestion"). Nothing in `auth.*` (Supabase's own login
--     tables) is touched at all; this function only ever operates on
--     `public.*`.
--
-- Every other table in `public` (22 of them) is purged: bmr_observations,
-- bmr_records, bmr_weighment_lines, coa_records, dead_stock_items,
-- documents, environmental_control_readings, equipment,
-- finished_product_batches, finished_product_components,
-- inventory_ledger, item_types, items, line_clearance_checks,
-- mfr_definitions, mfr_lines, packaging_issue_items, packaging_issues,
-- purchase_lines, purchase_orders, quality_checks, vendors.
--
-- Every code-generating sequence used by those tables is also reset to
-- restart at 1, so the next item/vendor/PO/AR/MFR/equipment/dead-stock
-- code generated after a purge starts clean at *-0001 again — same
-- behavior Ravi confirmed he wanted from the 2 Sept test-data reset.
-- feedback_ticket_seq is deliberately NOT reset, since page_feedback
-- itself is kept and ticket numbers must stay unique/continuous.
--
-- TRUNCATE, not DELETE: this table set has real foreign-key chains
-- (purchase_lines -> purchase_orders, quality_checks -> purchase_lines/
-- finished_product_batches, etc.) — TRUNCATE ... CASCADE handles all of
-- that in one atomic statement regardless of dependency order, which a
-- hand-ordered sequence of DELETEs would be fragile against as the
-- schema evolves. CASCADE only reaches tables that reference the ones
-- listed here; `profiles`/`user_roles`/`page_feedback` only reference
-- `auth.users`, never any table in this purge list, so they are
-- structurally safe from being swept in by CASCADE — confirmed by
-- reading their migrations before writing this, not assumed.
-- ============================================================

create or replace function public.purge_test_data()
returns table(table_name text, rows_purged bigint)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tables text[] := array[
    'bmr_observations', 'bmr_records', 'bmr_weighment_lines', 'coa_records',
    'dead_stock_items', 'documents', 'environmental_control_readings', 'equipment',
    'finished_product_batches', 'finished_product_components', 'inventory_ledger',
    'item_types', 'items', 'line_clearance_checks', 'mfr_definitions', 'mfr_lines',
    'packaging_issue_items', 'packaging_issues', 'purchase_lines', 'purchase_orders',
    'quality_checks', 'vendors'
  ];
  -- feedback_ticket_seq intentionally excluded — page_feedback is kept.
  v_sequences text[] := array[
    'item_code_seq_raw', 'item_code_seq_pkg', 'item_code_seq_fp', 'item_code_seq_pkgfp',
    'vendor_code_seq', 'po_number_seq', 'ar_number_seq', 'mfr_code_seq', 'fp_batch_seq',
    'coa_number_seq', 'equipment_code_seq', 'dead_stock_code_seq'
  ];
  v_tbl text;
  v_seq text;
  v_count bigint;
  v_truncate_list text;
begin
  -- Same role-check convention as every other SECURITY DEFINER write
  -- function in this app: RLS is bypassed by SECURITY DEFINER, so this
  -- explicit check is what's actually gating the call, not table policy.
  -- Admin-only, same as delete/reopen actions — this is far more
  -- destructive than any of those, so it gets at least that same bar.
  if not public.has_any_role('system_admin') then
    raise exception 'Only System Admin can purge test data.';
  end if;

  -- Snapshot row counts BEFORE truncating, since TRUNCATE itself reports
  -- nothing useful — this is what lets the app show a real summary of
  -- what was wiped ("items: 2,317 rows", "purchase_lines: 92,406 rows",
  -- ...) rather than a generic "done."
  foreach v_tbl in array v_tables loop
    execute format('select count(*) from public.%I', v_tbl) into v_count;
    table_name := v_tbl;
    rows_purged := v_count;
    return next;
  end loop;

  select string_agg(format('public.%I', t), ', ') into v_truncate_list from unnest(v_tables) as t;
  execute format('truncate table %s restart identity cascade', v_truncate_list);

  foreach v_seq in array v_sequences loop
    execute format('alter sequence public.%I restart with 1', v_seq);
  end loop;
end $$;

-- No explicit grant needed — see 0037's closing comment (default
-- privileges already cover functions created after 0001_init.sql).

-- ############################################################
-- ## 0040_rename_equipment_asset_id.sql
-- ############################################################

-- ============================================================
-- Rename equipment.legacy_asset_id to asset_id.
--
-- Ravi (14 Sept 2026): "in the instrument template why do we have 'Legacy
-- Asset ID' - this needs to be renamed everywhere 'Asset ID' as this will
-- be used to hold both legacy and new records. Change in all areas
-- screen, internal codes and database tables alike."
--
-- Ravi's initial note said the table was currently blank so this would be
-- a no-impact rename — checked directly against the live data and that
-- wasn't the case (screenshot showed real values: "ANHC/QC/02/205(B1)",
-- "BSDT/RM/02/150K/037", etc.), matching what docs/modules/equipment.md
-- already recorded: 274 of the 304 seeded rows carry a real
-- legacy_asset_id value. Flagged back to Ravi before proceeding — not
-- that it changes anything here, since a plain column RENAME (not a
-- drop/recreate) preserves every existing value byte-for-byte under the
-- new name; there was never a risk of data loss either way.
--
-- The app-facing UI already displayed "Asset ID" everywhere (the equipment
-- list column header, the new/edit form's field label, the read-only
-- detail view) — only the underlying DB column name, the Zod/Server
-- Action field names, and the bulk-upload template's actual column header
-- said "Legacy Asset ID". This migration is the DB half of the rename;
-- see lib/actions/equipment.ts, lib/actions/bulk-upload.ts,
-- lib/bulk-upload/schemas.ts, equipment-table.tsx, equipment-form.tsx,
-- and [id]/page.tsx for the code half (same commit).
-- ============================================================

alter table public.equipment rename column legacy_asset_id to asset_id;

-- ############################################################
-- ## 0041_mfr_deferred_approval.sql
-- ############################################################

-- ============================================================
-- Ravi (14 Sept 2026): "while creating MFR, transaction should be atomic,
-- new MFR, Finished Product or Packaged Finished Product should only get
-- created once MFR is approved otherwise there is no point of creating
-- these."
--
-- Two changes, both scoped via AskUserQuestion before writing this:
--
-- 1. ATOMICITY. createMfrDefinition() (lib/actions/mfr.ts) did up to five
--    separate inserts/updates with manual best-effort .delete() rollback
--    on each failure, "because the Supabase client doesn't give us a real
--    multi-statement transaction" (its own header comment, now removed).
--    That was never a real transaction — a crash between steps (lost
--    connection, function timeout) could leave a partial row behind with
--    no rollback at all. This migration moves both MFR creation and MFR
--    approval into `security definer` RPCs, the same pattern already
--    proven by bulk_create_mfr_definitions() (0037_bulk_upload_mfr.sql):
--    a function body runs inside one real Postgres transaction, so any
--    RAISE EXCEPTION anywhere in it rolls back every insert the call has
--    made so far, including a mid-crash.
--
-- 2. DEFERRED ITEM CREATION. Task F (claude/packaged-fp-redesign.md)
--    deliberately chose to create the paired Finished Product + Packaged
--    FP items "automatically, the moment FP-0001 is created" — eagerly,
--    at MFR-definition time, before any approval. Ravi's request today
--    reverses that specific choice: an MFR that's created but never
--    approved was, under the old design, still burning two item codes
--    (FP-##### / PKG-FP-#####) and leaving two live Item Master rows
--    behind for a recipe nobody signed off on — exactly what he saw
--    happen the time a failed/abandoned MFR draft had to be manually
--    cleaned up (the "draft FP and Finished FP deleted, counter not
--    reset" conversation, same day). Going forward:
--      - create_mfr_definition() creates ONLY mfr_definitions +
--        mfr_lines (version 1). finished_product_item_id stays null.
--      - approve_mfr_definition() is the one and only place a Finished
--        Product / Packaged FP item pair now gets created — the instant
--        an MFR is approved, atomically, in the same transaction as
--        setting approved_by/approved_at.
--      - Re-approving an edited recipe (updateMfrLines() already clears
--        approved_by/approved_at back to null on every edit, forcing
--        re-approval) does NOT create a second item pair —
--        approve_mfr_definition() only creates items the first time
--        finished_product_item_id is still null; on every later
--        (re-)approval it reuses the pair already on file.
--
--    Confirmed via AskUserQuestion (14 Sept 2026):
--      - /finished-product/new's MFR picker now also requires
--        approved_by is not null (app-side change, lib change only —
--        see that page). An unapproved recipe can no longer be used to
--        start production at all, not just "has no item yet."
--      - Bulk-uploaded MFRs (bulk_create_mfr_definitions(),
--        0037_bulk_upload_mfr.sql) get the exact same treatment for
--        consistency: item creation deferred to approval there too.
--        Bulk upload never auto-approves, so every bulk-uploaded MFR now
--        needs a manual Approve click (same screen as any other MFR)
--        before it can be used for production.
--
--    Where the submitted Item Type goes in the meantime: rather than add
--    a new staging column, this reuses mfr_definitions.item_type_id —
--    present since 0001_init.sql, marked deprecated by 0010 once the
--    linked Finished Product item became the source of truth for item
--    type. It's un-deprecated here, repurposed as exactly the "item type
--    to give the Finished Product item once one exists" field: written at
--    create time, read once at approval time to seed the new item, left
--    in place afterward (redundant with the item's own item_type_id post-
--    approval, but harmless — same "don't drop a column that still has a
--    real use" reasoning 0010 itself used).
-- ============================================================

-- ------------------------------------------------------------
-- create_mfr_definition() — replaces createMfrDefinition()'s first four
-- manual steps (FP item, PKG-FP item, pairing, mfr_definitions insert)
-- with just one: the mfr_definitions header (item_type_id stored, not
-- yet applied to any item — there isn't one yet) plus its version-1
-- mfr_lines, both inside one transaction.
-- ------------------------------------------------------------
create or replace function public.create_mfr_definition(
  p_name text,
  p_batch_size_qty numeric,
  p_batch_size_unit text,
  p_item_type_id uuid,
  p_lines jsonb
)
returns table(id uuid, code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := trim(both from coalesce(p_name, ''));
  v_line jsonb;
  v_mfr_code text;
  v_def_id uuid;
begin
  -- Mirrors MODULE_WRITE_ROLES.mfr (lib/constants/roles.ts) — same
  -- reasoning bulk_create_mfr_definitions() gives: security definer
  -- bypasses RLS, so this check is what actually gates the call.
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to create an MFR definition.';
  end if;

  if v_name = '' then
    raise exception 'Name is required.';
  end if;
  if p_batch_size_qty is null or p_batch_size_qty <= 0 then
    raise exception 'Batch size must be greater than 0.';
  end if;
  if p_batch_size_unit is null or p_batch_size_unit = '' then
    raise exception 'Batch size unit is required.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one recipe line.';
  end if;

  -- Same case-insensitive duplicate-name check createMfrDefinition() did
  -- before its first insert — still done first, before the code sequence
  -- is ever touched.
  if exists (select 1 from public.mfr_definitions where name ilike v_name) then
    raise exception '"%" already exists as an MFR.', v_name;
  end if;

  v_mfr_code := public.get_next_mfr_code();

  insert into public.mfr_definitions (code, name, batch_size_qty, batch_size_unit, item_type_id)
    values (v_mfr_code, v_name, p_batch_size_qty, p_batch_size_unit, p_item_type_id)
    returning mfr_definitions.id into v_def_id;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    if (v_line->>'item_id') is null or (v_line->>'quantity') is null
       or v_line->>'unit' is null or v_line->>'unit' = '' then
      raise exception 'Every recipe line needs an item, quantity, and unit.';
    end if;
    if (v_line->>'quantity')::numeric <= 0 then
      raise exception 'Recipe line quantity must be greater than 0.';
    end if;
    insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
      values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
  end loop;

  id := v_def_id;
  code := v_mfr_code;
  return next;
end $$;

-- ------------------------------------------------------------
-- approve_mfr_definition() — the new home for Finished Product / Packaged
-- FP item creation. `for update` locks the row for the duration of the
-- transaction, so two concurrent Approve clicks on the same MFR can't
-- both pass the "not yet approved" check — the loser blocks on the lock,
-- then fails the check once it acquires it, same optimistic-lock outcome
-- approveMfrDefinition() used to get from `.is("approved_by", null)` on
-- its update, just enforced by a real row lock instead of a second
-- round trip.
-- ------------------------------------------------------------
create or replace function public.approve_mfr_definition(p_id uuid)
returns table(fp_item_code text, packaged_item_code text, items_created boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def record;
  v_fp_item_id uuid;
  v_pkg_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_code text;
  v_created boolean := false;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to approve an MFR definition.';
  end if;

  select * into v_def from public.mfr_definitions where mfr_definitions.id = p_id for update;
  if not found then
    raise exception 'MFR definition not found.';
  end if;
  if v_def.approved_by is not null then
    raise exception 'This MFR is already approved.';
  end if;

  if v_def.finished_product_item_id is null then
    -- First-ever approval of this MFR (or of this recipe version's very
    -- first pass) — create the Finished Product + Packaged FP pair now,
    -- same shape createMfrDefinition() used to create eagerly at
    -- MFR-creation time, just moved here.
    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_def.name, 'processed', v_def.item_type_id, v_def.batch_size_unit)
      returning items.id into v_fp_item_id;

    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_def.name, 'packaged_fp', v_def.item_type_id, 'count')
      returning items.id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where items.id = v_fp_item_id;

    update public.mfr_definitions set finished_product_item_id = v_fp_item_id where mfr_definitions.id = p_id;
    v_created := true;
  else
    -- Re-approval after an edit (updateMfrLines() clears approved_by/
    -- approved_at on every recipe change, forcing this path again) —
    -- the item pair already exists from a prior approval. Reuse it
    -- rather than creating a second pair, which the unique constraints
    -- on mfr_definitions.finished_product_item_id and
    -- items.packaged_item_id would reject anyway.
    v_fp_item_id := v_def.finished_product_item_id;
    select item_code, packaged_item_id into v_fp_item_code, v_pkg_item_id
      from public.items where items.id = v_fp_item_id;
    if v_pkg_item_id is not null then
      select item_code into v_pkg_item_code from public.items where items.id = v_pkg_item_id;
    end if;
  end if;

  update public.mfr_definitions
    set approved_by = auth.uid(), approved_at = now()
    where mfr_definitions.id = p_id;

  fp_item_code := v_fp_item_code;
  packaged_item_code := v_pkg_item_code;
  items_created := v_created;
  return next;
end $$;

-- ------------------------------------------------------------
-- bulk_create_mfr_definitions() — same deferral applied to the bulk-
-- upload path, per Ravi's "defer for bulk upload too" answer. Drop first:
-- the return table's column set is changing (fp_item_code/
-- packaged_item_code dropped — nothing in the app reads them, confirmed
-- by grep), and Postgres won't let `create or replace function` change a
-- function's OUT columns in place.
-- ------------------------------------------------------------
drop function if exists public.bulk_create_mfr_definitions(jsonb);

create or replace function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;

    -- Finished Product / Packaged FP items are no longer created here —
    -- see approve_mfr_definition() above. A bulk-uploaded MFR now lands
    -- the same way a manually-created one does: a recipe on file,
    -- unapproved, with no item pair until someone approves it.
    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (code, name, batch_size_qty, batch_size_unit, item_type_id)
      values (v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_item_type_id)
      returning id into v_def_id;

    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    return next;
  end loop;
end $$;

-- No explicit grants needed for any of the three functions above —
-- 0001_init.sql's `alter default privileges ... grant execute on
-- functions to anon, authenticated` already covers every function
-- created after it (see 0037's own closing comment for the same note).

-- ############################################################
-- ## 0042_mfr_code_prefix.sql
-- ############################################################

-- ============================================================
-- Ravi (14 Sept 2026): "MFR Record code should start with MFR-0001 so it
-- is more explicit." get_next_mfr_code() has generated 'F-0001'-style
-- codes since 0001_init.sql — a single letter was ambiguous next to every
-- other module's clearer prefix (RM-/PKG-/FP-/V-/PO-/AR-/COA-/EQ-/DS-).
-- Purely cosmetic: same sequence (mfr_code_seq), same 4-digit padding,
-- only the prefix text changes. Existing mfr_definitions.code values
-- (e.g. the 'F-0001'/'F-0002' created before this migration) are text
-- already stored on those rows and are NOT rewritten — codes are
-- immutable once assigned everywhere else in this app (item codes,
-- vendor codes, etc. are never renumbered retroactively either), so
-- pre-existing MFRs keep their 'F-' codes; only MFRs created from now on
-- get 'MFR-'.
-- ============================================================

create or replace function public.get_next_mfr_code()
returns text language sql as $$
  select 'MFR-' || lpad(nextval('public.mfr_code_seq')::text, 4, '0');
$$;

-- ############################################################
-- ## 0043_mfr_recipe_edit_lock.sql
-- ############################################################

-- ============================================================
-- Ravi (14 Sept 2026), following up on the deferred-approval change
-- (0041_mfr_deferred_approval.sql): "before MFR is approved there should
-- be option to edit recipe 1. Currently An MFR should only have one
-- approved recipe. We will add recipe versioning if required but right
-- now lets not have this as standard feature." — then, scoped further via
-- AskUserQuestion: "for now MFR edit option should only available before
-- approval. Post approval edit should be not allowed. We will revisit if
-- required."
--
-- Two behavior changes from updateMfrLines()'s original design
-- (DESIGN.md §7.4, docs/modules/mfr.md "Versioning — the gap fix"):
--
-- 1. Editing no longer bumps mfr_definitions.version or keeps the
--    previous lines around under an old version number. There is just
--    one current recipe per MFR now — editing replaces it in place. This
--    was already slightly wrong before an MFR had ever been approved
--    (bumping straight to "version 2" for a draft that was never
--    version 1 of anything approved), and Ravi's now saying not to build
--    out the full version-history feature as standard behavior at all,
--    for either case, until/unless it's actually needed later. The
--    `version` column on both tables is left in place (schema-compatible,
--    always 1 going forward) rather than dropped, so real versioning can
--    be turned back on later without another migration.
-- 2. Editing is now blocked entirely once an MFR is approved — not
--    "allowed, but clears the approval," just refused outright. An
--    approved recipe is locked; the only way to change it is to
--    deactivate that MFR and create a new one. This is a tighter rule
--    than before (previously any edit was allowed, at the cost of
--    silently clearing approval) and matches Ravi's explicit
--    "post-approval edit should be not allowed."
--
-- update_mfr_recipe() replaces updateMfrLines()'s old two-step
-- (optimistic-locked version bump, then insert new lines, with a
-- best-effort revert if the insert failed) with one real transaction: a
-- `for update` row lock (blocks a concurrent Approve from landing mid-edit
-- and vice versa — same real-lock upgrade 0041 gave
-- approve_mfr_definition()), the "not approved" guard, then a delete +
-- re-insert of mfr_lines that either both happen or neither does. The old
-- design's failure mode — insert fails after the old lines were already
-- deleted, leaving an empty recipe — is no longer possible.
-- ============================================================

create or replace function public.update_mfr_recipe(p_id uuid, p_lines jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_approved_by uuid;
  v_line jsonb;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to edit an MFR recipe.';
  end if;

  select approved_by into v_approved_by from public.mfr_definitions where id = p_id for update;
  if not found then
    raise exception 'MFR definition not found.';
  end if;
  if v_approved_by is not null then
    raise exception 'This MFR is already approved — the recipe can no longer be edited. Deactivate it and create a new MFR if the recipe needs to change.';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one recipe line.';
  end if;

  delete from public.mfr_lines where mfr_definition_id = p_id;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    if (v_line->>'item_id') is null or (v_line->>'quantity') is null
       or v_line->>'unit' is null or v_line->>'unit' = '' then
      raise exception 'Every recipe line needs an item, quantity, and unit.';
    end if;
    if (v_line->>'quantity')::numeric <= 0 then
      raise exception 'Recipe line quantity must be greater than 0.';
    end if;
    insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
      values (p_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
  end loop;
end $$;

-- ############################################################
-- ## 0044_fp_batch_start_date.sql
-- ############################################################

-- Ravi (15 Sept 2026): "we need to update new batch creation process. A
-- finished product can take few days to get completed. Unless it is
-- completed it is not available in inventory for packaging and to be
-- issued to Store/R&D. also only when the batch process is complete
-- 'Expiry Date' can be associated."
--
-- Two things worth recording up front, confirmed by reading the actual
-- trigger code (not assumed) before writing this migration:
--
-- 1. "RM is deducted from inventory, but FP yield is not added until the
--    batch is complete" is *already* the live behavior, and stricter than
--    asked: finished_product_components inserts (at batch creation) pull
--    raw material immediately via trg_fp_component_live_remaining_pull
--    (0029_purchase_line_live_remaining_qty.sql), but the FP item's own
--    inventory_ledger push doesn't happen at Complete Batch time either —
--    it only happens once the batch's QC record is *approved*
--    (trg_fn_qc_review_finished_product, 0030_finished_product_ledger.sql).
--    So a batch sitting "in_process" (or even "submitted_to_qc") already
--    contributes nothing to stock_balance, and Packaging already can't
--    draw against it. No change needed for this part.
-- 2. The "In Process" status Ravi describes is also already the literal
--    stored status value (finished_product_batches.status = 'in_process',
--    0001_init.sql) — no rename needed.
--
-- What was actually missing: (a) a way to record when a batch's
-- production run started, separate from `created_at` (which is a plain
-- audit timestamp, not a business field a user enters/sees), and (b) the
-- app previously collected `expiry_date` up front in Step 1 of "New
-- Finished Product Batch" — before the batch had even been through a
-- single day of processing — which is exactly what Ravi is pointing out
-- doesn't make sense. The batch's real expiry is only knowable once it's
-- actually finished; that's `expiry_month` (a `date` column despite its
-- name — see complete-batch-form.tsx's existing comment on this), already
-- collected at Complete Batch time. Rather than introduce a third date
-- column, the app-layer change (see lib/actions/finished-product.ts) stops
-- collecting `expiry_date` at creation and stops reading it anywhere;
-- `expiry_month` becomes the one live "Expiry date" for a batch. The old
-- `expiry_date` column is left in place, unused going forward, same
-- non-destructive precedent as updateItem() dropping its old sampling
-- defaults and the FP wastage/total_units/net_qty removal (Seventh pass,
-- claude/known-issues.md) — existing historical batches keep whatever
-- value they already had, nothing is deleted.
alter table public.finished_product_batches
  add column if not exists batch_start_date date;

-- Backfill every existing row (including LEG-FP-... legacy batches) with
-- its own created_at date — the best available, non-guessing stand-in for
-- "when this batch's production run started" for batches that predate
-- this column. Purely informational going forward; nothing downstream
-- keys off it.
update public.finished_product_batches
set batch_start_date = created_at::date
where batch_start_date is null;

-- Defense-in-depth for "once the batch is finished, Finish Date and
-- Expiry Date — along with Batch yield and all three sample quantities —
-- are added together, and all of them are mandatory": the app layer
-- (completeFinishedProductBatch) is the real enforcement (this is a
-- workflow-completeness rule, not something a user should be able to
-- work around via direct API access either), so this mirrors it as a
-- `not valid` CHECK, same idiom as wastage_requires_batch
-- (0036_wastage_batch_required.sql) and every other "required together"
-- rule in this project: applies only to new writes going forward, never
-- scans or rejects an existing row. A batch that only ever set
-- finish_date (impossible going forward once the app change ships, but
-- exactly the shape some in-process legacy/test batches are in today) is
-- untouched by this constraint since it's `not valid`.
alter table public.finished_product_batches
  drop constraint if exists fp_completion_fields_required_together;
alter table public.finished_product_batches
  add constraint fp_completion_fields_required_together
  check (
    finish_date is null or (
      batch_yield is not null and batch_yield > 0 and
      expiry_month is not null and
      qc_sample_qty is not null and qc_sample_qty > 0 and
      stability_qty is not null and stability_qty > 0 and
      rnd_qty is not null and rnd_qty > 0
    )
  ) not valid;

-- ############################################################
-- ## 0045_fp_batch_number_year_reset.sql
-- ############################################################

-- ============================================================
-- Ravi (15 Sept 2026): "suggest suitable name for batch number instead of
-- FP-0003 etc." — get_next_fp_batch_number() (0001_init.sql) generated a
-- flat global sequence (FP-0001, FP-0002, FP-0003, ...) via fp_batch_seq,
-- the only code-generation format in the app that doesn't sort or scan
-- meaningfully by time. Presented four options grounded in the app's
-- existing conventions (year-reset like RM-01/26/PKG-01/26, seq+full-date
-- like AR-001-02092026, date-first daily-reset, or leave as is); Ravi
-- picked the year-reset format.
--
-- New format: FP-<2-digit seq>/<2-digit year>, e.g. the 3rd FP batch
-- created in 2026 is FP-03/26, resetting to 01 each calendar year —
-- matches get_next_batch_number()'s RM-/PKG- pattern (0001_init.sql,
-- prefix logic added in 0023_packaging_purchase_batch_prefix.sql) exactly,
-- except the count is global across all Finished Products rather than
-- per-item: RM/PKG batch numbers are scoped per raw material/packaging
-- item because those items are each purchased repeatedly, but FP batches
-- don't have an equivalent natural per-item bucket Ravi asked to reset
-- by — every finished_product_batches row this year counts, regardless of
-- which MFR product it's for.
--
-- Counted from created_at, which is when get_next_fp_batch_number() is
-- actually called (createFinishedProductBatch, at Step 2/compose submit —
-- i.e. batch start time, see 0044_fp_batch_start_date.sql), same as
-- get_next_batch_number() counts purchase_lines.created_at. This is a
-- count(*)+1, not a real sequence, same as get_next_batch_number() — two
-- concurrent batch creations in the same instant could compute the same
-- number, but finished_product_batches.batch_number is `not null unique`
-- (0001_init.sql), so a genuine race fails the second insert with a
-- constraint violation rather than silently assigning a duplicate code —
-- identical to how purchase_lines_item_batch_unique already backstops
-- get_next_batch_number().
--
-- Purely a function replace, no data migration: existing FP-0001-style
-- batch numbers already assigned to rows are NOT rewritten. Batch numbers
-- are immutable once assigned everywhere else in this app (item codes,
-- vendor codes, MFR codes per 0042_mfr_code_prefix.sql) — pre-existing FP
-- batches keep their old 'FP-0001' style codes; only batches created from
-- now on get the new 'FP-NN/YY' format. fp_batch_seq (0001_init.sql) is
-- left in place, unused — harmless, and 0039_purge_test_data.sql already
-- resets it along with the other sequences on test-data purge.
-- ============================================================

create or replace function public.get_next_fp_batch_number()
returns text language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
begin
  select count(*) + 1 into v_n
  from public.finished_product_batches
  where to_char(created_at, 'YY') = v_year;

  return 'FP-' || lpad(v_n::text, 2, '0') || '/' || v_year;
end $$;

-- ############################################################
-- ## 0046_fp_batch_draft_cancel.sql
-- ############################################################

-- ============================================================
-- Ravi (15 Sept 2026), on the FP batch detail screen (FP-0002
-- screenshot): "there should be a 'Create Batch' Button and a cancel
-- button, till 'Create Batch' is clicked batch should be in draft
-- status and if clicked on cancelled, the batch should be cancelled...
-- Till 'Create Batch' is clicked, 'Complete Batch' Should be disabled or
-- invisible. Only when 'Create Batch' is clicked... batch will move to
-- 'In Progress' state. If batch is in draft state for more than 30 mins,
-- it should automatically cancelled and raw material reserved should be
-- returned back to inventory. A smaller timer should be displayed to
-- remind to create batch."
--
-- Scoped via AskUserQuestion (three open questions):
-- 1. Where "draft" begins — confirmed: the existing compose/Step-2
--    submit (createFinishedProductBatch, lib/actions/finished-product.ts)
--    already pulls RM immediately via finished_product_components inserts
--    (trg_fp_component_pull, 0002_transactions.sql) and lands the user on
--    this exact detail page. That submit now creates the batch in
--    'draft' instead of 'in_process' — RM is pulled at the same moment
--    as before, nothing about that part changes. This detail page gets
--    the new Create Batch / Cancel buttons while status = 'draft'.
-- 2. Ravi initially described manual Cancel as NOT returning RM, but the
--    30-minute auto-cancel AS returning it — flagged as an apparent
--    inconsistency and asked to confirm. Ravi's answer: no, always
--    return RM on any cancel, manual or automatic. So there is exactly
--    one reversal rule, independent of what triggered the cancellation.
-- 3. This app has no scheduled/background job of any kind (checked:
--    no pg_cron, no vercel.json cron, no edge function). Ravi chose the
--    lazy option over adding real cron infrastructure: a stale draft
--    (>30 min old) is only actually flipped to 'cancelled' the next time
--    someone loads the FP list or that batch's detail page. Until then
--    its status row still literally says 'draft' — the on-screen
--    countdown timer (app-side, this migration doesn't need to know
--    about it) is a reminder, not the enforcement.
--
-- WHAT THIS MIGRATION DOES:
-- 1. Widens finished_product_batches.status to add 'draft' and
--    'cancelled', and flips the column default from 'in_process' to
--    'draft' (defense-in-depth backstop matching this app's established
--    pattern of a DB-level default/constraint mirroring an app-level
--    decision — see fp_completion_fields_required_together, 0044).
-- 2. Adds one new inventory_ledger reference_type, 'fp_draft_cancelled',
--    for the reversal push.
-- 3. One new trigger, symmetric to trg_fp_component_pull (which pulls RM
--    for finished_product_components on insert): fires on the
--    draft -> cancelled transition (however it happens — manual Cancel
--    and the lazy auto-expire below both just do the same UPDATE, so one
--    trigger keyed on the status transition covers both, the same shape
--    trg_fn_qc_review_finished_product already uses for its own
--    approved/rejected transition) and, per finished_product_components
--    row on that batch: (a) inserts an offsetting inventory_ledger push
--    (item-level stock_balance, same bookkeeping shape as every other
--    push/pull pair in this app) and (b) — found while verifying
--    locally, easy to miss — ALSO increments that exact purchase line's
--    live_remaining_qty back up, the same maintained column
--    trg_fn_fp_component_live_remaining_pull (0029_purchase_line_live_
--    remaining_qty.sql) decremented at draft-creation time. That column
--    is NOT derived live from inventory_ledger (it's a maintained figure,
--    only moved by specific triggers), so the FP compose picker's FIFO
--    allocation — which reads live_remaining_qty, not the ledger — would
--    still see this stock as unavailable after "cancel" without this
--    second update, even though the ledger-level push above makes
--    item-level stock_balance look correct. Confirmed exactly this gap
--    locally: after adding only the ledger push, live_remaining_qty
--    stayed at its drawn-down figure through a manual cancel; adding this
--    UPDATE fixed it (batch consumed 15kg, live_remaining_qty went
--    50 -> 35 -> 50 through create-draft -> cancel).
-- 4. One new function, expire_stale_fp_drafts() — the lazy check itself.
--    security definer (like every other ledger-writing trigger function
--    in this app) since fp_write (0001_init.sql) is scoped to
--    system_admin/mfr_manager/inventory_manager, and this needs to
--    self-heal for ANY signed-in user who happens to load a stale draft,
--    not just those roles. Called from the FP list and FP detail Server
--    Components before they query batches (app-side change, not in this
--    migration) — a bulk, idempotent UPDATE ... WHERE status = 'draft'
--    AND created_at < now() - 30 minutes, safe to call on every page load
--    by any number of concurrent users.
--
-- Purely additive: no existing finished_product_batches row's status
-- changes, and no existing data is touched. batch_start_date (0044) and
-- everything else on this table is unaffected.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Status: add 'draft' and 'cancelled'; new rows default to 'draft'.
-- ------------------------------------------------------------
alter table public.finished_product_batches
  drop constraint if exists finished_product_batches_status_check;
alter table public.finished_product_batches
  add constraint finished_product_batches_status_check
  check (status in ('draft', 'in_process', 'submitted_to_qc', 'approved', 'rejected', 'cancelled'));
alter table public.finished_product_batches
  alter column status set default 'draft';

-- ------------------------------------------------------------
-- 2. New reference_type for the reversal push.
-- ------------------------------------------------------------
alter table public.inventory_ledger
  drop constraint if exists inventory_ledger_reference_type_check;
alter table public.inventory_ledger
  add constraint inventory_ledger_reference_type_check
  check (reference_type in (
    'purchase', 'qc', 'qc_sample', 'stability_sample', 'rnd_sample', 'finished_product',
    'packaging', 'fp_yield', 'fp_packaging_pull', 'packaged_fp_yield', 'packaged_fp_issue',
    'fp_draft_cancelled'
  ));

-- ------------------------------------------------------------
-- 3. Reversal trigger.
-- ------------------------------------------------------------
create or replace function public.trg_fn_fp_batch_draft_cancel_reversal()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, reference_type, reference_id, event_by)
  select 'push', fpc.item_id, fpc.purchase_line_id, fpc.quantity, 'fp_draft_cancelled', new.id, auth.uid()
  from public.finished_product_components fpc
  where fpc.finished_product_batch_id = new.id;

  update public.purchase_lines pl
  set live_remaining_qty = pl.live_remaining_qty + agg.total_qty
  from (
    select purchase_line_id, sum(quantity) as total_qty
    from public.finished_product_components
    where finished_product_batch_id = new.id
    group by purchase_line_id
  ) agg
  where pl.id = agg.purchase_line_id;

  return new;
end $$;

drop trigger if exists trg_fp_batch_draft_cancel_reversal on public.finished_product_batches;
create trigger trg_fp_batch_draft_cancel_reversal
  after update on public.finished_product_batches
  for each row
  when (old.status = 'draft' and new.status = 'cancelled')
  execute function public.trg_fn_fp_batch_draft_cancel_reversal();

-- ------------------------------------------------------------
-- 4. Lazy 30-minute auto-expire.
-- ------------------------------------------------------------
create or replace function public.expire_stale_fp_drafts()
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.finished_product_batches
  set status = 'cancelled'
  where status = 'draft' and created_at < now() - interval '30 minutes';
end $$;

-- ############################################################
-- ## 0047_fp_batch_complete_awaiting_qc.sql
-- ############################################################

-- ============================================================
-- Ravi (15 Sept 2026), on Finished Product batch completion:
-- "Once I click on complete batch, I should get option to review all
-- information and confirm. In case I want to edit something, there
-- should be a 'Back Button' ... take me to original 'Complete Batch'
-- screen. If Confirmed, the Batch Status should be updated to
-- 'Complete - In QC' from 'In Progress'. Only Once batch is passed
-- QC, it should be marked Complete and available in inventory for
-- packaging."
--
-- Scoped via AskUserQuestion (four open questions):
-- 1. Whether "Complete batch" and "Submit to QC" should merge into one
--    Confirm action — Ravi: keep them separate manual steps, unchanged
--    from today's two-button flow.
-- 2. Whether the new intermediate stage is just a relabel of the
--    existing 'submitted_to_qc' status — Ravi: no, a brand new label,
--    naming it "Complete - Awaiting QC", with the full flow spelled
--    out as Draft -> In Progress -> Complete - Awaiting QC ->
--    Submitted_to_QC -> Complete. So this is a genuinely new, distinct
--    status value sitting between 'in_process' and 'submitted_to_qc',
--    not a display-only rename of either.
-- 3. Whether QC-approved should be relabeled "Complete" in the UI to
--    match the flow diagram's final arrow — Ravi: no, leave it as
--    "approved". (The flow diagram's trailing "-> Complete" is read as
--    describing the FP conceptually becoming complete/available for
--    packaging once QC clears it, not a literal rename of the
--    quality_checks/badge status text — flagged to Ravi in the same
--    reply that ships this migration, per the working agreement to
--    surface scope discoveries rather than silently guess.)
-- 4. What "Back" does on the new review screen — Ravi: keep what was
--    typed (return to the editable Complete Batch form with values
--    intact), never wipe it. This is a client-side-only concern (no
--    review draft is ever persisted to the DB — see completeFinishedProductBatch
--    in lib/actions/finished-product.ts, still only called once, on
--    Confirm) so it needs no schema support here.
--
-- WHAT THIS MIGRATION DOES:
-- Widens finished_product_batches.status to add 'complete_awaiting_qc',
-- inserted in the lifecycle between 'in_process' and 'submitted_to_qc'.
-- Additive only — every existing row's status value is already covered
-- by the pre-existing list, so nothing currently stored changes meaning
-- or needs backfilling. No default change: new batches still start at
-- 'draft' (0046_fp_batch_draft_cancel.sql).
--
-- App-level follow-through (lib/actions/finished-product.ts):
-- completeFinishedProductBatch() now also sets status to
-- 'complete_awaiting_qc' on a successful save (previously it saved the
-- fields but left status untouched at 'in_process'), and
-- submitFinishedProductToQc() now requires status = 'complete_awaiting_qc'
-- instead of 'in_process' to run. The review/confirm screen itself is
-- pure client-side state in complete-batch-form.tsx — nothing about the
-- "Back keeps what was typed" requirement is a database concern.

alter table public.finished_product_batches
  drop constraint if exists finished_product_batches_status_check;

alter table public.finished_product_batches
  add constraint finished_product_batches_status_check
  check (status in ('draft', 'in_process', 'complete_awaiting_qc', 'submitted_to_qc', 'approved', 'rejected', 'cancelled'));

-- ############################################################
-- ## 0048_mfr_procedure.sql
-- ############################################################

-- ============================================================
-- Ravi (16 Sept 2026), via a sample "Master Formula Record" Word document
-- (A. Jatamansi Tail Procedure.docx): "suggest a way to input and store
-- 'MANUFACTURING PROCEDURE' against each MFR." The sample is a Sr.No /
-- Stage / Operation table (Cleaning, Pulverisation, Preparation of Kwath,
-- ... Packing), preceded by a "Weigh/measure all raw materials at
-- production level (Batch size X)" intro line and closed by a
-- "Theoretical Yield = 100%, Permissible yield = NLT 98%" line — none of
-- which the MFR module (mfr_definitions/mfr_lines, the *recipe* only) had
-- anywhere to live before this.
--
-- Confirmed via AskUserQuestion before building:
--   - Entered from the MFR Detail page after the MFR already exists, not
--     bundled into /mfr/new — create_mfr_definition()'s signature and the
--     New MFR screen are untouched.
--   - The yield line is stored as two structured numeric percentages
--     (theoretical_yield_pct / permissible_yield_pct) rather than one
--     free-text line — the sample's "NLT 98%" reads as a not-less-than
--     minimum, so permissible_yield_pct is that threshold, printed as
--     "Permissible yield = NLT {value}%".
--   - Unlike the recipe (mfr_lines, locked once approved — see
--     0043_mfr_recipe_edit_lock.sql), the procedure stays editable at any
--     time, before or after approval: it documents how the batch is made,
--     not the signed-off formula itself, so there's no reason a
--     production-time correction should be blocked just because the MFR
--     is already approved and in use. update_mfr_procedure() below
--     deliberately has no "already approved" guard.
--
-- Shape mirrors mfr_lines: a child table keyed to mfr_definitions, a
-- `version` column (default 1, unused beyond that — same "left in place
-- for possible future versioning" reasoning as mfr_lines, see
-- docs/modules/mfr.md's Versioning section), replace-in-place editing via
-- a security definer RPC. All three new mfr_definitions columns are
-- nullable — additive, no backfill: every existing MFR simply has no
-- procedure until one is entered.
-- ============================================================

alter table public.mfr_definitions
  add column procedure_intro text,
  add column theoretical_yield_pct numeric,
  add column permissible_yield_pct numeric;

create table public.mfr_procedure_steps (
  id uuid primary key default gen_random_uuid(),
  mfr_definition_id uuid not null references public.mfr_definitions(id) on delete cascade,
  version integer not null default 1,
  step_no integer not null,
  stage text not null,
  operation text not null
);

alter table public.mfr_procedure_steps enable row level security;
create policy mfr_procedure_steps_select on public.mfr_procedure_steps for select using (public.is_signed_in());
create policy mfr_procedure_steps_write on public.mfr_procedure_steps for all
  using (public.has_any_role('system_admin', 'mfr_manager'))
  with check (public.has_any_role('system_admin', 'mfr_manager'));

-- ------------------------------------------------------------
-- update_mfr_procedure() — replace-in-place, same delete-and-reinsert-in-
-- one-transaction shape as update_mfr_recipe() (0043_mfr_recipe_edit_lock.sql
-- ), but deliberately WITHOUT that function's "refuse once approved" guard
-- — see the header comment above. Unlike the recipe, an empty procedure
-- (p_steps null/empty) is allowed: the procedure is optional, may not
-- have been entered yet, or may be cleared back to nothing.
-- ------------------------------------------------------------
create or replace function public.update_mfr_procedure(
  p_id uuid,
  p_intro text,
  p_theoretical_yield_pct numeric,
  p_permissible_yield_pct numeric,
  p_steps jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_step jsonb;
  v_idx int := 0;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to edit an MFR procedure.';
  end if;

  if not exists (select 1 from public.mfr_definitions where id = p_id for update) then
    raise exception 'MFR definition not found.';
  end if;

  if p_theoretical_yield_pct is not null and p_theoretical_yield_pct <= 0 then
    raise exception 'Theoretical yield must be greater than 0.';
  end if;
  if p_permissible_yield_pct is not null and p_permissible_yield_pct <= 0 then
    raise exception 'Permissible yield must be greater than 0.';
  end if;

  update public.mfr_definitions
    set procedure_intro = nullif(trim(both from coalesce(p_intro, '')), ''),
        theoretical_yield_pct = p_theoretical_yield_pct,
        permissible_yield_pct = p_permissible_yield_pct
    where id = p_id;

  delete from public.mfr_procedure_steps where mfr_definition_id = p_id;

  if p_steps is not null and jsonb_typeof(p_steps) = 'array' then
    for v_step in select * from jsonb_array_elements(p_steps)
    loop
      v_idx := v_idx + 1;
      if (v_step->>'stage') is null or v_step->>'stage' = ''
         or (v_step->>'operation') is null or v_step->>'operation' = '' then
        raise exception 'Step %: both stage and operation are required.', v_idx;
      end if;
      insert into public.mfr_procedure_steps (mfr_definition_id, version, step_no, stage, operation)
        values (p_id, 1, v_idx, v_step->>'stage', v_step->>'operation');
    end loop;
  end if;
end $$;

-- No explicit grant needed — 0001_init.sql's `alter default privileges
-- ... grant execute on functions to anon, authenticated` already covers
-- every function created after it (see 0037's/0041's own closing note).

-- ############################################################
-- ## 0049_qc_maker_checker.sql
-- ############################################################

-- ============================================================
-- Ravi (17 Sept 2026): "Every QC (Raw material or Finished Product) done
-- should go through maker/checker check — that means should be approved
-- by two people. The Id of both should be captured from the app and the
-- login credentials they have used." Design confirmed via AskUserQuestion
-- before building: maker + one independent checker (not two checkers),
-- System Admin exempt from the maker != checker rule, no re-authentication
-- step (the existing logged-in session is enough).
--
-- The Assign ("maker") / Review ("checker") two-step already existed
-- (0001_init.sql) and quality_checks.created_by already existed in the
-- schema — it was just never written to by any of the three insert paths
-- (RM assign, FP submit-to-QC, retest), so there was no recorded maker
-- identity and nothing stopped the same person from assigning an AR and
-- then reviewing/approving that same AR. This migration adds the
-- database-level backstop; lib/actions/qc.ts and
-- lib/actions/finished-product.ts (this same pass) start actually writing
-- created_by, and lib/actions/qc.ts adds a matching app-level check ahead
-- of it for a clean error message.
--
-- Deliberately a trigger, not a CHECK constraint or RLS WITH CHECK clause:
-- the rule needs to compare the *acting* user (auth.uid(), i.e. whoever is
-- actually running this UPDATE right now) against created_by, which a
-- plain CHECK constraint can't reference (auth.uid() isn't a column of
-- the row) and which — unlike the qc_update RLS policy's static role
-- check — is a per-row, data-dependent decision. Same "database
-- constraint, not a UI convention" posture this module's docs already
-- describe for the QC-gates-consumption trigger.
create or replace function public.trg_fn_qc_enforce_maker_checker()
returns trigger language plpgsql as $$
begin
  -- Only fires on the actual review decision (submitted -> approved/rejected).
  -- created_by is left untouched by this trigger for legacy rows that
  -- predate this fix (no created_by recorded) — there's nothing to compare
  -- against, so those are let through exactly as before rather than
  -- guessing at an identity that was never captured.
  if new.status in ('approved', 'rejected')
     and new.created_by is not null
     and auth.uid() = new.created_by
     and not public.has_any_role('system_admin') then
    raise exception 'The Quality Checker/Reviewer who approves or rejects an AR must be a different person from whoever assigned it.';
  end if;
  return new;
end $$;

create trigger trg_qc_enforce_maker_checker
  before update on public.quality_checks
  for each row execute function public.trg_fn_qc_enforce_maker_checker();

-- ############################################################
-- ## 0050_production_rm_from_packaging.sql
-- ############################################################

-- ============================================================
-- Packaging issued to Production converts Finished Product into a new,
-- standing Raw Material batch another Finished Product's recipe can draw
-- on (Ravi, 19 Sept 2026):
--
--   "when Packaging is issued to production - it would become available
--   as Raw material for another Finished Product... similar to how
--   PKG-FP-00001 is created, we should create a new Raw Material code
--   example RM-FP-00001 when a finished product is issued to Production.
--   In this case the finished Product FP-00001 quantity issued to
--   production will be deducted from inventory and new Raw Material
--   RM-FP-00001 will be added to inventory. There are no packaging items
--   required when a finished product is issued to Production."
--
-- Full design/rationale: claude/packaged-fp-redesign.md's "Packaging
-- issued to Production" addendum. Four decisions confirmed with Ravi via
-- AskUserQuestion before writing this:
--   1. No new QC step — the underlying Finished Product batch was already
--      QC-approved before Packaging could touch it at all; that clearance
--      carries through to the Raw Material it's converted into.
--   2. A new, lightweight batch table (not a synthetic purchase_lines/
--      vendor row) tracks the produced/remaining quantity — keeps
--      Purchase Register/RM Stock reports untouched by internal
--      repackaging.
--   3. This REPLACES the old Production packaging-issue behavior
--      (materials-only, no FP involved) going forward — new Production
--      issues always do the FP -> RM-FP conversion; no packaging
--      materials are required or accepted for a production issue.
--   4. RM-FP-00001 (and its pairing to FP-00001) is created LAZILY, the
--      first time that FP is actually issued to Production — not eagerly
--      at MFR approval, unlike PKG-FP-00001.
--
-- Unlike PKG-FP (always counted in "count", packaging units), RM-FP is a
-- straight same-quantity, same-unit conversion of the bulk Finished
-- Product — no pack-size multiplication, no unit selector.
--
-- Entirely additive: one new nullable self-referencing items column, one
-- new sequence, one new table, two new nullable columns (one each on
-- finished_product_components / inventory_ledger), one new reference_type
-- value, one new item_position column, and targeted `create or replace`
-- rewrites of five existing trigger/gate functions (each already
-- `security definer` / already shared across call sites, so a rewrite
-- picks up the new behavior everywhere it's used with no trigger
-- redefinition needed). No existing row, trigger, or column is altered
-- destructively.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Pairing column: set once, on the bulk FP ('processed') item, to the
--    id of its paired production-sourced Raw Material item. Second slot
--    alongside packaged_item_id (0032) — a bulk FP item can have both a
--    Packaged FP pairing (Store/R&D) and a Production-RM pairing, set
--    independently and lazily.
-- ------------------------------------------------------------
alter table public.items add column if not exists production_rm_item_id uuid references public.items(id);
alter table public.items drop constraint if exists items_production_rm_item_id_unique;
alter table public.items add constraint items_production_rm_item_id_unique unique (production_rm_item_id);
alter table public.items drop constraint if exists items_production_rm_item_id_not_self;
alter table public.items add constraint items_production_rm_item_id_not_self check (production_rm_item_id is null or production_rm_item_id <> id);

-- ------------------------------------------------------------
-- 2. Item code generator for the lazily-created Raw Material item.
--    Deliberately NOT folded into get_next_item_code(p_category) — that
--    function already maps category='raw' to prefix 'RM' for every
--    ordinary, purchased raw material (Item Master / bulk upload), and
--    this item, while genuinely category='raw', needs the distinct
--    'RM-FP' prefix Ravi specified. A dedicated function keeps the two
--    numbering sequences (and their prefixes) from ever colliding.
-- ------------------------------------------------------------
create sequence if not exists public.item_code_seq_rmfp start 1;
grant usage, select on public.item_code_seq_rmfp to anon, authenticated;

create or replace function public.get_next_production_rm_item_code()
returns text language sql as $$
  select 'RM-FP-' || lpad(nextval('public.item_code_seq_rmfp')::text, 5, '0');
$$;

-- ------------------------------------------------------------
-- 3. Batch tracking for Production-sourced Raw Material stock. Plays the
--    same functional role purchase_lines plays for purchased Raw
--    Material (a lot with a live, maintained remaining quantity that
--    Finished Product composition's FIFO allocator draws down) — kept as
--    its own table rather than a synthetic purchase_lines row so
--    Purchase-scoped reports (Purchase Register, RM Stock) never need to
--    filter out internal repackaging.
-- ------------------------------------------------------------
create table public.production_issue_batches (
  id uuid primary key default gen_random_uuid(),
  packaging_issue_id uuid not null references public.packaging_issues(id) on delete cascade,
  item_id uuid not null references public.items(id),
  batch_number text not null,
  quantity numeric not null check (quantity > 0),
  unit text not null,
  live_remaining_qty numeric not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id)
);
create unique index production_issue_batches_item_batch_unique
  on public.production_issue_batches (item_id, batch_number);
alter table public.production_issue_batches
  add constraint production_live_remaining_not_negative check (live_remaining_qty >= 0) not valid;

alter table public.production_issue_batches enable row level security;
create policy production_issue_batches_select on public.production_issue_batches
  for select using (public.is_signed_in());
-- Same "no direct write" shape as inventory_ledger (0001_init.sql,
-- ledger_no_direct_write): every row here is written exclusively by the
-- SECURITY DEFINER trigger below, as a side effect of a Production
-- packaging issue, inside that same transaction.
create policy production_issue_batches_no_direct_write on public.production_issue_batches
  for insert with check (false);

-- Batch numbering, same shape/race-safety idiom as get_next_batch_number
-- (0001_init.sql / 0013_batch_number_integrity.sql): item-scoped,
-- year-suffixed. Always called with the target item's row already locked
-- by the caller (see the trigger below), so — unlike purchase_lines'
-- original count(*)+1 race — two concurrent Production issues against the
-- same Raw Material item can't compute the same batch number here; no
-- separate unique-index-plus-retry backstop is needed the way 0013 needed
-- one for purchase_lines.
create or replace function public.get_next_production_batch_number(p_item_id uuid)
returns text language plpgsql as $$
declare v_year text := to_char(now(), 'YY'); v_n int;
begin
  select count(*) + 1 into v_n from public.production_issue_batches
  where item_id = p_item_id and to_char(created_at, 'YY') = v_year;
  return 'PROD-' || lpad(v_n::text, 2, '0') || '/' || v_year;
end $$;

-- ------------------------------------------------------------
-- 4. finished_product_components can now source a component from either
--    a purchased Raw Material batch (purchase_line_id, unchanged) or a
--    Production-sourced Raw Material batch (production_batch_id, new) —
--    never both, never neither.
-- ------------------------------------------------------------
alter table public.finished_product_components
  alter column purchase_line_id drop not null;
alter table public.finished_product_components
  add column if not exists production_batch_id uuid references public.production_issue_batches(id);
alter table public.finished_product_components
  drop constraint if exists fp_components_exactly_one_source;
alter table public.finished_product_components
  add constraint fp_components_exactly_one_source check (
    (purchase_line_id is not null and production_batch_id is null) or
    (purchase_line_id is null and production_batch_id is not null)
  );

-- ------------------------------------------------------------
-- 5. inventory_ledger gets the same second, alternate reference column —
--    mirrors purchase_line_id so a pull sourced from a Production batch
--    stays traceable back to it, same as a purchase-sourced pull already
--    is. Plus the one new reference_type value for the RM-FP push itself.
-- ------------------------------------------------------------
alter table public.inventory_ledger
  add column if not exists production_batch_id uuid references public.production_issue_batches(id);
alter table public.inventory_ledger
  drop constraint if exists inventory_ledger_reference_type_check;
alter table public.inventory_ledger
  add constraint inventory_ledger_reference_type_check
  check (reference_type in (
    'purchase','qc','qc_sample','stability_sample','rnd_sample','finished_product',
    'packaging','fp_yield','fp_packaging_pull','packaged_fp_yield','packaged_fp_issue',
    'fp_draft_cancelled','production_rm_yield'
  ));

-- ------------------------------------------------------------
-- 6. QC gate (shared by finished_product_components AND
--    bmr_weighment_lines, 0001/0026): skip the QC-approval/retest check
--    entirely when there's no purchase_line_id — a Production-sourced
--    component has nothing to check against (production_issue_batches
--    carries no QC state), and per the confirmed decision above, needs
--    none: the original FP batch's own QC approval already cleared this
--    material before it could be converted. bmr_weighment_lines rows
--    always have a real purchase_line_id (untouched by this migration),
--    so this new branch is a no-op for BMR — only finished_product_
--    components can actually hit it.
-- ------------------------------------------------------------
create or replace function public.check_batch_qc_approved()
returns trigger language plpgsql as $$
declare
  v_status public.purchase_batch_status%rowtype;
begin
  if new.purchase_line_id is null then
    return new;
  end if;

  select * into v_status
  from public.purchase_batch_status
  where purchase_line_id = new.purchase_line_id;

  if v_status.qc_status is distinct from 'approved' then
    raise exception 'Batch (purchase_line_id=%) is not QC-Approved and cannot be consumed', new.purchase_line_id;
  end if;

  if v_status.retest_date is not null and v_status.retest_date <= current_date then
    raise exception 'Batch (purchase_line_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
      new.purchase_line_id, v_status.retest_date;
  end if;

  return new;
end $$;

-- ------------------------------------------------------------
-- 7. finished_product_components -> inventory_ledger pull, and the
--    matching live_remaining_qty decrement, both now branch on which
--    source column is set.
-- ------------------------------------------------------------
create or replace function public.trg_fn_fp_component_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, production_batch_id, quantity, reference_type, reference_id, event_by)
  values
    ('pull', new.item_id, new.purchase_line_id, new.production_batch_id, new.quantity, 'finished_product', new.finished_product_batch_id, auth.uid());
  return new;
end $$;

create or replace function public.trg_fn_fp_component_live_remaining_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.purchase_line_id is not null then
    update public.purchase_lines
    set live_remaining_qty = live_remaining_qty - new.quantity
    where id = new.purchase_line_id;
  else
    update public.production_issue_batches
    set live_remaining_qty = live_remaining_qty - new.quantity
    where id = new.production_batch_id;
  end if;
  return new;
end $$;

-- ------------------------------------------------------------
-- 8. Draft-batch cancel reversal (0046_fp_batch_draft_cancel.sql):
--    reverse whichever source each component actually drew from.
-- ------------------------------------------------------------
create or replace function public.trg_fn_fp_batch_draft_cancel_reversal()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, production_batch_id, quantity, reference_type, reference_id, event_by)
  select 'push', fpc.item_id, fpc.purchase_line_id, fpc.production_batch_id, fpc.quantity, 'fp_draft_cancelled', new.id, auth.uid()
  from public.finished_product_components fpc
  where fpc.finished_product_batch_id = new.id;

  update public.purchase_lines pl
  set live_remaining_qty = pl.live_remaining_qty + agg.total_qty
  from (
    select purchase_line_id, sum(quantity) as total_qty
    from public.finished_product_components
    where finished_product_batch_id = new.id and purchase_line_id is not null
    group by purchase_line_id
  ) agg
  where pl.id = agg.purchase_line_id;

  update public.production_issue_batches pb
  set live_remaining_qty = pb.live_remaining_qty + agg.total_qty
  from (
    select production_batch_id, sum(quantity) as total_qty
    from public.finished_product_components
    where finished_product_batch_id = new.id and production_batch_id is not null
    group by production_batch_id
  ) agg
  where pb.id = agg.production_batch_id;

  return new;
end $$;

-- ------------------------------------------------------------
-- 9. The transform trigger itself. Production now runs a genuinely
--    different transform than Store/R&D (no packaging materials, no
--    "packaged units" concept, no immediate issue-out) — branched inside
--    the same function/trigger rather than a second trigger, since both
--    branches still share the FP-item/unit lookup at the top.
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_transform_and_issue()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_mfr_definition_id uuid;
  v_fp_item_id uuid;
  v_fp_unit text;
  v_pkg_item_id uuid;
  v_rm_item_id uuid;
  v_rm_item_code text;
  v_fp_item_code text;
  v_fp_item_name text;
  v_fp_item_type_id uuid;
  v_batch_number text;
begin
  if new.department not in ('store', 'rnd', 'production') then
    return new;
  end if;

  -- Defensive: the server action always sets this for every department
  -- this trigger now handles, but this trigger never fabricates a pull
  -- against a null/zero amount.
  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  select fpb.mfr_definition_id into v_mfr_definition_id
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_fp_item_id
    from public.mfr_definitions md
    where md.id = v_mfr_definition_id;

  -- Graceful skip, same posture as Phase 3's fp_yield trigger: a legacy
  -- MFR with no linked FP item has nothing to transform.
  if v_fp_item_id is null then
    return new;
  end if;

  if new.department = 'production' then
    -- Lock the FP item row first — it's what carries the
    -- production_rm_item_id pairing pointer, so this single lock
    -- serializes every concurrent Production issue against this same FP
    -- (both the lazy-create-the-RM-item race on the very first issue,
    -- and the batch-numbering race on every issue after that), the same
    -- `for update` idiom check_sufficient_stock()/submit_purchase_order()
    -- already use elsewhere in this app.
    select unit, item_code, name, item_type_id, production_rm_item_id
      into v_fp_unit, v_fp_item_code, v_fp_item_name, v_fp_item_type_id, v_rm_item_id
      from public.items where id = v_fp_item_id for update;

    if v_rm_item_id is null then
      -- First-ever Production issue for this FP — create its paired Raw
      -- Material item now (Ravi, 19 Sept 2026: lazily, on first use, not
      -- eagerly at MFR approval like PKG-FP). Same unit as the bulk FP —
      -- unlike PKG-FP this is a straight quantity/unit conversion, never
      -- counted in "count".
      v_rm_item_code := public.get_next_production_rm_item_code();
      insert into public.items (item_code, name, category, item_type_id, unit)
        values (v_rm_item_code, v_fp_item_name, 'raw', v_fp_item_type_id, v_fp_unit)
        returning id into v_rm_item_id;
      update public.items set production_rm_item_id = v_rm_item_id where id = v_fp_item_id;
    end if;

    -- 1. Pull the Finished Product quantity issued to Production.
    perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

    -- 2. Push the same quantity into the paired Raw Material item — a
    --    straight conversion, same quantity and unit, no packaging-count
    --    transform.
    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('push', v_rm_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'production_rm_yield', new.id, auth.uid());

    -- 3. Unlike Store/R&D's Packaged FP, this stock is NOT immediately
    --    issued back out — it stays on hand as real, available Raw
    --    Material stock. Record it as a new batch so Finished Product
    --    composition's FIFO allocator has something to draw from.
    v_batch_number := public.get_next_production_batch_number(v_rm_item_id);
    insert into public.production_issue_batches
      (packaging_issue_id, item_id, batch_number, quantity, unit, live_remaining_qty, created_by)
    values
      (new.id, v_rm_item_id, v_batch_number, new.fp_qty_consumed, v_fp_unit, new.fp_qty_consumed, auth.uid());

    return new;
  end if;

  -- Store / R&D — unchanged from before this migration.
  select unit, packaged_item_id into v_fp_unit, v_pkg_item_id
    from public.items where id = v_fp_item_id;

  -- Graceful skip: the FP item predates this feature's paired-item
  -- backfill, or was never paired for some other reason. Nothing to
  -- transform into — the packaging-material pulls above still happened
  -- normally; only the bulk-FP transform is skipped.
  if v_pkg_item_id is null then
    return new;
  end if;

  -- 1. Pull the bulk Finished Product consumed into this packaging run.
  perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

  -- 2. Push the Packaged Finished Product created — counted in packaged
  --    units (unit_count), not bulk volume.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('push', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_yield', new.id, auth.uid());

  -- 3. Immediately issue it back out. "Always fully issued, one-shot" —
  --    Packaged FP never sits in stock partially issued; on_hand for this
  --    item always nets back to zero right after this insert.
  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_pkg_item_id, new.unit_count, 'count', new.department, 'packaged_fp_issue', new.id, auth.uid());

  return new;
end $$;
-- trg_packaging_transform_and_issue (0032) already points at this
-- function by name — create or replace alone picks up the new body.

-- ------------------------------------------------------------
-- 10. packaged_qty (finished_product_batches) is specifically "how much
--     of this batch has been packaged into materials for distribution" —
--     a Production conversion involves no packaging materials at all, so
--     it should not bump this counter the way a real Store/R&D pack event
--     does. (packaged_qty has no UI consumer today — grepped, nothing
--     reads it yet — so this is a correctness fix ahead of a future
--     reader, not a behavior change anyone would see right now.)
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_pull()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.department <> 'production' then
    update public.finished_product_batches
      set packaged_qty = packaged_qty +
        case new.transaction_type when 'unpack' then -new.unit_count else new.unit_count end
      where id = new.finished_product_batch_id;
  end if;
  return new;
end $$;
-- trg_packaging_pull (0002/0027) already points at this function by
-- name — create or replace alone picks up the new body.

-- ------------------------------------------------------------
-- 11. item_position: one more additive column for the new push bucket,
--     same pattern 0032 used (new columns appended at the end only,
--     `create or replace view` requires every existing column to keep
--     its exact name/type/position). Consumption of a Production-sourced
--     Raw Material batch (by a later Finished Product) is already
--     covered by the existing consumed_by_fp bucket — it's the same
--     reference_type ('finished_product') regardless of which source
--     column the component drew from, so no change is needed there.
-- ------------------------------------------------------------
create or replace view public.item_position as
select
  i.id as item_id,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'purchase' then l.quantity else 0 end), 0) as received,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'fp_yield' then l.quantity else 0 end), 0) as yielded,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type in ('qc', 'qc_sample') then l.quantity else 0 end), 0) as held_qc,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'stability_sample' then l.quantity else 0 end), 0) as held_stability,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'rnd_sample' then l.quantity else 0 end), 0) as held_rnd,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'finished_product' then l.quantity else 0 end), 0) as consumed_by_fp,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaging' then l.quantity else 0 end), 0) as issued_packaging,
  coalesce(sum(case when l.event_type = 'wastage' then l.quantity else 0 end), 0) as wastage,
  coalesce(sum(case l.event_type when 'push' then l.quantity when 'wastage' then -l.quantity else -l.quantity end), 0) as on_hand,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'fp_packaging_pull' then l.quantity else 0 end), 0) as consumed_by_packaging,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'packaged_fp_yield' then l.quantity else 0 end), 0) as packaged_yield,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'store' then l.quantity else 0 end), 0) as issued_store,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'rnd' then l.quantity else 0 end), 0) as issued_rnd,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'production_rm_yield' then l.quantity else 0 end), 0) as production_rm_yield
from public.items i
left join public.inventory_ledger l on l.item_id = i.id
group by i.id;

-- ############################################################
-- ## 0051_batch_number_embed_item_code.sql
-- ############################################################

-- ============================================================
-- Embed the item code in generated batch numbers.
--
-- get_next_batch_number(p_item_id) (0001_init.sql, category-prefix
-- revision in 0023_packaging_purchase_batch_prefix.sql) has always scoped
-- its sequence per (item_id, year) but labeled every item with the same
-- bare "<category-prefix>-<seq>/<year>" string — e.g. "RM-01/26". That
-- means any two raw-material items' first purchase of a year collide on
-- the exact same batch number text (item_id is still what's actually
-- unique — see purchase_lines_item_batch_unique, 0013 — so nothing was
-- ever ambiguous in the data; it only read as a collision on screen).
-- Flagged by Ravi from the live Awaiting QC list (RM-00001 and RM-00002
-- both showing "RM-01/26"); this was confirmed working-as-designed, and
-- Ravi asked for the batch number itself to be unique/self-identifying
-- rather than just the underlying row.
--
-- Fix: fold the item's own item_code (already globally unique, already
-- the format users recognize from Item Master: RM-00001 / PKG-00001) into
-- the batch number in place of the plain category prefix. New format:
--   <item_code>-<seq>/<year>   e.g. "RM-00001-01/26", "PKG-00006-03/26"
-- instead of the old "RM-01/26" / "PKG-03/26".
--
-- Purely a function replace, same signature, same per-(item,year)
-- counting logic (unchanged, so this doesn't renumber or reset any
-- existing sequence) — only the label format changes. No data migration:
-- every batch number already issued (including legacy 'LEG-%' rows, which
-- this function never touches) is left exactly as stored. Every caller
-- (lib/actions/purchase.ts createPurchaseLine, and bulk_create_purchase_
-- orders in 0038_bulk_upload_purchase.sql) goes through this one RPC and
-- treats the result as an opaque string, so no app-side code needs to
-- change. purchase_lines_item_batch_unique (0013) stays keyed on
-- (item_id, batch_number) — still correct, just now also incidentally
-- globally unique since item_code is embedded.
--
-- Scope note: get_next_fp_batch_number() and the production-batch
-- numbering added in 0050_production_rm_from_packaging.sql are separate
-- functions, not touched here — Ravi's report was specifically about
-- purchase/raw-material batch numbers. Flagging in chat, not folding in
-- silently: worth a separate look if the same visual-collision question
-- applies there too.
-- ============================================================

create or replace function public.get_next_batch_number(p_item_id uuid)
returns text language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_item_code text;
begin
  select item_code into v_item_code from public.items where id = p_item_id;

  select count(*) + 1 into v_n from public.purchase_lines
  where item_id = p_item_id and to_char(created_at, 'YY') = v_year;

  return v_item_code || '-' || lpad(v_n::text, 2, '0') || '/' || v_year;
end $$;

-- ############################################################
-- ## 0052_batch_number_no_truncate_over_99.sql
-- ############################################################

-- ============================================================
-- Fix a latent truncation bug in get_next_batch_number(), found by
-- Ravi asking "what happens if in a year the batch number reaches
-- RM-00001-99/26?" right after the 0051 migration shipped.
--
-- 0051 (and, before it, the original 0001_init.sql /
-- 0023_packaging_purchase_batch_prefix.sql) formatted the per-item/year
-- sequence with `lpad(v_n::text, 2, '0')`. Postgres's lpad() TRUNCATES
-- its input when it's already longer than the target width (confirmed
-- directly: `lpad('100', 2, '0')` returns '10', not '100') — it does not
-- just skip padding. So the 100th purchase of the same item in the same
-- calendar year would silently compute the exact same batch-number
-- string as that item's real 10th purchase of the year: '10/26' either
-- way. In practice this wouldn't corrupt data — the
-- purchase_lines_item_batch_unique index (0013) would reject the insert
-- with a 23505 — but createPurchaseLine()'s retry logic recomputes the
-- identical wrong value every time (the count hasn't changed), so it
-- would retry 3 times and then fail outright with a generic duplicate-
-- batch error, with nothing pointing at the real cause.
--
-- Fix: pad to *at least* 2 digits instead of *exactly* 2 digits, via
-- `greatest(2, length(v_n::text))` as the lpad width. Every value under
-- 100 renders byte-for-byte identically to before (09, 42, 99); 100 and
-- above now render as the real number (100, 101, ...) instead of being
-- cut down to 2 digits. Confirmed directly against local Postgres:
-- lpad('9',2,'0')='09', lpad('99',2,'0')='99' (unchanged),
-- lpad('100', greatest(2,3), '0') = '100', lpad('101', greatest(2,3),
-- '0') = '101' (fixed, no collision).
--
-- Purely a function replace, same signature, no data migration, no
-- schema change — every batch number already issued stays exactly as
-- stored (none of them were ever >= 100 within one item/year, so none of
-- them could have hit the bug this closes). Same callers as 0051
-- (lib/actions/purchase.ts createPurchaseLine, bulk_create_purchase_
-- orders in 0038_bulk_upload_purchase.sql) — opaque string, no app-code
-- change needed.
-- ============================================================

create or replace function public.get_next_batch_number(p_item_id uuid)
returns text language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_item_code text;
begin
  select item_code into v_item_code from public.items where id = p_item_id;

  select count(*) + 1 into v_n from public.purchase_lines
  where item_id = p_item_id and to_char(created_at, 'YY') = v_year;

  return v_item_code || '-' || lpad(v_n::text, greatest(2, length(v_n::text)), '0') || '/' || v_year;
end $$;

-- ############################################################
-- ## 0064_fix_bulk_create_mfr_definitions_replay.sql
-- ############################################################

-- ============================================================
-- Fixes a latent bug in the migration history, found (not caused) while
-- verifying migration 0063 — flagged to Ravi and fixed at his request
-- (27 Sept 2026), unrelated to FB-0039/0063's own change.
--
-- 0037_bulk_upload_mfr.sql originally created bulk_create_mfr_definitions()
-- returning 4 columns (mfr_name, mfr_code, fp_item_code, packaged_item_code).
-- 0041_mfr_deferred_approval.sql needed to drop the item-code columns
-- (item creation moved to approve_mfr_definition()) and correctly did
-- `drop function if exists ...` before recreating it with just 2 columns
-- (mfr_name, mfr_code) — Postgres requires the drop whenever a function's
-- OUT/return-table columns change; plain CREATE OR REPLACE can't do it.
-- 0053_bulk_upload_mfr_procedure.sql then needed to go back to 4 columns
-- (adding fp_item_code/packaged_item_code back, since bulk MFR creation
-- reverted to eager item creation) but used a plain `create or replace
-- function` with no drop first.
--
-- On a fresh database, replaying every migration in strict order (0001
-- through the latest) fails at 0053 with:
--   ERROR: cannot change return type of existing function
--   DETAIL: Row type defined by OUT parameters is different.
--   HINT: Use DROP FUNCTION bulk_create_mfr_definitions(jsonb) first.
-- confirmed by actually doing that replay, locally, against Postgres 16,
-- while verifying 0063.
--
-- This migration is a pure repair of that replay path — not a behavior
-- change. The function body below is byte-for-byte the same as 0053's
-- (itself unchanged since), just preceded by the DROP that migration
-- should have had. Run on a database that already has the 4-column
-- version live (drop + immediate recreate with the same signature), it's
-- a no-op; run during a fresh from-scratch replay, it's what lets 0053
-- (and everything after it, including 0063) actually apply.
-- ============================================================

drop function if exists public.bulk_create_mfr_definitions(jsonb);

create or replace function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text, fp_item_code text, packaged_item_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_step jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_steps jsonb;
  v_procedure_intro text;
  v_theoretical_yield_pct numeric;
  v_permissible_yield_pct numeric;
  v_fp_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_id uuid;
  v_pkg_item_code text;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
  v_step_idx int;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';
    v_steps := v_def->'procedure_steps';
    v_procedure_intro := nullif(trim(both from coalesce(v_def->>'procedure_intro', '')), '');
    v_theoretical_yield_pct := nullif(v_def->>'theoretical_yield_pct', '')::numeric;
    v_permissible_yield_pct := nullif(v_def->>'permissible_yield_pct', '')::numeric;

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;
    if v_theoretical_yield_pct is not null and v_theoretical_yield_pct <= 0 then
      raise exception 'MFR "%": theoretical yield must be greater than 0.', v_name;
    end if;
    if v_permissible_yield_pct is not null and v_permissible_yield_pct <= 0 then
      raise exception 'MFR "%": permissible yield must be greater than 0.', v_name;
    end if;

    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_name, 'processed', v_item_type_id, v_batch_unit)
      returning id into v_fp_item_id;

    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_name, 'packaged_fp', v_item_type_id, 'nos')
      returning id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where id = v_fp_item_id;

    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (
      code, name, batch_size_qty, batch_size_unit, finished_product_item_id,
      procedure_intro, theoretical_yield_pct, permissible_yield_pct
    )
      values (
        v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_fp_item_id,
        v_procedure_intro, v_theoretical_yield_pct, v_permissible_yield_pct
      )
      returning id into v_def_id;

    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    if v_steps is not null and jsonb_typeof(v_steps) = 'array' and jsonb_array_length(v_steps) > 0 then
      v_step_idx := 0;
      for v_step in select * from jsonb_array_elements(v_steps)
      loop
        v_step_idx := v_step_idx + 1;
        if (v_step->>'stage') is null or v_step->>'stage' = ''
           or (v_step->>'operation') is null or v_step->>'operation' = '' then
          raise exception 'MFR "%": procedure step % needs both a stage and an operation.', v_name, v_step_idx;
        end if;
        insert into public.mfr_procedure_steps (mfr_definition_id, version, step_no, stage, operation)
          values (v_def_id, 1, v_step_idx, v_step->>'stage', v_step->>'operation');
      end loop;
    end if;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    fp_item_code := v_fp_item_code;
    packaged_item_code := v_pkg_item_code;
    return next;
  end loop;
end $$;

-- ############################################################
-- ## 0053_bulk_upload_mfr_procedure.sql
-- ############################################################

-- ============================================================
-- Bulk data upload — MFR RPC, extended for Manufacturing Process.
--
-- Ravi (20 Sept 2026): "do similar changes in MFR template. ... Also
-- include template to upload 'Manufacturing Process' along with recipe."
-- The app-layer bulk-upload template/parser (lib/bulk-upload/schemas.ts,
-- templates.ts, lib/actions/bulk-upload.ts) now lets one flat file carry,
-- per MFR group, both recipe lines (as before) and Manufacturing Process
-- rows (Procedure Intro / Theoretical Yield % / Permissible Yield % as
-- header-level fields, plus Stage/Operation per procedure-step row) — the
-- same fields update_mfr_procedure() (0048_mfr_procedure.sql) already
-- persists for the one-MFR-at-a-time UI flow.
--
-- bulk_create_mfr_definitions() (0037_bulk_upload_mfr.sql) doesn't know
-- about that schema at all yet: without this migration, the extra
-- procedure_intro/theoretical_yield_pct/permissible_yield_pct/
-- procedure_steps keys the app now sends would simply be ignored by the
-- JSONB payload reader below, so Manufacturing Process data typed into
-- the bulk template would silently fail to save even though the upload
-- itself reports success. This migration closes that gap by teaching the
-- same all-or-nothing RPC to also read and persist those fields, mirroring
-- update_mfr_procedure()'s exact validation:
--   - theoretical_yield_pct / permissible_yield_pct, if provided, must be
--     greater than 0;
--   - every procedure step needs both stage and operation, non-blank;
--   - the procedure is optional — an MFR with no procedure_steps (and no
--     intro/yields) is inserted exactly as it always has been.
-- Everything else about the function (recipe-lines handling, the FP/
-- packaged-FP/mfr_definitions insert sequence, the role check, the
-- sequence-advance caveat) is unchanged from 0037.
-- ============================================================

create or replace function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text, fp_item_code text, packaged_item_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_step jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_steps jsonb;
  v_procedure_intro text;
  v_theoretical_yield_pct numeric;
  v_permissible_yield_pct numeric;
  v_fp_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_id uuid;
  v_pkg_item_code text;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
  v_step_idx int;
begin
  -- Same reason record_wastage()/submit_purchase_order() check roles
  -- explicitly: SECURITY DEFINER bypasses RLS entirely, so the RLS
  -- policies on items/mfr_definitions/mfr_lines/mfr_procedure_steps are
  -- not what's actually gating this call — this check is. Mirrors
  -- MODULE_WRITE_ROLES.mfr (lib/constants/roles.ts).
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';
    v_steps := v_def->'procedure_steps';
    v_procedure_intro := nullif(trim(both from coalesce(v_def->>'procedure_intro', '')), '');
    v_theoretical_yield_pct := nullif(v_def->>'theoretical_yield_pct', '')::numeric;
    v_permissible_yield_pct := nullif(v_def->>'permissible_yield_pct', '')::numeric;

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;
    -- Same bounds update_mfr_procedure() enforces for the one-at-a-time
    -- UI flow — kept here too since this RPC is a defensive backstop,
    -- not just a pass-through of app-layer-validated data.
    if v_theoretical_yield_pct is not null and v_theoretical_yield_pct <= 0 then
      raise exception 'MFR "%": theoretical yield must be greater than 0.', v_name;
    end if;
    if v_permissible_yield_pct is not null and v_permissible_yield_pct <= 0 then
      raise exception 'MFR "%": permissible yield must be greater than 0.', v_name;
    end if;

    -- 1. Finished Product item — same shape as createMfrDefinition()'s
    --    first insert.
    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_name, 'processed', v_item_type_id, v_batch_unit)
      returning id into v_fp_item_id;

    -- 2. Paired Packaged Finished Product item (Task F) — same as
    --    createMfrDefinition()'s second insert.
    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_name, 'packaged_fp', v_item_type_id, 'count')
      returning id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where id = v_fp_item_id;

    -- 3. MFR definition itself, now including the optional Manufacturing
    --    Process header fields (procedure_intro / theoretical_yield_pct /
    --    permissible_yield_pct — same three columns 0048_mfr_procedure.sql
    --    added, all nullable).
    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (
      code, name, batch_size_qty, batch_size_unit, finished_product_item_id,
      procedure_intro, theoretical_yield_pct, permissible_yield_pct
    )
      values (
        v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_fp_item_id,
        v_procedure_intro, v_theoretical_yield_pct, v_permissible_yield_pct
      )
      returning id into v_def_id;

    -- 4. Recipe lines (version 1 — a bulk-created MFR has no prior
    --    version to increment past, same as a manually-created one).
    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    -- 5. Manufacturing Process steps (version 1, step_no by array order —
    --    same shape update_mfr_procedure() writes, optional: an MFR with
    --    no procedure_steps simply gets none, same as today).
    if v_steps is not null and jsonb_typeof(v_steps) = 'array' and jsonb_array_length(v_steps) > 0 then
      v_step_idx := 0;
      for v_step in select * from jsonb_array_elements(v_steps)
      loop
        v_step_idx := v_step_idx + 1;
        if (v_step->>'stage') is null or v_step->>'stage' = ''
           or (v_step->>'operation') is null or v_step->>'operation' = '' then
          raise exception 'MFR "%": procedure step % needs both a stage and an operation.', v_name, v_step_idx;
        end if;
        insert into public.mfr_procedure_steps (mfr_definition_id, version, step_no, stage, operation)
          values (v_def_id, 1, v_step_idx, v_step->>'stage', v_step->>'operation');
      end loop;
    end if;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    fp_item_code := v_fp_item_code;
    packaged_item_code := v_pkg_item_code;
    return next;
  end loop;
end $$;

-- No explicit grant needed — 0001_init.sql's
-- `alter default privileges in schema public grant execute on functions
-- to anon, authenticated` already covers every function created after
-- it (see 0037's/0048's own closing note).

-- ############################################################
-- ## 0054_qc_two_round_review.sql
-- ############################################################

-- ============================================================
-- QC two-round review (20 Sept 2026).
--
-- Ravi: "In QC, the first round of approval will be given by Quality
-- Checker, He will put his comments and will hit on approve or reject
-- button. If rejected, Raw Material Batch will be Rejected. If approved,
-- it will show as approved - Awaiting Review and will be moved from QC
-- Checker's queue to QC Reviewer's queue. It will go through same cycle
-- and One QC Reviewer approves it, the batch will be shown as Fully QC
-- approved and will be added to Inventory." Confirmed via AskUserQuestion
-- (then a follow-up correction) before building:
--   - Applies to every QC record, Raw Material or Finished Product alike
--     (matches Ravi's earlier maker/checker instruction's own scope).
--   - A Retest AR goes through the same two-round cycle, not a shortened
--     one — it's still a real QC decision on a batch already in use.
--   - No separate "assignee/maker" identity to enforce any more — Ravi's
--     own correction: "there is no need for the assignee role, 2 roles
--     suffice: Reviewer 1 - QC Checker (dont call it maker), Reviewer 2 -
--     QC Reviewer (dont call it checker)." This RETIRES
--     0049_qc_maker_checker.sql's created_by-vs-reviewer rule entirely —
--     whoever assigned/created the AR may now go on to be its own Round 1
--     QC Checker. The real separation-of-duties rule going forward is
--     Round 1 (QC Checker) actor ≠ Round 2 (QC Reviewer) actor.
--
-- Design, reusing as much of the existing single-decision shape as
-- possible rather than a bigger rebuild:
--   - `status` gains one new intermediate value, 'checker_approved' ("
--     Approved - Awaiting Review"), sitting between 'submitted' and the
--     existing terminal 'approved'/'rejected'. 'approved' KEEPS its
--     existing meaning ("fully, finally cleared") unchanged — this is
--     deliberate: check_batch_qc_approved() (the trigger that gates FP
--     composition/BMR consumption), purchase_batch_status, the RM Report's
--     computeBatchQcState(), retest eligibility, and every place across
--     the app that already reads status = 'approved' to mean "usable
--     stock" all keep working correctly with ZERO changes, since that's
--     still exactly when a batch actually becomes usable — now just one
--     step later in the flow (after Round 2, not Round 1).
--   - Round 1 (QC Checker) writes NEW columns `checker_by` / `checker_at`
--     / `checker_comments` — mirrors the shape `reviewed_by`/`reviewed_at`
--     /`review_comments` already had for the single decision.
--   - Round 2 (QC Reviewer) reuses the EXISTING `reviewed_by`/`reviewed_at`
--     /`review_comments`/`retest_period_days`/`retest_date` columns —
--     they already meant "the final decision," which remains true; this
--     avoids renaming columns half the app already reads (finished-
--     product.ts trigger, reports, the retest workflow's own
--     trg_fn_qc_compute_retest_date). Retest period is only asked at
--     Round 2 now (matches Ravi's description — the Checker's round just
--     approves/rejects with comments, no retest period field), which also
--     naturally fixes the earlier design's slight mismatch: the batch
--     isn't actually usable/retestable until Round 2 clears it anyway.
-- ============================================================

-- 1. Widen the status check constraint to allow the new intermediate value.
alter table public.quality_checks
  drop constraint quality_checks_status_check;
alter table public.quality_checks
  add constraint quality_checks_status_check
  check (status in ('submitted', 'checker_approved', 'approved', 'rejected'));

-- 2. Round 1 (QC Checker) decision columns — additive, nullable, no
--    backfill: every quality_checks row that predates this migration went
--    through the old single-decision flow and has nothing meaningful to
--    put here.
alter table public.quality_checks
  add column checker_by uuid references auth.users(id),
  add column checker_at timestamptz,
  add column checker_comments text;

-- 3. Widen the "at most one active (unresolved) AR per batch" partial
--    unique index (0025_qc_retest_workflow.sql) to also cover
--    'checker_approved' — a batch sitting in Round 1 limbo shouldn't be
--    startable as a second concurrent AR any more than a freshly
--    'submitted' one should.
drop index if exists public.quality_checks_purchase_line_pending_unique;
create unique index quality_checks_purchase_line_pending_unique
  on public.quality_checks (purchase_line_id)
  where status in ('submitted', 'checker_approved');

-- 4. Retire the old maker≠checker trigger (0049_qc_maker_checker.sql) —
--    Ravi's correction above: no assignee-identity rule any more. Replace
--    with the real two-round rule: each round needs its own matching
--    role, and Round 2's actor must differ from Round 1's (System Admin
--    exempt from the distinctness half, same exemption 0049 already had).
--    Deliberately a trigger, not just an RLS/app check, for the same
--    "database constraint, not UI convention" reason 0049's own header
--    comment gives — auth.uid() (the row's *acting* user) isn't something
--    a plain CHECK constraint or RLS USING clause can reference per-row.
drop trigger if exists trg_qc_enforce_maker_checker on public.quality_checks;
drop function if exists public.trg_fn_qc_enforce_maker_checker();

create or replace function public.trg_fn_qc_enforce_review_stages()
returns trigger language plpgsql as $$
begin
  -- Round 1: submitted -> checker_approved/rejected. Needs the Quality
  -- Checker role (System Admin exempt-in, same as everywhere else in this
  -- app's role model).
  if old.status = 'submitted' and new.status in ('checker_approved', 'rejected') then
    if not public.has_any_role('system_admin', 'quality_checker') then
      raise exception 'Only a Quality Checker (or System Admin) can make the first QC decision.';
    end if;
  end if;

  -- Round 2: checker_approved -> approved/rejected. Needs the QC Reviewer
  -- role, and must be a different person from whoever made the Round 1
  -- decision (System Admin exempt from the distinctness half only).
  if old.status = 'checker_approved' and new.status in ('approved', 'rejected') then
    if not public.has_any_role('system_admin', 'qc_reviewer') then
      raise exception 'Only a QC Reviewer (or System Admin) can make the final QC decision.';
    end if;
    if new.checker_by is not null
       and auth.uid() = new.checker_by
       and not public.has_any_role('system_admin') then
      raise exception 'The QC Reviewer who makes the final decision must be a different person from the Quality Checker who made the first one.';
    end if;
  end if;

  return new;
end $$;

create trigger trg_qc_enforce_review_stages
  before update on public.quality_checks
  for each row execute function public.trg_fn_qc_enforce_review_stages();

-- 5. trg_qc_review_finished_product (0030_finished_product_ledger.sql)
--    only fired its ledger-push/status-sync when the PREVIOUS status was
--    'submitted' — correct back when 'submitted' was the only status a
--    real decision could be made from. Now the real (Round 2, final)
--    decision can also be made from 'checker_approved'. Function body is
--    unchanged (it already only pushes to inventory_ledger when
--    new.status = 'approved', and already no-ops otherwise) — only the
--    WHEN clause needs widening so it actually fires on that second
--    transition. Round 1's own submitted -> checker_approved transition
--    still correctly never fires this (new.status isn't in
--    ('approved','rejected')), so finished_product_batches.status is
--    untouched during Round 1 — it stays 'complete_awaiting_qc'/
--    'submitted_to_qc' throughout, only flipping at the real final
--    verdict, same as the RM side's purchase_batch_status behavior.
drop trigger if exists trg_qc_review_finished_product on public.quality_checks;
create trigger trg_qc_review_finished_product
  after update on public.quality_checks
  for each row
  when (new.finished_product_batch_id is not null and old.status in ('submitted', 'checker_approved') and new.status in ('approved', 'rejected'))
  execute function public.trg_fn_qc_review_finished_product();

-- No changes needed to: check_batch_qc_approved() / trg_fp_component_qc_gate
-- (already keys off qc_status = 'approved', which still means exactly
-- "fully, finally cleared"); purchase_batch_status (a plain view over
-- quality_checks.status — 'checker_approved' just flows through as a new
-- possible value, already excluded from qc/new's "open for QC" picker
-- since it isn't 'not_submitted'); trg_fn_qc_compute_retest_date (still
-- fires correctly off reviewed_at/retest_period_days, now set at Round 2
-- instead of the old single decision); trg_qc_sample_pull (fires at AR
-- creation, before either round, untouched); computeBatchQcState()
-- (lib/batch-qc-status.ts — its catch-all "anything that isn't literally
-- approved/rejected reads as qc_pending" already folds 'checker_approved'
-- into the correct bucket with no code change).

-- ############################################################
-- ## 0055_fp_batch_number_embed_item_code.sql
-- ############################################################

-- ============================================================
-- Finished Product batch numbers: embed the FP item's own item_code and
-- scope the per-year sequence per FP item, matching Raw Material/
-- Packaging batch numbers exactly.
--
-- Ravi (21 Sept 2026), looking at a Finished Product batch detail page
-- showing "FP-01/26" next to Composition rows reading "RM-00001-01/26" /
-- "RM-00002-03/26": "Finished product batch number should be in same
-- format as of Raw material Batch Number. Also what happens when finished
-- product batch number reaches FP-99/26?"
--
-- This is the exact follow-up 0051_batch_number_embed_item_code.sql's own
-- "Scope note" flagged and deliberately left open: that migration embedded
-- each RM/PKG item's item_code into ITS batch numbers (RM-01/26 ->
-- RM-00001-01/26) because two different items' first purchase of a year
-- otherwise rendered the identical string. get_next_fp_batch_number()
-- (0045_fp_batch_number_year_reset.sql) was never touched — it still
-- returns a bare 'FP-<seq>/<year>' counted GLOBALLY across every Finished
-- Product batch of any MFR created that year, not per finished product.
-- So today two different MFRs' first FP batch of the year collide on
-- screen exactly the same way RM/PKG items used to (both would show
-- "FP-01/26"), and — Ravi's second question — get_next_fp_batch_number()
-- still pads with the pre-0052 exact-width `lpad(v_n::text, 2, '0')`,
-- which Postgres TRUNCATES rather than skips once v_n reaches 3 digits
-- (confirmed in 0052: lpad('100', 2, '0') = '10'). Globally-counted FP
-- batches are a much smaller number than per-item RM purchases in
-- practice, but the 100th FP batch of any kind created in one calendar
-- year would silently compute 'FP-10/26' again — the exact same batch
-- number as that year's real 10th FP batch — and the insert would fail on
-- finished_product_batches.batch_number's `unique` constraint with a raw
-- 23505 error, since createFinishedProductBatch() (lib/actions/
-- finished-product.ts) has no retry loop around this call (unlike
-- createPurchaseLine(), which retries a few times specifically because
-- get_next_batch_number() has the same count()+1 shape — see that
-- function's own comment).
--
-- Fix, mirroring 0051 + 0052 in one pass so FP batch numbers never need
-- their own follow-up truncation fix later:
--   1. Scope the sequence per Finished Product item, not globally. Every
--      MFR is linked 1:1 to exactly one 'processed'-category item via
--      mfr_definitions.finished_product_item_id (0010_mfr_finished_
--      product_link.sql, unique both ways) — and that link is set once
--      and never changes across MFR versions (mfr_definitions is a single
--      row whose `version` column is bumped in place, not re-inserted —
--      0001_init.sql). So counting finished_product_batches rows by
--      mfr_definition_id is exactly counting them by FP item.
--   2. Format as '<item_code>-<seq>/<year>', e.g. the 3rd FP batch of
--      MFR-0001 / item FP-00001 created in 2026 is 'FP-00001-03/26' —
--      byte-for-byte the same shape as 'RM-00001-01/26'.
--   3. Pad with `greatest(2, length(v_n::text))` (0052's fix) from the
--      start, so hitting 100 FP batches of the same product in one year
--      renders 'FP-00001-100/26' correctly instead of truncating to
--      'FP-00001-10/26' and colliding.
--
-- Defensive fallback: finished_product_item_id is nullable (pre-0010 MFRs,
-- or a 'processed' item created directly through Item Master before that
-- change existed, predate the link and have no counterpart) — 0010's own
-- comment says every MFR created from here on always sets it, but this
-- function still coalesces to the bare 'FP' prefix if a linked item_code
-- can't be found, rather than raising and blocking batch creation
-- entirely for one of those legacy rows.
--
-- Signature change: get_next_fp_batch_number() -> get_next_fp_batch_number
-- (p_mfr_definition_id uuid) — its one caller (createFinishedProductBatch,
-- lib/actions/finished-product.ts) already has mfrDefinitionId in scope at
-- the call site, so this is a one-line change there, included in this same
-- patch. No data migration: existing FP batch numbers already assigned
-- (both the original flat 'FP-0001' style and the 2026 'FP-NN/26' style)
-- are immutable and left exactly as stored, same as every other batch/code
-- format change in this app.
-- ============================================================

create or replace function public.get_next_fp_batch_number(p_mfr_definition_id uuid)
returns text language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_item_code text;
begin
  select i.item_code into v_item_code
  from public.mfr_definitions m
  join public.items i on i.id = m.finished_product_item_id
  where m.id = p_mfr_definition_id;

  select count(*) + 1 into v_n
  from public.finished_product_batches
  where mfr_definition_id = p_mfr_definition_id and to_char(created_at, 'YY') = v_year;

  return coalesce(v_item_code, 'FP') || '-' || lpad(v_n::text, greatest(2, length(v_n::text)), '0') || '/' || v_year;
end $$;

-- The old zero-argument signature is superseded, not just shadowed — drop
-- it so nothing can call the global-count version by accident (Postgres
-- allows overloads by argument count, and the old signature has no
-- remaining callers to preserve — see the header comment).
drop function if exists public.get_next_fp_batch_number();

-- ############################################################
-- ## 0056_performance_indexes.sql
-- ############################################################

-- ============================================================
-- Add missing indexes on the foreign-key columns this app actually
-- filters/joins on most.
--
-- Ravi (21 Sept 2026): "the app is very slow, help optimize it." Alongside
-- the click-feedback fix (app/(dashboard)/loading.tsx — see
-- docs/modules/shell.md), I surveyed the schema for the other half of
-- "why is it slow": across 56 migrations, only `page_feedback`'s 3 columns
-- and two narrow partial-unique indexes (purchase_lines(item_id,
-- batch_number), quality_checks(purchase_line_id) scoped to pending) have
-- ever had an index. Postgres does NOT automatically index foreign-key
-- columns — every `.eq("item_id", ...)` / `.eq("purchase_line_id", ...)` /
-- `.eq("mfr_definition_id", ...)` / `.eq("finished_product_batch_id", ...)`
-- / `.eq("purchase_order_id", ...)` call in the app (confirmed by grep
-- against lib/actions/*.ts and app/(dashboard)/**/page.tsx — real,
-- evidenced call sites, not a guess) has been running a full sequential
-- scan of the whole table, every time, since 0001_init.sql.
--
-- Two of these tables already have real size: purchase_lines is ~92,000
-- rows on the live database today, and inventory_ledger gets a new row on
-- every purchase/QC/production/packaging transaction, so it only grows
-- from here. A few are hit on nearly every page load:
--   - stock_balance (0001_init.sql) is `group by item_id` over ALL of
--     inventory_ledger, with no index on inventory_ledger.item_id. This
--     view is queried from the Dashboard, Items list, Item detail,
--     Inventory Balance, Reports, and the Finished Product compose screen.
--   - purchase_batch_status (0001_init.sql) LEFT JOIN LATERALs into
--     quality_checks per purchase_lines row with no general-purpose index
--     on quality_checks.purchase_line_id (only a partial one scoped to
--     status='submitted', which the planner can't use for an unscoped
--     lookup). This view backs the QC list's "Awaiting QC"/"Due for
--     retest" cards (every /qc visit) and the Finished Product compose
--     screen's candidate-batch lookup.
--   - get_next_fp_batch_number(p_mfr_definition_id) (0055, shipped
--     earlier today) counts finished_product_batches WHERE
--     mfr_definition_id = ..., with no index on that column either — every
--     "Create Batch" click does a full scan of that table.
--
-- Purely additive: CREATE INDEX only, no data touched, no existing query
-- result changes (only how fast it's computed) — safe to run any time,
-- and trivially reversible with DROP INDEX if one is ever not wanted.
--
-- Scope note: this is the schema-level half of "the app is very slow."
-- It does NOT address list pages (Reports, Items, Inventory Balance) that
-- fetch entire tables to the browser and paginate client-side — that's a
-- separate, larger app-layer change (server-side pagination), flagged to
-- Ravi rather than done here. These indexes help every query on these
-- tables, including those pages' underlying fetches, but don't reduce how
-- much data those specific pages pull per visit.
-- ============================================================

-- inventory_ledger: backs stock_balance (grouped by item_id) and every
-- per-item ledger view/report. Grows with every transaction.
create index if not exists inventory_ledger_item_id_idx
  on public.inventory_ledger (item_id);
create index if not exists inventory_ledger_purchase_line_id_idx
  on public.inventory_ledger (purchase_line_id);

-- quality_checks: general-purpose lookups by purchase line, FP batch, and
-- item — the existing quality_checks_purchase_line_pending_unique index
-- (0025/0054) is scoped to status='submitted' and can't serve these.
create index if not exists quality_checks_purchase_line_id_idx
  on public.quality_checks (purchase_line_id);
create index if not exists quality_checks_finished_product_batch_id_idx
  on public.quality_checks (finished_product_batch_id);
create index if not exists quality_checks_item_id_idx
  on public.quality_checks (item_id);

-- purchase_lines: purchase_lines_item_batch_unique (0013) is a PARTIAL
-- index (excludes 'LEG-%' rows) with item_id as its leading column, but
-- the planner can only use it for queries that also respect that partial
-- predicate — a plain `.eq("item_id", ...)` over ALL rows (get_next_batch_
-- number's per-item/year count, item detail page, etc.) isn't covered by
-- it. purchase_order_id backs every Purchase Order detail page.
create index if not exists purchase_lines_item_id_idx
  on public.purchase_lines (item_id);
create index if not exists purchase_lines_purchase_order_id_idx
  on public.purchase_lines (purchase_order_id);

-- finished_product_components: FP batch detail page, packaging issue
-- lookups, and the "already consumed" checks around QC/inventory.
create index if not exists finished_product_components_batch_id_idx
  on public.finished_product_components (finished_product_batch_id);
create index if not exists finished_product_components_item_id_idx
  on public.finished_product_components (item_id);
create index if not exists finished_product_components_purchase_line_id_idx
  on public.finished_product_components (purchase_line_id);
create index if not exists finished_product_components_production_batch_id_idx
  on public.finished_product_components (production_batch_id);

-- mfr_lines / mfr_procedure_steps: every MFR detail/report page loads both,
-- filtered by mfr_definition_id.
create index if not exists mfr_lines_mfr_definition_id_idx
  on public.mfr_lines (mfr_definition_id);
create index if not exists mfr_procedure_steps_mfr_definition_id_idx
  on public.mfr_procedure_steps (mfr_definition_id);

-- finished_product_batches: get_next_fp_batch_number() (0055) counts rows
-- WHERE mfr_definition_id = ... on every "Create Batch" click.
create index if not exists finished_product_batches_mfr_definition_id_idx
  on public.finished_product_batches (mfr_definition_id);

-- ############################################################
-- ## 0057_inventory_ledger_with_balance_refresh.sql
-- ############################################################

-- ============================================================
-- Fix: Inventory Ledger page showing "Could not find a relationship
-- between 'inventory_ledger_with_balance' and 'production_issue_batches'
-- in the schema cache" (Ravi, live screenshot, 21 Sept 2026), on both the
-- Ledger tab (app/(dashboard)/inventory/(tabs)/page.tsx) and the per-item
-- embedded ledger (app/(dashboard)/inventory/items/[id]/page.tsx) — both
-- query inventory_ledger_with_balance with
-- "...production_issue_batches(batch_number)" embedded in the select.
--
-- Root cause: inventory_ledger_with_balance (0031_stock_position.sql) is
-- defined as `select il.*, <running_balance window fn> from
-- inventory_ledger il`. Postgres expands `il.*` into the base table's
-- column list AT THE MOMENT the view is created (or last CREATE OR REPLACE
-- VIEW) — it is NOT re-evaluated when a column is added to the base table
-- later. inventory_ledger.production_batch_id was added by
-- 0050_production_rm_from_packaging.sql, nineteen migrations after 0031
-- created this view, and the view was never re-created since — so
-- production_batch_id has never actually existed on
-- inventory_ledger_with_balance in production. PostgREST can't embed a
-- relationship to production_issue_batches through a column that doesn't
-- exist on the view it's querying, hence the exact error above. (The other
-- embed in the same select, purchase_lines(batch_number), works fine:
-- purchase_line_id was already a column on inventory_ledger back when 0031
-- first created the view, so it was captured correctly.)
--
-- Checked every other `alter table public.inventory_ledger add column`
-- across every migration after 0031 (0003 predates it; 0028/0030/0032/
-- 0036/0046 only touch check constraints, no new columns) —
-- production_batch_id is the only column this view has been missing.
--
-- Fix: DROP + re-CREATE the view (verbatim same query as 0031) so `il.*`
-- re-expands against inventory_ledger's CURRENT column list, picking up
-- production_batch_id.
--
-- Tried `CREATE OR REPLACE VIEW` first — it fails here:
--   ERROR: cannot change name of view column "running_balance" to
--   "production_batch_id"
-- because Postgres only allows CREATE OR REPLACE to APPEND new trailing
-- columns; it can't insert one in the middle. production_batch_id sits at
-- the end of inventory_ledger's own column list (it was added via ALTER
-- TABLE ... ADD COLUMN, after `seq`), so `il.*` expands to place it right
-- before the view's own explicit `running_balance` column — which is
-- already that view's last (existing) column. Since production_batch_id
-- would have to land BEFORE running_balance, not after it, this counts as
-- reordering an existing column, which CREATE OR REPLACE VIEW refuses.
-- DROP + CREATE has no such constraint (confirmed against a local Postgres
-- reproduction of the exact 0031-then-0050 sequence before writing this).
--
-- Grants: dropping and recreating the view does NOT need a new GRANT
-- statement — 0001_init.sql's `alter default privileges in schema public
-- grant select, insert, update, delete on tables to anon, authenticated`
-- applies automatically to any new relation (table OR view) created by the
-- same role from here on, exactly like every `CREATE OR REPLACE FUNCTION`
-- in this codebase already relies on for execute grants. Confirmed locally:
-- after DROP + CREATE, `\dp` shows anon/authenticated already have
-- arwd on the recreated view with no explicit GRANT needed.
--
-- No data migration, no app-code change — both call sites above already
-- select production_issue_batches(batch_number) correctly and will simply
-- start working once the view exposes the column it needs.
--
-- Forward-looking note: this same "CREATE OR REPLACE fails, must DROP +
-- CREATE instead" applies again any time inventory_ledger gains another
-- column in the future — worth remembering before reaching for the more
-- familiar CREATE OR REPLACE pattern this codebase uses everywhere else.
-- ============================================================

drop view if exists public.inventory_ledger_with_balance;

create view public.inventory_ledger_with_balance as
select
  il.*,
  sum(case il.event_type when 'push' then il.quantity when 'wastage' then -il.quantity else -il.quantity end)
    over (partition by il.item_id order by il.event_at, il.seq rows between unbounded preceding and current row) as running_balance
from public.inventory_ledger il;

-- Supabase's PostgREST instance normally picks up view/schema changes on
-- its own shortly after a DDL statement runs, but that reload isn't
-- instant or guaranteed for every change — this forces it immediately so
-- the fix takes effect as soon as this migration finishes running, rather
-- than leaving the same error visible for an indeterminate few minutes.
notify pgrst, 'reload schema';

-- ############################################################
-- ## 0058_audit_trail.sql
-- ############################################################

-- ============================================================
-- Audit trail for approval/status-gated records.
--
-- Ravi (21 Sept 2026): "lets fix the audit trail issue" — following up on
-- claude/open-requirements-log.md's own "Still open" note: "Every table
-- still only carries created/created_by/updated/updated_by/active —
-- there is still no separate audit-log/history table... no way to see a
-- row's prior values before an edit, only who last touched it and when."
--
-- Notably, user_roles (0001_init.sql) already defines a 'super_auditor'
-- role — it's in ROLES/ROLE_LABELS (lib/constants/roles.ts) too — but
-- nothing in the app has ever granted it a permission or a page. This
-- migration is the first thing that actually uses it: audit_log's SELECT
-- policy below grants it (alongside system_admin) read access to the
-- history this migration starts capturing.
--
-- Scope, confirmed with Ravi via AskUserQuestion: "approval/status gates
-- only" — the tables where a status flip or approval decision is the
-- thing you'd need to prove later, not every table in the schema. That's:
--   - quality_checks        (QC decision: submitted/checker_approved/
--                             approved/rejected — the two-round review
--                             gate, 0054_qc_two_round_review.sql)
--   - finished_product_batches (batch status through to approved/rejected)
--   - purchase_orders       (draft/submitted — the Final Submit gate,
--                             0019_purchase_submit_workflow.sql)
--   - mfr_definitions       (approved_by/approved_at — the recipe
--                             approval gate, 0041_mfr_deferred_approval.sql)
--
-- One table from that original candidate list is deliberately left out,
-- narrowing what was proposed — flagging it here rather than silently:
--   - line_clearance_checks: every column check (lib/actions/
--     line-clearance.ts) is a plain insert, nothing ever updates or
--     deletes a row after it's created. Its own checked_by/checked_at
--     columns are already a complete, immutable record of who decided
--     what and when — an audit trail exists to answer "what did this
--     look like before it changed," and a row that never changes has no
--     before/after to capture. Revisit if that ever stops being true
--     (e.g. an edit/void flow gets added to that page).
--
-- Design: one generic table + one generic trigger function, attached per
-- table — the same "shared helper trigger, attach per table" shape this
-- schema already uses for updated_at/updated_by (set_updated_at(),
-- 0001_init.sql), rather than a bespoke history table per subject. Each
-- row change writes ONE audit_log row via to_jsonb(old)/to_jsonb(new) —
-- full row snapshots, not a computed field-level diff, so nothing about
-- a table's shape needs to be taught to this migration and a future
-- column added to any of the four tables is automatically captured with
-- no further change needed here.
-- ============================================================

create table public.audit_log (
  id uuid primary key default gen_random_uuid(),
  table_name text not null,
  row_id uuid not null,
  action text not null check (action in ('insert', 'update', 'delete')),
  old_data jsonb,
  new_data jsonb,
  changed_by uuid references auth.users(id),
  changed_at timestamptz not null default now()
);

-- "History for this record" (row_id) and "everything that happened
-- recently" (changed_at, and changed_at scoped to one table for the
-- Audit Log page's table filter) are the two access patterns this needs.
create index audit_log_table_row_idx on public.audit_log (table_name, row_id, changed_at desc);
create index audit_log_table_changed_at_idx on public.audit_log (table_name, changed_at desc);
create index audit_log_changed_at_idx on public.audit_log (changed_at desc);

alter table public.audit_log enable row level security;

create policy audit_log_select on public.audit_log for select
  using (public.has_any_role('system_admin', 'super_auditor'));

-- Same "no direct write" shape as inventory_ledger's ledger_no_direct_write
-- policy (0001_init.sql) — this table is written exclusively by
-- trg_fn_audit_log() below (SECURITY DEFINER, bypasses this), never by a
-- client insert/update/delete. Nothing should ever UPDATE or DELETE an
-- audit_log row at all — that would defeat the point — so those aren't
-- given a policy either, which for RLS-enabled tables means "denied."
create policy audit_log_no_direct_write on public.audit_log for insert with check (false);

create or replace function public.trg_fn_audit_log()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (table_name, row_id, action, new_data, changed_by)
    values (tg_table_name, new.id, 'insert', to_jsonb(new), auth.uid());
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by)
    values (tg_table_name, new.id, 'update', to_jsonb(old), to_jsonb(new), auth.uid());
    return new;
  elsif tg_op = 'DELETE' then
    insert into public.audit_log (table_name, row_id, action, old_data, changed_by)
    values (tg_table_name, old.id, 'delete', to_jsonb(old), auth.uid());
    return old;
  end if;
  return null;
end $$;

-- auth.uid() reads a per-request JWT claim (request.jwt.claims), not the
-- calling function's own privilege level — it resolves to the real
-- signed-in user whether the row change happened via a plain client
-- .update() (qc.ts, finished-product.ts, purchase.ts) or from inside a
-- SECURITY DEFINER RPC (submit_purchase_order(), approve_mfr_definition(),
-- the QC two-round-review functions in 0054). Confirmed by the fact that
-- updated_by already relies on exactly this same behavior, through the
-- exact same call paths, today.
create trigger trg_audit_quality_checks
  after insert or update or delete on public.quality_checks
  for each row execute function public.trg_fn_audit_log();

create trigger trg_audit_finished_product_batches
  after insert or update or delete on public.finished_product_batches
  for each row execute function public.trg_fn_audit_log();

create trigger trg_audit_purchase_orders
  after insert or update or delete on public.purchase_orders
  for each row execute function public.trg_fn_audit_log();

create trigger trg_audit_mfr_definitions
  after insert or update or delete on public.mfr_definitions
  for each row execute function public.trg_fn_audit_log();

-- ############################################################
-- ## 0059_coa_templates.sql
-- ############################################################

-- ============================================================
-- Certificate of Analysis — templates, step 1 of 2.
--
-- Ravi (22 Sept 2026), via two sample COAs (Raw Material and Finished
-- Product): "let's create functionality to generate certificate of
-- analysis... There is one template per Item Type. First step would be to
-- define Certificate of Analysis steps per item type... Once Item Type is
-- selected, user will get input form to enter Test and Specification.
-- Serial number will be autogenerated (similar to Manufacturing Process
-- entry form in MFR). Once submitted, user will also have option to edit
-- this."
--
-- This migration is template management only (a Test/Specification list
-- per item type) — generating an actual certificate against a batch, with
-- real results and a pixel-matched PDF, is step 2, a separate migration
-- extending coa_records once this is confirmed working.
--
-- Design, deliberately mirroring mfr_procedure_steps/update_mfr_procedure
-- (0048_mfr_procedure.sql) — the exact pattern Ravi pointed at:
--   - One template per item_type_id (unique constraint) — item_types is
--     already the one taxonomy shared by both Raw Material items
--     (items.item_type_id) and Finished Product recipes
--     (mfr_definitions.item_type_id), so this one column resolves either
--     subject to the right template at generation time.
--   - Lines are a child table with a `seq` column (the auto-numbered
--     S.No.), replaced in place on every edit via a security definer RPC
--     (delete-and-reinsert in one transaction) — same "no versioning,
--     edit in place" precedent as update_mfr_recipe()/
--     update_mfr_procedure(), and the same choice Ravi already made for
--     MFR recipes ("we will add versioning if required but right now
--     let's not have this as standard feature").
--   - Write access reuses the existing "coa" role set already granted on
--     coa_records (system_admin, quality_checker, qc_reviewer) — this is
--     the same module, just its template-setup half.
-- ============================================================

create table public.coa_templates (
  id uuid primary key default gen_random_uuid(),
  item_type_id uuid not null unique references public.item_types(id),
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id),
  updated_at timestamptz,
  updated_by uuid references auth.users(id)
);
create trigger trg_coa_templates_updated before update on public.coa_templates
  for each row execute function public.set_updated_at();

create table public.coa_template_lines (
  id uuid primary key default gen_random_uuid(),
  coa_template_id uuid not null references public.coa_templates(id) on delete cascade,
  seq integer not null,
  test text not null,
  specification text not null
);
create index coa_template_lines_template_idx on public.coa_template_lines (coa_template_id, seq);

alter table public.coa_templates enable row level security;
alter table public.coa_template_lines enable row level security;

create policy coa_templates_select on public.coa_templates for select using (public.is_signed_in());
create policy coa_templates_write on public.coa_templates for all
  using (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'))
  with check (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'));

create policy coa_template_lines_select on public.coa_template_lines for select using (public.is_signed_in());
-- Lines are only ever written via upsert_coa_template() (security definer,
-- below) — no direct client insert/update/delete, same "the RPC is the
-- only writer" shape as mfr_procedure_steps (that table has no write
-- policy of its own either, relying entirely on update_mfr_procedure()).

-- ------------------------------------------------------------
-- upsert_coa_template() — one call creates the template row (if this is
-- the item type's first template) or reuses the existing one, then
-- replaces its lines in place. Mirrors update_mfr_procedure()'s
-- delete-and-reinsert shape; unlike that function, at least one line is
-- required (a template with zero tests isn't a usable template — Ravi's
-- "input form to enter Test and Specification" implies real content),
-- and seq is always renumbered 1..N from the submitted order, matching
-- "Serial number will be autogenerated."
-- ------------------------------------------------------------
create or replace function public.upsert_coa_template(
  p_item_type_id uuid,
  p_lines jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_template_id uuid;
  v_line jsonb;
  v_idx int := 0;
begin
  if not public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer') then
    raise exception 'Not authorized to manage Certificate of Analysis templates.';
  end if;

  if p_item_type_id is null then
    raise exception 'Item type is required.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'At least one test is required.';
  end if;

  insert into public.coa_templates (item_type_id, created_by)
  values (p_item_type_id, auth.uid())
  on conflict (item_type_id) do update
    set updated_at = now(), updated_by = auth.uid()
  returning id into v_template_id;

  delete from public.coa_template_lines where coa_template_id = v_template_id;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_idx := v_idx + 1;
    if (v_line->>'test') is null or v_line->>'test' = ''
       or (v_line->>'specification') is null or v_line->>'specification' = '' then
      raise exception 'Row %: both Test and Specification are required.', v_idx;
    end if;
    insert into public.coa_template_lines (coa_template_id, seq, test, specification)
    values (v_template_id, v_idx, v_line->>'test', v_line->>'specification');
  end loop;

  return v_template_id;
end $$;

-- No explicit grant needed — 0001_init.sql's `alter default privileges ...
-- grant execute on functions to anon, authenticated` already covers every
-- function created after it (same closing note as 0037/0041/0048).

-- ############################################################
-- ## 0060_coa_generation.sql
-- ############################################################

-- ============================================================
-- Certificate of Analysis — generation, step 2 of 2 (see
-- 0059_coa_templates.sql for step 1, templates).
--
-- Ravi (22 Sept 2026): "Once template is ready, Post QC is done
-- Certificate of analysis can be generated from this screen for Raw
-- Material and Finished Product. The input for this will be Raw
-- Material/Finished Product and its batch number. Based on this
-- information, their Item Type will be determined and correct template
-- will be associated. At this time, actual results will be input in the
-- form against each test. Once submitted, the certificate of analysis
-- can be downloaded in pdf."
--
-- Purely additive to the existing coa_records table (0001_init.sql) —
-- same non-destructive precedent as every other schema evolution in this
-- app (FP wastage/net_qty removal, item sampling defaults removal,
-- etc.): every new column is nullable, no backfill, and every coa_records
-- row created by the OLD "pick an approved QC, paste a file URL" flow
-- (lib/actions/coa.ts's createCoaRecord, retired by this feature per
-- Ravi's confirmation on the templates patch) is left exactly as it was —
-- file_url stays populated on those rows, and the four new columns are
-- simply null for them, same as any pre-existing row whose feature
-- didn't exist yet.
--
-- coa_template_id + result_lines is deliberately a SNAPSHOT, not a live
-- reference: result_lines copies the template's Test/Specification text
-- (plus the entered Result) at the moment the certificate is generated,
-- so a template edited later never retroactively changes a certificate
-- that already issued — the same "history shouldn't move under you"
-- reasoning as every other issued/signed-off record in this schema
-- (approved MFRs, reviewed QC decisions).
-- ============================================================

alter table public.coa_records
  add column if not exists coa_template_id uuid references public.coa_templates(id),
  add column if not exists subject_type text check (subject_type in ('raw_material', 'finished_product')),
  add column if not exists header_data jsonb,
  add column if not exists result_lines jsonb,
  -- The standard closing line both sample certificates carry ("The above
  -- sample complies/Not complies as per ...") — entered fresh per
  -- certificate rather than hardcoded, since the standard referenced can
  -- vary (Ravi's samples read "IHS" on one and what looks like "HHS" on
  -- the other — most likely both meant to read the same "In-House
  -- Specification," but this is a first-pass reading of a handwritten-
  -- adjacent scan, not confirmed, so the form pre-fills a best guess and
  -- leaves it editable rather than asserting one spelling as fact).
  add column if not exists remarks text;

-- No RLS change needed — coa_insert (0001_init.sql) already grants
-- system_admin/quality_checker/qc_reviewer insert on coa_records, and the
-- new flow inserts through that same table via a plain client insert
-- (Server Action re-verifies the QC is Approved and the template exists
-- server-side before inserting, same as createCoaRecord already does for
-- the QC-approved check), not a new RPC.

-- ############################################################
-- ## 0061_rename_coa_subject_type.sql
-- ############################################################

-- ============================================================
-- Rename coa_records.subject_type -> coa_type.
--
-- Ravi (22 Sept 2026), after trying the new /coa/new screen: the on-screen
-- "Subject" label read ambiguously, so the picker field was renamed to
-- "Raw/Finished" (patch 0018). He then asked whether the underlying DB
-- column should follow suit — decided yes, with "coa_type" as the chosen
-- name (over subject_type/raw_finished_type/item_class/coa_subject).
--
-- A straight rename, not a drop-and-recreate: existing values
-- ('raw_material' / 'finished_product') and every row's data are
-- untouched, only the column's name changes. Postgres carries the column's
-- existing check constraint and foreign-key-adjacent indexes along with
-- the rename automatically, so nothing else needs to be re-created.
-- ============================================================

alter table public.coa_records
  rename column subject_type to coa_type;

-- ############################################################
-- ## 0062_bulk_upload_coa_templates.sql
-- ############################################################

-- ============================================================
-- Bulk Data Upload — COA Templates.
--
-- Ravi (22 Sept 2026), via a screenshot of the COA Template edit screen
-- (app/(dashboard)/coa/templates/[itemTypeId]/page.tsx): "we want to
-- automate data upload of this screen per item type. So template will
-- have 3 inputs, Item Type, Test and specification." This is templates
-- only (the Test/Specification list a certificate is later generated
-- from) — a materially different, simpler thing than bulk-generating
-- actual certificates against approved batches, which was the first
-- (wrong) reading of Ravi's earlier, less specific "bulk upload
-- Certificate of Analysis" request; superseded by this screenshot.
--
-- One row = one Test/Specification line; several rows sharing the same
-- Item Type become that item type's template, grouped app-side in
-- lib/actions/bulk-upload.ts's bulkUploadCoaTemplates() exactly the way
-- MFR recipe lines are grouped by MFR Name. Needs its own RPC (rather
-- than looping upsert_coa_template() from application code once per
-- group) for the same reason MFR/Purchase bulk upload do
-- (bulk_create_mfr_definitions/bulk_create_purchase_orders): true
-- all-or-nothing atomicity across every item type in the file, in one
-- transaction, not just within any one group.
--
-- Deliberately CREATE-only, unlike upsert_coa_template() (which is a
-- true upsert, meant for hand-editing one existing template in place).
-- A row whose Item Type already has a template raises and rolls back the
-- whole file — same "reject an existing name, never silently overwrite"
-- convention as every other master-data bulk upload in this app (Item
-- Type Master's Description, Vendor Master's Name, etc.), chosen over
-- overwrite per the working agreement's "never modify existing data
-- without flagging it first." The app-side pre-check in
-- bulkUploadCoaTemplates() gives a friendly named error before this RPC
-- is ever called; the check repeated here is defense-in-depth against a
-- template created by someone else in the gap between download and
-- upload (same belt-and-suspenders relationship the unique constraint on
-- coa_templates.item_type_id already has with that same app-side check).
-- ============================================================

create or replace function public.bulk_create_coa_templates(p_payload jsonb)
returns setof uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_group jsonb;
  v_lines jsonb;
  v_line jsonb;
  v_item_type_id uuid;
  v_template_id uuid;
  v_idx int;
begin
  if not public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer') then
    raise exception 'Not authorized to manage Certificate of Analysis templates.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No COA template rows to import.';
  end if;

  for v_group in select * from jsonb_array_elements(p_payload)
  loop
    v_item_type_id := (v_group->>'item_type_id')::uuid;
    if v_item_type_id is null then
      raise exception 'Item Type is required for every row.';
    end if;
    if exists (select 1 from public.coa_templates where item_type_id = v_item_type_id) then
      raise exception 'An item type in this file already has a COA template — edit it from Manage Templates instead of uploading it again.';
    end if;

    v_lines := v_group->'lines';
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'At least one test is required per item type.';
    end if;

    insert into public.coa_templates (item_type_id, created_by)
    values (v_item_type_id, auth.uid())
    returning id into v_template_id;

    v_idx := 0;
    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      v_idx := v_idx + 1;
      if (v_line->>'test') is null or v_line->>'test' = ''
         or (v_line->>'specification') is null or v_line->>'specification' = '' then
        raise exception 'Both Test and Specification are required for every row.';
      end if;
      insert into public.coa_template_lines (coa_template_id, seq, test, specification)
      values (v_template_id, v_idx, v_line->>'test', v_line->>'specification');
    end loop;

    return next v_template_id;
  end loop;

  return;
end $$;

-- No explicit grant needed — 0001_init.sql's `alter default privileges ...
-- grant execute on functions to anon, authenticated` already covers every
-- function created after it (same closing note as 0037/0041/0048/0059).

-- ############################################################
-- ## 0063_unit_count_rename_to_nos.sql
-- ############################################################

-- ============================================================
-- FB-0039 (Namrata, 24 Sept 2026), refined 27 Sept 2026: "in Item Master,
-- unit count change to 'nos'" — Ravi's own follow-up widened this from a
-- display-only relabel to a real rename of the stored unit value,
-- app-wide, "including data" ("we only have test data currently so no
-- data migration needed as we would purge all current data anyways" —
-- the cleanup UPDATEs below still run so this migration itself doesn't
-- get rejected by the new, stricter CHECK constraints below on whatever
-- rows exist at the moment it's applied; nothing here assumes the purge
-- already happened).
--
-- Scope, confirmed with Ravi: only the unit value literally spelled
-- "count" — the one set on an Item Master item (Raw Material, Packaging,
-- or the Packaged Finished Product item auto-created at MFR approval) —
-- becomes "nos". `unit_count` (a numeric quantity column on
-- packaging_issues, "how many packaged units") is a same-word, unrelated
-- field and is NOT touched anywhere in this migration.
--
-- Four things needed, in this order (constraints dropped before the data
-- cleanup runs, so the cleanup UPDATEs below don't get rejected by the
-- OLD constraint on their way to the new value):
--   1. Drop the two CHECK constraints that hard-code the old unit list.
--   2. Data cleanup: every column that can carry an item's unit onto a
--      transaction row, updated from 'count' to 'nos'.
--   3. Re-add both CHECK constraints with 'nos' in place of 'count'.
--   4. Re-create the three functions that insert the literal 'count':
--      approve_mfr_definition() (0041), bulk_create_mfr_definitions()
--      (0053, the latest of three prior versions), and
--      trg_fn_packaging_transform_and_issue() (0050, the latest of three
--      prior versions) — bodies otherwise unchanged from their current
--      (already-applied) definitions.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Drop the old CHECK constraints.
-- ------------------------------------------------------------
alter table public.items drop constraint if exists items_unit_check;
alter table public.items drop constraint if exists items_default_sample_unit_check;

-- ------------------------------------------------------------
-- 2. Data cleanup — every column that stores an item's unit (or a copy of
--    it on a transaction row). Harmless no-op on any column with zero
--    'count' rows.
-- ------------------------------------------------------------
update public.items set unit = 'nos' where unit = 'count';
update public.items set default_sample_unit = 'nos' where default_sample_unit = 'count';
update public.purchase_lines set unit = 'nos' where unit = 'count';
update public.quality_checks set sample_unit = 'nos' where sample_unit = 'count';
update public.inventory_ledger set unit = 'nos' where unit = 'count';
update public.mfr_definitions set batch_size_unit = 'nos' where batch_size_unit = 'count';
update public.mfr_lines set unit = 'nos' where unit = 'count';
update public.finished_product_batches set unit = 'nos' where unit = 'count';
update public.packaging_issues set pack_size_unit = 'nos' where pack_size_unit = 'count';
update public.packaging_issue_items set unit = 'nos' where unit = 'count';
update public.production_issue_batches set unit = 'nos' where unit = 'count';

-- ------------------------------------------------------------
-- 3. Re-add both CHECK constraints, 'nos' replacing 'count'.
-- ------------------------------------------------------------
alter table public.items
  add constraint items_unit_check
  check (unit in ('kg','g','mg','ltr','ml','nos','bottle','pack'));

alter table public.items
  add constraint items_default_sample_unit_check
  check (default_sample_unit in ('kg','g','mg','ltr','ml','nos','bottle','pack'));

-- ------------------------------------------------------------
-- 4a. approve_mfr_definition() — unchanged from 0041_mfr_deferred_approval.sql
--     except the Packaged FP item's unit literal.
-- ------------------------------------------------------------
create or replace function public.approve_mfr_definition(p_id uuid)
returns table(fp_item_code text, packaged_item_code text, items_created boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def record;
  v_fp_item_id uuid;
  v_pkg_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_code text;
  v_created boolean := false;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to approve an MFR definition.';
  end if;

  select * into v_def from public.mfr_definitions where mfr_definitions.id = p_id for update;
  if not found then
    raise exception 'MFR definition not found.';
  end if;
  if v_def.approved_by is not null then
    raise exception 'This MFR is already approved.';
  end if;

  if v_def.finished_product_item_id is null then
    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_def.name, 'processed', v_def.item_type_id, v_def.batch_size_unit)
      returning items.id into v_fp_item_id;

    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_def.name, 'packaged_fp', v_def.item_type_id, 'nos')
      returning items.id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where items.id = v_fp_item_id;

    update public.mfr_definitions set finished_product_item_id = v_fp_item_id where mfr_definitions.id = p_id;
    v_created := true;
  else
    v_fp_item_id := v_def.finished_product_item_id;
    select item_code, packaged_item_id into v_fp_item_code, v_pkg_item_id
      from public.items where items.id = v_fp_item_id;
    if v_pkg_item_id is not null then
      select item_code into v_pkg_item_code from public.items where items.id = v_pkg_item_id;
    end if;
  end if;

  update public.mfr_definitions
    set approved_by = auth.uid(), approved_at = now()
    where mfr_definitions.id = p_id;

  fp_item_code := v_fp_item_code;
  packaged_item_code := v_pkg_item_code;
  items_created := v_created;
  return next;
end $$;

-- ------------------------------------------------------------
-- 4b. bulk_create_mfr_definitions() — unchanged from
--     0053_bulk_upload_mfr_procedure.sql except the Packaged FP item's
--     unit literal. Same OUT columns as 0053 (fp_item_code/
--     packaged_item_code included), so no drop-first needed here.
-- ------------------------------------------------------------
create or replace function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text, fp_item_code text, packaged_item_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_step jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_steps jsonb;
  v_procedure_intro text;
  v_theoretical_yield_pct numeric;
  v_permissible_yield_pct numeric;
  v_fp_item_id uuid;
  v_fp_item_code text;
  v_pkg_item_id uuid;
  v_pkg_item_code text;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
  v_step_idx int;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';
    v_steps := v_def->'procedure_steps';
    v_procedure_intro := nullif(trim(both from coalesce(v_def->>'procedure_intro', '')), '');
    v_theoretical_yield_pct := nullif(v_def->>'theoretical_yield_pct', '')::numeric;
    v_permissible_yield_pct := nullif(v_def->>'permissible_yield_pct', '')::numeric;

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;
    if v_theoretical_yield_pct is not null and v_theoretical_yield_pct <= 0 then
      raise exception 'MFR "%": theoretical yield must be greater than 0.', v_name;
    end if;
    if v_permissible_yield_pct is not null and v_permissible_yield_pct <= 0 then
      raise exception 'MFR "%": permissible yield must be greater than 0.', v_name;
    end if;

    v_fp_item_code := public.get_next_item_code('processed');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_fp_item_code, v_name, 'processed', v_item_type_id, v_batch_unit)
      returning id into v_fp_item_id;

    v_pkg_item_code := public.get_next_item_code('packaged_fp');
    insert into public.items (item_code, name, category, item_type_id, unit)
      values (v_pkg_item_code, v_name, 'packaged_fp', v_item_type_id, 'nos')
      returning id into v_pkg_item_id;

    update public.items set packaged_item_id = v_pkg_item_id where id = v_fp_item_id;

    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (
      code, name, batch_size_qty, batch_size_unit, finished_product_item_id,
      procedure_intro, theoretical_yield_pct, permissible_yield_pct
    )
      values (
        v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_fp_item_id,
        v_procedure_intro, v_theoretical_yield_pct, v_permissible_yield_pct
      )
      returning id into v_def_id;

    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    if v_steps is not null and jsonb_typeof(v_steps) = 'array' and jsonb_array_length(v_steps) > 0 then
      v_step_idx := 0;
      for v_step in select * from jsonb_array_elements(v_steps)
      loop
        v_step_idx := v_step_idx + 1;
        if (v_step->>'stage') is null or v_step->>'stage' = ''
           or (v_step->>'operation') is null or v_step->>'operation' = '' then
          raise exception 'MFR "%": procedure step % needs both a stage and an operation.', v_name, v_step_idx;
        end if;
        insert into public.mfr_procedure_steps (mfr_definition_id, version, step_no, stage, operation)
          values (v_def_id, 1, v_step_idx, v_step->>'stage', v_step->>'operation');
      end loop;
    end if;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    fp_item_code := v_fp_item_code;
    packaged_item_code := v_pkg_item_code;
    return next;
  end loop;
end $$;

-- ------------------------------------------------------------
-- 4c. trg_fn_packaging_transform_and_issue() — unchanged from
--     0050_production_rm_from_packaging.sql except the two Packaged FP
--     ledger-row unit literals (push/pull). The existing trigger
--     (0032_packaged_finished_product.sql) already points at this
--     function by name — create or replace alone picks up the new body,
--     same note 0050 itself left.
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_transform_and_issue()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_mfr_definition_id uuid;
  v_fp_item_id uuid;
  v_fp_unit text;
  v_pkg_item_id uuid;
  v_rm_item_id uuid;
  v_rm_item_code text;
  v_fp_item_code text;
  v_fp_item_name text;
  v_fp_item_type_id uuid;
  v_batch_number text;
begin
  if new.department not in ('store', 'rnd', 'production') then
    return new;
  end if;

  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  select fpb.mfr_definition_id into v_mfr_definition_id
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_fp_item_id
    from public.mfr_definitions md
    where md.id = v_mfr_definition_id;

  if v_fp_item_id is null then
    return new;
  end if;

  if new.department = 'production' then
    select unit, item_code, name, item_type_id, production_rm_item_id
      into v_fp_unit, v_fp_item_code, v_fp_item_name, v_fp_item_type_id, v_rm_item_id
      from public.items where id = v_fp_item_id for update;

    if v_rm_item_id is null then
      v_rm_item_code := public.get_next_production_rm_item_code();
      insert into public.items (item_code, name, category, item_type_id, unit)
        values (v_rm_item_code, v_fp_item_name, 'raw', v_fp_item_type_id, v_fp_unit)
        returning id into v_rm_item_id;
      update public.items set production_rm_item_id = v_rm_item_id where id = v_fp_item_id;
    end if;

    perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('push', v_rm_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'production_rm_yield', new.id, auth.uid());

    v_batch_number := public.get_next_production_batch_number(v_rm_item_id);
    insert into public.production_issue_batches
      (packaging_issue_id, item_id, batch_number, quantity, unit, live_remaining_qty, created_by)
    values
      (new.id, v_rm_item_id, v_batch_number, new.fp_qty_consumed, v_fp_unit, new.fp_qty_consumed, auth.uid());

    return new;
  end if;

  select unit, packaged_item_id into v_fp_unit, v_pkg_item_id
    from public.items where id = v_fp_item_id;

  if v_pkg_item_id is null then
    return new;
  end if;

  perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('push', v_pkg_item_id, new.unit_count, 'nos', new.department, 'packaged_fp_yield', new.id, auth.uid());

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_pkg_item_id, new.unit_count, 'nos', new.department, 'packaged_fp_issue', new.id, auth.uid());

  return new;
end $$;

-- ############################################################
-- ## 0065_fp_rnd_qty_optional.sql
-- ############################################################

-- ============================================================
-- FB-0040 (24 Sept 2026): "In Finished Product, at the time of batch
-- completion, the sample shows R&D entry as a mandatory field. Please
-- make it optional, as it is not necessary to take a sample for R&D for
-- every batch."
--
-- fp_completion_fields_required_together (0044_fp_batch_start_date.sql,
-- 15 Sept 2026) currently requires Batch yield, Expiry date, and all
-- three of QC/Stability/R&D sample qty together, non-null and > 0,
-- whenever a batch's Finish date is set — per Ravi's own instruction at
-- the time ("the batch is only truly finished once every one of them is
-- known"). Confirmed with Ravi before this migration: FB-0040 narrows
-- that rule for R&D only. Batch yield, Expiry date, QC sample qty, and
-- Stability sample qty all stay exactly as mandatory as they were —
-- R&D sample qty may now be null, and is only checked to be > 0 when it
-- IS provided.
--
-- No other constraint needs touching: fp_batch_yield_not_negative
-- (0030_finished_product_ledger.sql) already does
-- `coalesce(rnd_qty, 0)`, and trg_fn_qc_review_finished_product's R&D
-- sample pull (same migration) already only fires
-- `if coalesce(rnd_qty, 0) > 0` — both were already written to tolerate
-- a null/zero R&D sample; only this CHECK and the app layer
-- (lib/actions/finished-product.ts, complete-batch-form.tsx) were
-- actually preventing R&D from ever being left empty.
-- ============================================================

alter table public.finished_product_batches
  drop constraint if exists fp_completion_fields_required_together;
alter table public.finished_product_batches
  add constraint fp_completion_fields_required_together
  check (
    finish_date is null or (
      batch_yield is not null and batch_yield > 0 and
      expiry_month is not null and
      qc_sample_qty is not null and qc_sample_qty > 0 and
      stability_qty is not null and stability_qty > 0 and
      (rnd_qty is null or rnd_qty > 0)
    )
  ) not valid;

-- ############################################################
-- ## 0066_fp_market_short_batch_no.sql
-- ############################################################

-- ============================================================
-- FB-0044 follow-up (27 Sept 2026): Namrata's original ask was to drop the
-- item-code embedding from batch numbers entirely ("PR01/26" instead of
-- "FP-00002-01/26") — flagged back to Ravi as a direct conflict with his
-- own 21 Sept decision (0051/0055_*_batch_number_embed_item_code.sql),
-- which deliberately embedded the item code to fix a real on-screen
-- collision he'd reported (two different items' first batch of the year
-- both rendering as "RM-01/26"). Ravi then clarified the real constraint:
-- bottle labels have no room to print the long compound batch number.
--
-- Resolution, scoped and confirmed with Ravi via a short back-and-forth in
-- chat (not AskUserQuestion this time — a direct design proposal he
-- confirmed piece by piece): keep the canonical, globally-unique
-- `batch_number` exactly as it is (nothing about 0051/0055 changes) and
-- add a second, print-only `short_batch_no` column that a label can
-- reference instead. It's deliberately NOT globally unique — it reuses the
-- same per-item-scoped sequence number the canonical batch number already
-- has, just with the item code swapped for a short, fixed prefix — because
-- every label template that prints "Batch No." also prints the product
-- name right above it, so the ambiguity that made the bare format
-- confusing on 21 Sept (a shared list with no product context) doesn't
-- exist on a printed label.
--
-- Mid-conversation, Ravi added a real, separate business requirement: some
-- Finished Products are for domestic use and some are for export, decided
-- once per MFR (an MFR is permanently 1:1 with one Finished Product item —
-- 0010_mfr_finished_product_link.sql — so this is really a property of the
-- product, just set where the product is defined). The short batch prefix
-- depends on it: "PR" for domestic, "OR" for export. Confirmed via three
-- follow-up questions, asked one at a time per Ravi's request:
--   1. Market is set once at MFR creation and is NOT editable afterward —
--      same permanence as the MFR's own link to its Finished Product item.
--      No new edit UI needed.
--   2. Every existing MFR (no Market on file) defaults to 'domestic' —
--      Ravi confirmed no existing MFRs need flagging as export instead.
--   3. Existing Finished Product batches already in the new compound
--      format (e.g. FP-00002-01/26) get short_batch_no backfilled — since
--      every existing MFR defaults to domestic, every backfilled row gets
--      the 'PR' prefix. Older flat-style batches (FP-0001, no seq/year to
--      extract) are left null; the label falls back to the full
--      batch_number for those (see label-picker.tsx).
-- ============================================================

-- ------------------------------------------------------------
-- 1. mfr_definitions.market — set once at MFR creation, never changed
--    after. Existing rows default to 'domestic' per Ravi's confirmation.
-- ------------------------------------------------------------
alter table public.mfr_definitions
  add column if not exists market text not null default 'domestic';

alter table public.mfr_definitions
  drop constraint if exists mfr_definitions_market_check;
alter table public.mfr_definitions
  add constraint mfr_definitions_market_check check (market in ('domestic', 'export'));

-- ------------------------------------------------------------
-- 2. finished_product_batches.short_batch_no — nullable, print-only,
--    populated going forward by get_next_fp_batch_number() below and
--    backfilled for existing rows where it's mechanically derivable.
-- ------------------------------------------------------------
alter table public.finished_product_batches
  add column if not exists short_batch_no text;

-- ------------------------------------------------------------
-- 3. create_mfr_definition() — one new parameter, p_market, validated and
--    stored alongside the rest of the header. Everything else in this
--    function (0041_mfr_deferred_approval.sql) is unchanged.
--
--    Adding a parameter changes the argument list, so CREATE OR REPLACE
--    does not replace the old 5-arg function in place — it silently adds a
--    second, overloaded 5-arg-vs-6-with-default function instead, and a
--    5-positional-argument call then fails as ambiguous ("not unique").
--    Caught directly via a local RPC test (calling with the original 5
--    positional args), not assumed — same DROP-FUNCTION-first class of bug
--    already documented above for get_next_fp_batch_number() and fixed by
--    migration 0064 for bulk_create_mfr_definitions(), just triggered by an
--    added parameter instead of a changed return type this time.
-- ------------------------------------------------------------
drop function if exists public.create_mfr_definition(text, numeric, text, uuid, jsonb);

create or replace function public.create_mfr_definition(
  p_name text,
  p_batch_size_qty numeric,
  p_batch_size_unit text,
  p_item_type_id uuid,
  p_lines jsonb,
  p_market text default 'domestic'
)
returns table(id uuid, code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := trim(both from coalesce(p_name, ''));
  v_market text := coalesce(p_market, 'domestic');
  v_line jsonb;
  v_mfr_code text;
  v_def_id uuid;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to create an MFR definition.';
  end if;

  if v_name = '' then
    raise exception 'Name is required.';
  end if;
  if p_batch_size_qty is null or p_batch_size_qty <= 0 then
    raise exception 'Batch size must be greater than 0.';
  end if;
  if p_batch_size_unit is null or p_batch_size_unit = '' then
    raise exception 'Batch size unit is required.';
  end if;
  if v_market not in ('domestic', 'export') then
    raise exception 'Market must be Domestic or Export.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one recipe line.';
  end if;

  if exists (select 1 from public.mfr_definitions where name ilike v_name) then
    raise exception '"%" already exists as an MFR.', v_name;
  end if;

  v_mfr_code := public.get_next_mfr_code();

  insert into public.mfr_definitions (code, name, batch_size_qty, batch_size_unit, item_type_id, market)
    values (v_mfr_code, v_name, p_batch_size_qty, p_batch_size_unit, p_item_type_id, v_market)
    returning mfr_definitions.id into v_def_id;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    if (v_line->>'item_id') is null or (v_line->>'quantity') is null
       or v_line->>'unit' is null or v_line->>'unit' = '' then
      raise exception 'Every recipe line needs an item, quantity, and unit.';
    end if;
    if (v_line->>'quantity')::numeric <= 0 then
      raise exception 'Recipe line quantity must be greater than 0.';
    end if;
    insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
      values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
  end loop;

  id := v_def_id;
  code := v_mfr_code;
  return next;
end $$;

-- ------------------------------------------------------------
-- 4. get_next_fp_batch_number() — now returns BOTH the canonical batch
--    number and the short print form together, computed from the exact
--    same v_n/v_year, so the two can never disagree. Signature's return
--    type is changing (text -> table), so the old function must be
--    dropped first — Postgres can't CREATE OR REPLACE across an OUT-column
--    change (same class of issue 0064 fixed for bulk_create_mfr_
--    definitions; confirmed directly rather than assumed, per that
--    migration's own precedent).
-- ------------------------------------------------------------
drop function if exists public.get_next_fp_batch_number(uuid);

create or replace function public.get_next_fp_batch_number(p_mfr_definition_id uuid)
returns table(batch_number text, short_batch_no text)
language plpgsql as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_item_code text;
  v_market text;
  v_seq_year text;
  v_short_prefix text;
begin
  select i.item_code, m.market into v_item_code, v_market
  from public.mfr_definitions m
  join public.items i on i.id = m.finished_product_item_id
  where m.id = p_mfr_definition_id;

  select count(*) + 1 into v_n
  from public.finished_product_batches
  where mfr_definition_id = p_mfr_definition_id and to_char(created_at, 'YY') = v_year;

  v_seq_year := lpad(v_n::text, greatest(2, length(v_n::text)), '0') || '/' || v_year;
  -- Domestic -> PR, Export -> OR. coalesce covers a null market the same
  -- way v_item_code is already coalesced below (defensive, not expected in
  -- practice since the column is not null default 'domestic').
  v_short_prefix := case coalesce(v_market, 'domestic') when 'export' then 'OR' else 'PR' end;

  batch_number := coalesce(v_item_code, 'FP') || '-' || v_seq_year;
  short_batch_no := v_short_prefix || '-' || v_seq_year;
  return next;
end $$;

-- ------------------------------------------------------------
-- 5. Backfill short_batch_no for existing batches already in the compound
--    <item_code>-<seq>/<year> format (0051/0055's format) — mechanically
--    derivable by pulling the trailing "-<seq>/<year>" back off the
--    existing batch_number. Every existing MFR defaults to 'domestic'
--    (confirmed with Ravi — no exceptions to flag), so every backfilled
--    row gets the 'PR' prefix. Older flat 'FP-0001'-style batches have no
--    seq/year to extract (the regex simply won't match) and are correctly
--    left null; label-picker.tsx falls back to the full batch_number for
--    those. batch_number is immutable/never rewritten by this migration —
--    only the new, additive short_batch_no column is touched.
-- ------------------------------------------------------------
update public.finished_product_batches
set short_batch_no = 'PR-' || substring(batch_number from '-(\d+/\d{2})$')
where short_batch_no is null
  and batch_number ~ '-\d+/\d{2}$';

-- ############################################################
-- ## 0067_packaging_issue_code.sql
-- ############################################################

-- ============================================================
-- Packaging Issue identifier (planned in claude/packaging-issue-
-- identifier-options.md, confirmed by Ravi 28 Sept 2026 — "ok, lets
-- start implementing"). packaging_issues had no human-readable
-- identifier at all, just a UUID primary key, while every other record
-- type in the app already has one (PO-0001, AR-.../F-0001, COA-0001-2026,
-- RM-01/26 batch codes). This adds a plain sequential PKG-#### code
-- (Option A from the planning doc), kept as a separate displayed field
-- alongside the FP batch number rather than fused into one string —
-- Option B (a PKG-01/26 year-scoped code) was rejected because it would
-- visually collide in shape with production_issue_batches' own
-- PROD-NN/YY code on the same event, and Option C (embedding the FP
-- batch number directly) was rejected because it repeats FB-0044's exact
-- compound-string complaint and still isn't unique on its own.
--
-- Built overflow-safe from day one, unlike most of this app's other code
-- generators. get_next_equipment_code() and its siblings use a plain
-- lpad(n, 4, '0'), which Postgres truncates from the LEFT once n exceeds
-- 4 digits (lpad('10000', 4, '0') = '1000', not '10000') — silently
-- colliding with an earlier, shorter code once the sequence crosses
-- 9999. This exact bug class was already found and fixed twice in this
-- codebase (migration 0052 for RM batch numbers, 0066 for FP batch
-- numbers). Since this generator is brand new, it's free to build
-- correctly from the start with lpad(n, greatest(4, length(n)), '0')
-- instead of retrofitting later — the ~10 other pre-existing generators
-- still on the old pattern are tracked as their own separate open item
-- in claude/known-issues.md, not touched by this migration.
-- ============================================================

create sequence if not exists public.packaging_issue_code_seq start 1;

-- Nullable for now — every existing row (all test data) is backfilled
-- below, then the column is locked down with not null + unique. Adding a
-- not-null column straight onto an already-populated table fails
-- outright, so the ordering here matters: add nullable, backfill,
-- *then* constrain.
alter table public.packaging_issues
  add column if not exists code text;

create or replace function public.get_next_packaging_issue_code()
returns text language plpgsql as $$
declare
  v_n text := nextval('public.packaging_issue_code_seq')::text;
begin
  return 'PKG-' || lpad(v_n, greatest(4, length(v_n)), '0');
end;
$$;

-- Non-consuming preview, same pattern as peek_next_vendor_code()/
-- peek_next_item_code() (0012_peek_next_codes.sql) and
-- peek_next_equipment_code() (0034_equipment_master.sql) — kept
-- overflow-safe the same way as the real generator above, for the same
-- reason.
create or replace function public.peek_next_packaging_issue_code()
returns text language sql stable as $$
  select 'PKG-' || lpad(
    (case when is_called then last_value + 1 else last_value end)::text,
    greatest(4, length((case when is_called then last_value + 1 else last_value end)::text)),
    '0'
  )
  from public.packaging_issue_code_seq;
$$;

-- ------------------------------------------------------------
-- Backfill every existing packaging_issues row (all of it test data
-- created during this project's live verification passes, per the
-- standing "fine to leave test data during this testing phase"
-- preference — nothing here needs cleanup first). Ordered by
-- created_at, tie-broken by id so the assignment is reproducible rather
-- than dependent on incidental row order.
-- ------------------------------------------------------------
with numbered as (
  select id, row_number() over (order by created_at, id) as rn
  from public.packaging_issues
  where code is null
)
update public.packaging_issues p
set code = 'PKG-' || lpad(numbered.rn::text, greatest(4, length(numbered.rn::text)), '0')
from numbered
where p.id = numbered.id;

-- Advance the sequence past however many rows were just backfilled, so
-- the next call to get_next_packaging_issue_code() continues right after
-- them rather than colliding with a backfilled code. Only touches the
-- sequence when there's actually something to advance past — on a
-- genuinely empty table (a brand-new install, or right after a Purge
-- Test Data run) this is a no-op, so the very first issue still gets
-- PKG-0001 rather than the sequence being nudged to skip it.
do $$
declare
  v_count bigint;
begin
  select count(*) into v_count from public.packaging_issues;
  if v_count > 0 then
    perform setval('public.packaging_issue_code_seq', v_count, true);
  end if;
end $$;

alter table public.packaging_issues
  alter column code set not null;

alter table public.packaging_issues
  drop constraint if exists packaging_issues_code_unique;
alter table public.packaging_issues
  add constraint packaging_issues_code_unique unique (code);

-- ------------------------------------------------------------
-- purge_test_data() (0039_purge_test_data.sql) resets every other
-- code-generation sequence it's aware of on a purge; packaging_issue_
-- code_seq didn't exist yet when that function was written, so it needs
-- to be added to the reset list now — otherwise a future Purge Test Data
-- run would correctly wipe every packaging_issues row but leave PKG
-- numbering wherever it was, unlike every other code type. Return type
-- is unchanged (table(table_name text, rows_purged bigint)), so this is
-- a plain CREATE OR REPLACE, no DROP FUNCTION needed first.
-- ------------------------------------------------------------
create or replace function public.purge_test_data()
returns table(table_name text, rows_purged bigint)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tables text[] := array[
    'bmr_observations', 'bmr_records', 'bmr_weighment_lines', 'coa_records',
    'dead_stock_items', 'documents', 'environmental_control_readings', 'equipment',
    'finished_product_batches', 'finished_product_components', 'inventory_ledger',
    'item_types', 'items', 'line_clearance_checks', 'mfr_definitions', 'mfr_lines',
    'packaging_issue_items', 'packaging_issues', 'purchase_lines', 'purchase_orders',
    'quality_checks', 'vendors'
  ];
  -- feedback_ticket_seq intentionally excluded — page_feedback is kept.
  v_sequences text[] := array[
    'item_code_seq_raw', 'item_code_seq_pkg', 'item_code_seq_fp', 'item_code_seq_pkgfp',
    'vendor_code_seq', 'po_number_seq', 'ar_number_seq', 'mfr_code_seq', 'fp_batch_seq',
    'coa_number_seq', 'equipment_code_seq', 'dead_stock_code_seq', 'packaging_issue_code_seq'
  ];
  v_tbl text;
  v_seq text;
  v_count bigint;
  v_truncate_list text;
begin
  if not public.has_any_role('system_admin') then
    raise exception 'Only System Admin can purge test data.';
  end if;

  foreach v_tbl in array v_tables loop
    execute format('select count(*) from public.%I', v_tbl) into v_count;
    table_name := v_tbl;
    rows_purged := v_count;
    return next;
  end loop;

  select string_agg(format('public.%I', t), ', ') into v_truncate_list from unnest(v_tables) as t;
  execute format('truncate table %s restart identity cascade', v_truncate_list);

  foreach v_seq in array v_sequences loop
    execute format('alter sequence public.%I restart with 1', v_seq);
  end loop;
end $$;

-- ############################################################
-- ## 0068_production_rm_full_qc.sql
-- ############################################################

-- ============================================================
-- FB-0043 — Production-issued Raw Material now goes through full sample
-- reservation + QC + retest, exactly like a purchased Raw Material batch.
-- Full scoping/design writeup: claude/fb-0043-production-rm-qc-
-- implementation-plan.md ("Start Implementation" — Ravi, 28 Sept 2026).
--
-- Recap of what changes, in one place (each piece below has its own
-- comment at the point it's built):
--   1. packaging_issues gains qc_qty/stability_qty/rnd_qty (Production
--      issues only — entered on the New Issue form's Production branch,
--      same UX Purchase's line form already has).
--   2. production_issue_batches gains its own qc_qty/stability_qty/rnd_qty
--      (already converted into the batch's own unit, mirroring
--      purchase_lines' convention) plus a real, netted live_remaining_qty
--      from the moment a batch is created — no more "the full issued
--      quantity is immediately available."
--   3. quality_checks.qc_one_subject widens from a 2-way to a 3-way
--      exclusive check, adding production_batch_id — a Production-issued
--      batch now gets a real, retestable QC history exactly like a
--      purchased one.
--   4. A new production_batch_status view (mirrors purchase_batch_status)
--      backs the new AR-per-batch partial unique index and the new QC
--      gate branch below.
--   5. check_batch_qc_approved() gains a real check for the
--      production_batch_id case — it used to no-op immediately (decision
--      at build time: "the FP batch's own QC approval already cleared
--      this material"). That decision is superseded by this ticket: a
--      Production-issued batch is now its own, separately gated batch.
--   6. trg_fn_packaging_transform_and_issue()'s Production branch reserves
--      QC/Stability/R&D samples at issue time, mirroring
--      submit_purchase_order()'s fixed (0028_ledger_sample_pull_fix.sql)
--      push-then-three-labelled-pulls pattern — never the older,
--      double-pull-prone trg_fn_qc_sample_pull path (retired by that same
--      migration and never revived here).
--   7. One-time backfill: every production_issue_batches row that
--      predates this migration (built under the old "no QC step" rule —
--      live data: RM-FP-00001, 10 kg on hand) is grandfathered in as
--      already QC-Approved, per Ravi's confirmed decision #4. Nothing
--      already consumed from it is disturbed — this only adds a
--      quality_checks row, it doesn't touch inventory_ledger or
--      live_remaining_qty for these rows.
--
-- The RM Intimation slip itself (vendor default "ATHARVA NATURE
-- HEALTHCARE PVT. LTD.", Invoice Number = packaging_issues.code, Invoice
-- Date = packaging_issues.created_at) is a client-side PDF export with no
-- schema footprint — built in app code only, nothing here.
-- ============================================================

-- ------------------------------------------------------------
-- 1. packaging_issues — QC/Stability/R&D sample quantities, Production
--    issues only. Nullable: Store/R&D rows never set these (packaging
--    materials are their own sampling concern, untouched by this
--    ticket). Already converted to the Finished Product's own unit by
--    the app layer before insert — same "no separate as-entered unit
--    column" convention purchase_lines and finished_product_batches both
--    use (see 0021_fp_stability_rnd_qty.sql's comment for why).
-- ------------------------------------------------------------
alter table public.packaging_issues
  add column if not exists qc_qty numeric,
  add column if not exists stability_qty numeric,
  add column if not exists rnd_qty numeric;

alter table public.packaging_issues drop constraint if exists packaging_sample_qty_not_negative;
alter table public.packaging_issues
  add constraint packaging_sample_qty_not_negative
  check (coalesce(qc_qty, 0) >= 0 and coalesce(stability_qty, 0) >= 0 and coalesce(rnd_qty, 0) >= 0);

-- `not valid`: every existing row (Store/R&D issues, and Production issues
-- created before this migration) has all three columns null, which passes
-- trivially — this only guards new inserts going forward. Same idiom
-- 0030_finished_product_ledger.sql used for its own analogous check.
alter table public.packaging_issues drop constraint if exists packaging_sample_qty_not_exceed_consumed;
alter table public.packaging_issues
  add constraint packaging_sample_qty_not_exceed_consumed
  check (
    fp_qty_consumed is null or
    (coalesce(qc_qty, 0) + coalesce(stability_qty, 0) + coalesce(rnd_qty, 0)) <= fp_qty_consumed
  ) not valid;

-- ------------------------------------------------------------
-- 2. production_issue_batches — its own qc_qty/stability_qty/rnd_qty,
--    matching purchase_lines' convention (already-converted, batch-unit
--    amounts). `not null default 0`: every existing row (built before
--    this migration, under the old "no sampling" rule) correctly
--    backfills to zero — no sample was ever reserved against them, and
--    decision #4 (grandfather, don't retrofit) means none should be.
-- ------------------------------------------------------------
alter table public.production_issue_batches
  add column if not exists qc_qty numeric not null default 0,
  add column if not exists stability_qty numeric not null default 0,
  add column if not exists rnd_qty numeric not null default 0;

-- `not valid`, same reasoning as above — trivially satisfied by every
-- existing row (qc_qty = stability_qty = rnd_qty = 0), only new inserts
-- are actually checked.
alter table public.production_issue_batches drop constraint if exists production_batch_sample_not_negative;
alter table public.production_issue_batches
  add constraint production_batch_sample_not_negative
  check (quantity - qc_qty - stability_qty - rnd_qty >= 0) not valid;

-- ------------------------------------------------------------
-- 3. quality_checks — production_batch_id, the third possible subject.
--    Widens qc_one_subject from a 2-way to a proper "exactly one of
--    three" check (equivalent to the old check when production_batch_id
--    is always null, so this is a strict superset of the old rule, not a
--    behavior change for any existing row).
-- ------------------------------------------------------------
alter table public.quality_checks
  add column if not exists production_batch_id uuid references public.production_issue_batches(id);

alter table public.quality_checks drop constraint if exists qc_one_subject;
alter table public.quality_checks
  add constraint qc_one_subject check (
    (case when purchase_line_id is not null then 1 else 0 end) +
    (case when finished_product_batch_id is not null then 1 else 0 end) +
    (case when production_batch_id is not null then 1 else 0 end) = 1
  );

-- At-most-one-open-AR-per-batch, same partial-unique-index shape
-- 0025_qc_retest_workflow.sql used for purchase_line_id and
-- 0054_qc_two_round_review.sql later widened to also cover
-- 'checker_approved' — built directly in that already-widened shape here
-- since this table only exists after both of those migrations.
create unique index if not exists quality_checks_production_batch_pending_unique
  on public.quality_checks (production_batch_id)
  where status in ('submitted', 'checker_approved');

-- ------------------------------------------------------------
-- 4. production_batch_status — the production_batch_id equivalent of
--    purchase_batch_status (0001_init.sql), same lateral-join-latest-row
--    shape, so it transparently supports a real retest history (multiple
--    quality_checks rows per batch) with zero extra logic, exactly like
--    the RM side.
-- ------------------------------------------------------------
create or replace view public.production_batch_status as
select pib.id as production_batch_id,
       coalesce(qc.status, 'not_submitted') as qc_status,
       qc.ar_number, qc.retest_date, qc.id as quality_check_id
from public.production_issue_batches pib
left join lateral (
  select * from public.quality_checks
  where production_batch_id = pib.id
  order by created_at desc limit 1
) qc on true;

-- ------------------------------------------------------------
-- 5. check_batch_qc_approved() — the production_batch_id branch is real
--    now, not a bypass. This supersedes 0050's original "no new QC step"
--    decision (that decision was explicitly scoped to "for now," and this
--    ticket is exactly the follow-up that changes it — see the plan doc).
--    The purchase_line_id branch is untouched (same two checks, same
--    exception wording, just re-scoped under its own `if`). Referencing
--    new.production_batch_id is safe against bmr_weighment_lines (which
--    has no such column at all) the same way 0050 already established
--    for new.purchase_line_id there: bmr_weighment_lines.purchase_line_id
--    is `not null`, so that first branch always returns before this
--    function ever evaluates the new field on that table's row.
-- ------------------------------------------------------------
create or replace function public.check_batch_qc_approved()
returns trigger language plpgsql as $$
declare
  v_status public.purchase_batch_status%rowtype;
  v_prod_status public.production_batch_status%rowtype;
begin
  if new.purchase_line_id is not null then
    select * into v_status
    from public.purchase_batch_status
    where purchase_line_id = new.purchase_line_id;

    if v_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (purchase_line_id=%) is not QC-Approved and cannot be consumed', new.purchase_line_id;
    end if;

    if v_status.retest_date is not null and v_status.retest_date <= current_date then
      raise exception 'Batch (purchase_line_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.purchase_line_id, v_status.retest_date;
    end if;

    return new;
  end if;

  if new.production_batch_id is not null then
    select * into v_prod_status
    from public.production_batch_status
    where production_batch_id = new.production_batch_id;

    if v_prod_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (production_batch_id=%) is not QC-Approved and cannot be consumed', new.production_batch_id;
    end if;

    if v_prod_status.retest_date is not null and v_prod_status.retest_date <= current_date then
      raise exception 'Batch (production_batch_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.production_batch_id, v_prod_status.retest_date;
    end if;

    return new;
  end if;

  return new;
end $$;

-- ------------------------------------------------------------
-- 6. trg_fn_packaging_transform_and_issue() — Production branch gains
--    sample reservation. Unchanged from 0063_unit_count_rename_to_nos.sql
--    (the current, latest body) except: the production_issue_batches
--    insert now carries qc_qty/stability_qty/rnd_qty and a properly netted
--    live_remaining_qty, and three new labelled sample pulls follow it in
--    the same transaction — the exact submit_purchase_order() /
--    0028_ledger_sample_pull_fix.sql pattern, with the new batch's own id
--    (not the packaging_issues id) as both reference_id and the ledger
--    row's production_batch_id, matching how that function's sample pulls
--    use the purchase_line's own id for both purchase_line_id and
--    reference_id. Store/R&D branch (below the `if new.department =
--    'production'` block) is untouched, byte-for-byte.
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_transform_and_issue()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_mfr_definition_id uuid;
  v_fp_item_id uuid;
  v_fp_unit text;
  v_pkg_item_id uuid;
  v_rm_item_id uuid;
  v_rm_item_code text;
  v_fp_item_code text;
  v_fp_item_name text;
  v_fp_item_type_id uuid;
  v_batch_number text;
  v_qc_qty numeric;
  v_stability_qty numeric;
  v_rnd_qty numeric;
  v_prod_batch_id uuid;
begin
  if new.department not in ('store', 'rnd', 'production') then
    return new;
  end if;

  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  select fpb.mfr_definition_id into v_mfr_definition_id
    from public.finished_product_batches fpb
    where fpb.id = new.finished_product_batch_id;

  select md.finished_product_item_id into v_fp_item_id
    from public.mfr_definitions md
    where md.id = v_mfr_definition_id;

  if v_fp_item_id is null then
    return new;
  end if;

  if new.department = 'production' then
    select unit, item_code, name, item_type_id, production_rm_item_id
      into v_fp_unit, v_fp_item_code, v_fp_item_name, v_fp_item_type_id, v_rm_item_id
      from public.items where id = v_fp_item_id for update;

    if v_rm_item_id is null then
      v_rm_item_code := public.get_next_production_rm_item_code();
      insert into public.items (item_code, name, category, item_type_id, unit)
        values (v_rm_item_code, v_fp_item_name, 'raw', v_fp_item_type_id, v_fp_unit)
        returning id into v_rm_item_id;
      update public.items set production_rm_item_id = v_rm_item_id where id = v_fp_item_id;
    end if;

    perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('push', v_rm_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'production_rm_yield', new.id, auth.uid());

    v_batch_number := public.get_next_production_batch_number(v_rm_item_id);
    v_qc_qty := coalesce(new.qc_qty, 0);
    v_stability_qty := coalesce(new.stability_qty, 0);
    v_rnd_qty := coalesce(new.rnd_qty, 0);

    insert into public.production_issue_batches
      (packaging_issue_id, item_id, batch_number, quantity, unit, live_remaining_qty,
       qc_qty, stability_qty, rnd_qty, created_by)
    values
      (new.id, v_rm_item_id, v_batch_number, new.fp_qty_consumed, v_fp_unit,
       new.fp_qty_consumed - v_qc_qty - v_stability_qty - v_rnd_qty,
       v_qc_qty, v_stability_qty, v_rnd_qty, auth.uid())
    returning id into v_prod_batch_id;

    if v_qc_qty > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, production_batch_id, quantity, unit, department, reference_type, reference_id, event_by)
      values
        ('pull', v_rm_item_id, v_prod_batch_id, v_qc_qty, v_fp_unit, new.department, 'qc_sample', v_prod_batch_id, auth.uid());
    end if;

    if v_stability_qty > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, production_batch_id, quantity, unit, department, reference_type, reference_id, event_by)
      values
        ('pull', v_rm_item_id, v_prod_batch_id, v_stability_qty, v_fp_unit, new.department, 'stability_sample', v_prod_batch_id, auth.uid());
    end if;

    if v_rnd_qty > 0 then
      insert into public.inventory_ledger
        (event_type, item_id, production_batch_id, quantity, unit, department, reference_type, reference_id, event_by)
      values
        ('pull', v_rm_item_id, v_prod_batch_id, v_rnd_qty, v_fp_unit, new.department, 'rnd_sample', v_prod_batch_id, auth.uid());
    end if;

    return new;
  end if;

  select unit, packaged_item_id into v_fp_unit, v_pkg_item_id
    from public.items where id = v_fp_item_id;

  if v_pkg_item_id is null then
    return new;
  end if;

  perform public.check_sufficient_stock(v_fp_item_id, new.fp_qty_consumed);

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_fp_item_id, new.fp_qty_consumed, v_fp_unit, new.department, 'fp_packaging_pull', new.id, auth.uid());

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('push', v_pkg_item_id, new.unit_count, 'nos', new.department, 'packaged_fp_yield', new.id, auth.uid());

  insert into public.inventory_ledger
    (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
  values
    ('pull', v_pkg_item_id, new.unit_count, 'nos', new.department, 'packaged_fp_issue', new.id, auth.uid());

  return new;
end $$;

-- ------------------------------------------------------------
-- 7. Grandfather every pre-existing production_issue_batches row (built
--    under the old "no QC step" rule) as already QC-Approved — decision
--    #4, confirmed with Ravi. Idempotent: only rows with no
--    quality_checks row against them yet are touched, so re-running this
--    migration (or applying it a second time by accident) is a no-op the
--    second time. No retest period is invented for these — they simply
--    never enter the retest cycle, matching "grandfather in, don't
--    retrofit a fake history."
-- ------------------------------------------------------------
do $$
declare
  r record;
  v_ar text;
begin
  for r in
    select pib.id, pib.item_id
    from public.production_issue_batches pib
    where not exists (
      select 1 from public.quality_checks qc where qc.production_batch_id = pib.id
    )
  loop
    v_ar := public.get_next_ar_number();
    insert into public.quality_checks
      (ar_number, production_batch_id, item_id, status, reviewed_at)
    values
      (v_ar, r.id, r.item_id, 'approved', now());
  end loop;
end $$;

-- ############################################################
-- ## 0069_lpad_overflow_fix.sql
-- ############################################################

-- ============================================================
-- Code sequence overflow issue — closes out claude/known-issues.md's
-- Twenty-eighth pass (28 Sept 2026): lpad(input, N, '0') TRUNCATES input
-- down to N characters once it's already >= N chars, instead of skipping
-- padding — confirmed directly: lpad('100', 2, '0') returns '10', not
-- '100'. A generator built as '<PREFIX>-' || lpad(nextval(seq)::text, N,
-- '0') therefore doesn't error or widen once the sequence/count reaches
-- 10^N — it silently renders the same code text as an earlier, shorter
-- value already issued. Already fixed this way three times before
-- (0052 — RM/Purchase batch numbers, 0066 — FP batch numbers, 0067 —
-- packaging issue code, built safe from day one); this migration closes
-- it out for the remaining eleven generators (fifteen functions total,
-- since four of the eleven have a peek_next_*() preview twin that needs
-- the identical fix or the UI's "next code" preview could drift from
-- what actually gets assigned).
--
-- Correction to the count given in known-issues.md's own "New open item"
-- bullet: it says "Ten sequence-based code generators" but actually
-- lists eleven (get_next_feedback_ticket makes eleven, not ten) —
-- confirmed by recounting directly rather than trusting the prior
-- summary. All eleven are fixed here; known-issues.md's wording will be
-- corrected to match once this ships.
--
-- A second gap closed while double-checking for completeness, per Ravi's
-- explicit "make sure ... all scenarios are taken care of": known-
-- issues.md's own review also missed peek_next_vendor_code()
-- (0012_peek_next_codes.sql) — a fourth peek_next_*() preview twin,
-- alongside item/equipment/dead-stock, that nothing in the original pass
-- ever listed. Found by grepping every lpad( call across every migration
-- for its *live* (latest CREATE OR REPLACE) definition, not by trusting
-- the earlier catalog. It's included below.
--
-- Mitigating copy-paste risk across fifteen near-identical edits (Ravi's
-- explicit ask before this was written): the actual fix logic — pad to
-- *at least* N digits instead of *exactly* N — is written exactly ONCE,
-- in the small shared helper _pad_seq_code() below. Every one of the
-- fifteen functions calls it instead of repeating
-- `greatest(N, length(...))` inline fifteen times, so there is exactly
-- one place the real logic can be wrong. Two self-checks are built into
-- this migration itself and will FAIL THE WHOLE MIGRATION — it's wrapped
-- in one explicit transaction, so nothing partially applies — if either
-- the helper's own logic is wrong (self-check A) or if any one of the
-- fifteen functions was missed and left calling the old, unfixed
-- lpad(...) form (self-check B).
--
-- No schema change, no data touched, no app-code change — every one of
-- these functions keeps its exact existing signature and return type
-- (confirmed against each function's current, live definition before
-- writing this, not from memory), so this is a pure CREATE OR REPLACE
-- swap, same as 0052/0066/0067. Every value under a generator's current
-- digit width renders byte-for-byte identical to before (confirmed by
-- self-check A using the same proof values 0052 originally used); only
-- a value at or beyond the width changes, from truncated/colliding to
-- correct.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- 1. The one place the actual fix logic lives.
-- ------------------------------------------------------------
create or replace function public._pad_seq_code(p_n text, p_width int)
returns text language sql immutable as $$
  select lpad(p_n, greatest(p_width, length(p_n)), '0');
$$;

-- Self-check A: the helper itself, against 0052's own original proof
-- values plus the two boundary cases (right at the width, just over it).
do $$
begin
  if public._pad_seq_code('7', 4) <> '0007' then
    raise exception '0069 self-check A failed: _pad_seq_code(''7'', 4) should be ''0007'', got %', public._pad_seq_code('7', 4);
  end if;
  if public._pad_seq_code('9999', 4) <> '9999' then
    raise exception '0069 self-check A failed: _pad_seq_code(''9999'', 4) should stay ''9999'', got %', public._pad_seq_code('9999', 4);
  end if;
  if public._pad_seq_code('10000', 4) <> '10000' then
    raise exception '0069 self-check A failed: _pad_seq_code(''10000'', 4) should widen to ''10000'' (not truncate), got %', public._pad_seq_code('10000', 4);
  end if;
  if public._pad_seq_code('100', 2) <> '100' then
    raise exception '0069 self-check A failed: _pad_seq_code(''100'', 2) should widen to ''100'' — 0052''s own original case, got %', public._pad_seq_code('100', 2);
  end if;
end $$;

-- ------------------------------------------------------------
-- 2. Vendor Master — V-#### (0001_init.sql), plus its non-consuming
--    preview twin peek_next_vendor_code() (0012_peek_next_codes.sql) —
--    the gap found while double-checking for completeness, see header.
-- ------------------------------------------------------------
create or replace function public.get_next_vendor_code()
returns text language sql as $$
  select 'V-' || public._pad_seq_code(nextval('public.vendor_code_seq')::text, 4);
$$;

create or replace function public.peek_next_vendor_code()
returns text language sql stable as $$
  select 'V-' || public._pad_seq_code(
    (case when is_called then last_value + 1 else last_value end)::text,
    4
  )
  from public.vendor_code_seq;
$$;

-- ------------------------------------------------------------
-- 3. Purchase Order — PO-#### (0001_init.sql) — Ravi's own "PO-99999" example
-- ------------------------------------------------------------
create or replace function public.get_next_po_number()
returns text language sql as $$
  select 'PO-' || public._pad_seq_code(nextval('public.po_number_seq')::text, 4);
$$;

-- ------------------------------------------------------------
-- 4. QC AR number — AR-###-DDMMYYYY (0001_init.sql)
-- ------------------------------------------------------------
create or replace function public.get_next_ar_number()
returns text language sql as $$
  select 'AR-' || public._pad_seq_code(nextval('public.ar_number_seq')::text, 3) || '-' || to_char(now(), 'DDMMYYYY');
$$;

-- ------------------------------------------------------------
-- 5. COA — COA-####-YYYY (0001_init.sql)
-- ------------------------------------------------------------
create or replace function public.get_next_coa_number()
returns text language sql as $$
  select 'COA-' || public._pad_seq_code(nextval('public.coa_number_seq')::text, 4) || '-' || to_char(now(), 'YYYY');
$$;

-- ------------------------------------------------------------
-- 6. MFR — MFR-#### (0042_mfr_code_prefix.sql; bug carried forward from
--    0001_init.sql's original 'F-' version, cosmetic rename only)
-- ------------------------------------------------------------
create or replace function public.get_next_mfr_code()
returns text language sql as $$
  select 'MFR-' || public._pad_seq_code(nextval('public.mfr_code_seq')::text, 4);
$$;

-- ------------------------------------------------------------
-- 7/8. Item Master — RM-/PKG-/FP-/PKG-FP-##### (0032_packaged_finished_
--      product.sql). get_next_item_code()'s four category branches all
--      share one lpad call site (only the sequence/prefix differ per
--      branch), so one fix covers all four — confirmed by reading the
--      live function before assuming otherwise. This is Ravi's
--      "PF-99999"-style example (real Finished Product prefix is FP-,
--      not PF-, but same risk).
-- ------------------------------------------------------------
create or replace function public.get_next_item_code(p_category text)
returns text language plpgsql as $$
declare v_num int; v_prefix text;
begin
  if p_category = 'packaging' then
    v_num := nextval('public.item_code_seq_pkg'); v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_num := nextval('public.item_code_seq_fp'); v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_num := nextval('public.item_code_seq_pkgfp'); v_prefix := 'PKG-FP';
  else
    v_num := nextval('public.item_code_seq_raw'); v_prefix := 'RM';
  end if;
  return v_prefix || '-' || public._pad_seq_code(v_num::text, 5);
end $$;

create or replace function public.peek_next_item_code(p_category text)
returns text language plpgsql stable as $$
declare
  v_num bigint;
  v_prefix text;
  v_seq regclass;
begin
  if p_category = 'packaging' then
    v_seq := 'public.item_code_seq_pkg'; v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_seq := 'public.item_code_seq_fp'; v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_seq := 'public.item_code_seq_pkgfp'; v_prefix := 'PKG-FP';
  else
    v_seq := 'public.item_code_seq_raw'; v_prefix := 'RM';
  end if;

  execute format(
    'select case when is_called then last_value + 1 else last_value end from %s',
    v_seq
  ) into v_num;

  return v_prefix || '-' || public._pad_seq_code(v_num::text, 5);
end $$;

-- ------------------------------------------------------------
-- 9/10. Equipment Master — EQ-#### (0034_equipment_master.sql)
-- ------------------------------------------------------------
create or replace function public.get_next_equipment_code()
returns text language sql as $$
  select 'EQ-' || public._pad_seq_code(nextval('public.equipment_code_seq')::text, 4);
$$;

create or replace function public.peek_next_equipment_code()
returns text language sql stable as $$
  select 'EQ-' || public._pad_seq_code(
    (case when is_called then last_value + 1 else last_value end)::text,
    4
  )
  from public.equipment_code_seq;
$$;

-- ------------------------------------------------------------
-- 11/12. Dead Stock Register — DS-#### (0035_dead_stock_register.sql)
-- ------------------------------------------------------------
create or replace function public.get_next_dead_stock_code()
returns text language sql as $$
  select 'DS-' || public._pad_seq_code(nextval('public.dead_stock_code_seq')::text, 4);
$$;

create or replace function public.peek_next_dead_stock_code()
returns text language sql stable as $$
  select 'DS-' || public._pad_seq_code(
    (case when is_called then last_value + 1 else last_value end)::text,
    4
  )
  from public.dead_stock_code_seq;
$$;

-- ------------------------------------------------------------
-- 13. Production-sourced RM item code — RM-FP-##### (0050_production_
--     rm_from_packaging.sql). Note: this item still lands in items.
--     item_code, which is globally unique — a collision here fails loud
--     (23505), never silent.
-- ------------------------------------------------------------
create or replace function public.get_next_production_rm_item_code()
returns text language sql as $$
  select 'RM-FP-' || public._pad_seq_code(nextval('public.item_code_seq_rmfp')::text, 5);
$$;

-- ------------------------------------------------------------
-- 14. Production batch number — PROD-##/YY (0050_production_rm_from_
--     packaging.sql). count(*)+1 per item/year, not nextval() — narrower
--     blast radius than the others, same bug class, same fix. This is
--     the function behind FB-0043's own live PROD-02/26 batch.
-- ------------------------------------------------------------
create or replace function public.get_next_production_batch_number(p_item_id uuid)
returns text language plpgsql as $$
declare v_year text := to_char(now(), 'YY'); v_n int;
begin
  select count(*) + 1 into v_n from public.production_issue_batches
  where item_id = p_item_id and to_char(created_at, 'YY') = v_year;
  return 'PROD-' || public._pad_seq_code(v_n::text, 2) || '/' || v_year;
end $$;

-- ------------------------------------------------------------
-- 15. Tester Feedback ticket number — FB-#### (0005_feedback_ticket_
--     number.sql)
-- ------------------------------------------------------------
create or replace function public.get_next_feedback_ticket()
returns text language sql as $$
  select 'FB-' || public._pad_seq_code(nextval('public.feedback_ticket_seq')::text, 4);
$$;

-- ------------------------------------------------------------
-- Self-check B: confirm every one of the fifteen functions above
-- genuinely calls the new helper — catches a copy-paste omission (a
-- function accidentally left on the old, unfixed inline lpad(...) form)
-- without touching any real sequence or table, since pg_get_functiondef
-- just reads each function's stored definition text.
-- ------------------------------------------------------------
do $$
declare
  v_fns text[] := array[
    'public.get_next_vendor_code()',
    'public.peek_next_vendor_code()',
    'public.get_next_po_number()',
    'public.get_next_ar_number()',
    'public.get_next_coa_number()',
    'public.get_next_mfr_code()',
    'public.get_next_item_code(text)',
    'public.peek_next_item_code(text)',
    'public.get_next_equipment_code()',
    'public.peek_next_equipment_code()',
    'public.get_next_dead_stock_code()',
    'public.peek_next_dead_stock_code()',
    'public.get_next_production_rm_item_code()',
    'public.get_next_production_batch_number(uuid)',
    'public.get_next_feedback_ticket()'
  ];
  v_fn text;
  v_src text;
begin
  foreach v_fn in array v_fns loop
    select pg_get_functiondef(v_fn::regprocedure) into v_src;
    if v_src not like '%_pad_seq_code%' then
      raise exception '0069 self-check B failed: % does not call _pad_seq_code() — the overflow fix was not applied to this function.', v_fn;
    end if;
  end loop;
end $$;

commit;

-- ############################################################
-- ## 0070_workflow_state_guards.sql
-- ############################################################

-- ============================================================
-- SEC-04 / DES-03 (docs/AI_TESTING_SECURITY_PERFORMANCE_REFERENCE.md):
-- stop direct table writes from bypassing the workflow.
--
-- The problem: several workflow steps are enforced only inside SECURITY
-- DEFINER RPCs or triggers, while the tables' own RLS write policies are
-- role-only. Any user holding the right role can call PostgREST directly
-- with their normal JWT and the public anon key, skipping those steps:
--   * set finished_product_batches.status = 'approved' without QC — no
--     fp_yield ledger push ever happens (stock silently missing);
--   * set mfr_definitions.approved_by/approved_at without
--     approve_mfr_definition() — no FP / Packaged-FP item pair is created;
--   * edit or delete mfr_lines of an APPROVED MFR — the recipe lock in
--     update_mfr_recipe() (0043) is only enforced inside that RPC;
--   * edit lines of a SUBMITTED purchase order (DES-03) — live_remaining_qty
--     is recomputed but the ledger push made at submit is not, so batch and
--     stock balances drift apart;
--   * flip purchase_orders.status directly (draft <-> submitted) without
--     submit_purchase_order()/reopen_purchase_order() — the ledger push or
--     its compensating reversal never happens. 0019 accepted this as a trust
--     decision; it is closed here too because otherwise the purchase-line
--     guard above could be sidestepped by reopening a PO by hand.
--
-- The rule, applied by BEFORE triggers on the five tables:
--   A write is a DIRECT CLIENT WRITE when current_user is 'authenticated' or
--   'anon' — i.e. it came through PostgREST (the app's Server Actions, or
--   anyone calling the API directly). Every trusted writer in the schema is
--   a SECURITY DEFINER function owned by postgres (submit/reopen PO, record
--   wastage, approve/create/update MFR, bulk uploads, the QC-review trigger,
--   the FP draft-cancel reversal, packaging/component triggers,
--   expire_stale_fp_drafts), so inside them current_user is 'postgres' and
--   they pass untouched. So does the Supabase SQL editor (postgres) and the
--   service-role client (service_role). The guard functions themselves are
--   deliberately NOT security definer, so current_user reflects the caller.
--   Direct client writes keep working for every step the app legitimately
--   performs directly today (checked against every .insert/.update/.delete
--   on these tables in lib/actions): FP draft -> in_process / cancelled,
--   in_process -> complete_awaiting_qc, complete_awaiting_qc ->
--   submitted_to_qc; MFR active toggle; creating a draft PO; adding,
--   editing and deleting lines of a draft PO.
--
-- Guard trigger names start with "trg_00_guard_" so they sort (and
-- therefore fire) before every existing BEFORE trigger on the same tables
-- (e.g. trg_fp_updated, trg_purchase_line_live_remaining) — they see exactly
-- what the client sent, before updated_at/live_remaining_qty are filled in.
--
-- No data is changed. Existing rows are untouched; only future direct
-- writes are checked. Run as one transaction; the self-check at the end
-- aborts everything if any guard trigger is missing.
-- ============================================================

begin;

create or replace function public._is_direct_client_write()
returns boolean language sql stable as $$
  select current_user in ('authenticated', 'anon');
$$;

comment on function public._is_direct_client_write() is
  'True when the current statement comes straight from PostgREST (authenticated/anon), false inside SECURITY DEFINER functions, the SQL editor, or the service role. Used by the trg_00_guard_* workflow triggers (0070).';

-- ------------------------------------------------------------
-- 1. finished_product_batches — status may only move along the app's own
--    direct steps; approved/rejected only via the QC review trigger.
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_fp_batch_workflow()
returns trigger language plpgsql set search_path = public as $$
begin
  if not public._is_direct_client_write() then
    return coalesce(new, old);
  end if;

  if tg_op = 'INSERT' then
    if new.status is distinct from 'draft' then
      raise exception 'A new finished product batch must start as a draft (got "%").', new.status
        using errcode = '42501';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status not in ('draft', 'cancelled') then
      raise exception 'Finished product batch % is "%" and cannot be deleted.', old.batch_number, old.status
        using errcode = '42501';
    end if;
    return old;
  end if;

  -- UPDATE
  if new.status is distinct from old.status then
    if not (
         (old.status = 'draft'                and new.status in ('in_process', 'cancelled'))
      or (old.status = 'in_process'           and new.status = 'complete_awaiting_qc')
      or (old.status = 'complete_awaiting_qc' and new.status = 'submitted_to_qc')
    ) then
      raise exception 'Finished product batch % cannot move from "%" to "%" directly. Approval and rejection happen only through the QC review.',
        old.batch_number, old.status, new.status
        using errcode = '42501';
    end if;
  elsif old.status not in ('draft', 'in_process') then
    raise exception 'Finished product batch % is "%" and can no longer be edited.', old.batch_number, old.status
      using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_guard_fp_batch_workflow on public.finished_product_batches;
create trigger trg_00_guard_fp_batch_workflow
  before insert or update or delete on public.finished_product_batches
  for each row execute function public.trg_fn_guard_fp_batch_workflow();

-- ------------------------------------------------------------
-- 2. mfr_definitions — approval fields only via approve_mfr_definition();
--    an approved MFR can only be activated/deactivated directly.
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_mfr_definition_workflow()
returns trigger language plpgsql set search_path = public as $$
begin
  if not public._is_direct_client_write() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.approved_by is not null or new.approved_at is not null or new.finished_product_item_id is not null then
      raise exception 'A new MFR must be created unapproved; use Approve to approve it.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE
  if new.approved_by is distinct from old.approved_by
     or new.approved_at is distinct from old.approved_at
     or new.finished_product_item_id is distinct from old.finished_product_item_id
     or new.version is distinct from old.version then
    raise exception 'MFR % approval details can only be changed with Approve.', old.code
      using errcode = '42501';
  end if;

  if old.approved_by is not null
     and (to_jsonb(new) - 'active' - 'updated_at' - 'updated_by')
         is distinct from (to_jsonb(old) - 'active' - 'updated_at' - 'updated_by') then
    raise exception 'MFR % is approved and locked; only Activate/Deactivate is allowed.', old.code
      using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_guard_mfr_definition_workflow on public.mfr_definitions;
create trigger trg_00_guard_mfr_definition_workflow
  before insert or update on public.mfr_definitions
  for each row execute function public.trg_fn_guard_mfr_definition_workflow();

-- ------------------------------------------------------------
-- 3. mfr_lines — recipe lines of an approved MFR are locked.
--    (A parent that no longer exists — e.g. an admin deleting the MFR,
--    which cascades here — is not treated as approved.)
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_mfr_lines_locked()
returns trigger language plpgsql set search_path = public as $$
declare
  v_code text;
begin
  if not public._is_direct_client_write() then
    return coalesce(new, old);
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    select code into v_code from public.mfr_definitions
    where id = old.mfr_definition_id and approved_by is not null;
    if found then
      raise exception 'MFR % is approved; its recipe lines are locked.', v_code
        using errcode = '42501';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select code into v_code from public.mfr_definitions
    where id = new.mfr_definition_id and approved_by is not null;
    if found then
      raise exception 'MFR % is approved; its recipe lines are locked.', v_code
        using errcode = '42501';
    end if;
    return new;
  end if;

  return old;
end $$;

drop trigger if exists trg_00_guard_mfr_lines_locked on public.mfr_lines;
create trigger trg_00_guard_mfr_lines_locked
  before insert or update or delete on public.mfr_lines
  for each row execute function public.trg_fn_guard_mfr_lines_locked();

-- ------------------------------------------------------------
-- 4. purchase_orders — status and submit/reopen stamps only via
--    submit_purchase_order() / reopen_purchase_order(); a submitted PO's
--    header is locked (only active may change).
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_purchase_order_workflow()
returns trigger language plpgsql set search_path = public as $$
begin
  if not public._is_direct_client_write() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status is distinct from 'draft'
       or new.submitted_at is not null or new.submitted_by is not null
       or new.reopened_at is not null or new.reopened_by is not null then
      raise exception 'A new purchase order must start as a draft; use Final Submit to submit it.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE
  if new.status is distinct from old.status
     or new.submitted_at is distinct from old.submitted_at
     or new.submitted_by is distinct from old.submitted_by
     or new.reopened_at is distinct from old.reopened_at
     or new.reopened_by is distinct from old.reopened_by then
    raise exception 'Purchase order % can only be submitted with Final Submit and reopened with Reopen.', old.po_number
      using errcode = '42501';
  end if;

  if old.status = 'submitted'
     and (to_jsonb(new) - 'active' - 'updated_at' - 'updated_by')
         is distinct from (to_jsonb(old) - 'active' - 'updated_at' - 'updated_by') then
    raise exception 'Purchase order % is submitted and locked. Ask a System Admin to reopen it first.', old.po_number
      using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_guard_purchase_order_workflow on public.purchase_orders;
create trigger trg_00_guard_purchase_order_workflow
  before insert or update on public.purchase_orders
  for each row execute function public.trg_fn_guard_purchase_order_workflow();

-- ------------------------------------------------------------
-- 5. purchase_lines — lines can only be added, edited or deleted while
--    their PO is a draft; pushed_at and live_remaining_qty are never set
--    directly (the submit RPC and the stock triggers own them).
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_purchase_line_workflow()
returns trigger language plpgsql set search_path = public as $$
declare
  v_po record;
begin
  if not public._is_direct_client_write() then
    return coalesce(new, old);
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    select po_number, status into v_po from public.purchase_orders where id = old.purchase_order_id;
    if found and v_po.status <> 'draft' then
      raise exception 'Purchase order % is submitted, so its lines are locked. Ask a System Admin to reopen it first.', v_po.po_number
        using errcode = '42501';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if tg_op = 'UPDATE' then
    if new.purchase_order_id is distinct from old.purchase_order_id then
      raise exception 'A purchase line cannot be moved to a different purchase order.'
        using errcode = '42501';
    end if;
    if new.pushed_at is distinct from old.pushed_at
       or new.live_remaining_qty is distinct from old.live_remaining_qty then
      raise exception 'Stock fields on a purchase line are maintained automatically and cannot be set directly.'
        using errcode = '42501';
    end if;
  end if;

  select po_number, status into v_po from public.purchase_orders where id = new.purchase_order_id;
  if found and v_po.status <> 'draft' then
    raise exception 'Purchase order % is submitted, so lines cannot be added or changed. Ask a System Admin to reopen it first.', v_po.po_number
      using errcode = '42501';
  end if;
  if tg_op = 'INSERT' and new.pushed_at is not null then
    raise exception 'Stock fields on a purchase line are maintained automatically and cannot be set directly.'
      using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_guard_purchase_line_workflow on public.purchase_lines;
create trigger trg_00_guard_purchase_line_workflow
  before insert or update or delete on public.purchase_lines
  for each row execute function public.trg_fn_guard_purchase_line_workflow();

-- ------------------------------------------------------------
-- Self-check: all five guards exist, fire before the older triggers on
-- their tables, and the guard functions are NOT security definer (which
-- would silently disable them by making current_user the owner).
-- ------------------------------------------------------------
do $$
declare
  v_expected text[] := array[
    'finished_product_batches:trg_00_guard_fp_batch_workflow',
    'mfr_definitions:trg_00_guard_mfr_definition_workflow',
    'mfr_lines:trg_00_guard_mfr_lines_locked',
    'purchase_orders:trg_00_guard_purchase_order_workflow',
    'purchase_lines:trg_00_guard_purchase_line_workflow'
  ];
  v_item text;
  v_count int;
begin
  foreach v_item in array v_expected loop
    select count(*) into v_count
    from pg_trigger t
    where not t.tgisinternal
      and t.tgrelid = ('public.' || split_part(v_item, ':', 1))::regclass
      and t.tgname = split_part(v_item, ':', 2);
    if v_count <> 1 then
      raise exception '0070 self-check failed: trigger % is missing.', v_item;
    end if;

    select count(*) into v_count
    from pg_trigger t
    where not t.tgisinternal
      and t.tgrelid = ('public.' || split_part(v_item, ':', 1))::regclass
      and (t.tgtype & 2) = 2                        -- BEFORE trigger
      and t.tgname < split_part(v_item, ':', 2);
    if v_count <> 0 then
      raise exception '0070 self-check failed: a BEFORE trigger on % sorts ahead of its guard.', split_part(v_item, ':', 1);
    end if;
  end loop;

  select count(*) into v_count
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname in ('_is_direct_client_write', 'trg_fn_guard_fp_batch_workflow',
                      'trg_fn_guard_mfr_definition_workflow', 'trg_fn_guard_mfr_lines_locked',
                      'trg_fn_guard_purchase_order_workflow', 'trg_fn_guard_purchase_line_workflow')
    and p.prosecdef;
  if v_count <> 0 then
    raise exception '0070 self-check failed: a guard function is SECURITY DEFINER, which would disable it.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0071_record_wastage_hardening.sql
-- ############################################################

-- ============================================================
-- SEC-06 (docs/AI_TESTING_SECURITY_PERFORMANCE_REFERENCE.md):
-- record_wastage() trusted whatever it was given.
--
-- The previous definition (0036_wastage_batch_required.sql) wrote
-- p_item_id and p_unit into inventory_ledger verbatim and subtracted
-- p_quantity from the batch's live_remaining_qty without checking that:
--   * the batch belongs to that item (item A's stock could be reduced in
--     the ledger while item B's batch balance shrank);
--   * the unit matches the batch's unit — a "500 g" entry against a kg
--     batch removed 500 kg. This was reachable from the normal Wastage
--     screen, whose Unit dropdown offered every unit and defaulted to the
--     ITEM's unit, not the batch's;
--   * the quantity is positive;
--   * the batch is actually in stock (its purchase order submitted).
-- A read-only check on production (28 Sept 2026) found no past wastage
-- entry affected, so no data correction is needed — this only prevents it.
--
-- New behaviour (same name, arguments and return type, so the app keeps
-- calling it unchanged):
--   * the batch row is looked up and locked (FOR UPDATE), so two wastage
--     entries against one batch are applied one after the other;
--   * the ledger row always uses the batch's own item and unit;
--   * p_item_id, if given, must match the batch's item;
--   * p_unit is compared ignoring case/spaces; a different unit in the same
--     family is converted with convert_unit() (e.g. 500 g -> 0.5 kg), an
--     incompatible one is refused;
--   * quantity must be > 0; the batch's PO must be submitted and the line
--     pushed to stock;
--   * live_remaining_not_negative (0029) still caps it at what's left.
--
-- Wrapped in a transaction with a self-check that the function is still
-- SECURITY DEFINER with the expected signature, and that the conversion it
-- relies on behaves as expected.
-- ============================================================

begin;

create or replace function public.record_wastage(
  p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_line record;
  v_from text;
  v_to text;
  v_qty numeric;
  v_id uuid;
begin
  if not public.has_any_role('system_admin','inventory_manager','quality_checker','qc_reviewer') then
    raise exception 'not authorized to record wastage';
  end if;

  if p_purchase_line_id is null then
    raise exception 'Batch (purchase line) is required to record wastage.';
  end if;

  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Wastage quantity must be greater than zero.';
  end if;

  select pl.id, pl.item_id, pl.unit, pl.batch_number, pl.pushed_at, po.status as po_status
    into v_line
  from public.purchase_lines pl
  join public.purchase_orders po on po.id = pl.purchase_order_id
  where pl.id = p_purchase_line_id
  for update of pl;

  if not found then
    raise exception 'That batch could not be found.';
  end if;

  if v_line.po_status <> 'submitted' or v_line.pushed_at is null then
    raise exception 'Batch % has not been received into stock yet (its purchase order is not submitted), so wastage cannot be recorded against it.',
      v_line.batch_number;
  end if;

  if p_item_id is not null and p_item_id <> v_line.item_id then
    raise exception 'Batch % does not belong to the selected item.', v_line.batch_number;
  end if;

  v_to := lower(trim(v_line.unit));
  v_from := lower(trim(coalesce(nullif(trim(p_unit), ''), v_line.unit)));

  if v_from = v_to then
    v_qty := p_quantity;
  else
    v_qty := public.convert_unit(p_quantity, v_from, v_to);
    if v_qty is null then
      raise exception 'Batch % is held in %, so wastage cannot be recorded in "%". Use % or a unit that converts to it.',
        v_line.batch_number, v_line.unit, p_unit, v_line.unit;
    end if;
  end if;

  insert into public.inventory_ledger (event_type, item_id, purchase_line_id, quantity, unit, reference_type, event_by, reason)
  values ('wastage', v_line.item_id, v_line.id, v_qty, v_line.unit, 'purchase', auth.uid(), p_reason)
  returning id into v_id;

  -- live_remaining_not_negative (0029) is still the real bound on how much
  -- can be written off from this batch.
  update public.purchase_lines
  set live_remaining_qty = live_remaining_qty - v_qty
  where id = v_line.id;

  return v_id;
end $$;

do $$
declare
  v_secdef boolean;
begin
  select p.prosecdef into v_secdef
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname = 'record_wastage'
    and pg_get_function_identity_arguments(p.oid)
        = 'p_item_id uuid, p_purchase_line_id uuid, p_quantity numeric, p_unit text, p_reason text';
  if v_secdef is null then
    raise exception '0071 self-check failed: record_wastage with the expected signature is missing.';
  end if;
  if not v_secdef then
    raise exception '0071 self-check failed: record_wastage must be SECURITY DEFINER.';
  end if;
  if public.convert_unit(500, 'g', 'kg') <> 0.5
     or public.convert_unit(250, 'ml', 'ltr') <> 0.25
     or public.convert_unit(1, 'nos', 'kg') is not null then
    raise exception '0071 self-check failed: convert_unit() does not behave as record_wastage expects.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0072_complete_audit_trail.sql
-- ############################################################

-- ============================================================
-- DES-02 (docs/AI_TESTING_SECURITY_PERFORMANCE_REFERENCE.md): complete audit
-- trail, built on the existing one from 0058_audit_trail.sql.
--
-- What 0058 already provides, reused as-is: the audit_log table (full
-- before/after JSON snapshots, changed_by from the session, never writable
-- by clients), its three indexes, its admin/super_auditor-only RLS, and the
-- generic trg_fn_audit_log() trigger — attached then to only four tables
-- (quality_checks, finished_product_batches, purchase_orders,
-- mfr_definitions).
--
-- What this migration adds (Ravi, 28 Sept 2026: "make sure each
-- insert/edit/delete etc is being audited and everything is covered and not
-- missing anything, also make sure no adverse impact on performance"):
--
-- 1. EVERY business table is audited for INSERT, UPDATE and DELETE (28
--    tables; previously 4). inventory_ledger is the one partial case: it is
--    already an append-only audit record (event_by/event_at on every row),
--    so its INSERTs are not duplicated here — but any UPDATE or DELETE of a
--    ledger row (which the app can never do) IS logged.
-- 2. TRUNCATE (e.g. the admin Purge Test Data button) is logged: one row per
--    emptied table. It previously left no trace at all.
-- 3. user_roles is covered — the audit function now accepts the table's key
--    column as a trigger argument (user_roles has no "id"; it uses user_id).
-- 4. User accounts (auth.users): account creation, password changes,
--    the forced-password-change flag, email changes, bans and deletion are
--    logged, with the password hash never stored. Plain sign-ins are not
--    (they only move last_sign_in_at). System-admin actions are also
--    attributed to the admin through audit_account_action(), called by the
--    app — Supabase Auth itself does not know which admin asked.
-- 5. changed_via on every audit row: 'app' (a signed-in user through the
--    app/API), 'server' (the app's service-role key), 'auth service'
--    (Supabase Auth) or 'database' (SQL editor / migrations) — so a fix made
--    directly in the SQL editor is visibly labelled rather than anonymous.
-- 6. Noise and cost control: an UPDATE that changes nothing, or changes only
--    system-maintained columns (updated_at/updated_by everywhere, plus the
--    stock counters purchase_lines.live_remaining_qty,
--    production_issue_batches.live_remaining_qty and
--    finished_product_batches.packaged_qty that move on every stock
--    movement and are already recorded in inventory_ledger), is skipped.
-- 7. The audit log is tamper-proof: its rows cannot be updated, deleted or
--    truncated by anyone, including the SQL editor (the guard trigger would
--    have to be dropped deliberately first).
-- 8. Reliable "who created / who last changed" on every row: created_at,
--    created_by, updated_at, updated_by exist on every business table
--    (added where missing — existing rows stay NULL, their history is not
--    known) and are now filled by the database: created_by is always the
--    signed-in user (a client-supplied value is overwritten, so it cannot be
--    faked or forgotten — before this, most inserts left it empty) and
--    updated_at/updated_by use the existing set_updated_at() trigger.
-- 9. audit_coverage_report(): lists any table that is missing audit or
--    stamp triggers. Empty result = full coverage. Checked at the end of
--    this migration and usable any time (e.g. after a future migration).
--
-- Performance (measured on a local replay before shipping, see
-- known-issues.md Thirty-third pass): one small insert into audit_log per
-- changed row, done in the same transaction; no extra reads; no change to
-- any query the app runs. The existing audit_log indexes cover the Audit Log
-- screen.
--
-- Not covered, by design: reads (SELECTs) and schema changes (migrations —
-- tracked in git and claude/deployment-log.md).
-- ============================================================

begin;

-- ------------------------------------------------------------
-- audit_log: new action value, new changed_via column
-- ------------------------------------------------------------
alter table public.audit_log drop constraint if exists audit_log_action_check;
alter table public.audit_log
  add constraint audit_log_action_check check (action in ('insert', 'update', 'delete', 'truncate'));
alter table public.audit_log add column if not exists changed_via text;

comment on column public.audit_log.changed_via is
  'How the change reached the database: app (signed-in user), server (service-role key), auth service (Supabase Auth), database (SQL editor / migration). Rows before 0072 are NULL.';

-- Where did this change come from? Reads the request claims PostgREST sets
-- for every API call; anything without them came from inside the database.
create or replace function public._audit_changed_via()
returns text language plpgsql stable set search_path = public as $$
declare
  v_role text;
begin
  v_role := nullif(current_setting('request.jwt.claim.role', true), '');
  if v_role is null then
    begin
      v_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
    exception when others then
      v_role := null;
    end;
  end if;
  if v_role = 'authenticated' then return 'app'; end if;
  if v_role = 'service_role' then return 'server'; end if;
  if session_user = 'supabase_auth_admin' then return 'auth service'; end if;
  return 'database';
end $$;

-- ------------------------------------------------------------
-- The generic row trigger — same name and behaviour as 0058 for callers
-- with no arguments, extended with:
--   TG_ARGV[0]  key column holding the row id (default 'id')
--   TG_ARGV[1…] extra system-maintained columns to ignore on UPDATE
-- ------------------------------------------------------------
create or replace function public.trg_fn_audit_log()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_key text := coalesce(nullif(tg_argv[0], ''), 'id');
  v_ignore text[] := array['updated_at', 'updated_by'];
  v_old jsonb;
  v_new jsonb;
  v_row_id uuid;
  i int;
begin
  if tg_nargs > 1 then
    for i in 1 .. tg_nargs - 1 loop
      v_ignore := v_ignore || tg_argv[i];
    end loop;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then v_old := to_jsonb(old); end if;
  if tg_op in ('INSERT', 'UPDATE') then v_new := to_jsonb(new); end if;

  if tg_op = 'UPDATE' and (v_new - v_ignore) = (v_old - v_ignore) then
    return new;  -- nothing a person changed: skip (see header, point 6)
  end if;

  v_row_id := (coalesce(v_new, v_old) ->> v_key)::uuid;

  insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by, changed_via)
  values (tg_table_name, v_row_id, lower(tg_op), v_old, v_new, auth.uid(), public._audit_changed_via());

  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

-- Statement-level TRUNCATE logging (one row per emptied table).
create or replace function public.trg_fn_audit_truncate()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by, changed_via)
  values (tg_table_name, '00000000-0000-0000-0000-000000000000', 'truncate', null,
          jsonb_build_object('note', 'All rows in this table were removed (TRUNCATE).'),
          auth.uid(), public._audit_changed_via());
  return null;
end $$;

-- "Who created it": always the signed-in user when there is one — a
-- client-supplied created_by is overwritten, so it can't be faked or left
-- out. Inside the database (SQL editor, Supabase Auth) there is no signed-in
-- user and whatever was supplied is kept.
create or replace function public.trg_fn_stamp_created()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.created_at is null then
    new.created_at := now();
  end if;
  if auth.uid() is not null then
    new.created_by := auth.uid();
  end if;
  return new;
end $$;

-- ------------------------------------------------------------
-- Attach everything, table by table.
-- ------------------------------------------------------------
do $$
declare
  -- table name, key column, extra ignored columns (comma-separated)
  v_cfg text[][] := array[
    ['bmr_observations',               'id', ''],
    ['bmr_records',                    'id', ''],
    ['bmr_weighment_lines',            'id', ''],
    ['coa_records',                    'id', ''],
    ['coa_template_lines',             'id', ''],
    ['coa_templates',                  'id', ''],
    ['dead_stock_items',               'id', ''],
    ['documents',                      'id', ''],
    ['environmental_control_readings', 'id', ''],
    ['equipment',                      'id', ''],
    ['finished_product_batches',       'id', 'packaged_qty'],
    ['finished_product_components',    'id', ''],
    ['item_types',                     'id', ''],
    ['items',                          'id', ''],
    ['line_clearance_checks',          'id', ''],
    ['mfr_definitions',                'id', ''],
    ['mfr_lines',                      'id', ''],
    ['mfr_procedure_steps',            'id', ''],
    ['packaging_issue_items',          'id', ''],
    ['packaging_issues',               'id', ''],
    ['page_feedback',                  'id', ''],
    ['production_issue_batches',       'id', 'live_remaining_qty'],
    ['profiles',                       'id', ''],
    ['purchase_lines',                 'id', 'live_remaining_qty'],
    ['purchase_orders',                'id', ''],
    ['quality_checks',                 'id', ''],
    ['user_roles',                     'user_id', ''],
    ['vendors',                        'id', '']
  ];
  v_tbl text;
  v_key text;
  v_extra text;
  v_args text;
  i int;
begin
  for i in 1 .. array_length(v_cfg, 1) loop
    v_tbl := v_cfg[i][1];
    v_key := v_cfg[i][2];
    v_extra := v_cfg[i][3];
    v_args := quote_literal(v_key);
    if v_extra <> '' then
      v_args := v_args || ', ' || (select string_agg(quote_literal(trim(x)), ', ') from unnest(string_to_array(v_extra, ',')) x);
    end if;

    -- row-level audit (replaces the four 0058 triggers with identically
    -- named ones that pass the new arguments)
    execute format('drop trigger if exists %I on public.%I', 'trg_audit_' || v_tbl, v_tbl);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.trg_fn_audit_log(%s)',
                   'trg_audit_' || v_tbl, v_tbl, v_args);

    -- truncate audit
    execute format('drop trigger if exists %I on public.%I', 'trg_audit_truncate_' || v_tbl, v_tbl);
    execute format('create trigger %I after truncate on public.%I for each statement execute function public.trg_fn_audit_truncate()',
                   'trg_audit_truncate_' || v_tbl, v_tbl);

    -- standard who/when columns (nullable: existing rows' history is unknown)
    execute format('alter table public.%I add column if not exists created_at timestamptz', v_tbl);
    execute format('alter table public.%I alter column created_at set default now()', v_tbl);
    execute format('alter table public.%I add column if not exists created_by uuid references auth.users(id)', v_tbl);
    execute format('alter table public.%I add column if not exists updated_at timestamptz', v_tbl);
    execute format('alter table public.%I add column if not exists updated_by uuid references auth.users(id)', v_tbl);

    execute format('drop trigger if exists %I on public.%I', 'trg_stamp_created_' || v_tbl, v_tbl);
    execute format('create trigger %I before insert on public.%I for each row execute function public.trg_fn_stamp_created()',
                   'trg_stamp_created_' || v_tbl, v_tbl);

    -- updated_at/updated_by via the existing set_updated_at(), only where a
    -- table doesn't already have it under its own name
    if not exists (
      select 1 from pg_trigger t
      where t.tgrelid = ('public.' || v_tbl)::regclass and not t.tgisinternal
        and t.tgfoid = 'public.set_updated_at'::regproc
    ) then
      execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
                     'trg_stamp_updated_' || v_tbl, v_tbl);
    end if;
  end loop;
end $$;

-- inventory_ledger: its inserts are already the audit record; log only the
-- (never expected) updates/deletes, plus truncate.
drop trigger if exists trg_audit_inventory_ledger on public.inventory_ledger;
create trigger trg_audit_inventory_ledger
  after update or delete on public.inventory_ledger
  for each row execute function public.trg_fn_audit_log('id');
drop trigger if exists trg_audit_truncate_inventory_ledger on public.inventory_ledger;
create trigger trg_audit_truncate_inventory_ledger
  after truncate on public.inventory_ledger
  for each statement execute function public.trg_fn_audit_truncate();

-- ------------------------------------------------------------
-- audit_log is tamper-proof.
-- ------------------------------------------------------------
create or replace function public.trg_fn_audit_log_immutable()
returns trigger language plpgsql as $$
begin
  raise exception 'Audit log entries cannot be changed or deleted.' using errcode = '42501';
end $$;

drop trigger if exists trg_audit_log_immutable on public.audit_log;
create trigger trg_audit_log_immutable
  before update or delete on public.audit_log
  for each row execute function public.trg_fn_audit_log_immutable();
drop trigger if exists trg_audit_log_no_truncate on public.audit_log;
create trigger trg_audit_log_no_truncate
  before truncate on public.audit_log
  for each statement execute function public.trg_fn_audit_log_immutable();

-- ------------------------------------------------------------
-- User accounts (auth.users). The snapshot never includes the password hash.
-- ------------------------------------------------------------
create or replace function public._audit_account_snapshot(p_row jsonb)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'email', p_row ->> 'email',
    'full_name', p_row -> 'raw_user_meta_data' ->> 'full_name',
    'must_change_password', coalesce((p_row -> 'raw_app_meta_data' ->> 'must_change_password')::boolean, false),
    'email_confirmed', (p_row ->> 'email_confirmed_at') is not null,
    'banned_until', p_row ->> 'banned_until',
    'deleted_at', p_row ->> 'deleted_at'
  );
$$;

create or replace function public.trg_fn_audit_auth_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_old jsonb;
  v_new jsonb;
  v_pw_changed boolean := false;
begin
  if tg_op in ('UPDATE', 'DELETE') then v_old := public._audit_account_snapshot(to_jsonb(old)); end if;
  if tg_op in ('INSERT', 'UPDATE') then v_new := public._audit_account_snapshot(to_jsonb(new)); end if;

  if tg_op = 'UPDATE' then
    v_pw_changed := (to_jsonb(new) ->> 'encrypted_password') is distinct from (to_jsonb(old) ->> 'encrypted_password');
    if not v_pw_changed and v_new = v_old then
      return new;  -- sign-ins and token refreshes only touch timestamps
    end if;
    v_new := v_new || jsonb_build_object('password_changed', v_pw_changed);
  end if;

  insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by, changed_via)
  values ('auth.users', case when tg_op = 'DELETE' then old.id else new.id end,
          lower(tg_op), v_old, v_new, auth.uid(), public._audit_changed_via());
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

-- Creating a trigger on auth.users is normally allowed (0001 does it for
-- handle_new_user). If a future Supabase change refuses it, don't block the
-- rest of this migration — audit_coverage_report() will then list it.
do $$
begin
  execute 'drop trigger if exists trg_audit_auth_users on auth.users';
  execute 'create trigger trg_audit_auth_users after insert or update or delete on auth.users for each row execute function public.trg_fn_audit_auth_user()';
exception when insufficient_privilege then
  raise notice '0072: could not attach the account-change audit trigger to auth.users (%). Everything else is applied.', sqlerrm;
end $$;

-- Attribution for account actions done through Supabase Auth's admin API
-- (which does not know which System Admin asked). Called by the app right
-- after the action succeeds, with the admin's own session.
create or replace function public.audit_account_action(p_user_id uuid, p_event text)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_email text;
begin
  if p_event not in ('account_created_by_admin', 'password_reset_by_admin', 'password_changed_by_user') then
    raise exception 'Unknown account event "%".', p_event;
  end if;
  if p_event = 'password_changed_by_user' then
    if auth.uid() is null or auth.uid() <> p_user_id then
      raise exception 'not authorized';
    end if;
  elsif not public.has_any_role('system_admin') then
    raise exception 'not authorized';
  end if;

  select email into v_email from auth.users where id = p_user_id;

  insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by, changed_via)
  values ('auth.users', p_user_id,
          case when p_event = 'account_created_by_admin' then 'insert' else 'update' end,
          null, jsonb_build_object('event', p_event, 'email', v_email),
          auth.uid(), public._audit_changed_via());
end $$;

revoke all on function public.audit_account_action(uuid, text) from public, anon;
grant execute on function public.audit_account_action(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- Coverage report: one row per gap. Empty = everything covered.
-- ------------------------------------------------------------
create or replace function public.audit_coverage_report()
returns table (table_name text, missing text)
language sql stable set search_path = public as $$
  with tbls as (
    select c.oid, c.relname::text as tbl
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relname <> 'audit_log'
  ),
  trg as (
    select t.tgrelid, t.tgfoid, t.tgtype from pg_trigger t where not t.tgisinternal
  )
  select tbl, 'row audit for INSERT' from tbls
   where tbl <> 'inventory_ledger'
     and not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.trg_fn_audit_log'::regproc
                     and (tgtype & 1) = 1 and (tgtype & 4) = 4)
  union all
  select tbl, 'row audit for UPDATE' from tbls
   where not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.trg_fn_audit_log'::regproc
                     and (tgtype & 1) = 1 and (tgtype & 16) = 16)
  union all
  select tbl, 'row audit for DELETE' from tbls
   where not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.trg_fn_audit_log'::regproc
                     and (tgtype & 1) = 1 and (tgtype & 8) = 8)
  union all
  select tbl, 'TRUNCATE audit' from tbls
   where not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.trg_fn_audit_truncate'::regproc
                     and (tgtype & 32) = 32)
  union all
  select tbl, 'created_by stamp' from tbls
   where tbl <> 'inventory_ledger'
     and not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.trg_fn_stamp_created'::regproc)
  union all
  select tbl, 'updated_by stamp' from tbls
   where tbl <> 'inventory_ledger'
     and not exists (select 1 from trg where tgrelid = tbls.oid and tgfoid = 'public.set_updated_at'::regproc)
  union all
  select 'audit_log', 'tamper guard'
   where not exists (select 1 from trg where tgrelid = 'public.audit_log'::regclass
                     and tgfoid = 'public.trg_fn_audit_log_immutable'::regproc and (tgtype & 8) = 8 and (tgtype & 16) = 16)
  union all
  select 'auth.users', 'account-change audit'
   where not exists (select 1 from trg where tgrelid = 'auth.users'::regclass
                     and tgfoid = 'public.trg_fn_audit_auth_user'::regproc);
$$;

revoke all on function public.audit_coverage_report() from public, anon;
grant execute on function public.audit_coverage_report() to authenticated;

-- ------------------------------------------------------------
-- Self-check: every public table covered (auth.users is reported but, per
-- the guarded block above, does not abort the migration).
-- ------------------------------------------------------------
do $$
declare
  v_gaps text;
begin
  select string_agg(table_name || ': ' || missing, '; ') into v_gaps
  from public.audit_coverage_report()
  where table_name <> 'auth.users';
  if v_gaps is not null then
    raise exception '0072 self-check failed — audit coverage gaps: %', v_gaps;
  end if;
end $$;

commit;

-- ############################################################
-- ## 0073_set_user_roles.sql
-- ############################################################

-- ============================================================
-- SEC-07 (docs/AI_TESTING_SECURITY_PERFORMANCE_REFERENCE.md): role changes
-- are saved in one step, and the last System Admin can never be removed.
--
-- Before: setUserRoles() (lib/actions/user-roles.ts) deleted all of a
-- user's roles, then inserted the new set in a second request. A failure
-- between the two left the user with no roles at all. And nothing stopped
-- the last System Admin being removed (by un-ticking the box, by a direct
-- API call, or by deleting that user's account), after which nobody could
-- manage users or roles from the app.
--
-- 1. set_user_roles(p_user_id, p_roles): the only thing the User Roles &
--    Access screen now calls. System Admin only. One transaction: adds the
--    newly ticked roles, removes the un-ticked ones, leaves the rest alone
--    (so the audit log from 0072 shows only the roles that really changed,
--    not a delete-all + re-add of every role).
-- 2. A guard on user_roles itself: any statement that removes a
--    system_admin row (delete, update, or the cascade from deleting that
--    user's account) is refused if no System Admin would remain. It applies
--    to every path — the screen, a direct API call, the SQL editor — and
--    rolls back the whole change, so the user keeps their old roles.
--    Two admins removing each other at the same moment are serialised by a
--    transaction lock, so they cannot both succeed.
--
-- Unaffected: adding roles (createUserAccount inserts directly, as before —
-- still gated by the user_roles_write RLS policy), purge_test_data() (keeps
-- user_roles), and a fresh database with no admin yet (the guard only fires
-- when a statement actually removes a system_admin row).
-- ============================================================

begin;

-- ------------------------------------------------------------
-- Guard: at least one System Admin must remain
-- ------------------------------------------------------------
create or replace function public.trg_fn_keep_one_system_admin()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if exists (select 1 from old_rows where role = 'system_admin') then
    -- Serialise with any other role change in flight, then look at the
    -- committed state (read committed: this query takes a fresh snapshot).
    perform pg_advisory_xact_lock(hashtext('public.user_roles'));
    if not exists (select 1 from public.user_roles where role = 'system_admin') then
      raise exception 'At least one System Admin must remain. Give System Admin to another user first.'
        using errcode = 'P0001';
    end if;
  end if;
  return null;
end;
$$;

drop trigger if exists trg_user_roles_keep_admin_delete on public.user_roles;
create trigger trg_user_roles_keep_admin_delete
  after delete on public.user_roles
  referencing old table as old_rows
  for each statement execute function public.trg_fn_keep_one_system_admin();

drop trigger if exists trg_user_roles_keep_admin_update on public.user_roles;
create trigger trg_user_roles_keep_admin_update
  after update on public.user_roles
  referencing old table as old_rows
  for each statement execute function public.trg_fn_keep_one_system_admin();

-- ------------------------------------------------------------
-- set_user_roles: replace a user's roles in one step
-- ------------------------------------------------------------
create or replace function public.set_user_roles(p_user_id uuid, p_roles text[])
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_valid constant text[] := array[
    'inventory_manager', 'system_admin', 'super_auditor',
    'quality_checker', 'qc_reviewer', 'mfr_manager'
  ];
  v_roles text[];
  v_bad   text;
begin
  if not public.has_role('system_admin') then
    raise exception 'Not authorized. Only System Admin can change user roles.'
      using errcode = '42501';
  end if;

  if p_user_id is null or not exists (select 1 from auth.users where id = p_user_id) then
    raise exception 'User not found.' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(distinct r), '{}')
    into v_roles
    from unnest(coalesce(p_roles, '{}'::text[])) as r
   where r is not null;

  select r into v_bad from unnest(v_roles) as r where r <> all (v_valid) limit 1;
  if v_bad is not null then
    raise exception 'Unknown role: %', v_bad using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('public.user_roles'));

  -- Add first, then remove, so a user is never briefly role-less.
  insert into public.user_roles (user_id, role)
  select p_user_id, r from unnest(v_roles) as r
  on conflict (user_id, role) do nothing;

  delete from public.user_roles
   where user_id = p_user_id
     and role <> all (v_roles);
end;
$$;

revoke all on function public.set_user_roles(uuid, text[]) from public, anon;
grant execute on function public.set_user_roles(uuid, text[]) to authenticated;

commit;

-- ############################################################
-- ## 0074_disable_user_account.sql
-- ############################################################

-- ============================================================
-- Disable / re-enable a user account (Ravi, 28 Sept 2026: "add functionality
-- to disable user if user leaves").
--
-- An account that has ever made a change cannot be deleted — audit_log
-- (and the created_by/updated_by columns) still point to it, which is what
-- keeps the history attributable. So a leaver is DISABLED instead, from User
-- Roles & Access (lib/actions/admin-users.ts):
--   1. all their roles are removed with set_user_roles() (0073) — one
--      transaction, and refused if they are the last System Admin;
--   2. Supabase Auth bans the account (no sign-in, no session refresh);
--   3. the app (proxy) signs out any session they still have open on their
--      next request.
-- Re-enabling lifts the ban; the System Admin then ticks their roles again.
--
-- The ban itself is recorded automatically by 0072's account-change audit
-- (banned_until), but Supabase Auth does not know which admin asked. This
-- migration only lets audit_account_action() record two more events so the
-- Audit Log names the admin: account_disabled_by_admin and
-- account_enabled_by_admin. Nothing else changes.
-- ============================================================

begin;

create or replace function public.audit_account_action(p_user_id uuid, p_event text)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_email text;
begin
  if p_event not in ('account_created_by_admin', 'password_reset_by_admin', 'password_changed_by_user',
                     'account_disabled_by_admin', 'account_enabled_by_admin') then
    raise exception 'Unknown account event "%".', p_event;
  end if;
  if p_event = 'password_changed_by_user' then
    if auth.uid() is null or auth.uid() <> p_user_id then
      raise exception 'not authorized';
    end if;
  elsif not public.has_any_role('system_admin') then
    raise exception 'not authorized';
  end if;

  select email into v_email from auth.users where id = p_user_id;

  insert into public.audit_log (table_name, row_id, action, old_data, new_data, changed_by, changed_via)
  values ('auth.users', p_user_id,
          case when p_event = 'account_created_by_admin' then 'insert' else 'update' end,
          null, jsonb_build_object('event', p_event, 'email', v_email),
          auth.uid(), public._audit_changed_via());
end $$;

revoke all on function public.audit_account_action(uuid, text) from public, anon;
grant execute on function public.audit_account_action(uuid, text) to authenticated;

commit;

-- ############################################################
-- ## 0075_security_hardening.sql
-- ############################################################

-- ============================================================
-- Security hardening bundle (Ravi, 28 Sept 2026:
-- "Implement SEC-10, SEC-01 part 2, SEC-12, SEC-09 (app part) and SEC-14").
-- See claude/security-bundle-decision.md. This migration holds the database
-- parts of SEC-01 part 2 and SEC-14; the rest is app code.
--
-- 1. SEC-01 part 2 — reading data needs at least one role.
--    Before: every business table's read policy was is_signed_in(), i.e.
--    any account with a login — including one with no roles, and a leaver
--    whose account was just disabled (roles removed, access token still
--    valid for up to an hour) — could read formulae, prices, QC and stock
--    straight through the API.
--    Now: has_app_access() = "signed in AND holds at least one role". All
--    read policies that used is_signed_in() use it instead, written as
--    (select public.has_app_access()) so Postgres evaluates it once per
--    query rather than once per row. Two small exceptions keep the
--    "Awaiting access" screen working for a role-less user: they can still
--    read their OWN profile row and their OWN (empty) role list.
--
-- 2. SEC-01 part 2, found while doing (1) — the five reporting views
--    (stock_balance, item_position, inventory_ledger_with_balance,
--    purchase_batch_status, production_batch_status) ran with their
--    owner's rights, which skips row level security entirely, and were
--    granted to the "anon" role. So stock quantities, the stock ledger and
--    batch QC status could be read with only the public API key, without
--    signing in. Now: security_invoker = on (the reader's own access rules
--    apply, i.e. (1) above), anon has no access, and signed-in users can
--    only SELECT from them.
--
-- 3. SEC-14 — batch QC check can no longer race a QC decision.
--    check_batch_qc_approved() (the "only QC-Approved batches can be used"
--    gate) read the batch's QC status without holding anything, so a batch
--    could be used in the same instant a QC Reviewer rejected it (or a
--    retest was opened) and both would succeed. Now the gate takes a shared
--    per-batch lock before reading, and any insert/update of that batch's
--    QC record takes the same lock exclusively. One waits for the other
--    (normally for a few milliseconds) and then sees the real status. Many
--    users can still use the same batch at once (shared locks don't block
--    each other).
--
-- Nothing else changes: write policies, role checks in functions, and the
-- screens users see (apart from the new "Awaiting access" page for a
-- signed-in user with no role, which is app code).
-- ============================================================

begin;

-- ------------------------------------------------------------
-- 1. has_app_access(): signed in and holds at least one role
-- ------------------------------------------------------------
-- security definer: it reads user_roles, whose own read policy uses it —
-- running as the owner avoids that loop (the owner is not subject to RLS).
create or replace function public.has_app_access()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.user_roles where user_id = auth.uid());
$$;

revoke all on function public.has_app_access() from public;
grant execute on function public.has_app_access() to anon, authenticated, service_role;

-- Every read-only policy whose rule is exactly is_signed_in() — 27 business
-- tables plus page_feedback — switches to has_app_access(). Found from the
-- catalogue rather than a hand-kept list, so none can be missed.
do $$
declare
  r record;
begin
  for r in
    select tablename, policyname
      from pg_policies
     where schemaname = 'public'
       and cmd = 'SELECT'
       and qual = 'is_signed_in()'
       and tablename not in ('profiles', 'user_roles')
  loop
    execute format('alter policy %I on public.%I using ((select public.has_app_access()))',
                   r.policyname, r.tablename);
  end loop;
end $$;

-- A role-less user still sees their own name and their own (empty) roles,
-- which the "Awaiting access" screen shows.
alter policy profiles_select on public.profiles
  using ((select public.has_app_access()) or id = (select auth.uid()));
alter policy user_roles_select on public.user_roles
  using ((select public.has_app_access()) or user_id = (select auth.uid()));

-- Feedback: submitting also needs a role now (reading it already does via
-- the loop above).
alter policy page_feedback_insert on public.page_feedback
  with check ((select public.has_app_access()) and submitted_by = auth.uid());

-- ------------------------------------------------------------
-- 2. Reporting views: reader's own access rules, no anonymous access
-- ------------------------------------------------------------
do $$
declare
  v text;
begin
  foreach v in array array['stock_balance', 'item_position', 'inventory_ledger_with_balance',
                           'purchase_batch_status', 'production_batch_status']
  loop
    execute format('alter view public.%I set (security_invoker = on)', v);
    execute format('revoke all on public.%I from anon', v);
    execute format('revoke insert, update, delete, truncate, references, trigger on public.%I from authenticated', v);
    execute format('grant select on public.%I to authenticated', v);
  end loop;
end $$;

-- ------------------------------------------------------------
-- 3. SEC-14: batch QC gate and QC decisions take the same per-batch lock
-- ------------------------------------------------------------
create or replace function public._batch_qc_lock_key(p_purchase_line_id uuid, p_production_batch_id uuid)
returns integer
language sql
immutable
as $$
  select hashtext(coalesce(p_purchase_line_id::text, 'pb:' || p_production_batch_id::text));
$$;

create or replace function public.check_batch_qc_approved()
returns trigger language plpgsql as $$
declare
  v_status public.purchase_batch_status%rowtype;
  v_prod_status public.production_batch_status%rowtype;
begin
  if new.purchase_line_id is not null then
    -- SEC-14: wait for any QC decision on this batch that is being saved
    -- right now, and keep QC decisions on it waiting until this is saved.
    perform pg_advisory_xact_lock_shared(hashtext('batch-qc'),
                                         public._batch_qc_lock_key(new.purchase_line_id, null));

    select * into v_status
    from public.purchase_batch_status
    where purchase_line_id = new.purchase_line_id;

    if v_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (purchase_line_id=%) is not QC-Approved and cannot be consumed', new.purchase_line_id;
    end if;

    if v_status.retest_date is not null and v_status.retest_date <= current_date then
      raise exception 'Batch (purchase_line_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.purchase_line_id, v_status.retest_date;
    end if;

    return new;
  end if;

  if new.production_batch_id is not null then
    perform pg_advisory_xact_lock_shared(hashtext('batch-qc'),
                                         public._batch_qc_lock_key(null, new.production_batch_id));

    select * into v_prod_status
    from public.production_batch_status
    where production_batch_id = new.production_batch_id;

    if v_prod_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (production_batch_id=%) is not QC-Approved and cannot be consumed', new.production_batch_id;
    end if;

    if v_prod_status.retest_date is not null and v_prod_status.retest_date <= current_date then
      raise exception 'Batch (production_batch_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.production_batch_id, v_prod_status.retest_date;
    end if;

    return new;
  end if;

  return new;
end $$;

create or replace function public.trg_fn_lock_batch_qc()
returns trigger language plpgsql as $$
begin
  if new.purchase_line_id is not null or new.production_batch_id is not null then
    perform pg_advisory_xact_lock(hashtext('batch-qc'),
                                  public._batch_qc_lock_key(new.purchase_line_id, new.production_batch_id));
  end if;
  if tg_op = 'UPDATE'
     and (old.purchase_line_id is distinct from new.purchase_line_id
          or old.production_batch_id is distinct from new.production_batch_id)
     and (old.purchase_line_id is not null or old.production_batch_id is not null) then
    perform pg_advisory_xact_lock(hashtext('batch-qc'),
                                  public._batch_qc_lock_key(old.purchase_line_id, old.production_batch_id));
  end if;
  return new;
end $$;

-- "trg_00_" so it runs before the other QC triggers (alphabetical order).
drop trigger if exists trg_00_lock_batch_qc on public.quality_checks;
create trigger trg_00_lock_batch_qc
  before insert or update on public.quality_checks
  for each row execute function public.trg_fn_lock_batch_qc();

-- ------------------------------------------------------------
-- Self-check: no read policy may still rely on is_signed_in() alone
-- ------------------------------------------------------------
do $$
declare
  v_left text;
begin
  select string_agg(tablename || '.' || policyname, ', ') into v_left
    from pg_policies
   where schemaname = 'public'
     and (coalesce(qual, '') like '%is_signed_in()%' or coalesce(with_check, '') like '%is_signed_in()%');
  if v_left is not null then
    raise exception '0075: policies still using is_signed_in(): %', v_left;
  end if;
end $$;

commit;

-- ############################################################
-- ## 0076_single_unit_per_item.sql
-- ############################################################

-- ============================================================
-- One stock unit per item (accuracy audit ACC-02, ACC-03, ACC-04 —
-- claude/app-accuracy-audit-2026-09-28.md; Ravi, 29 Sept 2026: "yes Start
-- Implementing").
--
-- The problem: quantities were stored in whatever unit a line was typed in
-- (a kg item bought once as 500 g, a recipe line in g for a kg item, a
-- finished-product batch in g for an MFR sized in kg) and every stock
-- figure then added them up as if they were one unit — e.g. 10 kg + 500 g
-- showed as 509.9 kg on hand, and a 500 g recipe line took 500 kg out of a
-- kg batch.
--
-- The rule from now on: every item has ONE stock unit — the unit on its
-- Item Master record. Users can still type a quantity in a related unit
-- (g or mg for a kg item, ml for a ltr item); the database converts it to
-- the item's unit when it is saved. A unit that can't be converted (e.g.
-- "nos" for a kg item) is refused with a clear message. So stock, the
-- ledger, batch remaining quantities, recipe scaling and reports always
-- work in one unit per item.
--
--   1. purchase_lines: quantity, QC/Stability/R&D quantities AND the unit
--      price are converted (500 g @ ₹0.50/g is saved as 0.5 kg @ ₹500/kg —
--      the line value is unchanged).
--   2. mfr_lines (recipe lines): quantity converted to the item's unit.
--   3. finished_product_batches: the batch is always in its MFR's
--      batch-size unit (target entered as 50,000 g for a 100 kg MFR is
--      saved as 50 kg), so recipe scaling is always like-for-like.
--   4. packaging_issue_items (packaging materials): converted to the item's
--      unit.
--   5. inventory_ledger (safety net under everything): every stock movement
--      is stored in its item's unit — converted if needed, labelled with the
--      item's unit where the writer left the unit blank (e.g. raw material
--      consumed by a finished-product batch). Nothing can add mixed units
--      to stock again, whatever screen or import wrote it.
--   6. items: an item's unit can't be changed once it has purchases,
--      recipes, stock movements or packaging records (it would silently
--      change the meaning of every stored quantity). An item with no unit
--      set yet takes the unit of its first use.
--
-- Existing data: production has no rows in a different unit from their
-- item (audit-impact-check.sql, 29 Sept 2026 — all zero), and all data is
-- test data (Ravi, 29 Sept 2026), so no back-conversion is needed.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- Helper: the item's stock unit, and the factor to convert into it
-- ------------------------------------------------------------
-- Returns the item's unit. If the item has no unit yet, it adopts p_unit
-- (the first unit it is used with) and returns that.
create or replace function public._item_stock_unit(p_item_id uuid, p_unit text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_unit text;
begin
  select unit into v_unit from public.items where id = p_item_id;
  if v_unit is null and p_unit is not null then
    update public.items set unit = p_unit where id = p_item_id and unit is null;
    v_unit := p_unit;
  end if;
  return v_unit;
end $$;

-- Factor that converts a quantity in p_from into p_to (1 when equal).
-- Raises a user-facing message when the units can't be converted.
create or replace function public._unit_factor(p_from text, p_to text, p_item_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_factor numeric;
  v_name text;
begin
  if p_from is null or p_to is null or p_from = p_to then
    return 1;
  end if;
  v_factor := public.convert_unit(1, p_from, p_to);
  if v_factor is null then
    select item_code || ' — ' || name into v_name from public.items where id = p_item_id;
    raise exception '% is kept in stock in "%", so a quantity in "%" can''t be used for it. Enter it in % (or a unit that converts to it).',
      coalesce(v_name, 'This item'), p_to, p_from, p_to
      using errcode = 'P0001';
  end if;
  -- Unit ratios are powers of ten; drop the trailing zeros numeric
  -- division leaves (0.00100000000000000000 → 0.001).
  return trim_scale(v_factor);
end $$;

-- ------------------------------------------------------------
-- 1. Purchase lines
-- ------------------------------------------------------------
create or replace function public.trg_fn_purchase_line_item_unit()
returns trigger
language plpgsql
as $$
declare
  v_item_unit text;
  v_factor numeric;
begin
  if tg_op = 'UPDATE' then
    -- Quantities on an existing row are already in the item's unit; a row
    -- is converted once, when it is created. Changing its unit later would
    -- be ambiguous (which of its numbers are in the new unit?), so it is
    -- refused. A row whose unit is unchanged is left alone.
    if new.unit is distinct from old.unit then
      raise exception 'The unit of an existing line can''t be changed. Delete the line and add it again in the new unit.'
        using errcode = 'P0001';
    end if;
    return new;
  end if;
  v_item_unit := public._item_stock_unit(new.item_id, new.unit);
  if v_item_unit is null or new.unit = v_item_unit then
    return new;
  end if;
  v_factor := public._unit_factor(new.unit, v_item_unit, new.item_id);
  new.quantity      := trim_scale(new.quantity * v_factor);
  new.qc_qty        := trim_scale(new.qc_qty * v_factor);
  new.stability_qty := trim_scale(new.stability_qty * v_factor);
  new.rnd_qty       := trim_scale(new.rnd_qty * v_factor);
  -- Price is per unit, so it moves the other way (per g × 1000 = per kg).
  if new.unit_price is not null then
    new.unit_price := trim_scale(new.unit_price / v_factor);
  end if;
  new.unit := v_item_unit;
  return new;
end $$;

-- "trg_00_unit_" sorts after the workflow guard (trg_00_guard_…) and before
-- trg_purchase_line_live_remaining, which must see converted quantities.
drop trigger if exists trg_00_unit_purchase_line on public.purchase_lines;
create trigger trg_00_unit_purchase_line
  before insert or update on public.purchase_lines
  for each row execute function public.trg_fn_purchase_line_item_unit();

-- ------------------------------------------------------------
-- 2. Recipe lines
-- ------------------------------------------------------------
create or replace function public.trg_fn_mfr_line_item_unit()
returns trigger
language plpgsql
as $$
declare
  v_item_unit text;
begin
  if tg_op = 'UPDATE' then
    -- Quantities on an existing row are already in the item's unit; a row
    -- is converted once, when it is created. Changing its unit later would
    -- be ambiguous (which of its numbers are in the new unit?), so it is
    -- refused. A row whose unit is unchanged is left alone.
    if new.unit is distinct from old.unit then
      raise exception 'The unit of an existing line can''t be changed. Delete the line and add it again in the new unit.'
        using errcode = 'P0001';
    end if;
    return new;
  end if;
  v_item_unit := public._item_stock_unit(new.item_id, new.unit);
  if v_item_unit is null or new.unit = v_item_unit then
    return new;
  end if;
  new.quantity := trim_scale(new.quantity * public._unit_factor(new.unit, v_item_unit, new.item_id));
  new.unit := v_item_unit;
  return new;
end $$;

drop trigger if exists trg_00_unit_mfr_line on public.mfr_lines;
create trigger trg_00_unit_mfr_line
  before insert or update on public.mfr_lines
  for each row execute function public.trg_fn_mfr_line_item_unit();

-- ------------------------------------------------------------
-- 3. Finished-product batches: always in the MFR's batch-size unit
-- ------------------------------------------------------------
create or replace function public.trg_fn_fp_batch_unit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch_unit text;
  v_fp_item_id uuid;
  v_fp_item_unit text;
begin
  if tg_op = 'UPDATE' then
    if new.unit is distinct from old.unit then
      raise exception 'A finished-product batch''s unit can''t be changed after it is created.'
        using errcode = 'P0001';
    end if;
    return new;
  end if;

  select batch_size_unit, finished_product_item_id
    into v_batch_unit, v_fp_item_id
    from public.mfr_definitions where id = new.mfr_definition_id;

  if v_batch_unit is null then
    return new;
  end if;

  -- The finished product's stock item (created at first MFR approval with
  -- the batch-size unit) must be convertible from the batch unit, or the
  -- batch's yield could never be added to stock.
  if v_fp_item_id is not null then
    select unit into v_fp_item_unit from public.items where id = v_fp_item_id;
    if v_fp_item_unit is not null and public.convert_unit(1, v_batch_unit, v_fp_item_unit) is null then
      raise exception 'This MFR''s batch size is in "%" but its finished product is kept in stock in "%". Correct the MFR before making a batch.',
        v_batch_unit, v_fp_item_unit
        using errcode = 'P0001';
    end if;
  end if;

  if new.unit is distinct from v_batch_unit then
    new.target_qty := trim_scale(new.target_qty * public._unit_factor(new.unit, v_batch_unit, v_fp_item_id));
    new.unit := v_batch_unit;
  end if;
  return new;
end $$;

drop trigger if exists trg_00_unit_fp_batch on public.finished_product_batches;
create trigger trg_00_unit_fp_batch
  before insert or update on public.finished_product_batches
  for each row execute function public.trg_fn_fp_batch_unit();

-- ------------------------------------------------------------
-- 4. Packaging material lines
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_item_unit()
returns trigger
language plpgsql
as $$
declare
  v_item_unit text;
begin
  if tg_op = 'UPDATE' then
    -- Quantities on an existing row are already in the item's unit; a row
    -- is converted once, when it is created. Changing its unit later would
    -- be ambiguous (which of its numbers are in the new unit?), so it is
    -- refused. A row whose unit is unchanged is left alone.
    if new.unit is distinct from old.unit then
      raise exception 'The unit of an existing line can''t be changed. Delete the line and add it again in the new unit.'
        using errcode = 'P0001';
    end if;
    return new;
  end if;
  v_item_unit := public._item_stock_unit(new.item_id, new.unit);
  if v_item_unit is null or new.unit = v_item_unit then
    return new;
  end if;
  new.quantity := trim_scale(new.quantity * public._unit_factor(new.unit, v_item_unit, new.item_id));
  new.unit := v_item_unit;
  return new;
end $$;

drop trigger if exists trg_00_unit_packaging_item on public.packaging_issue_items;
create trigger trg_00_unit_packaging_item
  before insert or update on public.packaging_issue_items
  for each row execute function public.trg_fn_packaging_item_unit();

-- ------------------------------------------------------------
-- 5. Stock ledger safety net: every movement in its item's unit
-- ------------------------------------------------------------
create or replace function public.trg_fn_ledger_item_unit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item_unit text;
begin
  v_item_unit := public._item_stock_unit(new.item_id, new.unit);
  if v_item_unit is null then
    return new;
  end if;
  if new.unit is null then
    -- Writer didn't label it (e.g. RM consumed by an FP batch): the
    -- quantity is already in the batch's unit, which is the item's unit.
    new.unit := v_item_unit;
  elsif new.unit <> v_item_unit then
    new.quantity := trim_scale(new.quantity * public._unit_factor(new.unit, v_item_unit, new.item_id));
    new.unit := v_item_unit;
  end if;
  return new;
end $$;

drop trigger if exists trg_00_unit_ledger on public.inventory_ledger;
create trigger trg_00_unit_ledger
  before insert on public.inventory_ledger
  for each row execute function public.trg_fn_ledger_item_unit();

-- ------------------------------------------------------------
-- 6. An item's unit is fixed once it has been used
-- ------------------------------------------------------------
create or replace function public.trg_fn_item_unit_locked()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.unit is null or new.unit is not distinct from old.unit then
    return new;
  end if;
  if exists (select 1 from public.inventory_ledger where item_id = old.id)
     or exists (select 1 from public.purchase_lines where item_id = old.id)
     or exists (select 1 from public.mfr_lines where item_id = old.id)
     or exists (select 1 from public.packaging_issue_items where item_id = old.id)
     or exists (select 1 from public.production_issue_batches where item_id = old.id)
     or exists (select 1 from public.mfr_definitions where finished_product_item_id = old.id) then
    raise exception 'The unit of % can''t be changed: it already has purchases, recipes or stock movements recorded in "%".',
      old.item_code, old.unit
      using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_unit_locked_item on public.items;
create trigger trg_00_unit_locked_item
  before update of unit on public.items
  for each row execute function public.trg_fn_item_unit_locked();

-- ------------------------------------------------------------
-- Self-check: nothing already stored in a unit different from its item
-- ------------------------------------------------------------
do $$
declare
  v_bad bigint;
begin
  select
      (select count(*) from public.inventory_ledger l join public.items i on i.id = l.item_id where l.unit <> i.unit)
    + (select count(*) from public.purchase_lines pl join public.items i on i.id = pl.item_id where pl.unit <> i.unit)
    + (select count(*) from public.mfr_lines ml join public.items i on i.id = ml.item_id where ml.unit <> i.unit)
    + (select count(*) from public.packaging_issue_items p join public.items i on i.id = p.item_id where p.unit <> i.unit)
    into v_bad;
  if v_bad > 0 then
    raise notice '0076: % existing row(s) are stored in a unit different from their item. New rows are now always converted; existing rows were left as they are.', v_bad;
  end if;
end $$;

commit;

-- ############################################################
-- ## 0077_purchase_line_qc_view.sql
-- ############################################################

-- ============================================================
-- purchase_line_qc — one row per purchase line with its item, PO status and
-- current QC status already joined (accuracy audit ACC-08, 29 Sept 2026).
--
-- Why: the QC page's "Awaiting QC" / "Due for retest" cards and the New AR
-- batch picker first fetched EVERY purchase line with a given QC status from
-- purchase_batch_status (packaging lines, draft-PO lines and all legacy
-- lines included — tens of thousands), then looked those ids up again in
-- purchase_lines with the real filters. Supabase returns at most 1,000 rows
-- per request, so the first step returned an arbitrary 1,000 and a batch
-- that had just arrived could be missing — and then couldn't be given an AR
-- number. (Passing thousands of ids back in the second request also makes
-- an over-long URL.)
--
-- This view lets those screens ask for exactly what they need in ONE
-- filtered request (e.g. qc_status = 'not_submitted', po_status =
-- 'submitted', item_category = 'raw'), with the filters applied in the
-- database before any row limit. QC status comes from purchase_batch_status,
-- so the "latest QC record" rule is unchanged.
--
-- security_invoker: the reader's own access rules apply (0075), and anon has
-- no access — same as the other reporting views.
-- ============================================================

begin;

create or replace view public.purchase_line_qc
with (security_invoker = on) as
select
  pl.id                    as purchase_line_id,
  pl.batch_number,
  pl.item_id,
  i.item_code,
  i.name                   as item_name,
  i.category               as item_category,
  i.default_sample_unit,
  pl.quantity,
  pl.qc_qty,
  pl.stability_qty,
  pl.rnd_qty,
  pl.unit,
  pl.live_remaining_qty,
  pl.active,
  pl.created_at,
  pl.purchase_order_id,
  po.status                as po_status,
  s.qc_status,
  s.ar_number,
  s.retest_date,
  s.quality_check_id
from public.purchase_lines pl
join public.items i on i.id = pl.item_id
join public.purchase_orders po on po.id = pl.purchase_order_id
join public.purchase_batch_status s on s.purchase_line_id = pl.id;

revoke all on public.purchase_line_qc from anon;
revoke insert, update, delete, truncate, references, trigger on public.purchase_line_qc from authenticated;
grant select on public.purchase_line_qc to authenticated;

commit;

-- ############################################################
-- ## 0078_po_reopen_correctness.sql
-- ############################################################

-- ============================================================
-- Reopening a purchase order: correct stock, every time (accuracy audit
-- ACC-01, ACC-06, ACC-27 — claude/app-accuracy-audit-2026-09-28.md; Ravi,
-- 29 Sept 2026: "lets start implementation").
--
-- Three problems with reopen_purchase_order() (0028):
--
-- ACC-01  Reopening the same PO a SECOND time reversed its stock twice.
--         Each reopen reversed every receipt and sample pull the PO had ever
--         made — including the ones an earlier reopen had already reversed.
--         100 kg line: submit 94 → reopen 0 → submit 94 → reopen −94 →
--         submit 0 (should be 94).
--         Now: reopen reverses only what is still NET in stock for each
--         line (receipts minus earlier reversals; sample pulls minus earlier
--         returns), so any number of submit/reopen cycles comes out right.
--
-- ACC-27  Reopening after a batch had been used (in a finished-product
--         batch, or written off as wastage) reversed the full receipt while
--         the used stock was already gone, driving stock negative.
--         Now: reopen is refused while any batch on the PO has been used,
--         naming the batch and how much. (A cancelled FP draft gives its
--         stock back first, so it doesn't block.)
--
-- ACC-06  A batch on a reopened (draft) PO kept its QC approval and could
--         still be used in production, taking stock that was no longer on
--         hand.
--         Now: the QC gate (check_batch_qc_approved) also requires the
--         batch's purchase order to be submitted. The FP compose screen and
--         New AR also only offer submitted batches (app code).
--
-- Nothing else changes: Final Submit, QC, and the first submit/reopen cycle
-- behave exactly as before.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- reopen_purchase_order: net reversal + refuse when stock was used
-- ------------------------------------------------------------
create or replace function public.reopen_purchase_order(p_po_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
  v_used record;
begin
  if not public.has_any_role('system_admin') then
    raise exception 'Not authorized.';
  end if;

  select status into v_status from public.purchase_orders where id = p_po_id for update;
  if v_status is null then
    raise exception 'Purchase order not found.';
  end if;
  if v_status <> 'submitted' then
    raise exception 'This purchase order is not currently submitted.';
  end if;

  -- ACC-27: refuse if any batch has been used. live_remaining_qty is the
  -- batch's received quantity less samples, less everything consumed or
  -- written off (and plus anything returned by a cancelled FP draft).
  select pl.batch_number, pl.unit,
         (pl.quantity - coalesce(pl.qc_qty, 0) - coalesce(pl.stability_qty, 0) - coalesce(pl.rnd_qty, 0))
           - pl.live_remaining_qty as used_qty
    into v_used
    from public.purchase_lines pl
   where pl.purchase_order_id = p_po_id
     and pl.pushed_at is not null
     and (pl.quantity - coalesce(pl.qc_qty, 0) - coalesce(pl.stability_qty, 0) - coalesce(pl.rnd_qty, 0))
           - pl.live_remaining_qty > 0
   order by pl.batch_number
   limit 1;
  if found then
    raise exception 'This purchase order can''t be reopened: batch % has already been used (% % taken for production or written off). Reverse that use first.',
      v_used.batch_number, trim_scale(v_used.used_qty), v_used.unit
      using errcode = 'P0001';
  end if;

  -- ACC-01: take back only what is still net in stock from each line's
  -- receipt (receipts minus earlier reversals).
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'pull', pl.item_id, pl.id, n.net_qty, pl.unit, 'purchase', pl.id, auth.uid()
  from public.purchase_lines pl
  join lateral (
    select sum(case il.event_type when 'push' then il.quantity else -il.quantity end) as net_qty
      from public.inventory_ledger il
     where il.purchase_line_id = pl.id
       and il.reference_type = 'purchase'
       and il.reference_id = pl.id
  ) n on true
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is not null
    and n.net_qty > 0;

  -- ...and give back only the sample pulls still outstanding (pulls minus
  -- earlier returns), per sample type.
  insert into public.inventory_ledger
    (event_type, item_id, purchase_line_id, quantity, unit, reference_type, reference_id, event_by)
  select 'push', pl.item_id, pl.id, n.net_qty, pl.unit, n.reference_type, pl.id, auth.uid()
  from public.purchase_lines pl
  join lateral (
    select il.reference_type,
           sum(case il.event_type when 'pull' then il.quantity else -il.quantity end) as net_qty
      from public.inventory_ledger il
     where il.purchase_line_id = pl.id
       and il.reference_type in ('qc_sample', 'stability_sample', 'rnd_sample')
       and il.reference_id = pl.id
     group by il.reference_type
  ) n on true
  where pl.purchase_order_id = p_po_id
    and pl.pushed_at is not null
    and n.net_qty > 0;

  update public.purchase_lines
  set pushed_at = null
  where purchase_order_id = p_po_id and pushed_at is not null;

  update public.purchase_orders
  set status = 'draft', reopened_at = now(), reopened_by = auth.uid()
  where id = p_po_id;
end $$;

revoke all on function public.reopen_purchase_order(uuid) from public, anon;
grant execute on function public.reopen_purchase_order(uuid) to authenticated;

-- ------------------------------------------------------------
-- QC gate: a batch can only be used while its PO is submitted (ACC-06)
-- ------------------------------------------------------------
-- Same function as 0075 (shared per-batch lock, QC status, retest date),
-- plus the submitted-PO check for purchased batches.
create or replace function public.check_batch_qc_approved()
returns trigger language plpgsql as $$
declare
  v_status public.purchase_batch_status%rowtype;
  v_prod_status public.production_batch_status%rowtype;
  v_pushed_at timestamptz;
  v_batch_number text;
begin
  if new.purchase_line_id is not null then
    perform pg_advisory_xact_lock_shared(hashtext('batch-qc'),
                                         public._batch_qc_lock_key(new.purchase_line_id, null));

    select pushed_at, batch_number into v_pushed_at, v_batch_number
      from public.purchase_lines where id = new.purchase_line_id;
    if v_pushed_at is null then
      raise exception 'Batch % can''t be used: its purchase order isn''t submitted (it may have been reopened for editing).',
        coalesce(v_batch_number, new.purchase_line_id::text)
        using errcode = 'P0001';
    end if;

    select * into v_status
    from public.purchase_batch_status
    where purchase_line_id = new.purchase_line_id;

    if v_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (purchase_line_id=%) is not QC-Approved and cannot be consumed', new.purchase_line_id;
    end if;

    if v_status.retest_date is not null and v_status.retest_date <= current_date then
      raise exception 'Batch (purchase_line_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.purchase_line_id, v_status.retest_date;
    end if;

    return new;
  end if;

  if new.production_batch_id is not null then
    perform pg_advisory_xact_lock_shared(hashtext('batch-qc'),
                                         public._batch_qc_lock_key(null, new.production_batch_id));

    select * into v_prod_status
    from public.production_batch_status
    where production_batch_id = new.production_batch_id;

    if v_prod_status.qc_status is distinct from 'approved' then
      raise exception 'Batch (production_batch_id=%) is not QC-Approved and cannot be consumed', new.production_batch_id;
    end if;

    if v_prod_status.retest_date is not null and v_prod_status.retest_date <= current_date then
      raise exception 'Batch (production_batch_id=%) is due for retest (retest date %) and cannot be consumed until it is re-approved',
        new.production_batch_id, v_prod_status.retest_date;
    end if;

    return new;
  end if;

  return new;
end $$;

commit;

-- ############################################################
-- ## 0079_packaging_fp_integrity.sql
-- ############################################################

-- ============================================================
-- Packaging and finished-product integrity (accuracy audit ACC-05, ACC-12,
-- ACC-17, ACC-19, ACC-20 — claude/app-accuracy-audit-2026-09-28.md; Ravi,
-- 29 Sept 2026).
--
-- ACC-05  "Unpack"/"Repack" took MORE bulk product and packaging material
--         out instead of returning it. Ravi: "from packaging remove
--         transaction type — by default in packaging everything should be
--         packed — no repack, unpack required". Every packaging issue is now
--         a Pack; the database accepts nothing else for new records.
--
-- ACC-12  A packaging issue was saved in two steps (header, then material
--         lines). The header alone already took the finished product out of
--         stock; if the materials step failed (e.g. "Not enough stock" on
--         jars) the clean-up delete was silently blocked, so the stock stayed
--         deducted — and a retry deducted it again.
--         Now: create_packaging_issue() saves header and materials in ONE
--         transaction — all of it or none of it.
--
-- ACC-17  Same two-step problem for a new finished-product batch: a failed
--         component insert left an empty draft batch behind (and used up a
--         batch number) for anyone who isn't System Admin.
--         Now: create_finished_product_batch() saves batch and components in
--         one transaction.
--
-- ACC-19  A finished-product batch could be packed/issued beyond its OWN
--         yield (the stock check was item-level, so another batch of the
--         same product "covered" it) — breaking batch traceability on
--         packaging records and labels.
--         Now: each packaging issue is checked against what is left of that
--         batch (yield − QC/stability/R&D samples − earlier issues).
--
-- ACC-20  Packaging materials (bottles, jars, labels) came out of item stock
--         but never out of any purchase batch, so every batch still showed
--         its full quantity remaining.
--         Now: materials are drawn from their oldest submitted purchase
--         batches first (FIFO), each batch's remaining quantity goes down,
--         and each stock movement records which batch it came from. (Any
--         part not covered by a batch — e.g. an opening balance with no
--         batch — is still taken from item stock, as before.)
--
-- Both new functions run with the CALLER's rights (security invoker): the
-- same role and row rules apply as before; they only make the two inserts
-- one unit.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- ACC-05: only "pack" from now on
-- ------------------------------------------------------------
alter table public.packaging_issues drop constraint if exists packaging_issues_transaction_type_check;
alter table public.packaging_issues
  add constraint packaging_issues_transaction_type_check check (transaction_type = 'pack') not valid;
alter table public.packaging_issues alter column transaction_type set default 'pack';

-- ------------------------------------------------------------
-- ACC-19: a batch can't be packed/issued beyond what is left of it
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_batch_balance()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch record;
  v_fp_unit text;
  v_factor numeric;
  v_left numeric;
  v_issued numeric;
begin
  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  -- Lock the batch so two issues against it at the same moment are checked
  -- one after the other.
  select fpb.batch_number, fpb.batch_yield, fpb.unit,
         coalesce(fpb.qc_sample_qty, 0) + coalesce(fpb.stability_qty, 0) + coalesce(fpb.rnd_qty, 0) as samples,
         md.finished_product_item_id
    into v_batch
    from public.finished_product_batches fpb
    join public.mfr_definitions md on md.id = fpb.mfr_definition_id
   where fpb.id = new.finished_product_batch_id
     for update of fpb;

  if v_batch.batch_yield is null then
    return new;   -- no yield recorded (older data): item-level check still applies
  end if;

  select unit into v_fp_unit from public.items where id = v_batch.finished_product_item_id;
  -- fp_qty_consumed is in the finished product's stock unit; the batch's
  -- yield is in the batch's unit (0076 keeps these compatible).
  v_factor := coalesce(public.convert_unit(1, v_batch.unit, coalesce(v_fp_unit, v_batch.unit)), 1);

  select coalesce(sum(fp_qty_consumed), 0) into v_issued
    from public.packaging_issues
   where finished_product_batch_id = new.finished_product_batch_id
     and id is distinct from new.id;

  v_left := (v_batch.batch_yield - v_batch.samples) * v_factor - v_issued;

  if new.fp_qty_consumed > v_left + 0.0000001 then
    raise exception 'Batch % has only % % left to pack or issue (yield less samples, less % % already issued). This issue needs % %.',
      v_batch.batch_number, trim_scale(round(greatest(v_left, 0), 6)), coalesce(v_fp_unit, v_batch.unit),
      trim_scale(round(v_issued, 6)), coalesce(v_fp_unit, v_batch.unit),
      trim_scale(round(new.fp_qty_consumed, 6)), coalesce(v_fp_unit, v_batch.unit)
      using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_packaging_batch_balance on public.packaging_issues;
create trigger trg_00_packaging_batch_balance
  before insert on public.packaging_issues
  for each row execute function public.trg_fn_packaging_batch_balance();

-- ------------------------------------------------------------
-- ACC-20: packaging materials drawn FIFO from their purchase batches
-- ------------------------------------------------------------
create or replace function public.trg_fn_packaging_item_pull()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_department text;
  v_left numeric;
  v_take numeric;
  r record;
begin
  select department into v_department
  from public.packaging_issues
  where id = new.packaging_issue_id;

  perform public.check_sufficient_stock(new.item_id, new.quantity);

  v_left := new.quantity;
  for r in
    select pl.id, pl.live_remaining_qty
      from public.purchase_lines pl
     where pl.item_id = new.item_id
       and pl.active
       and pl.pushed_at is not null
       and pl.live_remaining_qty > 0
     order by pl.created_at, pl.id
       for update
  loop
    exit when v_left <= 0;
    v_take := least(r.live_remaining_qty, v_left);
    update public.purchase_lines set live_remaining_qty = live_remaining_qty - v_take where id = r.id;
    insert into public.inventory_ledger
      (event_type, item_id, purchase_line_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('pull', new.item_id, r.id, v_take, new.unit, v_department, 'packaging', new.packaging_issue_id, auth.uid());
    v_left := v_left - v_take;
  end loop;

  if v_left > 0 then
    -- Stock not held in any batch (e.g. an opening balance): taken from the
    -- item as before.
    insert into public.inventory_ledger
      (event_type, item_id, quantity, unit, department, reference_type, reference_id, event_by)
    values
      ('pull', new.item_id, v_left, new.unit, v_department, 'packaging', new.packaging_issue_id, auth.uid());
  end if;
  return new;
end $$;

-- ------------------------------------------------------------
-- ACC-12: packaging issue + materials in one transaction
-- ------------------------------------------------------------
create or replace function public.create_packaging_issue(p_issue jsonb, p_materials jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  m jsonb;
begin
  insert into public.packaging_issues
    (code, finished_product_batch_id, pack_size, pack_size_qty, pack_size_unit, fp_qty_consumed,
     unit_count, department, transaction_type, qc_qty, stability_qty, rnd_qty)
  values
    (p_issue->>'code',
     (p_issue->>'finished_product_batch_id')::uuid,
     p_issue->>'pack_size',
     nullif(p_issue->>'pack_size_qty', '')::numeric,
     nullif(p_issue->>'pack_size_unit', ''),
     nullif(p_issue->>'fp_qty_consumed', '')::numeric,
     (p_issue->>'unit_count')::numeric,
     p_issue->>'department',
     'pack',
     nullif(p_issue->>'qc_qty', '')::numeric,
     nullif(p_issue->>'stability_qty', '')::numeric,
     nullif(p_issue->>'rnd_qty', '')::numeric)
  returning id into v_id;

  for m in select * from jsonb_array_elements(coalesce(p_materials, '[]'::jsonb))
  loop
    insert into public.packaging_issue_items (packaging_issue_id, item_id, quantity, unit)
    values (v_id, (m->>'item_id')::uuid, (m->>'quantity')::numeric, m->>'unit');
  end loop;

  return v_id;
end $$;

revoke all on function public.create_packaging_issue(jsonb, jsonb) from public, anon;
grant execute on function public.create_packaging_issue(jsonb, jsonb) to authenticated;

-- ------------------------------------------------------------
-- ACC-17: finished-product batch + components in one transaction
-- ------------------------------------------------------------
create or replace function public.create_finished_product_batch(p_batch jsonb, p_components jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  c jsonb;
begin
  if jsonb_array_length(coalesce(p_components, '[]'::jsonb)) = 0 then
    raise exception 'A batch needs at least one component.' using errcode = 'P0001';
  end if;

  insert into public.finished_product_batches
    (batch_number, short_batch_no, mfr_definition_id, mfr_version, target_qty, unit, batch_start_date, status)
  values
    (p_batch->>'batch_number',
     p_batch->>'short_batch_no',
     (p_batch->>'mfr_definition_id')::uuid,
     (p_batch->>'mfr_version')::integer,
     (p_batch->>'target_qty')::numeric,
     p_batch->>'unit',
     nullif(p_batch->>'batch_start_date', '')::date,
     'draft')
  returning id into v_id;

  for c in select * from jsonb_array_elements(p_components)
  loop
    insert into public.finished_product_components
      (finished_product_batch_id, item_id, purchase_line_id, production_batch_id, quantity)
    values
      (v_id,
       (c->>'item_id')::uuid,
       nullif(c->>'purchase_line_id', '')::uuid,
       nullif(c->>'production_batch_id', '')::uuid,
       (c->>'quantity')::numeric);
  end loop;

  return v_id;
end $$;

revoke all on function public.create_finished_product_batch(jsonb, jsonb) from public, anon;
grant execute on function public.create_finished_product_batch(jsonb, jsonb) to authenticated;

commit;

-- ############################################################
-- ## 0080_batch_numbers_and_retests.sql
-- ############################################################

-- ============================================================
-- Batch numbers and retests (accuracy audit ACC-09, ACC-10, ACC-16, ACC-39 —
-- claude/app-accuracy-audit-2026-09-28.md; Ravi, 29 Sept 2026: "Start
-- Implementation").
--
-- ACC-09  Batch numbers were "count this item's batches this year + 1". After
--         a draft line was deleted, the count went down and the next number
--         repeated one already in use: for normal items every save then failed
--         for the rest of the year; for items whose code starts with LEG- (not
--         covered by the unique index) two batches silently got the same
--         number. Same count+1 pattern in finished-product and production
--         batch numbers.
--         Now: next number = highest number already used for that item (or
--         MFR) this year + 1, read from the batch numbers themselves, so a
--         deletion can never make a number repeat. A guard also refuses a
--         duplicate purchase batch number for ANY item, LEG- included.
--
-- ACC-10  An approved batch with no stability sample (0 is allowed, and all
--         legacy lines are 0) was blocked from production once its retest date
--         passed — but "Due for retest" didn't list it and "Start Retest"
--         refused it, so it could never be retested.
-- ACC-16  Every retest recorded the FULL stability reserve as its sample, and
--         the reserve never went down.
-- ACC-39  "Due for retest" listed batches with nothing left.
--         Now: start_retest() takes the retest sample size entered by QC. It
--         is drawn from the batch's stability reserve first (already out of
--         stock since Final Submit), and only any remainder from the batch's
--         remaining stock (a normal QC-sample stock movement). Each retest
--         records how much came from each, so the reserve goes down. Every
--         due batch that still has stock is listed, with or without a
--         stability reserve.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- ACC-09: next batch number = highest used + 1
-- ------------------------------------------------------------
-- Highest sequence already used among batch numbers shaped
-- <prefix><digits><suffix>, e.g. 'RM-00012-' || '07' || '/26'.
create or replace function public._max_batch_seq(p_numbers text[], p_prefix text, p_suffix text)
returns integer
language sql
immutable
as $$
  select coalesce(max(substr(n, length(p_prefix) + 1, length(n) - length(p_prefix) - length(p_suffix))::integer), 0)
    from unnest(p_numbers) as n
   where left(n, length(p_prefix)) = p_prefix
     and right(n, length(p_suffix)) = p_suffix
     and substr(n, length(p_prefix) + 1, length(n) - length(p_prefix) - length(p_suffix)) ~ '^[0-9]{1,9}$';
$$;

create or replace function public.get_next_batch_number(p_item_id uuid)
returns text
language plpgsql
as $$
declare
  v_year text := to_char(now(), 'YY');
  v_item_code text;
  v_n int;
begin
  select item_code into v_item_code from public.items where id = p_item_id;
  select public._max_batch_seq(array_agg(batch_number), v_item_code || '-', '/' || v_year) + 1
    into v_n
    from public.purchase_lines where item_id = p_item_id;
  return v_item_code || '-' || lpad(v_n::text, greatest(2, length(v_n::text)), '0') || '/' || v_year;
end $$;

create or replace function public.get_next_fp_batch_number(p_mfr_definition_id uuid)
returns table(batch_number text, short_batch_no text)
language plpgsql
as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
  v_item_code text;
  v_market text;
  v_seq_year text;
  v_short_prefix text;
begin
  select i.item_code, m.market into v_item_code, v_market
  from public.mfr_definitions m
  join public.items i on i.id = m.finished_product_item_id
  where m.id = p_mfr_definition_id;

  select public._max_batch_seq(array_agg(fpb.batch_number), coalesce(v_item_code, 'FP') || '-', '/' || v_year) + 1
    into v_n
    from public.finished_product_batches fpb
   where fpb.mfr_definition_id = p_mfr_definition_id;

  v_seq_year := lpad(v_n::text, greatest(2, length(v_n::text)), '0') || '/' || v_year;
  v_short_prefix := case coalesce(v_market, 'domestic') when 'export' then 'OR' else 'PR' end;

  batch_number := coalesce(v_item_code, 'FP') || '-' || v_seq_year;
  short_batch_no := v_short_prefix || '-' || v_seq_year;
  return next;
end $$;

create or replace function public.get_next_production_batch_number(p_item_id uuid)
returns text
language plpgsql
as $$
declare
  v_year text := to_char(now(), 'YY');
  v_n int;
begin
  select public._max_batch_seq(array_agg(batch_number), 'PROD-', '/' || v_year) + 1
    into v_n
    from public.production_issue_batches where item_id = p_item_id;
  return 'PROD-' || public._pad_seq_code(v_n::text, 2) || '/' || v_year;
end $$;

-- Duplicate guard for purchase batch numbers on every item (the unique index
-- skips numbers starting LEG-, because imported legacy data has duplicates;
-- this guard checks new and changed rows only, so that data is untouched).
create or replace function public.trg_fn_purchase_line_batch_unique()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' and new.batch_number is not distinct from old.batch_number
     and new.item_id is not distinct from old.item_id then
    return new;
  end if;
  if exists (select 1 from public.purchase_lines
              where item_id = new.item_id and batch_number = new.batch_number and id <> new.id) then
    raise exception 'Batch number % is already used for this item.', new.batch_number
      using errcode = '23505';
  end if;
  return new;
end $$;

drop trigger if exists trg_00_batch_unique_purchase_line on public.purchase_lines;
create trigger trg_00_batch_unique_purchase_line
  before insert or update on public.purchase_lines
  for each row execute function public.trg_fn_purchase_line_batch_unique();

-- ------------------------------------------------------------
-- ACC-10 / ACC-16: retests draw from the stability reserve, then stock
-- ------------------------------------------------------------
alter table public.quality_checks add column if not exists stability_reserve_used numeric;
alter table public.quality_checks add column if not exists stock_sample_used numeric;
comment on column public.quality_checks.stability_reserve_used is
  'Retests only: part of the sample taken from the batch''s stability reserve, in the batch''s unit (0080).';
comment on column public.quality_checks.stock_sample_used is
  'Retests only: part of the sample taken from the batch''s remaining stock, in the batch''s unit (0080).';

-- Earlier retests took their sample from the reserve (in full).
update public.quality_checks q
   set stability_reserve_used = coalesce(public.convert_unit(q.sample_qty, q.sample_unit, pl.unit), q.sample_qty)
  from public.purchase_lines pl
 where q.is_retest and q.purchase_line_id = pl.id and q.stability_reserve_used is null;
update public.quality_checks q
   set stability_reserve_used = coalesce(public.convert_unit(q.sample_qty, q.sample_unit, pb.unit), q.sample_qty)
  from public.production_issue_batches pb
 where q.is_retest and q.production_batch_id = pb.id and q.stability_reserve_used is null;

create or replace function public.stability_reserve_left(p_purchase_line_id uuid, p_production_batch_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select greatest(
    coalesce(
      (select stability_qty from public.purchase_lines where id = p_purchase_line_id),
      (select stability_qty from public.production_issue_batches where id = p_production_batch_id),
      0)
    - coalesce((select sum(q.stability_reserve_used) from public.quality_checks q
                 where q.is_retest
                   and ((p_purchase_line_id is not null and q.purchase_line_id = p_purchase_line_id)
                     or (p_production_batch_id is not null and q.production_batch_id = p_production_batch_id))), 0),
    0);
$$;
grant execute on function public.stability_reserve_left(uuid, uuid) to authenticated;

create or replace function public.start_retest(
  p_purchase_line_id uuid,
  p_production_batch_id uuid,
  p_sample_qty numeric,
  p_sample_unit text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item_id uuid;
  v_unit text;
  v_batch_number text;
  v_live numeric;
  v_pushed timestamptz;
  v_latest record;
  v_qty numeric;
  v_reserve numeric;
  v_from_reserve numeric;
  v_from_stock numeric;
  v_id uuid;
begin
  if not public.has_any_role('system_admin', 'inventory_manager', 'quality_checker', 'qc_reviewer') then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if (p_purchase_line_id is null) = (p_production_batch_id is null) then
    raise exception 'Choose one batch to retest.' using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtext('batch-qc'),
                                public._batch_qc_lock_key(p_purchase_line_id, p_production_batch_id));

  if p_purchase_line_id is not null then
    select item_id, unit, batch_number, live_remaining_qty, pushed_at
      into v_item_id, v_unit, v_batch_number, v_live, v_pushed
      from public.purchase_lines where id = p_purchase_line_id for update;
    if v_item_id is null then
      raise exception 'Batch not found.' using errcode = 'P0002';
    end if;
    if v_pushed is null then
      raise exception 'Batch %: its purchase order isn''t submitted.', v_batch_number using errcode = 'P0001';
    end if;
    select status, retest_date into v_latest
      from public.quality_checks where purchase_line_id = p_purchase_line_id
     order by created_at desc limit 1;
  else
    select item_id, unit, batch_number, live_remaining_qty
      into v_item_id, v_unit, v_batch_number, v_live
      from public.production_issue_batches where id = p_production_batch_id for update;
    if v_item_id is null then
      raise exception 'Batch not found.' using errcode = 'P0002';
    end if;
    select status, retest_date into v_latest
      from public.quality_checks where production_batch_id = p_production_batch_id
     order by created_at desc limit 1;
  end if;

  if v_latest.status is distinct from 'approved' then
    raise exception 'Batch % is not due for retest (it isn''t currently approved).', v_batch_number using errcode = 'P0001';
  end if;
  if v_latest.retest_date is null or v_latest.retest_date > current_date then
    raise exception 'Batch %''s retest date has not arrived yet.', v_batch_number using errcode = 'P0001';
  end if;

  if p_sample_qty is null or p_sample_qty <= 0 then
    raise exception 'Enter the retest sample quantity.' using errcode = 'P0001';
  end if;
  v_qty := public.convert_unit(p_sample_qty, p_sample_unit, v_unit);
  if v_qty is null then
    raise exception 'Batch % is kept in %, so a sample in % can''t be used.', v_batch_number, v_unit, p_sample_unit
      using errcode = 'P0001';
  end if;

  v_reserve := public.stability_reserve_left(p_purchase_line_id, p_production_batch_id);
  v_from_reserve := least(v_reserve, v_qty);
  v_from_stock := v_qty - v_from_reserve;

  if v_from_stock > coalesce(v_live, 0) + 0.0000001 then
    raise exception 'Batch % has only % % of stability reserve and % % of stock left — not enough for a % % sample.',
      v_batch_number, trim_scale(v_reserve), v_unit, trim_scale(coalesce(v_live, 0)), v_unit, trim_scale(v_qty), v_unit
      using errcode = 'P0001';
  end if;

  if v_from_stock > 0 then
    if p_purchase_line_id is not null then
      update public.purchase_lines set live_remaining_qty = live_remaining_qty - v_from_stock where id = p_purchase_line_id;
    else
      update public.production_issue_batches set live_remaining_qty = live_remaining_qty - v_from_stock where id = p_production_batch_id;
    end if;
    insert into public.inventory_ledger
      (event_type, item_id, purchase_line_id, production_batch_id, quantity, unit, reference_type, reference_id, event_by, reason)
    values
      ('pull', v_item_id, p_purchase_line_id, p_production_batch_id, v_from_stock, v_unit, 'qc_sample',
       coalesce(p_purchase_line_id, p_production_batch_id), auth.uid(), 'Retest sample');
  end if;

  insert into public.quality_checks
    (ar_number, purchase_line_id, production_batch_id, item_id, sample_qty, sample_unit, is_retest,
     stability_reserve_used, stock_sample_used)
  values
    (public.get_next_ar_number(), p_purchase_line_id, p_production_batch_id, v_item_id, p_sample_qty, p_sample_unit, true,
     v_from_reserve, v_from_stock)
  returning id into v_id;

  return v_id;
end $$;

revoke all on function public.start_retest(uuid, uuid, numeric, text) from public, anon;
grant execute on function public.start_retest(uuid, uuid, numeric, text) to authenticated;

-- purchase_line_qc (0077) gains the stability reserve still available, for
-- the "Due for retest" card.
create or replace view public.purchase_line_qc
with (security_invoker = on) as
select
  pl.id                    as purchase_line_id,
  pl.batch_number,
  pl.item_id,
  i.item_code,
  i.name                   as item_name,
  i.category               as item_category,
  i.default_sample_unit,
  pl.quantity,
  pl.qc_qty,
  pl.stability_qty,
  pl.rnd_qty,
  pl.unit,
  pl.live_remaining_qty,
  pl.active,
  pl.created_at,
  pl.purchase_order_id,
  po.status                as po_status,
  s.qc_status,
  s.ar_number,
  s.retest_date,
  s.quality_check_id,
  greatest(pl.stability_qty - coalesce((select sum(q.stability_reserve_used) from public.quality_checks q
                                          where q.is_retest and q.purchase_line_id = pl.id), 0), 0)
                           as stability_reserve_left
from public.purchase_lines pl
join public.items i on i.id = pl.item_id
join public.purchase_orders po on po.id = pl.purchase_order_id
join public.purchase_batch_status s on s.purchase_line_id = pl.id;

revoke all on public.purchase_line_qc from anon;
grant select on public.purchase_line_qc to authenticated;

commit;

-- ############################################################
-- ## 0081_india_time_zone.sql
-- ############################################################

-- ============================================================
-- India time for every date the database works out (accuracy audit ACC-13 —
-- claude/app-accuracy-audit-2026-09-28.md; Ravi, 29 Sept 2026: "Start
-- Implementation").
--
-- The database ran on UTC, so between 00:00 and 05:30 IST it still thought
-- it was yesterday:
--   - a QC approved at 01:00 IST on 5 Oct got its retest date counted from
--     4 Oct (one day early);
--   - AR, PO and batch numbers created then carried the previous day — and
--     on 1 January, the previous year;
--   - "is this batch due for retest today" checks used yesterday's date;
--   - date filters without an explicit offset were read as UTC days.
--
-- Now the database's own time zone is India (Asia/Kolkata): current_date,
-- now()::date, to_char(now(), ...) and date filters all follow IST. Stored
-- timestamps don't change (they are absolute moments); only the calendar day
-- a moment is counted in does. The retest-date calculation is also written
-- with the time zone spelled out, so it can never depend on a session
-- setting.
--
-- Takes effect for new database connections (the API recycles its
-- connections within about 30 minutes; the SQL editor uses a new one).
-- ============================================================

begin;

do $$
begin
  execute format('alter database %I set timezone to %L', current_database(), 'Asia/Kolkata');
end $$;

-- The API connects as "authenticator"; set it there too so a role-level
-- setting can never override the database default. (Skipped quietly if this
-- project doesn't allow it.)
do $$
begin
  execute 'alter role authenticator set timezone to ''Asia/Kolkata''';
exception when others then
  raise notice '0081: could not set the time zone on role authenticator (%); the database default applies.', sqlerrm;
end $$;

-- Retest date = the IST day the QC was approved + the retest period.
create or replace function public.trg_fn_qc_compute_retest_date()
returns trigger
language plpgsql
as $$
begin
  if new.reviewed_at is not null and new.retest_period_days is not null then
    new.retest_date := ((new.reviewed_at at time zone 'Asia/Kolkata')::date
                        + (new.retest_period_days || ' days')::interval)::date;
  else
    new.retest_date := null;
  end if;
  return new;
end $$;

commit;

-- ############################################################
-- ## 0082_current_qc_approval.sql
-- ############################################################

-- ============================================================
-- A COA only for a batch's CURRENT approval (accuracy audit ACC-15 —
-- claude/app-accuracy-audit-2026-09-28.md; Ravi, 29 Sept 2026: "Start
-- Implementation").
--
-- The New COA picker offered every QC record that had EVER been approved.
-- So a certificate could be issued for a batch that is now rejected, has a
-- retest in progress, or is past its retest date — quoting an approval that
-- no longer stands.
--
-- current_qc_approvals lists the QC records that are a batch's standing
-- approval today:
--   - status approved;
--   - the LATEST QC record for its batch (a later retest, pending or
--     decided, supersedes it);
--   - for raw-material and production batches, retest date not yet reached
--     (finished products have no retest workflow, so their retest date
--     doesn't retire the approval).
--
-- The New COA picker lists only these; saving a COA re-checks it, and the
-- database refuses a COA for any other QC record (backstop).
-- ============================================================

begin;

create index if not exists quality_checks_production_batch_id_idx
  on public.quality_checks (production_batch_id);

create or replace view public.current_qc_approvals
with (security_invoker = on) as
select q.id as quality_check_id,
       q.purchase_line_id,
       q.finished_product_batch_id,
       q.production_batch_id,
       q.retest_date
  from public.quality_checks q
 where q.status = 'approved'
   and (q.finished_product_batch_id is not null
        or q.retest_date is null
        or q.retest_date > current_date)
   and not exists (
         select 1 from public.quality_checks n
          where n.purchase_line_id = q.purchase_line_id
            and n.id <> q.id
            and (n.created_at > q.created_at or (n.created_at = q.created_at and n.id > q.id)))
   and not exists (
         select 1 from public.quality_checks n
          where n.finished_product_batch_id = q.finished_product_batch_id
            and n.id <> q.id
            and (n.created_at > q.created_at or (n.created_at = q.created_at and n.id > q.id)))
   and not exists (
         select 1 from public.quality_checks n
          where n.production_batch_id = q.production_batch_id
            and n.id <> q.id
            and (n.created_at > q.created_at or (n.created_at = q.created_at and n.id > q.id)));

revoke all on public.current_qc_approvals from public, anon;
grant select on public.current_qc_approvals to authenticated;

create or replace function public.qc_is_current_approval(p_quality_check_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.current_qc_approvals where quality_check_id = p_quality_check_id);
$$;

revoke all on function public.qc_is_current_approval(uuid) from public, anon;
grant execute on function public.qc_is_current_approval(uuid) to authenticated;

-- Backstop: a new COA must quote a batch's current approval.
create or replace function public.trg_fn_coa_current_approval()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ar text;
begin
  if new.quality_check_id is null then
    return new;
  end if;
  if not public.qc_is_current_approval(new.quality_check_id) then
    select ar_number into v_ar from public.quality_checks where id = new.quality_check_id;
    raise exception 'A COA can''t be issued against AR % — it is no longer this batch''s current approval (the batch was retested, rejected or is due for retest).',
      coalesce(v_ar, new.quality_check_id::text)
      using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists trg_coa_current_approval on public.coa_records;
create trigger trg_coa_current_approval
  before insert on public.coa_records
  for each row execute function public.trg_fn_coa_current_approval();

commit;

-- ############################################################
-- ## 0083_stock_position_reconciles.sql
-- ############################################################

-- 0083_stock_position_reconciles.sql
-- Accuracy audit ACC-21 (29 Sept 2026): the Stock Position breakdown did not
-- add up to On hand.
--
-- item_position (0031, extended 0032/0050) counted only the original movement
-- kinds. Three kinds of movement changed On hand without touching any breakdown
-- column:
--
--   1. PO reopen (0078) takes the receipt back out of stock ('pull' with
--      reference 'purchase') — Received still showed the full receipt.
--   2. PO reopen also puts the QC / Stability / R&D samples back ('push' with
--      reference 'qc_sample' / 'stability_sample' / 'rnd_sample') — the
--      "held" columns still showed the samples as held.
--   3. Cancelling a draft FP batch puts its components back ('push' with
--      reference 'fp_draft_cancelled') — "FP use" still showed them as used.
--
-- Example from the audit: Received 1,000 − FP use 602.1 ≠ On hand 497.9.
--
-- Fix: those columns are now NET of their own reversals, so each one is what
-- is really outstanding:
--
--   received        = receipts − reopen reversals
--   held_qc/…/rnd   = samples taken − samples returned
--   consumed_by_fp  = components used − components returned by cancelled drafts
--
-- The breakdown then adds up to on_hand for every item:
--
--   on_hand = received + yielded + production_rm_yield + packaged_yield
--             − held_qc − held_stability − held_rnd − consumed_by_fp
--             − issued_packaging − consumed_by_packaging
--             − issued_store − issued_rnd − wastage
--
-- (production_rm_yield already existed as a column; the screens did not show
-- it, so raw material made from production issues showed "Received 0". The
-- screens now show it as "Produced".)
--
-- Same columns, names, types and order as 0050, so `create or replace` is
-- enough; on_hand keeps its exact expression (stock_balance agrees with it).
-- The view options and grants set in 0075 are re-applied to be safe.

create or replace view public.item_position as
select
  i.id as item_id,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'purchase' then l.quantity
                    when l.event_type = 'pull' and l.reference_type = 'purchase' then -l.quantity
                    else 0 end), 0) as received,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'fp_yield' then l.quantity else 0 end), 0) as yielded,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type in ('qc', 'qc_sample') then l.quantity
                    when l.event_type = 'push' and l.reference_type = 'qc_sample' then -l.quantity
                    else 0 end), 0) as held_qc,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'stability_sample' then l.quantity
                    when l.event_type = 'push' and l.reference_type = 'stability_sample' then -l.quantity
                    else 0 end), 0) as held_stability,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'rnd_sample' then l.quantity
                    when l.event_type = 'push' and l.reference_type = 'rnd_sample' then -l.quantity
                    else 0 end), 0) as held_rnd,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'finished_product' then l.quantity
                    when l.event_type = 'push' and l.reference_type = 'fp_draft_cancelled' then -l.quantity
                    else 0 end), 0) as consumed_by_fp,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaging' then l.quantity else 0 end), 0) as issued_packaging,
  coalesce(sum(case when l.event_type = 'wastage' then l.quantity else 0 end), 0) as wastage,
  coalesce(sum(case l.event_type when 'push' then l.quantity when 'wastage' then -l.quantity else -l.quantity end), 0) as on_hand,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'fp_packaging_pull' then l.quantity else 0 end), 0) as consumed_by_packaging,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'packaged_fp_yield' then l.quantity else 0 end), 0) as packaged_yield,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'store' then l.quantity else 0 end), 0) as issued_store,
  coalesce(sum(case when l.event_type = 'pull' and l.reference_type = 'packaged_fp_issue' and l.department = 'rnd' then l.quantity else 0 end), 0) as issued_rnd,
  coalesce(sum(case when l.event_type = 'push' and l.reference_type = 'production_rm_yield' then l.quantity else 0 end), 0) as production_rm_yield
from public.items i
left join public.inventory_ledger l on l.item_id = i.id
group by i.id;

alter view public.item_position set (security_invoker = on);
revoke all on public.item_position from anon;
revoke insert, update, delete, truncate, references, trigger on public.item_position from authenticated;
grant select on public.item_position to authenticated;

-- ############################################################
-- ## 0084_dashboard_qc_counts.sql
-- ############################################################

-- ACC-26 (29 Sept 2026): the Dashboard's "Pending QC" card and "QC by status"
-- chart need to honour the app-wide "Hide legacy data" switch, like every
-- list does. A QC record is legacy if the item, or the purchase / finished
-- product / production batch it was raised against, carries a LEG- code
-- (the same rule as app/(dashboard)/qc/qc-table.tsx). That spans four tables,
-- so the counts are done here in one query instead of paging thousands of QC
-- rows to the browser.
--
-- One row per QC status: how many records there are in total, and how many of
-- those are not legacy. Read-only, runs as the caller (row-level security
-- applies), so it can show nothing a signed-in user could not already list.

create or replace function public.dashboard_qc_counts()
returns table (status text, total bigint, non_legacy bigint)
language sql
stable
security invoker
set search_path = public
as $$
  select
    q.status,
    count(*)::bigint as total,
    (count(*) filter (
      where not (
        coalesce(i.item_code, '') like 'LEG-%'
        or coalesce(pl.batch_number, '') like 'LEG-%'
        or coalesce(fp.batch_number, '') like 'LEG-%'
        or coalesce(pb.batch_number, '') like 'LEG-%'
      )
    ))::bigint as non_legacy
  from public.quality_checks q
  left join public.items i on i.id = q.item_id
  left join public.purchase_lines pl on pl.id = q.purchase_line_id
  left join public.finished_product_batches fp on fp.id = q.finished_product_batch_id
  left join public.production_issue_batches pb on pb.id = q.production_batch_id
  group by q.status
$$;

revoke all on function public.dashboard_qc_counts() from public, anon;
grant execute on function public.dashboard_qc_counts() to authenticated;

-- ############################################################
-- ## 0085_part_a_form_fixes.sql
-- ############################################################

-- ============================================================
-- Part A form fixes (29 Sept 2026): A5 and A6 of the master list.
--
-- A5 (FB-0025, rest): a batch could be completed with a finish date earlier
-- than its start date. The app now checks this; this CHECK is the backstop
-- for a direct API call. NOT VALID, the project's usual idiom (0016, 0036,
-- 0044): it applies to new writes only and never scans or rejects a row
-- that already exists. The comparison ignores rows where either date is
-- missing.
--
-- A6: "Submit to QC" for a finished product batch was two separate writes
-- (insert the QC record, then set the batch status). If the second failed,
-- the batch stayed "Complete - Awaiting QC" with a QC record already made
-- and a retry said "already submitted". submit_fp_batch_to_qc() does the AR
-- number, the QC insert and the status change in one transaction.
-- SECURITY INVOKER: it runs as the signed-in user, so row-level security
-- and the workflow guards (0070) apply exactly as they did for the two
-- separate calls. Any error rolls back all three steps.
-- ============================================================

alter table public.finished_product_batches
  drop constraint if exists fp_finish_not_before_start;
alter table public.finished_product_batches
  add constraint fp_finish_not_before_start
  check (finish_date is null or batch_start_date is null or finish_date >= batch_start_date) not valid;

create or replace function public.submit_fp_batch_to_qc(p_batch_id uuid)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  b record;
  v_ar text;
  v_qc uuid;
begin
  select status, batch_yield, finish_date, qc_sample_qty, unit, expiry_month
    into b
    from public.finished_product_batches
   where id = p_batch_id
   for update;
  if not found then
    raise exception 'Batch not found.' using errcode = 'P0002';
  end if;
  if b.status <> 'complete_awaiting_qc' then
    raise exception 'Only a batch that has been completed (Complete - Awaiting QC) can be submitted to QC.'
      using errcode = 'P0001';
  end if;
  if b.batch_yield is null or b.batch_yield <= 0 or b.finish_date is null then
    raise exception 'Complete the batch (batch yield, finish date, expiry date, sample quantities) before submitting to QC.'
      using errcode = 'P0001';
  end if;

  v_ar := public.get_next_ar_number();

  insert into public.quality_checks
    (ar_number, finished_product_batch_id, sample_qty, sample_unit, expiry_date, created_by)
  values
    (v_ar, p_batch_id, b.qc_sample_qty, b.unit, b.expiry_month, auth.uid())
  returning id into v_qc;

  update public.finished_product_batches
     set status = 'submitted_to_qc'
   where id = p_batch_id;

  return v_qc;
end;
$$;

revoke all on function public.submit_fp_batch_to_qc(uuid) from public, anon;
grant execute on function public.submit_fp_batch_to_qc(uuid) to authenticated;

-- ############################################################
-- ## 0086_part_a_db_hardening.sql
-- ############################################################

-- ============================================================
-- Part A batch 2 — database hardening (A7–A14 of the open-items master
-- list; audit items DES-04, DES-05, DES-06, DES-07, DES-08, DES-12,
-- DES-13). Nothing here changes existing rows: every new CHECK is NOT
-- VALID (applies to new writes only), the guards only look at future
-- writes, and the drops remove objects nothing references.
--
-- A7  Delete rights only while a record is still editable:
--       * finished_product_components — no screen ever edits or deletes
--         one; the rows are written by the batch-creation RPC and each
--         insert has already pulled stock, so a direct edit/delete would
--         leave the ledger and the batch balance out of step. Direct
--         client UPDATE/DELETE is now refused (Draft-cancel, the stale-
--         draft expiry and an admin deleting the whole batch are
--         unaffected: they run as postgres or through the FK cascade).
--       * documents, coa_templates — QC roles keep add/edit; delete is
--         System Admin only, like every other master table.
--       * mfr_lines — already locked once the MFR is approved (0070).
--       * mfr_procedure_steps — editable at any time by design (0048).
--       * bmr_* — deprecated, deliberately untouched.
-- A8  CHECK constraints on equipment quantity, dead-stock amounts, MFR
--     batch size (NOT VALID).
-- A9  purge_test_data(): also resets item_code_seq_rmfp, drops the
--     retired fp_batch_seq, and reports the four tables that were being
--     emptied by the cascade but not listed in its result.
-- A10 bulk_create_mfr_definitions(): no longer creates the Finished
--     Product / Packaged FP items at import. They are created when the
--     MFR is approved, exactly as for a single MFR (0041), so an
--     unapproved bulk MFR no longer leaves orphan items or burns codes.
-- A11 Paired items must be the right category (packaged_item_id ->
--     packaged_fp, production_rm_item_id -> raw, holder = processed;
--     mfr_definitions.finished_product_item_id -> processed).
-- A13 page_feedback.submitted_by_name is taken from the submitter's
--     profile by a trigger, so it cannot be faked through the API.
-- A14 Dead code removed: trg_qc_sample_pull + trg_fn_qc_sample_pull (a
--     no-op since 0028), trg_fn_purchase_line_push (trigger dropped in
--     0019) and fp_batch_seq (unused since 0045). Unused columns stay.
-- ============================================================

-- ------------------------------------------------------------
-- A7. finished_product_components: no direct edits or deletes
-- ------------------------------------------------------------
create or replace function public.trg_fn_guard_fp_components_locked()
returns trigger language plpgsql set search_path = public as $$
begin
  if not public._is_direct_client_write() then
    return coalesce(new, old);
  end if;

  -- A parent that no longer exists (an admin deleting the whole batch,
  -- which cascades here) is not blocked.
  if not exists (
    select 1 from public.finished_product_batches where id = old.finished_product_batch_id
  ) then
    return coalesce(new, old);
  end if;

  raise exception 'Batch components are recorded when the batch is created and can''t be changed or deleted directly. Cancel the draft batch instead.'
    using errcode = '42501';
end $$;

drop trigger if exists trg_00_guard_fp_components_locked on public.finished_product_components;
create trigger trg_00_guard_fp_components_locked
  before update or delete on public.finished_product_components
  for each row execute function public.trg_fn_guard_fp_components_locked();

-- ------------------------------------------------------------
-- A7. documents / coa_templates: split the catch-all write policy so
--     delete is System Admin only (add and edit unchanged).
-- ------------------------------------------------------------
drop policy if exists documents_write on public.documents;
create policy documents_insert on public.documents for insert
  with check (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'));
create policy documents_update on public.documents for update
  using (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'))
  with check (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'));
create policy documents_delete on public.documents for delete
  using (public.has_any_role('system_admin'));

drop policy if exists coa_templates_write on public.coa_templates;
create policy coa_templates_insert on public.coa_templates for insert
  with check (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'));
create policy coa_templates_update on public.coa_templates for update
  using (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'))
  with check (public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer'));
create policy coa_templates_delete on public.coa_templates for delete
  using (public.has_any_role('system_admin'));

-- ------------------------------------------------------------
-- A8. Sanity CHECKs (new writes only; existing rows are not scanned)
-- ------------------------------------------------------------
alter table public.equipment
  drop constraint if exists equipment_quantity_positive,
  add constraint equipment_quantity_positive check (quantity > 0) not valid;

alter table public.dead_stock_items
  drop constraint if exists dead_stock_quantity_positive,
  drop constraint if exists dead_stock_price_nonneg,
  drop constraint if exists dead_stock_depreciation_range,
  drop constraint if exists dead_stock_rejected_nonneg,
  drop constraint if exists dead_stock_balance_nonneg,
  add constraint dead_stock_quantity_positive check (quantity > 0) not valid,
  add constraint dead_stock_price_nonneg check (purchase_price is null or purchase_price >= 0) not valid,
  add constraint dead_stock_depreciation_range check (depreciation_pct >= 0 and depreciation_pct <= 100) not valid,
  add constraint dead_stock_rejected_nonneg check (rejected_qty >= 0 and rejected_value >= 0) not valid,
  add constraint dead_stock_balance_nonneg check (
    (balance_qty is null or balance_qty >= 0) and (balance_value is null or balance_value >= 0)
  ) not valid;

alter table public.mfr_definitions
  drop constraint if exists mfr_definitions_batch_size_positive,
  add constraint mfr_definitions_batch_size_positive check (batch_size_qty > 0) not valid;

-- ------------------------------------------------------------
-- A9 + A14 (fp_batch_seq). purge_test_data(): complete lists.
--     Recreated without fp_batch_seq (dropped below) and with
--     item_code_seq_rmfp. The four extra tables were already emptied by
--     the TRUNCATE ... CASCADE; listing them just makes the result
--     table report them.
-- ------------------------------------------------------------
create or replace function public.purge_test_data()
returns table(table_name text, rows_purged bigint)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tables text[] := array[
    'bmr_observations', 'bmr_records', 'bmr_weighment_lines', 'coa_records',
    'coa_template_lines', 'coa_templates',
    'dead_stock_items', 'documents', 'environmental_control_readings', 'equipment',
    'finished_product_batches', 'finished_product_components', 'inventory_ledger',
    'item_types', 'items', 'line_clearance_checks', 'mfr_definitions', 'mfr_lines',
    'mfr_procedure_steps', 'packaging_issue_items', 'packaging_issues',
    'production_issue_batches', 'purchase_lines', 'purchase_orders',
    'quality_checks', 'vendors'
  ];
  -- feedback_ticket_seq intentionally excluded — page_feedback is kept.
  v_sequences text[] := array[
    'item_code_seq_raw', 'item_code_seq_pkg', 'item_code_seq_fp', 'item_code_seq_pkgfp',
    'item_code_seq_rmfp',
    'vendor_code_seq', 'po_number_seq', 'ar_number_seq', 'mfr_code_seq',
    'coa_number_seq', 'equipment_code_seq', 'dead_stock_code_seq', 'packaging_issue_code_seq'
  ];
  v_tbl text;
  v_seq text;
  v_count bigint;
  v_truncate_list text;
begin
  if not public.has_any_role('system_admin') then
    raise exception 'Only System Admin can purge test data.';
  end if;

  foreach v_tbl in array v_tables loop
    execute format('select count(*) from public.%I', v_tbl) into v_count;
    table_name := v_tbl;
    rows_purged := v_count;
    return next;
  end loop;

  select string_agg(format('public.%I', t), ', ') into v_truncate_list from unnest(v_tables) as t;
  execute format('truncate table %s restart identity cascade', v_truncate_list);

  foreach v_seq in array v_sequences loop
    execute format('alter sequence public.%I restart with 1', v_seq);
  end loop;
end $$;

-- ------------------------------------------------------------
-- A10. bulk_create_mfr_definitions(): defer item creation to approval
--      (same as create_mfr_definition, 0041). The return shape shrinks
--      to (mfr_name, mfr_code), so the old function is dropped first.
-- ------------------------------------------------------------
drop function if exists public.bulk_create_mfr_definitions(jsonb);

create function public.bulk_create_mfr_definitions(p_payload jsonb)
returns table(mfr_name text, mfr_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_def jsonb;
  v_line jsonb;
  v_step jsonb;
  v_name text;
  v_batch_qty numeric;
  v_batch_unit text;
  v_item_type_id uuid;
  v_lines jsonb;
  v_steps jsonb;
  v_procedure_intro text;
  v_theoretical_yield_pct numeric;
  v_permissible_yield_pct numeric;
  v_mfr_code text;
  v_def_id uuid;
  v_idx int := 0;
  v_step_idx int;
begin
  if not public.has_any_role('system_admin', 'mfr_manager') then
    raise exception 'Not authorized to bulk-create MFR definitions.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No MFR definitions to create.';
  end if;

  for v_def in select * from jsonb_array_elements(p_payload)
  loop
    v_idx := v_idx + 1;
    v_name := trim(both from coalesce(v_def->>'name', ''));
    v_batch_qty := nullif(v_def->>'batch_size_qty', '')::numeric;
    v_batch_unit := v_def->>'batch_size_unit';
    v_item_type_id := nullif(v_def->>'item_type_id', '')::uuid;
    v_lines := v_def->'lines';
    v_steps := v_def->'procedure_steps';
    v_procedure_intro := nullif(trim(both from coalesce(v_def->>'procedure_intro', '')), '');
    v_theoretical_yield_pct := nullif(v_def->>'theoretical_yield_pct', '')::numeric;
    v_permissible_yield_pct := nullif(v_def->>'permissible_yield_pct', '')::numeric;

    if v_name = '' then
      raise exception 'MFR #%: name is required.', v_idx;
    end if;
    if v_batch_qty is null or v_batch_qty <= 0 then
      raise exception 'MFR "%": batch size must be greater than 0.', v_name;
    end if;
    if v_batch_unit is null or v_batch_unit = '' then
      raise exception 'MFR "%": batch size unit is required.', v_name;
    end if;
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'MFR "%": needs at least one recipe line.', v_name;
    end if;
    if v_theoretical_yield_pct is not null and v_theoretical_yield_pct <= 0 then
      raise exception 'MFR "%": theoretical yield must be greater than 0.', v_name;
    end if;
    if v_permissible_yield_pct is not null and v_permissible_yield_pct <= 0 then
      raise exception 'MFR "%": permissible yield must be greater than 0.', v_name;
    end if;

    -- No Finished Product / Packaged FP items here — approve_mfr_definition()
    -- creates them (finished_product_item_id stays null until then).
    v_mfr_code := public.get_next_mfr_code();
    insert into public.mfr_definitions (
      code, name, batch_size_qty, batch_size_unit, item_type_id,
      procedure_intro, theoretical_yield_pct, permissible_yield_pct
    )
      values (
        v_mfr_code, v_name, v_batch_qty, v_batch_unit, v_item_type_id,
        v_procedure_intro, v_theoretical_yield_pct, v_permissible_yield_pct
      )
      returning id into v_def_id;

    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      if (v_line->>'item_id') is null or (v_line->>'quantity') is null
         or v_line->>'unit' is null or v_line->>'unit' = '' then
        raise exception 'MFR "%": every recipe line needs an item, quantity, and unit.', v_name;
      end if;
      if (v_line->>'quantity')::numeric <= 0 then
        raise exception 'MFR "%": recipe line quantity must be greater than 0.', v_name;
      end if;
      insert into public.mfr_lines (mfr_definition_id, version, item_id, quantity, unit)
        values (v_def_id, 1, (v_line->>'item_id')::uuid, (v_line->>'quantity')::numeric, v_line->>'unit');
    end loop;

    if v_steps is not null and jsonb_typeof(v_steps) = 'array' and jsonb_array_length(v_steps) > 0 then
      v_step_idx := 0;
      for v_step in select * from jsonb_array_elements(v_steps)
      loop
        v_step_idx := v_step_idx + 1;
        if (v_step->>'stage') is null or v_step->>'stage' = ''
           or (v_step->>'operation') is null or v_step->>'operation' = '' then
          raise exception 'MFR "%": procedure step % needs both a stage and an operation.', v_name, v_step_idx;
        end if;
        insert into public.mfr_procedure_steps (mfr_definition_id, version, step_no, stage, operation)
          values (v_def_id, 1, v_step_idx, v_step->>'stage', v_step->>'operation');
      end loop;
    end if;

    mfr_name := v_name;
    mfr_code := v_mfr_code;
    return next;
  end loop;
end $$;

revoke all on function public.bulk_create_mfr_definitions(jsonb) from public, anon;
grant execute on function public.bulk_create_mfr_definitions(jsonb) to authenticated;

-- ------------------------------------------------------------
-- A11. Pairing pointers must point at the right category
--      Checked only when the pointer is set or changed, so unrelated
--      updates to a legacy row are never blocked.
-- ------------------------------------------------------------
create or replace function public.trg_fn_check_item_pairing()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_cat text;
begin
  if new.packaged_item_id is not null
     and (tg_op = 'INSERT' or new.packaged_item_id is distinct from old.packaged_item_id) then
    select category into v_cat from public.items where id = new.packaged_item_id;
    if new.category <> 'processed' or v_cat is distinct from 'packaged_fp' then
      raise exception 'A Finished Product item can only be paired with a Packaged Finished Product item.'
        using errcode = '23514';
    end if;
  end if;

  if new.production_rm_item_id is not null
     and (tg_op = 'INSERT' or new.production_rm_item_id is distinct from old.production_rm_item_id) then
    select category into v_cat from public.items where id = new.production_rm_item_id;
    if new.category <> 'processed' or v_cat is distinct from 'raw' then
      raise exception 'A Finished Product item can only be paired with a Raw Material item as its production stock.'
        using errcode = '23514';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_items_check_pairing on public.items;
create trigger trg_items_check_pairing
  before insert or update of packaged_item_id, production_rm_item_id on public.items
  for each row execute function public.trg_fn_check_item_pairing();

create or replace function public.trg_fn_check_mfr_fp_item()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_cat text;
begin
  if new.finished_product_item_id is not null
     and (tg_op = 'INSERT' or new.finished_product_item_id is distinct from old.finished_product_item_id) then
    select category into v_cat from public.items where id = new.finished_product_item_id;
    if v_cat is distinct from 'processed' then
      raise exception 'An MFR can only be linked to a Finished Product item.'
        using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_mfr_def_check_fp_item on public.mfr_definitions;
create trigger trg_mfr_def_check_fp_item
  before insert or update of finished_product_item_id on public.mfr_definitions
  for each row execute function public.trg_fn_check_mfr_fp_item();

-- ------------------------------------------------------------
-- A13. Feedback: the submitter's name comes from their profile
--      (or their email when the profile has no name — the same
--      fallback the app uses), never from the request.
-- ------------------------------------------------------------
create or replace function public.trg_fn_feedback_set_submitter_name()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_name text;
begin
  if new.submitted_by is null then
    return new;
  end if;
  select coalesce(p.full_name, u.email)
    into v_name
    from auth.users u
    left join public.profiles p on p.id = u.id
    where u.id = new.submitted_by;
  if v_name is not null then
    new.submitted_by_name := v_name;
  end if;
  return new;
end $$;

drop trigger if exists trg_00_feedback_submitter_name on public.page_feedback;
create trigger trg_00_feedback_submitter_name
  before insert on public.page_feedback
  for each row execute function public.trg_fn_feedback_set_submitter_name();

-- ------------------------------------------------------------
-- A14. Dead code
-- ------------------------------------------------------------
drop trigger if exists trg_qc_sample_pull on public.quality_checks;
drop function if exists public.trg_fn_qc_sample_pull();
drop function if exists public.trg_fn_purchase_line_push();
drop sequence if exists public.fp_batch_seq;

-- ------------------------------------------------------------
-- Self-check: abort everything if a piece is missing.
-- ------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_trigger where tgname = 'trg_00_guard_fp_components_locked')
     or not exists (select 1 from pg_trigger where tgname = 'trg_items_check_pairing')
     or not exists (select 1 from pg_trigger where tgname = 'trg_mfr_def_check_fp_item')
     or not exists (select 1 from pg_trigger where tgname = 'trg_00_feedback_submitter_name') then
    raise exception '0086 self-check failed: a trigger is missing.';
  end if;
  if exists (select 1 from pg_trigger where tgname = 'trg_qc_sample_pull')
     or exists (select 1 from pg_class where relname = 'fp_batch_seq') then
    raise exception '0086 self-check failed: dead objects still present.';
  end if;
  if (select count(*) from pg_policies
      where schemaname = 'public'
        and policyname in ('documents_insert','documents_update','documents_delete',
                           'coa_templates_insert','coa_templates_update','coa_templates_delete')) <> 6 then
    raise exception '0086 self-check failed: split policies missing.';
  end if;
end $$;

-- ############################################################
-- ## 0087_performance_indexes_bulk_codes.sql
-- ############################################################

-- ============================================================
-- Part A batch 3 — indexes and bulk code generation (A16 / A17 / A18,
-- audit items PERF-02 / PERF-03 / PERF-04).
-- Postgres does not index foreign-key columns by itself, so deleting or
-- joining on these columns scans the whole table. Checked against a
-- 400,000-row ledger: the lookup the QC-review trigger does on
-- (reference_type, reference_id) goes from a full scan (~30 ms) to an
-- index hit (~0.03 ms); the other indexes matter for joins, cascades and
-- "where is this used" checks as the tables grow.
--
-- Nothing changes in behaviour or data. Two older single-column indexes
-- are dropped because the new composite ones start with the same column
-- and serve the same lookups:
--   inventory_ledger_item_id_idx           -> inventory_ledger_item_event_idx
--   quality_checks_purchase_line_id_idx    -> quality_checks_pl_created_idx
-- Not added on purpose: purchase_orders(status) (only two values, an
-- index would not be used), the deprecated bmr_* tables, and the legacy
-- unused packaging_issues.packaging_item_id column.
-- Plain CREATE INDEX (not CONCURRENTLY) so it runs in the SQL Editor; the
-- tables hold test data only, so the brief lock is not a concern.
-- ============================================================

-- Ledger
create index if not exists inventory_ledger_item_event_idx
  on public.inventory_ledger (item_id, event_at, seq);
create index if not exists inventory_ledger_reference_idx
  on public.inventory_ledger (reference_type, reference_id);
create index if not exists inventory_ledger_production_batch_idx
  on public.inventory_ledger (production_batch_id) where production_batch_id is not null;
drop index if exists public.inventory_ledger_item_id_idx;

-- Quality control
create index if not exists quality_checks_pl_created_idx
  on public.quality_checks (purchase_line_id, created_at desc);
drop index if exists public.quality_checks_purchase_line_id_idx;

-- COA
create index if not exists coa_records_quality_check_id_idx
  on public.coa_records (quality_check_id);
create index if not exists coa_records_fp_batch_id_idx
  on public.coa_records (finished_product_batch_id);
create index if not exists coa_records_template_id_idx
  on public.coa_records (coa_template_id);

-- Purchase, items, MFR
create index if not exists purchase_orders_vendor_id_idx
  on public.purchase_orders (vendor_id);
create index if not exists items_item_type_id_idx
  on public.items (item_type_id);
create index if not exists mfr_definitions_item_type_id_idx
  on public.mfr_definitions (item_type_id);
create index if not exists mfr_lines_item_id_idx
  on public.mfr_lines (item_id);

-- Packaging
create index if not exists packaging_issues_fp_batch_id_idx
  on public.packaging_issues (finished_product_batch_id);
create index if not exists packaging_issue_items_issue_id_idx
  on public.packaging_issue_items (packaging_issue_id);
create index if not exists packaging_issue_items_item_id_idx
  on public.packaging_issue_items (item_id);
create index if not exists production_issue_batches_issue_id_idx
  on public.production_issue_batches (packaging_issue_id);

-- ------------------------------------------------------------
-- A18. Bulk code generation in one call (PERF-04)
-- Bulk uploads used to ask the database for one code per row (up to 500
-- round trips) before the single insert. These return N codes from the
-- same sequences in one call, in order, so a 500-row import makes one
-- request instead of 500. The single-code functions are unchanged.
-- ------------------------------------------------------------
create or replace function public.get_next_item_codes(p_category text, p_count int)
returns setof text language plpgsql as $$
declare i int;
begin
  if p_count is null or p_count < 1 or p_count > 5000 then
    raise exception 'Code count must be between 1 and 5000.' using errcode = '22023';
  end if;
  for i in 1 .. p_count loop
    return next public.get_next_item_code(p_category);
  end loop;
end $$;

create or replace function public.get_next_vendor_codes(p_count int)
returns setof text language plpgsql as $$
declare i int;
begin
  if p_count is null or p_count < 1 or p_count > 5000 then
    raise exception 'Code count must be between 1 and 5000.' using errcode = '22023';
  end if;
  for i in 1 .. p_count loop
    return next public.get_next_vendor_code();
  end loop;
end $$;

create or replace function public.get_next_equipment_codes(p_count int)
returns setof text language plpgsql as $$
declare i int;
begin
  if p_count is null or p_count < 1 or p_count > 5000 then
    raise exception 'Code count must be between 1 and 5000.' using errcode = '22023';
  end if;
  for i in 1 .. p_count loop
    return next public.get_next_equipment_code();
  end loop;
end $$;

create or replace function public.get_next_dead_stock_codes(p_count int)
returns setof text language plpgsql as $$
declare i int;
begin
  if p_count is null or p_count < 1 or p_count > 5000 then
    raise exception 'Code count must be between 1 and 5000.' using errcode = '22023';
  end if;
  for i in 1 .. p_count loop
    return next public.get_next_dead_stock_code();
  end loop;
end $$;

revoke all on function public.get_next_item_codes(text, int), public.get_next_vendor_codes(int),
  public.get_next_equipment_codes(int), public.get_next_dead_stock_codes(int) from public, anon;
grant execute on function public.get_next_item_codes(text, int), public.get_next_vendor_codes(int),
  public.get_next_equipment_codes(int), public.get_next_dead_stock_codes(int) to authenticated;

-- Self-check
do $$
begin
  if (select count(*) from pg_indexes where schemaname = 'public' and indexname in (
        'inventory_ledger_item_event_idx','inventory_ledger_reference_idx','inventory_ledger_production_batch_idx',
        'quality_checks_pl_created_idx','coa_records_quality_check_id_idx','coa_records_fp_batch_id_idx',
        'coa_records_template_id_idx','purchase_orders_vendor_id_idx','items_item_type_id_idx',
        'mfr_definitions_item_type_id_idx','mfr_lines_item_id_idx','packaging_issues_fp_batch_id_idx',
        'packaging_issue_items_issue_id_idx','packaging_issue_items_item_id_idx',
        'production_issue_batches_issue_id_idx')) <> 15
     or (select count(*) from pg_proc where proname in ('get_next_item_codes','get_next_vendor_codes',
        'get_next_equipment_codes','get_next_dead_stock_codes')) <> 4 then
    raise exception '0087 self-check failed: an index is missing.';
  end if;
end $$;

-- ############################################################
-- ## 0088_coa_template_upload_rpc.sql
-- ############################################################

-- ============================================================
-- 0088 — COA Templates bulk upload: re-create the upload function
--
-- Live symptom (30 Sept 2026): uploading the COA Templates sheet failed with
-- "Something went wrong (reference PGRST202)". PGRST202 = the database API
-- could not find the function `bulk_create_coa_templates(p_payload jsonb)`.
-- The function is defined in 0062 but was missing from (or not visible to)
-- the live API.
--
-- This migration is safe to run whether or not the function already exists:
--   1. re-creates the function exactly as in 0062 (create or replace),
--   2. grants it explicitly (0062 relied on default privileges),
--   3. asks the database API to reload its function list, so the fix works
--      without waiting or restarting anything.
-- No data is read or changed.
-- ============================================================

create or replace function public.bulk_create_coa_templates(p_payload jsonb)
returns setof uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_group jsonb;
  v_lines jsonb;
  v_line jsonb;
  v_item_type_id uuid;
  v_template_id uuid;
  v_idx int;
begin
  if not public.has_any_role('system_admin', 'quality_checker', 'qc_reviewer') then
    raise exception 'Not authorized to manage Certificate of Analysis templates.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No COA template rows to import.';
  end if;

  for v_group in select * from jsonb_array_elements(p_payload)
  loop
    v_item_type_id := (v_group->>'item_type_id')::uuid;
    if v_item_type_id is null then
      raise exception 'Item Type is required for every row.';
    end if;
    if exists (select 1 from public.coa_templates where item_type_id = v_item_type_id) then
      raise exception 'An item type in this file already has a COA template — edit it from Manage Templates instead of uploading it again.';
    end if;

    v_lines := v_group->'lines';
    if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
      raise exception 'At least one test is required per item type.';
    end if;

    insert into public.coa_templates (item_type_id, created_by)
    values (v_item_type_id, auth.uid())
    returning id into v_template_id;

    v_idx := 0;
    for v_line in select * from jsonb_array_elements(v_lines)
    loop
      v_idx := v_idx + 1;
      if (v_line->>'test') is null or v_line->>'test' = ''
         or (v_line->>'specification') is null or v_line->>'specification' = '' then
        raise exception 'Both Test and Specification are required for every row.';
      end if;
      insert into public.coa_template_lines (coa_template_id, seq, test, specification)
      values (v_template_id, v_idx, v_line->>'test', v_line->>'specification');
    end loop;

    return next v_template_id;
  end loop;

  return;
end $$;

revoke all on function public.bulk_create_coa_templates(jsonb) from public, anon;
grant execute on function public.bulk_create_coa_templates(jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ############################################################
-- ## 0089_no_self_demotion.sql
-- ############################################################

-- ============================================================
-- A System Admin cannot remove their OWN System Admin role (Ravi, 30 Sept 2026:
-- "own System Admin option should be disabled for System Admins so they can
-- not degrade their own access. Only another system admin can degrade other
-- system admins access/role").
--
-- One row-level guard on user_roles, so it holds on every path: the User Roles
-- & Access screen (set_user_roles, 0073), a direct API call, or disabling an
-- account. It refuses a delete of the signed-in user's own system_admin row,
-- or an update that changes that row's role or owner.
--
-- Not affected: another System Admin changing this user's roles (the existing
-- "at least one System Admin must remain" guard from 0073 still applies);
-- changes to a user's other roles; the SQL editor / service role (no signed-in
-- user, auth.uid() is null); adding roles.
-- ============================================================

begin;

create or replace function public.trg_fn_no_self_admin_removal()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.role = 'system_admin'
     and old.user_id is not null
     and old.user_id = auth.uid()
     and (tg_op = 'DELETE' or new.role is distinct from old.role or new.user_id is distinct from old.user_id)
  then
    raise exception 'You cannot remove your own System Admin role. Ask another System Admin to do it.'
      using errcode = 'P0001';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

drop trigger if exists trg_user_roles_no_self_admin_removal on public.user_roles;
create trigger trg_user_roles_no_self_admin_removal
  before delete or update on public.user_roles
  for each row execute function public.trg_fn_no_self_admin_removal();

commit;

-- ############################################################
-- ## 0090_fifo_hard_rule.sql
-- ############################################################

-- ============================================================
-- B16: oldest stock first (FIFO) is a HARD rule for finished-product batches
-- (Ravi, 30 Sept 2026: "Hard rule").
--
-- Before: the Compose screen picked batches oldest-first, but the database
-- accepted any batch, so a tampered request could consume a newer batch while
-- an older one was still in stock. (Packaging materials were already drawn
-- oldest-first in the database, since 0079.)
--
-- Now: a raw material can only be consumed from a batch if no OLDER batch of
-- the same item is still usable. "Usable" mirrors what the Compose screen
-- offers:
--   * purchase batch: active, purchase order submitted, QC-approved, retest
--     date not reached, quantity left;
--   * production-issued raw material batch: active, QC-approved, retest date
--     not reached, quantity left.
-- "Older" = received earlier (created_at), across both kinds of batch. Batches
-- received at exactly the same moment (bulk loads) are interchangeable.
-- A quarantined, rejected, retest-due, reopened or used-up older batch does not
-- block anything. There is no exception path.
--
-- Also: create_finished_product_batch now saves the components oldest batch
-- first, so a recipe that draws from several batches always satisfies the rule
-- in the order it is written. Consumption of one item is serialised with a
-- lock, so two people composing at once cannot both skip the older batch.
--
-- Not covered on purpose: wastage (a specific damaged batch is chosen) and QC
-- sample pulls (they come from the batch under test).
-- ============================================================

begin;

create or replace function public.trg_fn_fp_component_fifo()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_created timestamptz;
  v_batch   text;
  v_item    uuid;
  o         record;
  v_name    text;
begin
  if new.purchase_line_id is not null then
    select created_at, batch_number, item_id into v_created, v_batch, v_item
      from public.purchase_lines where id = new.purchase_line_id;
  elsif new.production_batch_id is not null then
    select created_at, batch_number, item_id into v_created, v_batch, v_item
      from public.production_issue_batches where id = new.production_batch_id;
  else
    return new;
  end if;
  if v_item is null or v_created is null then
    return new;
  end if;

  -- One item at a time: a second person composing the same item waits here,
  -- then sees the first person's draw.
  perform pg_advisory_xact_lock(hashtext('fifo-item'), hashtext(v_item::text));

  select x.batch_number, x.remaining, x.unit, x.created_at into o
  from (
    select pl.batch_number, pl.live_remaining_qty as remaining, pl.unit, pl.created_at
      from public.purchase_lines pl
      join public.purchase_batch_status s on s.purchase_line_id = pl.id
     where pl.item_id = v_item
       and pl.active
       and pl.pushed_at is not null
       and pl.live_remaining_qty > 0
       and pl.created_at < v_created
       and pl.id is distinct from new.purchase_line_id
       and s.qc_status = 'approved'
       and (s.retest_date is null or s.retest_date > current_date)
    union all
    select pb.batch_number, pb.live_remaining_qty, pb.unit, pb.created_at
      from public.production_issue_batches pb
      join public.production_batch_status s on s.production_batch_id = pb.id
     where pb.item_id = v_item
       and pb.active
       and pb.live_remaining_qty > 0
       and pb.created_at < v_created
       and pb.id is distinct from new.production_batch_id
       and s.qc_status = 'approved'
       and (s.retest_date is null or s.retest_date > current_date)
  ) x
  order by x.created_at, x.batch_number
  limit 1;

  if found then
    select coalesce(item_code || ' ' || name, name) into v_name from public.items where id = v_item;
    raise exception 'Oldest stock must be used first. Batch % of % (% % still available) is older than batch % and has to be used before it.',
      o.batch_number, v_name, o.remaining, o.unit, coalesce(v_batch, '?')
      using errcode = 'P0001';
  end if;

  return new;
end $$;

-- Named so it runs after the QC gate (trg_fp_component_qc_gate): an unapproved
-- batch is reported as "not QC-Approved" before anything about order.
drop trigger if exists trg_fp_component_z_fifo on public.finished_product_components;
create trigger trg_fp_component_z_fifo
  before insert on public.finished_product_components
  for each row execute function public.trg_fn_fp_component_fifo();

-- Components are saved oldest batch first (ties keep the order sent).
create or replace function public.create_finished_product_batch(p_batch jsonb, p_components jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  c jsonb;
begin
  if jsonb_array_length(coalesce(p_components, '[]'::jsonb)) = 0 then
    raise exception 'A batch needs at least one component.' using errcode = 'P0001';
  end if;

  insert into public.finished_product_batches
    (batch_number, short_batch_no, mfr_definition_id, mfr_version, target_qty, unit, batch_start_date, status)
  values
    (p_batch->>'batch_number',
     p_batch->>'short_batch_no',
     (p_batch->>'mfr_definition_id')::uuid,
     (p_batch->>'mfr_version')::integer,
     (p_batch->>'target_qty')::numeric,
     p_batch->>'unit',
     nullif(p_batch->>'batch_start_date', '')::date,
     'draft')
  returning id into v_id;

  for c in
    select e.value
      from jsonb_array_elements(p_components) with ordinality as e(value, n)
      left join public.purchase_lines pl on pl.id = nullif(e.value->>'purchase_line_id', '')::uuid
      left join public.production_issue_batches pb on pb.id = nullif(e.value->>'production_batch_id', '')::uuid
     order by coalesce(pl.created_at, pb.created_at) nulls last, e.n
  loop
    insert into public.finished_product_components
      (finished_product_batch_id, item_id, purchase_line_id, production_batch_id, quantity)
    values
      (v_id,
       (c->>'item_id')::uuid,
       nullif(c->>'purchase_line_id', '')::uuid,
       nullif(c->>'production_batch_id', '')::uuid,
       (c->>'quantity')::numeric);
  end loop;

  return v_id;
end $$;

revoke all on function public.create_finished_product_batch(jsonb, jsonb) from public, anon;
grant execute on function public.create_finished_product_batch(jsonb, jsonb) to authenticated;

commit;

-- ############################################################
-- ## 0091_rm_code_three_digits.sql
-- ############################################################

-- ============================================================
-- FB-0045 (1 Oct 2026, Namrata Gaikwad): "RM code 001 (3 digit) not 00001".
-- Ravi: "make RM code 001 (3 Digit) not 00001. Make sure overflow issue is
-- taken care when RM code reaches RM999".
--
-- New Raw Material item codes are RM-001, RM-002 ... RM-999, and then RM-1000,
-- RM-1001 ...: the number is padded to AT LEAST three digits, never cut, so
-- reaching 999 cannot truncate, repeat an earlier code or raise an error.
-- (Same shared helper as 0069: _pad_seq_code(number, width).)
--
-- Only Raw Material changes. Packaging (PKG-00001), Finished Product (FP-00001),
-- packaged Finished Product (PKG-FP-00001) and Production raw material
-- (RM-FP-00001) keep five digits.
--
-- Existing items keep the code they have (RM-00001 stays RM-00001). The
-- sequence is not reset, so the next new Raw Material code continues the
-- number (for example after RM-00045 the next one is RM-046); a new code can
-- never equal an old one.
-- The "next code" preview on New item (peek_next_item_code) is changed in the
-- same way so it always shows what will be assigned.
--
-- No table, no data and no app code is touched; signatures and return types
-- are unchanged (CREATE OR REPLACE only). Has a built-in self-check.
-- ============================================================

begin;

create or replace function public.get_next_item_code(p_category text)
returns text language plpgsql as $$
declare v_num int; v_prefix text; v_width int := 5;
begin
  if p_category = 'packaging' then
    v_num := nextval('public.item_code_seq_pkg'); v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_num := nextval('public.item_code_seq_fp'); v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_num := nextval('public.item_code_seq_pkgfp'); v_prefix := 'PKG-FP';
  else
    v_num := nextval('public.item_code_seq_raw'); v_prefix := 'RM'; v_width := 3;
  end if;
  return v_prefix || '-' || public._pad_seq_code(v_num::text, v_width);
end $$;

create or replace function public.peek_next_item_code(p_category text)
returns text language plpgsql stable as $$
declare
  v_num bigint;
  v_prefix text;
  v_seq regclass;
  v_width int := 5;
begin
  if p_category = 'packaging' then
    v_seq := 'public.item_code_seq_pkg'; v_prefix := 'PKG';
  elsif p_category = 'processed' then
    v_seq := 'public.item_code_seq_fp'; v_prefix := 'FP';
  elsif p_category = 'packaged_fp' then
    v_seq := 'public.item_code_seq_pkgfp'; v_prefix := 'PKG-FP';
  else
    v_seq := 'public.item_code_seq_raw'; v_prefix := 'RM'; v_width := 3;
  end if;

  execute format(
    'select case when is_called then last_value + 1 else last_value end from %s',
    v_seq
  ) into v_num;

  return v_prefix || '-' || public._pad_seq_code(v_num::text, v_width);
end $$;

-- Self-check: the padding the Raw Material generator now uses, at and around
-- the 999 boundary, and that the other categories are unchanged.
do $$
begin
  if public._pad_seq_code('1', 3) <> '001' or public._pad_seq_code('45', 3) <> '045'
     or public._pad_seq_code('999', 3) <> '999' or public._pad_seq_code('1000', 3) <> '1000'
     or public._pad_seq_code('12345', 3) <> '12345' then
    raise exception '0091 self-check failed: 3-digit padding is wrong.';
  end if;
  if public._pad_seq_code('1', 5) <> '00001' or public._pad_seq_code('100000', 5) <> '100000' then
    raise exception '0091 self-check failed: 5-digit padding changed.';
  end if;
  if position('v_width := 3' in pg_get_functiondef('public.get_next_item_code(text)'::regprocedure)) = 0
     or position('v_width := 3' in pg_get_functiondef('public.peek_next_item_code(text)'::regprocedure)) = 0 then
    raise exception '0091 self-check failed: a generator is missing the 3-digit Raw Material width.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0092_packaging_issue_date.sql
-- ############################################################

-- ============================================================
-- FB-0051 (1 Oct 2026, Namrata Gaikwad): "Issue start date missing" on Packaging.
-- Ravi: call it "Issue Date"; past dates allowed; future dates not; not added to
-- any printed document yet (decided later).
--
-- packaging_issues gets issue_date (a date, India time). Existing issues take the
-- day they were saved. New issues default to today and may be set to any earlier
-- day; create_packaging_issue() refuses a day after today (India time). The
-- date is purely informational: stock, FIFO and every other rule are unchanged.
-- ============================================================

begin;

alter table public.packaging_issues add column if not exists issue_date date;

update public.packaging_issues
   set issue_date = (created_at at time zone 'Asia/Kolkata')::date
 where issue_date is null;

alter table public.packaging_issues
  alter column issue_date set default ((now() at time zone 'Asia/Kolkata')::date),
  alter column issue_date set not null;

create or replace function public.create_packaging_issue(p_issue jsonb, p_materials jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  m jsonb;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_issue_date date := coalesce(nullif(p_issue->>'issue_date', '')::date, v_today);
begin
  if v_issue_date > v_today then
    raise exception 'Issue date cannot be in the future.' using errcode = '22023';
  end if;

  insert into public.packaging_issues
    (code, finished_product_batch_id, pack_size, pack_size_qty, pack_size_unit, fp_qty_consumed,
     unit_count, department, transaction_type, qc_qty, stability_qty, rnd_qty, issue_date)
  values
    (p_issue->>'code',
     (p_issue->>'finished_product_batch_id')::uuid,
     p_issue->>'pack_size',
     nullif(p_issue->>'pack_size_qty', '')::numeric,
     nullif(p_issue->>'pack_size_unit', ''),
     nullif(p_issue->>'fp_qty_consumed', '')::numeric,
     (p_issue->>'unit_count')::numeric,
     p_issue->>'department',
     'pack',
     nullif(p_issue->>'qc_qty', '')::numeric,
     nullif(p_issue->>'stability_qty', '')::numeric,
     nullif(p_issue->>'rnd_qty', '')::numeric,
     v_issue_date)
  returning id into v_id;

  for m in select * from jsonb_array_elements(coalesce(p_materials, '[]'::jsonb))
  loop
    insert into public.packaging_issue_items (packaging_issue_id, item_id, quantity, unit)
    values (v_id, (m->>'item_id')::uuid, (m->>'quantity')::numeric, m->>'unit');
  end loop;

  return v_id;
end $$;

revoke all on function public.create_packaging_issue(jsonb, jsonb) from public, anon;
grant execute on function public.create_packaging_issue(jsonb, jsonb) to authenticated;

do $$
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'packaging_issues'
                   and column_name = 'issue_date' and is_nullable = 'NO') then
    raise exception '0092 self-check failed: packaging_issues.issue_date missing or nullable.';
  end if;
  if position('Issue date cannot be in the future' in pg_get_functiondef('public.create_packaging_issue(jsonb,jsonb)'::regprocedure)) = 0 then
    raise exception '0092 self-check failed: create_packaging_issue lacks the future-date check.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0093_packaging_multi_line.sql
-- ############################################################

-- ============================================================
-- FB-0052 (1 Oct 2026, Namrata Gaikwad): one Packaging issue should be able to carry
-- several lines — e.g. 200 ml x 50 and 1 ltr x 8 packed from the same Finished Product
-- batch on the same day — instead of one save per pack size.
--
-- create_packaging_issues(p_header, p_lines) saves up to 30 lines for Store or R&D in ONE
-- database transaction (all or nothing). Each line becomes its own packaging_issues row
-- with its own PKG-#### code, exactly as a single issue is saved today (it calls
-- create_packaging_issue() per line), so the Packaging list, reports, stock movements,
-- FIFO and the per-batch yield rule (ACC-19) are unchanged. Because the lines are saved
-- one after another in the same transaction, two lines drawing on the same batch are
-- checked against the batch TOGETHER — the second line sees what the first one used.
--
-- p_header: {"issue_date": "YYYY-MM-DD", "department": "store"|"rnd"}   (shared by all lines)
-- p_lines : [{"finished_product_batch_id", "pack_size", "pack_size_qty", "pack_size_unit",
--             "fp_qty_consumed", "unit_count", "materials": [{"item_id","quantity","unit"}]}, ...]
-- Returns the codes created, in line order. Production issues keep the existing single
-- create_packaging_issue() path (decided with Ravi, 2 Oct 2026; revisited later).
-- A failure is reported as "Line N: <reason>".
-- ============================================================

begin;

create or replace function public.create_packaging_issues(p_header jsonb, p_lines jsonb)
returns text[]
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_dept  text := p_header->>'department';
  v_date  text := nullif(p_header->>'issue_date', '');
  v_n     int;
  v_i     int := 0;
  v_line  jsonb;
  v_codes text[] := '{}';
  v_code  text;
begin
  if v_dept is null or v_dept not in ('store', 'rnd') then
    raise exception 'Several lines can only be saved for Store or R&D.' using errcode = '22023';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'Add at least one line.' using errcode = '22023';
  end if;
  v_n := jsonb_array_length(p_lines);
  if v_n < 1 then
    raise exception 'Add at least one line.' using errcode = '22023';
  end if;
  if v_n > 30 then
    raise exception 'A packaging issue can have at most 30 lines (you have %).', v_n using errcode = '22023';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_i := v_i + 1;
    begin
      v_code := public.get_next_packaging_issue_code();
      perform public.create_packaging_issue(
        jsonb_build_object(
          'code', v_code,
          'finished_product_batch_id', v_line->>'finished_product_batch_id',
          'pack_size', v_line->>'pack_size',
          'pack_size_qty', v_line->>'pack_size_qty',
          'pack_size_unit', v_line->>'pack_size_unit',
          'fp_qty_consumed', v_line->>'fp_qty_consumed',
          'unit_count', v_line->>'unit_count',
          'department', v_dept,
          'issue_date', v_date),
        coalesce(v_line->'materials', '[]'::jsonb));
      v_codes := v_codes || v_code;
    exception when others then
      -- Name the line, keep the original error class so the app still shows the message.
      raise exception 'Line %: %', v_i, sqlerrm using errcode = sqlstate;
    end;
  end loop;

  return v_codes;
end $$;

revoke all on function public.create_packaging_issues(jsonb, jsonb) from public, anon;
grant execute on function public.create_packaging_issues(jsonb, jsonb) to authenticated;

do $$
begin
  if position('Several lines can only be saved' in pg_get_functiondef('public.create_packaging_issues(jsonb,jsonb)'::regprocedure)) = 0 then
    raise exception '0093 self-check failed: create_packaging_issues missing or incomplete.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0094_consistent_shortage_messages.sql
-- ############################################################

-- ============================================================
-- FB-0052 follow-up (2 Oct 2026, Ravi): the two "not enough" messages on a packaging
-- save read differently —
--   packaging material:  "Not enough stock on hand for D60: 4800 available, 250000 requested."
--   finished product:    "Batch FP-... has only 0 kg left to pack or issue (yield less samples,
--                         less 0 kg already issued). This issue needs 5 kg."
-- Both now use one shape, with the code and name and the unit on both numbers:
--   "Not enough stock for PKG-00001 · D60: 4800 nos available, 250000 nos needed."
--   "Not enough stock for batch FP-00002-01/26 · Atharva Amalaki Vati: 39100 nos available, 500000 nos needed."
-- Only the wording changes. The rules (what is allowed and refused) are exactly as before.
-- check_sufficient_stock() is shared, so wastage and Production issues read the same way too.
-- ============================================================

begin;

create or replace function public.check_sufficient_stock(p_item_id uuid, p_quantity numeric)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_code text;
  v_name text;
  v_unit text;
  v_available numeric;
begin
  select item_code, name, unit into v_code, v_name, v_unit from public.items where id = p_item_id for update;

  select on_hand into v_available from public.stock_balance where item_id = p_item_id;
  v_available := coalesce(v_available, 0);

  if p_quantity > v_available then
    raise exception 'Not enough stock for %: % % available, % % needed.',
      case when v_code is null then 'this item' else v_code || ' · ' || coalesce(v_name, '') end,
      trim_scale(round(v_available, 6)), coalesce(v_unit, ''),
      trim_scale(round(p_quantity, 6)), coalesce(v_unit, '');
  end if;
end $$;

create or replace function public.trg_fn_packaging_batch_balance()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch record;
  v_fp_unit text;
  v_fp_name text;
  v_factor numeric;
  v_left numeric;
  v_issued numeric;
begin
  if new.fp_qty_consumed is null or new.fp_qty_consumed <= 0 then
    return new;
  end if;

  -- Lock the batch so two issues against it at the same moment are checked
  -- one after the other.
  select fpb.batch_number, fpb.batch_yield, fpb.unit,
         coalesce(fpb.qc_sample_qty, 0) + coalesce(fpb.stability_qty, 0) + coalesce(fpb.rnd_qty, 0) as samples,
         md.finished_product_item_id
    into v_batch
    from public.finished_product_batches fpb
    join public.mfr_definitions md on md.id = fpb.mfr_definition_id
   where fpb.id = new.finished_product_batch_id
     for update of fpb;

  if v_batch.batch_yield is null then
    return new;   -- no yield recorded (older data): item-level check still applies
  end if;

  select unit, name into v_fp_unit, v_fp_name from public.items where id = v_batch.finished_product_item_id;
  -- fp_qty_consumed is in the finished product's stock unit; the batch's
  -- yield is in the batch's unit (0076 keeps these compatible).
  v_factor := coalesce(public.convert_unit(1, v_batch.unit, coalesce(v_fp_unit, v_batch.unit)), 1);

  select coalesce(sum(fp_qty_consumed), 0) into v_issued
    from public.packaging_issues
   where finished_product_batch_id = new.finished_product_batch_id
     and id is distinct from new.id;

  v_left := (v_batch.batch_yield - v_batch.samples) * v_factor - v_issued;

  if new.fp_qty_consumed > v_left + 0.0000001 then
    raise exception 'Not enough stock for batch % · %: % % available, % % needed.',
      v_batch.batch_number, coalesce(v_fp_name, ''),
      trim_scale(round(greatest(v_left, 0), 6)), coalesce(v_fp_unit, v_batch.unit),
      trim_scale(round(new.fp_qty_consumed, 6)), coalesce(v_fp_unit, v_batch.unit)
      using errcode = 'P0001';
  end if;
  return new;
end $$;

do $$
begin
  if position('Not enough stock for batch' in pg_get_functiondef('public.trg_fn_packaging_batch_balance()'::regprocedure)) = 0
     or position('available, % % needed' in pg_get_functiondef('public.check_sufficient_stock(uuid,numeric)'::regprocedure)) = 0 then
    raise exception '0094 self-check failed: shortage messages not updated.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0095_production_multi_line.sql
-- ############################################################

-- ============================================================
-- FB-0052 (Production, 2 Oct 2026, Ravi): the Production issue, like Store and R&D (0093),
-- can carry several lines in one save — each line its own Finished Product batch, quantity
-- to convert and QC / Stability / R&D samples.
--
-- create_production_issues(p_header, p_lines) saves up to 30 lines in ONE transaction (all or
-- nothing). Each line becomes its own packaging_issues row (own PKG-#### code) and, through the
-- existing triggers, its own Raw Material (RM-FP) batch with its own QC cycle — exactly as a
-- single Production issue does today (it calls create_packaging_issue() per line, no
-- packaging materials). Stock rules (per-batch yield, product stock) are unchanged.
--
-- New rule (Ravi): a Finished Product batch may appear on ONE line only per issue:
--   "Line 2: Batch FP-... · Name is already on line 1. A batch can be issued to Production
--    only once per issue."
-- R&D quantity is optional (empty = 0); the app sends 0.
--
-- p_header: {"issue_date": "YYYY-MM-DD"}
-- p_lines : [{"finished_product_batch_id", "pack_size", "fp_qty_consumed", "unit_count",
--             "qc_qty", "stability_qty", "rnd_qty"}, ...]
-- Returns the codes created, in line order. Errors read "Line N: <reason>".
-- ============================================================

begin;

create or replace function public.create_production_issues(p_header jsonb, p_lines jsonb)
returns text[]
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_date  text := nullif(p_header->>'issue_date', '');
  v_n     int;
  v_i     int := 0;
  v_j     int;
  v_line  jsonb;
  v_codes text[] := '{}';
  v_code  text;
  v_ids   text[] := '{}';
  v_label text;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'Add at least one line.' using errcode = '22023';
  end if;
  v_n := jsonb_array_length(p_lines);
  if v_n < 1 then
    raise exception 'Add at least one line.' using errcode = '22023';
  end if;
  if v_n > 30 then
    raise exception 'A packaging issue can have at most 30 lines (you have %).', v_n using errcode = '22023';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_i := v_i + 1;

    -- One batch, one line.
    v_j := array_position(v_ids, v_line->>'finished_product_batch_id');
    if v_j is not null then
      select fpb.batch_number || coalesce(' · ' || it.name, '')
        into v_label
        from public.finished_product_batches fpb
        left join public.mfr_definitions md on md.id = fpb.mfr_definition_id
        left join public.items it on it.id = md.finished_product_item_id
       where fpb.id = (v_line->>'finished_product_batch_id')::uuid;
      raise exception 'Line %: Batch % is already on line %. A batch can be issued to Production only once per issue.',
        v_i, coalesce(v_label, 'this batch'), v_j using errcode = '22023';
    end if;
    v_ids := v_ids || (v_line->>'finished_product_batch_id');

    begin
      v_code := public.get_next_packaging_issue_code();
      perform public.create_packaging_issue(
        jsonb_build_object(
          'code', v_code,
          'finished_product_batch_id', v_line->>'finished_product_batch_id',
          'pack_size', v_line->>'pack_size',
          'fp_qty_consumed', v_line->>'fp_qty_consumed',
          'unit_count', v_line->>'unit_count',
          'department', 'production',
          'issue_date', v_date,
          'qc_qty', v_line->>'qc_qty',
          'stability_qty', v_line->>'stability_qty',
          'rnd_qty', coalesce(nullif(v_line->>'rnd_qty', ''), '0')),
        '[]'::jsonb);
      v_codes := v_codes || v_code;
    exception when others then
      raise exception 'Line %: %', v_i, sqlerrm using errcode = sqlstate;
    end;
  end loop;

  return v_codes;
end $$;

revoke all on function public.create_production_issues(jsonb, jsonb) from public, anon;
grant execute on function public.create_production_issues(jsonb, jsonb) to authenticated;

do $$
begin
  if position('only once per issue' in pg_get_functiondef('public.create_production_issues(jsonb,jsonb)'::regprocedure)) = 0 then
    raise exception '0095 self-check failed: create_production_issues missing or incomplete.';
  end if;
end $$;

commit;

-- ############################################################
-- ## 0096_coa_template_per_item.sql
-- ############################################################

-- ============================================================
-- Certificate of Analysis templates move from "one per Item Type" to
-- "one per item".
--
-- Ravi (3 Oct 2026): "COA Templates should be defined at each Item Level.
-- For each Raw Material there would be one template, for each Finished
-- Product there would be one template. This should be defined at the time
-- of defining the product ... when MFR is created, there should be option
-- to define its COA similar to how Manufacturing Procedure is defined.
-- However COA is not part of MFR so should be tracked and reported
-- separately." Decisions (AskUserQuestion, same day): the existing Item
-- Type templates are discarded (all test data); a template is optional
-- when the item or MFR is created (a COA cannot be issued until one
-- exists); whoever can edit the item can edit its template; a register,
-- change history and Excel/PDF export are added.
--
-- Design:
--   - coa_templates is keyed by EITHER a raw-material item (item_id) OR an
--     MFR (mfr_definition_id), never both, never neither. A Finished
--     Product's template hangs off its MFR (the FP item only exists after
--     the MFR is approved, but the template can be defined from the moment
--     the MFR is created, and stays editable after approval: COA is not
--     part of the MFR recipe, so the recipe lock does not apply).
--   - Every save writes a snapshot row to coa_template_revisions, so the
--     register can show who changed what and when without reading the
--     delete-and-reinsert noise in the audit log.
--   - Issued certificates are unaffected: they carry their own snapshot
--     (header_data / result_lines). coa_records.coa_template_id becomes
--     "on delete set null" so removing a template or item never blocks.
-- ============================================================

-- 1. Discard the old per-Item-Type templates.
alter table public.coa_records drop constraint if exists coa_records_coa_template_id_fkey;
alter table public.coa_records
  add constraint coa_records_coa_template_id_fkey
  foreign key (coa_template_id) references public.coa_templates(id) on delete set null;

delete from public.coa_templates;   -- lines cascade; issued COAs keep their snapshot

-- 2. Re-key.
alter table public.coa_templates drop constraint if exists coa_templates_item_type_id_key;
alter table public.coa_templates drop column if exists item_type_id;
alter table public.coa_templates
  add column item_id uuid references public.items(id) on delete cascade,
  add column mfr_definition_id uuid references public.mfr_definitions(id) on delete cascade;
alter table public.coa_templates
  add constraint coa_templates_one_subject
  check ((item_id is not null) <> (mfr_definition_id is not null));
create unique index coa_templates_item_uidx on public.coa_templates (item_id) where item_id is not null;
create unique index coa_templates_mfr_uidx on public.coa_templates (mfr_definition_id) where mfr_definition_id is not null;

-- 3. Revision history (one row per save, written by the RPCs only).
create table public.coa_template_revisions (
  id uuid primary key default gen_random_uuid(),
  coa_template_id uuid not null references public.coa_templates(id) on delete cascade,
  revision_no integer not null,
  lines jsonb not null,
  changed_by uuid references auth.users(id),
  changed_at timestamptz not null default now(),
  unique (coa_template_id, revision_no)
);
alter table public.coa_template_revisions enable row level security;
create policy coa_template_revisions_select on public.coa_template_revisions
  for select using ((select public.has_app_access()));
-- no insert/update/delete policy: only the security definer functions below write here.

-- 4. Who may manage a template: whoever may edit the thing it belongs to.
create or replace function public.can_manage_coa_template(p_item_id uuid, p_mfr_definition_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_item_id is not null then public.has_any_role('system_admin', 'inventory_manager', 'mfr_manager')
    when p_mfr_definition_id is not null then public.has_any_role('system_admin', 'mfr_manager')
    else false
  end;
$$;

-- Direct writes to the template header row: System Admin only. Everyone else
-- goes through the functions below (lines have never had a direct write policy).
drop policy if exists coa_templates_insert on public.coa_templates;
drop policy if exists coa_templates_update on public.coa_templates;
drop policy if exists coa_templates_delete on public.coa_templates;
create policy coa_templates_insert on public.coa_templates for insert
  with check (public.has_any_role('system_admin'));
create policy coa_templates_update on public.coa_templates for update
  using (public.has_any_role('system_admin')) with check (public.has_any_role('system_admin'));
create policy coa_templates_delete on public.coa_templates for delete
  using (public.has_any_role('system_admin'));

-- 5. Save one template (create or replace its lines) and record a revision.
drop function if exists public.upsert_coa_template(uuid, jsonb);

create or replace function public.upsert_coa_template(
  p_item_id uuid,
  p_mfr_definition_id uuid,
  p_lines jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_template_id uuid;
  v_line jsonb;
  v_idx int := 0;
  v_snapshot jsonb := '[]'::jsonb;
  v_category text;
begin
  if (p_item_id is null) = (p_mfr_definition_id is null) then
    raise exception 'A COA template belongs to either a raw material or an MFR.';
  end if;
  if not public.can_manage_coa_template(p_item_id, p_mfr_definition_id) then
    raise exception 'Not authorized to manage this COA template.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'At least one test is required.';
  end if;

  if p_item_id is not null then
    select category into v_category from public.items where id = p_item_id;
    if v_category is null then
      raise exception 'Item not found.';
    end if;
    if v_category <> 'raw' then
      raise exception 'COA templates are defined for raw materials and MFRs only.';
    end if;
    select id into v_template_id from public.coa_templates where item_id = p_item_id for update;
  else
    if not exists (select 1 from public.mfr_definitions where id = p_mfr_definition_id) then
      raise exception 'MFR not found.';
    end if;
    select id into v_template_id from public.coa_templates where mfr_definition_id = p_mfr_definition_id for update;
  end if;

  if v_template_id is null then
    insert into public.coa_templates (item_id, mfr_definition_id, created_by)
    values (p_item_id, p_mfr_definition_id, auth.uid())
    returning id into v_template_id;
  else
    update public.coa_templates set updated_at = now(), updated_by = auth.uid() where id = v_template_id;
    delete from public.coa_template_lines where coa_template_id = v_template_id;
  end if;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_idx := v_idx + 1;
    if coalesce(trim(v_line->>'test'), '') = '' or coalesce(trim(v_line->>'specification'), '') = '' then
      raise exception 'Row %: both Test and Specification are required.', v_idx;
    end if;
    insert into public.coa_template_lines (coa_template_id, seq, test, specification)
    values (v_template_id, v_idx, trim(v_line->>'test'), trim(v_line->>'specification'));
    v_snapshot := v_snapshot || jsonb_build_array(
      jsonb_build_object('seq', v_idx, 'test', trim(v_line->>'test'), 'specification', trim(v_line->>'specification')));
  end loop;

  insert into public.coa_template_revisions (coa_template_id, revision_no, lines, changed_by)
  values (
    v_template_id,
    coalesce((select max(revision_no) from public.coa_template_revisions where coa_template_id = v_template_id), 0) + 1,
    v_snapshot,
    auth.uid()
  );

  return v_template_id;
end $$;

-- 6. Bulk upload: payload is [{item_id | mfr_definition_id, lines:[{test, specification}]}].
create or replace function public.bulk_create_coa_templates(p_payload jsonb)
returns setof uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_group jsonb;
  v_item_id uuid;
  v_mfr_id uuid;
  v_template_id uuid;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'array' or jsonb_array_length(p_payload) = 0 then
    raise exception 'No COA template rows to import.';
  end if;

  for v_group in select * from jsonb_array_elements(p_payload)
  loop
    v_item_id := nullif(v_group->>'item_id', '')::uuid;
    v_mfr_id := nullif(v_group->>'mfr_definition_id', '')::uuid;
    if (v_item_id is null) = (v_mfr_id is null) then
      raise exception 'Every row needs either a raw material code or an MFR code.';
    end if;
    if exists (select 1 from public.coa_templates
               where (v_item_id is not null and item_id = v_item_id)
                  or (v_mfr_id is not null and mfr_definition_id = v_mfr_id)) then
      raise exception 'An item or MFR in this file already has a COA template — edit it on its own screen instead of uploading it again.';
    end if;
    v_template_id := public.upsert_coa_template(v_item_id, v_mfr_id, v_group->'lines');
    return next v_template_id;
  end loop;
  return;
end $$;

-- 7. Register: every raw material and every MFR, with or without a template.
create or replace view public.coa_template_register
with (security_invoker = on) as
select
  'raw_material'::text as subject_type,
  i.id as subject_id,
  i.item_code as code,
  i.name as name,
  it.description as item_type,
  i.active as active,
  t.id as template_id,
  coalesce((select count(*) from public.coa_template_lines l where l.coa_template_id = t.id), 0)::int as tests,
  coalesce((select max(revision_no) from public.coa_template_revisions r where r.coa_template_id = t.id), 0)::int as revisions,
  coalesce(t.updated_at, t.created_at) as last_changed_at,
  coalesce(t.updated_by, t.created_by) as last_changed_by
from public.items i
left join public.item_types it on it.id = i.item_type_id
left join public.coa_templates t on t.item_id = i.id
where i.category = 'raw'
union all
select
  'finished_product',
  m.id,
  m.code,
  m.name,
  it.description,
  m.active,
  t.id,
  coalesce((select count(*) from public.coa_template_lines l where l.coa_template_id = t.id), 0)::int,
  coalesce((select max(revision_no) from public.coa_template_revisions r where r.coa_template_id = t.id), 0)::int,
  coalesce(t.updated_at, t.created_at),
  coalesce(t.updated_by, t.created_by)
from public.mfr_definitions m
left join public.items fp on fp.id = m.finished_product_item_id
left join public.item_types it on it.id = coalesce(fp.item_type_id, m.item_type_id)
left join public.coa_templates t on t.mfr_definition_id = m.id;

grant select on public.coa_template_register to authenticated;

-- Same exposure as the other template functions: signed-in users only.
revoke all on function public.upsert_coa_template(uuid, uuid, jsonb) from public, anon;
grant execute on function public.upsert_coa_template(uuid, uuid, jsonb) to authenticated;
revoke all on function public.bulk_create_coa_templates(jsonb) from public, anon;
grant execute on function public.bulk_create_coa_templates(jsonb) to authenticated;
revoke all on function public.can_manage_coa_template(uuid, uuid) from public, anon;
grant execute on function public.can_manage_coa_template(uuid, uuid) to authenticated;

-- The revisions table joins the audit trail like every other business table
-- (same triggers 0072 attaches: row audit, truncate audit, who/when stamps).
do $$
declare
  v_tbl text := 'coa_template_revisions';
begin
  execute format('drop trigger if exists %I on public.%I', 'trg_audit_' || v_tbl, v_tbl);
  execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.trg_fn_audit_log(%L)',
                 'trg_audit_' || v_tbl, v_tbl, 'id');
  execute format('drop trigger if exists %I on public.%I', 'trg_audit_truncate_' || v_tbl, v_tbl);
  execute format('create trigger %I after truncate on public.%I for each statement execute function public.trg_fn_audit_truncate()',
                 'trg_audit_truncate_' || v_tbl, v_tbl);
  execute format('alter table public.%I add column if not exists created_at timestamptz', v_tbl);
  execute format('alter table public.%I alter column created_at set default now()', v_tbl);
  execute format('alter table public.%I add column if not exists created_by uuid references auth.users(id)', v_tbl);
  execute format('alter table public.%I add column if not exists updated_at timestamptz', v_tbl);
  execute format('alter table public.%I add column if not exists updated_by uuid references auth.users(id)', v_tbl);
  execute format('drop trigger if exists %I on public.%I', 'trg_stamp_created_' || v_tbl, v_tbl);
  execute format('create trigger %I before insert on public.%I for each row execute function public.trg_fn_stamp_created()',
                 'trg_stamp_created_' || v_tbl, v_tbl);
  execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
                 'trg_stamp_updated_' || v_tbl, v_tbl);
end $$;
